/**
 * ポジション 5 つ。解説（作成画面・用語集）もここに置く。
 * 現代のバスケはポジションの境目がゆるいので、選手はメインとサブの 2 つを持てる。
 */
export const POSITIONS = ['PG', 'SG', 'SF', 'PF', 'C'] as const
export type Position = (typeof POSITIONS)[number]

export interface PositionDef {
  /** 正式な名前 */
  name: string
  /** 役割をひとことで */
  role: string
  /** コートでの仕事 */
  job: string
  /** 大事な能力（表示用の名前） */
  keyAttrs: string[]
  /** 身長の目安（cm。NBA の平均的な範囲） */
  height: [number, number]
  /** 向いている人 */
  suits: string
  color: string
}

