/**
 * 成長タイプと年齢カーブ（Pitch Crown から移植）。
 * 1年あたりの伸び = rise * exp(-(age-center)^2 / 2w^2)、衰え = dec * 2.1 * sqrt(age - peakEnd)。
 * 能力グループごとに伸び方・衰え方の係数をかける（瞬発系は早く落ち、知性は35歳ごろまで伸びる）。
 */
import type { GrowthGroup } from './attributes'

export const GROWTH_TYPES = ['ultraEarly', 'early', 'normal', 'late', 'ultraLate'] as const
export type GrowthType = (typeof GROWTH_TYPES)[number]

export interface GrowthTypeDef {
  name: string
  center: number
  width: number
  peakEnd: number
  dec: number
  rise: number
  peak: string
}

export const GROWTH_DEFS: Record<GrowthType, GrowthTypeDef> = {
  ultraEarly: { name: '超早熟', center: 17.5, width: 3.3, peakEnd: 24, dec: 1.15, rise: 7.4, peak: '21〜24歳' },
  early: { name: '早熟', center: 19.5, width: 3.9, peakEnd: 26, dec: 1.0, rise: 6.9, peak: '23〜26歳' },
  normal: { name: '標準', center: 22.0, width: 4.5, peakEnd: 29, dec: 0.9, rise: 5.9, peak: '26〜29歳' },
  late: { name: '晩成', center: 25.0, width: 4.9, peakEnd: 32, dec: 0.8, rise: 5.6, peak: '29〜32歳' },
  ultraLate: { name: '超晩成', center: 27.5, width: 5.1, peakEnd: 34, dec: 0.78, rise: 5.5, peak: '31〜34歳' },
}

/** 年齢（小数可）での 1 年あたりの伸びと衰え（能力値ポイント） */
export function ageCurve(type: GrowthType, age: number): { up: number; down: number } {
  const p = GROWTH_DEFS[type]
  const up = p.rise * Math.exp(-((age - p.center) ** 2) / (2 * p.width * p.width))
  const down = age > p.peakEnd ? p.dec * 2.1 * Math.sqrt(age - p.peakEnd) : 0
  return { up, down }
}

export function groupUpFactor(g: GrowthGroup, age: number): number {
  if (g === 'phys') return age < 24 ? 1.18 : age < 28 ? 0.95 : 0.6
  if (g === 'body') return age < 20 ? 0.9 : 1.15
  if (g === 'mind') return age < 21 ? 0.72 : age < 26 ? 1.0 : 1.25
  if (g === 'tech') return age < 26 ? 1.06 : 0.95
  return 1.0
}

/** 負の値は衰え期でも伸びる */
export function groupDownFactor(g: GrowthGroup, age: number): number {
  if (g === 'phys') return age < 33 ? 1.55 : 2.1
  if (g === 'body') return 0.25
  if (g === 'tech') return 0.42
  if (g === 'mind') return age < 35 ? -0.45 : 0.25
  return 0.6
}

/** 現在値が上限の何割まで育っているかの目安（選手生成用） */
export function maturity(type: GrowthType, age: number): number {
  // 16 歳から年齢カーブの伸びを積み上げた割合
  let total = 0
  let sofar = 0
  for (let a = 16; a <= 36; a += 0.5) {
    const { up } = ageCurve(type, a)
    total += up
    if (a < age) sofar += up
  }
  return 0.7 + 0.3 * Math.min(1, sofar / (total * 0.92))
}
