/**
 * クラブ経営の人と物語: 会話の場面（オーナー・HC・選手・アドバイザー）と、選手の気持ち（満足度）。
 *   場面は club.scenes に積み、画面（ClubTalkScene）が順に出す。台詞は storyTalks.ts
 *   気持ち（0-100）: 出場時間の見込み（チームの中の力の順番）と実際の出場時間・チームの勝率で毎週ゆっくり動く（性格で速さが違う）
 *     38 未満で「出番が欲しい」、20 未満で「移籍したい」と言ってくる（同じ選手は 10 週あける）。30 未満だと調子が落ちる
 *     出番を約束すると 5 週後に確かめる（守れば上がり、破ると大きく下がる）。移籍を認めた選手（listed）には申し入れが来やすい
 *   オーナー: シーズンのはじめに目標・後半のはじめに途中の評価・終わりに結果。資金を入れたとき
 *   HC: シーズンのはじめに戦力の見立て・5 連敗で相談（選択）・7 連勝
 *   出来事（選択）: ブースター・スポンサー・お祭り・バスケ教室・設備・SNS・取材
 * 乱数は週のシード（clubAfterWeek の rng）。
 */
import { addFans } from './fans'
import { absWeekOf, ageAt } from '../core/calendar'
import { createRng, hashSeed, type Rng } from '../core/prng'
import { generateName } from '../data/nations'
import { PERSONALITY_DEFS, type Personality } from '../data/personality'
import { POSITIONS, type Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'
import { teamPower } from '../query'
import { gameDaySize } from '../match/rotation'
import { clubTeam, currentLedger } from './manage'
import { depthAuto } from './effects'
import { answerTradeOffer, retireNumber } from './nbaLife'
import type { CupGame } from '../competition/cup'
import { EACC_GROUP_WEEKS, type EaccGame } from '../competition/eacc'

export const OWNER = 'owner'
export const HC = 'hc'
export const ADV = 'todo_maiko'
export const REPORTER = 'minase_aoi'
export const pid = (id: number) => `p:${id}`

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))
const nowAbs = (s: GameState) => absWeekOf(s.season, s.week)

/** 出来事の費用・謝礼の目安（リーグごと。万円） */
export const EVENT_COST: Record<string, number> = { JBL3: 300, JBL2: 600, JBL1: 1500, NBA: 30000 }
export const eventCost = (state: GameState) => EVENT_COST[clubTeam(state).league] ?? 300

// ---------------------------------------------------------------- 場面

export function pushScene(state: GameState, id: string, speaker: string) {
  const c = state.club
  if (!c) return
  c.scenes ??= []
  if (c.scenes.some((s) => s.id === id) || c.sceneSeen?.includes(id)) return
  c.scenes.push({ id, speaker })
}

/** 返事の要る場面が積まれているか（1か月オートを止める） */
export const CHOICE_SCENES = /^(ask|leave|hc:slump|cap|ev:|trade|jersey)/
export function hasChoiceScene(state: GameState): boolean {
  return !!state.club?.scenes?.some((s) => CHOICE_SCENES.test(s.id))
}

/** オーナーの名前（シードで決まる） */
export function ownerName(state: GameState): string {
  return generateName('JP', createRng(hashSeed(state.seed, 0x0a11))).full
}

// ---------------------------------------------------------------- 気持ち

export function moodOf(state: GameState, id: number): number {
  return state.club?.mood?.[id] ?? 60
}

const gameLen = (state: GameState) => (clubTeam(state).league === 'NBA' ? 48 : 40)

/** 力の順番（総合値） */
function strengthOrder(state: GameState): number[] {
  const team = clubTeam(state)
  const o = new Map(team.roster.map((id) => [id, ovr(state.players[id])]))
  return [...team.roster].sort((a, b) => o.get(b)! - o.get(a)!)
}

/** 出番の見込み（1 試合の分）: チームの中の力の順番で。約束していれば先発並み */
export function expectedMinutes(state: GameState, id: number, order = strengthOrder(state)): number {
  const i = order.indexOf(id)
  // 試合のベンチに入らない順番（国内は 13 番手から）の選手は、出番がほとんどないと分かって入っている（登録 15 人で不満が続かないように）
  const bench = gameDaySize(clubTeam(state).league)
  const share = i < 0 ? 0 : i < 5 ? 0.6 : i < 8 ? 0.38 : i < 10 ? 0.25 : i < bench ? 0.15 : 0.04
  return gameLen(state) * Math.max(share, state.club?.promises?.[id] ? 0.5 : 0)
}

/** チームの今季の試合数（レギュラーシーズン） */
function teamGames(state: GameState): number {
  const team = clubTeam(state)
  const st = state.leagues[team.league].standings[team.id]
  return st ? st.w + st.l : 0
}

/** 性格ごとの気持ちの落ち着く先の上下 */
const MOOD_BASE: Record<Personality, number> = { hot: -6, genius: -8, leader: -3, effort: -2, cool: 0, mood: 4, mypace: 7, shy: 5 }

/** 毎週の気持ち（自分の試合があった週） */
function moodWeek(state: GameState) {
  const c = state.club!
  const team = clubTeam(state)
  c.mood ??= {}
  for (const k of Object.keys(c.mood)) if (!team.roster.includes(Number(k))) delete c.mood[Number(k)]
  const games = teamGames(state)
  if (games < 4) return
  const st = state.leagues[team.league].standings[team.id]
  const wp = st && games ? st.w / games : 0.5
  const order = strengthOrder(state)
  const abs = nowAbs(state)
  for (const id of team.roster) {
    const p = state.players[id]
    const m = c.mood[id] ?? 60
    if (p.injury) continue
    const mpg = p.stats.min / games
    // 性格で我慢の強さが違う（自信家・熱血は早く不満を言い、マイペース・内気は言いにくい）。若い選手は待てる
    const young = ageAt(abs, p.birthAbs) <= 22 ? 5 : 0
    const target = clamp(56 + MOOD_BASE[p.personality] + young + (mpg - expectedMinutes(state, id, order)) * 2 + (wp - 0.5) * 24, 5, 98)
    const k = 0.12 * PERSONALITY_DEFS[p.personality].moraleVar
    c.mood[id] = clamp(m + (target - m) * k, 0, 100)
    if (c.mood[id] < 30) p.condition = Math.max(5, p.condition - 1.5)
  }
}

/** 気持ちの沈んだ選手の申し出（1 週に 1 人まで） */
function requests(state: GameState) {
  const c = state.club!
  const abs = nowAbs(state)
  c.askedAt ??= {}
  for (const id of clubTeam(state).roster) {
    const m = c.mood?.[id]
    if (m === undefined || c.listed?.includes(id) || c.promises?.[id]) continue
    if (abs - (c.askedAt[id] ?? -99) < 10) continue
    if (m < 20) {
      pushScene(state, `leave:${id}:${abs}`, pid(id))
      c.askedAt[id] = abs
      return
    }
    if (m < 38) {
      pushScene(state, `ask:${id}:${abs}`, pid(id))
      c.askedAt[id] = abs
      return
    }
  }
}

/** 約束の確かめ（5 週後） */
function checkPromises(state: GameState) {
  const c = state.club!
  const abs = nowAbs(state)
  for (const [k, pr] of Object.entries(c.promises ?? {})) {
    if (abs < pr.until) continue
    delete c.promises![Number(k)]
    const p = state.players[Number(k)]
    if (!p || p.teamId !== c.teamId) continue
    const g = Math.max(1, teamGames(state) - pr.g0)
    const kept = (p.stats.min - pr.min0) / g >= gameLen(state) * 0.45
    c.mood![p.id] = clamp(moodOf(state, p.id) + (kept ? 12 : -25), 0, 100)
    pushScene(state, `promise:${p.id}:${kept ? 1 : 0}:${abs}`, pid(p.id))
  }
}

/** 主将: チームでいちばん長くいる主力（シーズン数 → 総合値） */
export function captainOf(state: GameState): Player | undefined {
  const c = state.club!
  const team = clubTeam(state)
  const tenure = (p: Player) => p.history.filter((h) => h.teamId === c.teamId).length
  return team.roster
    .map((id) => state.players[id])
    .sort((a, b) => tenure(b) - tenure(a) || ovr(b) - ovr(a))[0]
}

// ---------------------------------------------------------------- 毎週（clubAfterWeek から）

export function storyWeek(state: GameState, rng: Rng) {
  const c = state.club!
  const abs = nowAbs(state)
  const results = c.lastResults ?? []
  if (results.length) {
    moodWeek(state)
    // 連勝・連敗
    for (const r of results) {
      const win = r.us > r.them
      c.streak = win ? Math.max(0, c.streak ?? 0) + 1 : Math.min(0, c.streak ?? 0) - 1
      // 連敗の相談・連勝の話は、それぞれ 26 週に 1 回まで
      if (c.streak === -5 && fresh(state, 'slump', 26)) pushScene(state, `hc:slump:${abs}`, HC)
      if (c.streak === 7 && fresh(state, 'streak', 26)) pushScene(state, `hc:streak:${abs}`, HC)
    }
  }
  checkPromises(state)
  requests(state)
  // 後半のはじめ: オーナーの途中の評価・主将の相談
  if (state.week === 28 && teamGames(state) > 0) pushScene(state, `owner:mid:${state.season}`, OWNER)
  if (state.week === 22 && teamGames(state) > 0) {
    const team = clubTeam(state)
    const avg = team.roster.reduce((s, id) => s + moodOf(state, id), 0) / Math.max(1, team.roster.length)
    const cap = captainOf(state)
    if (cap && avg < 48) pushScene(state, `cap:${state.season}:${cap.id}`, pid(cap.id))
  }
  // 出来事（選択）: 返事待ちがなければ 7%
  if (!hasChoiceScene(state) && rng.chance(0.07)) choiceEvent(state, rng)
}

/** その話を最近出していなければ true にして、出した週を覚える */
function fresh(state: GameState, key: string, weeks: number): boolean {
  const c = state.club!
  const abs = nowAbs(state)
  c.evLast ??= {}
  if (abs - (c.evLast[key] ?? -999) < weeks) return false
  c.evLast[key] = abs
  return true
}

function choiceEvent(state: GameState, rng: Rng) {
  const abs = nowAbs(state)
  const team = clubTeam(state)
  const c = state.club!
  // 同じ種類の出来事は 30 週あける（炎上と設備のトラブルは 52 週）
  const gap: Record<string, number> = { sns: 52, trouble: 52 }
  const kinds = (['booster', 'sponsor', 'festival', 'clinic', 'trouble', 'sns', 'interview'] as const).filter((k) => abs - (c.evLast?.[k] ?? -999) >= (gap[k] ?? 30))
  if (!kinds.length) return
  const kind = rng.pick(kinds)
  fresh(state, kind, 0)
  const someone = () => {
    const ids = team.roster.filter((id) => !state.players[id].injury)
    return ids.length ? rng.pick(ids) : undefined
  }
  if (kind === 'sns' || kind === 'sponsor') {
    const id = someone()
    if (id === undefined) return
    pushScene(state, `ev:${kind}:${id}:${abs}`, kind === 'sns' ? pid(id) : ADV)
    return
  }
  pushScene(state, `ev:${kind}:${abs}`, kind === 'interview' ? REPORTER : ADV)
}

/** 新しいシーズンのはじめ（setOwnerGoal のあと）: オーナーの目標・HC の見立て。気持ちは半分 60 に戻る */
export function storySeasonStart(state: GameState) {
  const c = state.club!
  for (const k of Object.keys(c.mood ?? {})) c.mood![Number(k)] = 60 + (c.mood![Number(k)] - 60) * 0.5
  c.promises = {}
  c.streak = 0
  const team = clubTeam(state)
  c.seasonStart = { fans: c.fans, ovr: Object.fromEntries(team.roster.map((id) => [id, ovr(state.players[id])])) }
  pushScene(state, `owner:goal:${state.season}`, OWNER)
  pushScene(state, `hc:start:${state.season}`, HC)
}

/** いちばん手薄なポジション（そのポジションでいちばん上手い選手の総合値が低いところ。HC の見立てと補強の画面） */
export function weakestPosition(state: GameState): { pos: Position; best: number } {
  const team = clubTeam(state)
  const best = (pos: Position) => Math.max(0, ...team.roster.map((id) => state.players[id]).filter((p) => p.pos === pos).map((p) => ovr(p)))
  const pos = [...POSITIONS].sort((a, b) => best(a) - best(b))[0]
  return { pos, best: best(pos) }
}

/** HC の見立て: リーグの中の戦力の順位と、いちばん手薄なポジション */
export function hcReport(state: GameState): { rank: number; teams: number; weak: Position } {
  const team = clubTeam(state)
  const lg = state.leagues[team.league]
  const ids = team.league === 'NBA' ? lg.teamIds.filter((id) => state.teams[id].conf === team.conf) : lg.teamIds
  const power = ids.map((id) => [id, teamPower(state, state.teams[id])] as const).sort((a, b) => b[1] - a[1])
  return { rank: power.findIndex(([id]) => id === team.id) + 1, teams: ids.length, weak: weakestPosition(state).pos }
}

// ---------------------------------------------------------------- 選択の効果

/** 選んだ出来事のお金（資金の動き ＝ 帳簿の合計 を守るため、今の週の帳簿にも入れる） */
const addMoney = (state: GameState, v: number) => {
  state.club!.money += v
  currentLedger(state).other += v
}

export function applyClubChoice(state: GameState, sceneId: string, effect: string) {
  const c = state.club!
  const team = clubTeam(state)
  const [kind, a] = sceneId.split(':')
  const id = Number(a)
  const mood = (pid: number, d: number) => {
    c.mood ??= {}
    c.mood[pid] = clamp(moodOf(state, pid) + d, 0, 100)
  }
  const all = (d: number) => team.roster.forEach((x) => mood(x, d))
  if (kind === 'ask' || kind === 'leave') {
    const p = state.players[id]
    if (!p) return
    if (effect === 'promise') {
      c.promises ??= {}
      c.promises[id] = { until: nowAbs(state) + 5, min0: p.stats.min, g0: teamGames(state) }
      mood(id, 12)
      // 序列: 先発の 5 人目に入れる（おまかせなら、おすすめの序列が約束を守る）
      if (!depthAuto(state)) {
        const depth = (c.depth ?? strengthOrder(state)).filter((x) => x !== id && team.roster.includes(x))
        depth.splice(Math.min(4, depth.length), 0, id)
        c.depth = depth
      }
    }
    if (effect === 'wait') mood(id, -6)
    if (effect === 'list') {
      c.listed = [...new Set([...(c.listed ?? []), id])]
      mood(id, 8)
    }
    if (effect === 'stay') mood(id, -10)
  }
  if (kind === 'trade') answerTradeOffer(state, effect === 'yes')
  if (kind === 'jersey' && effect === 'yes') retireNumber(state, sceneId)
  if (kind === 'hc' && effect === 'hard') c.training.intensity = Math.min(2, c.training.intensity + 1) as 0 | 1 | 2
  if (kind === 'hc' && effect === 'trust') all(5)
  if (kind === 'cap' && effect === 'talk') all(5)
  if (kind === 'ev') {
    const cost = eventCost(state)
    const ev = a
    const who = Number(sceneId.split(':')[2])
    if (ev === 'booster' && effect === 'yes') {
      addMoney(state, -cost)
      addFans(state, 1.04)
    }
    if (ev === 'booster' && effect === 'no') c.popularity = Math.max(1, c.popularity - 1)
    if (ev === 'sponsor' && effect === 'yes') {
      addMoney(state, Math.round(cost * 0.6))
      const p = state.players[who]
      if (p) {
        p.fatigue = Math.min(100, p.fatigue + 15)
        mood(who, -3)
      }
    }
    if (ev === 'festival' && effect === 'yes') {
      addFans(state, 1.03)
      c.popularity = Math.min(100, c.popularity + 2)
      team.roster.forEach((x) => (state.players[x].fatigue = Math.min(100, state.players[x].fatigue + 8)))
    }
    if (ev === 'clinic' && effect === 'yes') {
      addMoney(state, -Math.round(cost * 0.3))
      addFans(state, 1.02)
      c.popularity = Math.min(100, c.popularity + 2)
    }
    if (ev === 'trouble') {
      if (effect === 'yes') addMoney(state, -Math.round(cost * 0.5))
      else {
        c.popularity = Math.max(1, c.popularity - 2)
        addFans(state, 0.99)
      }
    }
    if (ev === 'sns') {
      if (effect === 'apologize') {
        c.popularity = Math.max(1, c.popularity - 1)
        mood(who, -8)
      } else {
        c.popularity = Math.max(1, c.popularity - 3)
        mood(who, 10)
      }
    }
    if (ev === 'interview') {
      if (effect === 'title') {
        c.popularity = Math.min(100, c.popularity + 4)
        c.owner.trust = Math.min(100, c.owner.trust + 2)
      } else all(2)
    }
  }
}

// ---------------------------------------------------------------- 全日本選手権・東アジアのクラブ選手権（advanceWeek から）

/** 全日本選手権の賞金（優勝・準優勝・ベスト 4。万円） */
export const CUP_PRIZE = [3000, 1000, 300] as const
/** 東アジアのクラブ選手権の賞金（出場・1 勝・優勝。万円） */
export const EACC_PRIZE = { join: 1000, win: 300, champ: 6000 } as const

export function clubCupResult(state: GameState, res: { game: CupGame; winner: number; loser: number; upset: number }) {
  const c = state.club!
  const me = c.teamId
  if (res.winner !== me && res.loser !== me) return
  const r = res.game.r
  if (res.winner === me) {
    c.popularity = clamp(c.popularity + 1 + (res.upset > 0 ? 2 : 0), 1, 100)
    if (res.upset > 0) {
      c.cupUpsets = (c.cupUpsets ?? 0) + 1
      addFans(state, 1.01)
      pushScene(state, `cup:upset:${state.season}:${r}:${res.loser}`, HC)
    }
    if (r === 5) {
      addMoney(state, CUP_PRIZE[0])
      addFans(state, 1.06)
      c.popularity = clamp(c.popularity + 5, 1, 100)
      c.owner.trust = Math.min(100, c.owner.trust + 5)
      pushScene(state, `cup:champ:${state.season}`, OWNER)
    }
  } else if (r >= 4) addMoney(state, CUP_PRIZE[r === 5 ? 1 : 2])
}

export function clubEaccGames(state: GameState, games: EaccGame[]) {
  const c = state.club!
  const me = c.teamId
  const mine = games.filter((g) => g.home.team === me || g.away.team === me)
  if (!mine.length) return
  if (state.week === EACC_GROUP_WEEKS[0]) {
    addMoney(state, EACC_PRIZE.join)
    pushScene(state, `eacc:start:${state.season}`, ADV)
  }
  for (const g of mine) {
    const home = g.home.team === me
    if (home ? g.hs > g.as : g.as > g.hs) {
      addMoney(state, EACC_PRIZE.win)
      c.popularity = clamp(c.popularity + 1, 1, 100)
    }
  }
  if (state.eacc?.champion?.team === me) {
    addMoney(state, EACC_PRIZE.champ)
    addFans(state, 1.08)
    c.popularity = clamp(c.popularity + 6, 1, 100)
    c.owner.trust = Math.min(100, c.owner.trust + 6)
    pushScene(state, `eacc:champ:${state.season}`, OWNER)
  }
}
