/**
 * キャリアのくらしの拡充: サイドビジネス・自己投資（買い物・趣味・合宿）・オフの旅行・メディア・恋人と家族の出来事・子どもの節目。
 *   サイドビジネス: 開業 → Lv3 まで拡大 → 売却（注ぎ込んだお金の 6 割）。毎週の損益 = 売上 × レベル × 知名度 × 景気 × ゆらぎ − 経費 × レベル。
 *     景気は 4 週ごとに動く（0.75〜1.3）。ときどき評判（臨時の売上）とトラブル。スポーツテックはシーズンの終わりに大当たり（2.5 倍で売れる・10%）か倒産（12%）
 *   買い物: 経験点の種類ごとの上乗せ（growth.ts の purchaseExpMul）・回復（life.ts）
 *   趣味: 毎週少しずつ腕が上がり、調子と経験点。ヒロインと同じ趣味ならデートがはずむ
 *   合宿: 試合のない週の過ごし方「合宿」。費用・経験点・疲れ
 *   旅行: シーズン中に予約し、シーズンの終わりに出かける。メンタルの経験点・新しいシーズンの調子・恋人や家族との絆。アルバムに残る
 *   メディア: 4 週ごとに知名度で話が来る（会話で受けるか断る）。出演料・知名度・疲れ。自伝は 3 シーズン印税
 *   恋人・家族の出来事: 恋人なら約 5 週、結婚していれば約 4 週ごと。子どもの節目は誕生日の週、家族の行事は決まった週
 * 乱数は週ごとの専用の流れ（ほかの処理の並びを変えない）。
 */
import { WEEKS_PER_SEASON, absWeekOf, ageAt } from '../core/calendar'
import { weekRng, type Rng } from '../core/prng'
import {
  BIZ_BY_ID,
  CAMPS,
  CAMP_BY_ID,
  CAMP_TRAVEL,
  CHILD_MILESTONES,
  DONATIONS,
  FAMILY_EVENTS,
  HOBBIES,
  HOBBY_BY_ID,
  HOBBY_MAX,
  MEDIA,
  MEDIA_BY_KIND,
  PARTNER_EVENTS,
  PARTNER_EVENT_BY_ID,
  PURCHASES,
  TRIP_BY_ID,
  type BizId,
  type HobbyId,
  type MediaKind,
  type PurchaseId,
  type TripCompanion,
} from '../data/careerLife'
import type { GameState } from '../models/game'
import { gainExp } from './growth'
import { careerAge, careerFixtures, careerPlayer, regionOf } from './week'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))
const nowAbs = (state: GameState) => absWeekOf(state.season, state.week)
const news = (state: GameState, text: string, big = false) => state.news.push({ season: state.season, week: state.week, text, big })
const lifeRng = (state: GameState, salt: number): Rng => weekRng(state.seed, nowAbs(state), 0x11fe + salt)

// ---------------------------------------------------------------- サイドビジネス

const LEVEL_SALES = [1, 1.9, 2.8]

export const findBiz = (state: GameState, id: BizId) => state.career!.businesses?.find((b) => b.id === id)
export const bizCycle = (state: GameState) => state.career?.bizCycle ?? 1
export const cycleLabel = (v: number) => (v >= 1.12 ? '好景気' : v >= 1.04 ? 'やや好調' : v > 0.96 ? 'ふつう' : v > 0.88 ? 'やや不調' : '不景気')

function fameMul(state: GameState, id: BizId): number {
  return Math.max(0.2, 1 + BIZ_BY_ID[id].fameSens * (state.career!.fame / 100 - 0.4))
}

/** 毎週の損益の見込み（ゆらぎなし） */
export function bizEstimate(state: GameState, id: BizId, level: number): number {
  const d = BIZ_BY_ID[id]
  return Math.round(d.base * LEVEL_SALES[level - 1] * fameMul(state, id) * bizCycle(state) - d.upkeep * level)
}

export function canOpenBiz(state: GameState, id: BizId): string | null {
  const c = state.career!
  const d = BIZ_BY_ID[id]
  if (findBiz(state, id)) return '営業中'
  if (d.minFame && c.fame < d.minFame) return `知名度 ${d.minFame} から`
  if (c.money < d.cost) return '貯金が足りない'
  return null
}

export function openBiz(state: GameState, id: BizId): boolean {
  if (canOpenBiz(state, id)) return false
  const c = state.career!
  const d = BIZ_BY_ID[id]
  c.money -= d.cost
  c.businesses = [...(c.businesses ?? []), { id, level: 1, openedAbs: nowAbs(state), invested: d.cost, total: 0, season: 0 }]
  news(state, `${d.name}を始めた`)
  return true
}

export function bizUpgradeCost(state: GameState, id: BizId): number | null {
  const b = findBiz(state, id)
  if (!b || b.level >= 3) return null
  return BIZ_BY_ID[id].upgrade[b.level - 1]
}

export function upgradeBiz(state: GameState, id: BizId): boolean {
  const c = state.career!
  const b = findBiz(state, id)
  const cost = bizUpgradeCost(state, id)
  if (!b || cost === null || c.money < cost) return false
  c.money -= cost
  b.level++
  b.invested += cost
  news(state, `${BIZ_BY_ID[id].name}を広げた（Lv${b.level}）`)
  return true
}

export const bizSellValue = (invested: number, mul = 0.6) => Math.round((invested * mul) / 10) * 10

export function sellBiz(state: GameState, id: BizId, mul = 0.6, why = '手放した'): number {
  const c = state.career!
  const b = findBiz(state, id)
  if (!b) return 0
  const v = bizSellValue(b.invested, mul)
  c.money += v
  c.bizTotal = (c.bizTotal ?? 0) + b.total + v - b.invested
  c.businesses = (c.businesses ?? []).filter((x) => x.id !== id)
  news(state, `${BIZ_BY_ID[id].name}を${why}（${v.toLocaleString()} 万円）`, mul > 1)
  return v
}

/** 1 年の損益の見込み（くらしのお金の表） */
export function bizYearly(state: GameState): number {
  return (state.career!.businesses ?? []).reduce((s, b) => s + bizEstimate(state, b.id, b.level) * WEEKS_PER_SEASON, 0)
}

function bizWeek(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  const rng = lifeRng(state, 1)
  if (state.week % 4 === 0) c.bizCycle = Math.round(clamp(bizCycle(state) + rng.normal(0, 0.05) + (1 - bizCycle(state)) * 0.15, 0.75, 1.3) * 1000) / 1000
  for (const b of c.businesses ?? []) {
    const d = BIZ_BY_ID[b.id]
    let v = Math.round(d.base * LEVEL_SALES[b.level - 1] * fameMul(state, b.id) * bizCycle(state) * (0.85 + rng.next() * 0.3) - d.upkeep * b.level)
    if (rng.chance(0.012)) {
      const boom = Math.round(d.base * b.level * (4 + rng.next() * 4))
      v += boom
      news(state, `${d.name}が評判になり、臨時の売上 ${boom.toLocaleString()} 万円`)
    } else if (rng.chance(0.008)) {
      const loss = Math.round(d.upkeep * b.level * (3 + rng.next() * 3))
      v -= loss
      news(state, `${d.name}でトラブルがあり、${loss.toLocaleString()} 万円の出費`)
    }
    c.money += v
    b.total += v
    b.season += v
    const e = d.effect
    if (e?.fame) c.fame = clamp(c.fame + e.fame * b.level, 0, 100)
    if (e?.condition) p.condition = clamp(p.condition + e.condition * b.level, 5, 95)
    if (e?.exp) gainExp(state, Object.fromEntries(Object.entries(e.exp).map(([k, n]) => [k, (n ?? 0) * b.level])), careerAge(state))
  }
  // 貯金が足りなくなったら、今季いちばん赤字の事業を売る
  if (c.money < 0 && c.businesses?.length) {
    const worst = [...c.businesses].sort((a, b) => a.season - b.season)[0]
    sellBiz(state, worst.id, 0.6, '資金が足りず手放した')
  }
}

/** シーズンの終わり: 決算と、スポーツテックの大当たり・倒産 */
function bizSeasonEnd(state: GameState) {
  const c = state.career!
  const list = c.businesses ?? []
  if (!list.length) return
  const rng = lifeRng(state, 2)
  const st = findBiz(state, 'startup')
  if (st) {
    const r = rng.next()
    if (r < 0.1) sellBiz(state, 'startup', 2.5, '大当たり！ 大きな会社に買われ、2.5 倍で売れた')
    else if (r < 0.22) sellBiz(state, 'startup', 0, '倒産で失った')
  }
  const sum = (c.businesses ?? []).reduce((n, b) => n + b.season, 0)
  if (c.businesses?.length) news(state, `事業の決算: ${c.businesses.map((b) => `${BIZ_BY_ID[b.id].name} ${b.season >= 0 ? '+' : ''}${b.season.toLocaleString()}`).join('・')}（計 ${sum >= 0 ? '+' : ''}${sum.toLocaleString()} 万円）`)
  for (const b of c.businesses ?? []) b.season = 0
}

export function bizLifetime(state: GameState): number {
  const c = state.career!
  return (c.bizTotal ?? 0) + (c.businesses ?? []).reduce((n, b) => n + b.total, 0)
}

// ---------------------------------------------------------------- 買い物・趣味

export const hasPurchase = (state: GameState, id: PurchaseId) => !!state.career?.purchases?.includes(id)

export function canBuy(state: GameState, id: PurchaseId): string | null {
  const c = state.career!
  const d = PURCHASES.find((x) => x.id === id)!
  if (hasPurchase(state, id)) return '持っている'
  if (d.needHome && !(c.ownedHomes?.length ?? 0)) return '持ち家が要る'
  if (c.money < d.cost) return '貯金が足りない'
  return null
}

export function buyPurchase(state: GameState, id: PurchaseId): boolean {
  if (canBuy(state, id)) return false
  const c = state.career!
  const d = PURCHASES.find((x) => x.id === id)!
  c.money -= d.cost
  c.purchases = [...(c.purchases ?? []), id]
  news(state, `${d.name}を手に入れた`)
  return true
}

export function startHobby(state: GameState, id: HobbyId): boolean {
  const c = state.career!
  const d = HOBBY_BY_ID[id]
  if ((c.hobbies ?? []).some((h) => h.id === id) || (c.hobbies?.length ?? 0) >= HOBBY_MAX || c.money < d.cost) return false
  c.money -= d.cost
  c.hobbies = [...(c.hobbies ?? []), { id, skill: 5 }]
  return true
}

export function dropHobby(state: GameState, id: HobbyId) {
  const c = state.career!
  c.hobbies = (c.hobbies ?? []).filter((h) => h.id !== id)
}

function hobbyWeek(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  for (const h of c.hobbies ?? []) {
    h.skill = Math.min(100, h.skill + (1 - h.skill / 100) * 1.6)
    p.condition = clamp(p.condition + 0.3, 5, 95)
    gainExp(state, Object.fromEntries(Object.entries(HOBBY_BY_ID[h.id].exp).map(([k, n]) => [k, (n ?? 0) * (1 + h.skill / 100)])), careerAge(state))
  }
}

export const hobbySkill = (state: GameState, id: HobbyId) => state.career?.hobbies?.find((h) => h.id === id)?.skill ?? 0

// ---------------------------------------------------------------- 合宿（過ごし方「合宿」）

export function campsFor(state: GameState) {
  return CAMPS.filter((x) => !x.minFame || state.career!.fame >= x.minFame)
}

export function campCost(state: GameState, id: string): number {
  const d = CAMP_BY_ID[id]
  return d.cost + (d.where !== regionOf(state) ? CAMP_TRAVEL : 0)
}

/** 合宿に行けるか（試合のない週だけ） */
export function campOpen(state: GameState): boolean {
  return careerFixtures(state).length === 0
}

/** 週のはじめ（careerBeforeWeek から）: 合宿の効き目。費用が払えなければ自主トレになる */
export function campWeek(state: GameState): boolean {
  const c = state.career!
  const p = careerPlayer(state)
  const id = c.camp ?? campsFor(state)[0]?.id
  const d = id ? CAMP_BY_ID[id] : undefined
  if (!d || !campOpen(state)) return false
  const cost = campCost(state, d.id)
  if (c.money < cost) return false
  c.money -= cost
  gainExp(state, d.exp, careerAge(state))
  p.fatigue = clamp(p.fatigue + d.fatigue, 0, 100)
  c.talks.push({ id: `camp:${d.id}`, speaker: d.coach ?? 'todo_maiko' })
  return true
}

// ---------------------------------------------------------------- オフの旅行

export function tripPeople(state: GameState, w: TripCompanion): number {
  const c = state.career!
  return w === 'solo' || w === 'team' ? 1 : w === 'partner' ? 2 : 2 + (c.children?.length ?? 0)
}

export function tripCost(state: GameState, id: string, w: TripCompanion): number {
  return TRIP_BY_ID[id].cost * tripPeople(state, w)
}

export function canTrip(state: GameState, w: TripCompanion): boolean {
  const c = state.career!
  if (w === 'partner') return !!(c.partner || c.spouse)
  if (w === 'family') return !!c.spouse
  return true
}

/** 予約する（費用はそのとき払う。取り消せば全額戻る） */
export function bookTrip(state: GameState, id: string, w: TripCompanion): boolean {
  const c = state.career!
  const cost = tripCost(state, id, w)
  if (!canTrip(state, w) || c.money < cost) return false
  if (c.trip) c.money += c.trip.cost
  c.money -= cost
  c.trip = { id, with: w, season: state.season, cost }
  return true
}

export function cancelTrip(state: GameState) {
  const c = state.career!
  if (!c.trip) return
  c.money += c.trip.cost
  delete c.trip
}

/** シーズンの終わり: 出かける */
function tripSeasonEnd(state: GameState) {
  const c = state.career!
  const t = c.trip
  if (!t) return
  const d = TRIP_BY_ID[t.id]
  const p = careerPlayer(state)
  const partner = t.with === 'partner' || t.with === 'family' ? (c.spouse ?? c.partner) : undefined
  gainExp(state, { mind: d.mind }, careerAge(state))
  p.condition = clamp(p.condition + d.boost, 5, 95)
  p.fatigue = 0
  if (partner) c.bonds[partner] = Math.min(100, (c.bonds[partner] ?? 0) + d.bond)
  if (t.with === 'team') c.trust = clamp(c.trust + 2, 0, 100)
  c.album = [...(c.album ?? []), { season: t.season, trip: t.id, with: t.with, partner }]
  c.talks.push({ id: `trip:${t.id}:${t.with}`, speaker: partner ?? 'todo_maiko' })
  delete c.trip
}

// ---------------------------------------------------------------- メディア

function mediaWeek(state: GameState) {
  const c = state.career!
  const abs = nowAbs(state)
  if (c.mediaOffer && c.mediaOffer.until < abs) delete c.mediaOffer
  // 自伝の印税（3 シーズン、毎週）
  if (c.book && state.season - c.book.season < 3) c.money += c.book.royalty / WEEKS_PER_SEASON
  // 13 週ごと（半分くらい。1 シーズンに 1〜2 回）。同じ種類の話は 40 週あける。くらしの画面で断る設定にもできる
  if (c.mediaOff || c.mediaOffer || state.week % 13 !== 2 || c.fame < 15) return
  const rng = lifeRng(state, 3)
  if (!rng.chance(0.5)) return
  const region = regionOf(state)
  const age = careerAge(state)
  c.mediaLast ??= {}
  const cands = MEDIA.filter((m) => c.fame >= m.minFame && (!m.region || m.region === region) && !(m.kind === 'book' && (age < 28 || c.mediaDone?.includes('book'))) && abs - (c.mediaLast![m.kind] ?? -999) >= 40)
  if (!cands.length) return
  const m = rng.pick(cands)
  c.mediaLast[m.kind] = abs
  c.mediaOffer = { kind: m.kind, until: abs + 3 }
  c.talks.push({ id: `media:${m.kind}`, speaker: 'todo_maiko' })
}

/** 受ける（会話の選択から） */
export function acceptMedia(state: GameState, kind: MediaKind) {
  const c = state.career!
  const p = careerPlayer(state)
  const m = MEDIA_BY_KIND[kind]
  const net = Math.round(m.pay * 0.6)
  c.money += net
  c.fame = clamp(c.fame + m.fame, 0, 100)
  p.fatigue = clamp(p.fatigue + m.fatigue, 0, 100)
  if (m.trust) c.trust = clamp(c.trust + m.trust, 0, 100)
  if (m.mind) gainExp(state, { mind: m.mind }, careerAge(state))
  if (kind === 'book') c.book = { season: state.season, royalty: Math.round(1500 + c.fame * 40) }
  c.mediaDone = [...new Set([...(c.mediaDone ?? []), kind])]
  delete c.mediaOffer
  news(state, `${m.name}に出た（手取り ${net.toLocaleString()} 万円）`)
}

// ---------------------------------------------------------------- 恋人・家族の出来事・子どもの節目・家族の行事

function partnerEventWeek(state: GameState) {
  const c = state.career!
  const who = c.spouse ?? c.partner
  if (!who) return
  const abs = nowAbs(state)
  const rng = lifeRng(state, 4)
  const p = careerPlayer(state)
  c.pevLast ??= {}
  const push = (id: string, extra = '') => {
    const e = PARTNER_EVENTS.find((x) => x.id === id)!
    c.pevLast![id] = abs
    c.talks.push({ id: `pev:${id}:${who}${extra}`, speaker: who })
    if (!e.choices) applyPartnerEffect(state, who, e.effect)
  }
  // 年に 1 回: 主人公の誕生日の週と、付き合った（結婚した）日の週
  if ((abs - p.birthAbs) % WEEKS_PER_SEASON === 0 && abs - (c.pevLast.birthday ?? -99) > 40) return push('birthday')
  const since = c.spouse ? c.marriedSince : c.partnerSince
  if (since !== undefined && abs > since && (abs - since) % WEEKS_PER_SEASON === 0) return push('anniversary', `:${(abs - since) / WEEKS_PER_SEASON}:${c.spouse ? 1 : 0}`)
  // ふだんの出来事: 5〜8 週ごと（結婚してからは 4〜7 週）。同じ出来事はしばらく出さない
  // （ほかの話が積まれている週は出さない。誕生日と記念日は上で、ほかの話があっても出す）
  if (c.talks.length) return
  if (c.nextPartnerEvent === undefined) c.nextPartnerEvent = abs + rng.int(4, 7)
  if (abs < c.nextPartnerEvent) return
  c.nextPartnerEvent = abs + (c.spouse ? rng.int(4, 7) : rng.int(5, 8))
  const cands = PARTNER_EVENTS.filter(
    (e) =>
      !e.yearly &&
      (!e.only || (e.only === 'spouse' ? !!c.spouse : !c.spouse)) &&
      (!e.lowCondition || p.condition < 40) &&
      (!e.injured || !!p.injury) &&
      abs - (c.pevLast![e.id] ?? -999) >= (e.cooldown ?? 40) &&
      !(e.id === 'parents' && c.seen.includes(`pev:parents:${who}`)),
  )
  if (!cands.length) return
  push(rng.pick(cands).id)
}

export function applyPartnerEffect(state: GameState, who: string, e: { condition?: number; fatigue?: number; bond?: number; exp?: Partial<Record<string, number>>; money?: number }) {
  const c = state.career!
  const p = careerPlayer(state)
  if (e.condition) p.condition = clamp(p.condition + e.condition, 5, 95)
  if (e.fatigue) p.fatigue = clamp(p.fatigue + e.fatigue, 0, 100)
  if (e.bond) c.bonds[who] = clamp((c.bonds[who] ?? 0) + e.bond, 0, 100)
  if (e.money) c.money += e.money
  if (e.exp) gainExp(state, e.exp, careerAge(state))
}

/** 子どもの節目（誕生日の週）と、家族の行事（決まった週） */
function familyWeek(state: GameState) {
  const c = state.career!
  if (!c.spouse) return
  const abs = nowAbs(state)
  for (const [i, ch] of (c.children ?? []).entries()) {
    if ((abs - ch.birthAbs) % WEEKS_PER_SEASON !== 0) continue
    const age = ageAt(abs, ch.birthAbs)
    const ms = CHILD_MILESTONES.find((m) => m.age === age && (m.plays === undefined || m.plays === !!ch.plays))
    if (ms) c.talks.push({ id: `kid:${i}:${ms.id}`, speaker: c.spouse })
  }
  const fi = FAMILY_EVENTS.findIndex((e) => e.week === state.week)
  const fe = fi >= 0 && (state.season + fi) % 2 === 0 && !(FAMILY_EVENTS[fi].id === 'fathers' && !c.children?.length) ? FAMILY_EVENTS[fi] : undefined
  if (fe && !c.talks.some((t) => t.id.startsWith('fam:'))) {
    const p = careerPlayer(state)
    p.condition = clamp(p.condition + fe.condition, 5, 95)
    c.bonds[c.spouse] = clamp((c.bonds[c.spouse] ?? 0) + fe.bond, 0, 100)
    c.talks.push({ id: `fam:${fe.id}:${state.season}`, speaker: c.spouse })
  }
}

/** 子どもの選択（8 歳「バスケ、やってみたい」） */
export function setChildPlays(state: GameState, index: number, plays: boolean) {
  const ch = state.career!.children?.[index]
  if (ch) ch.plays = plays
}

export const childPlaysLabel = (plays?: boolean) => (plays ? 'バスケをしている' : plays === false ? 'ほかの道を歩いている' : '')

// ---------------------------------------------------------------- 社会貢献

export function setFoundation(state: GameState, level: number) {
  const c = state.career!
  c.foundation = clamp(level, 0, 3)
}

export function canDonate(state: GameState, id: string): string | null {
  const c = state.career!
  const d = DONATIONS.find((x) => x.id === id)
  if (!d) return 'ない'
  if (c.donations?.includes(id)) return '寄付した'
  if (c.money < d.cost) return '貯金が足りない'
  return null
}

export function donate(state: GameState, id: string): boolean {
  if (canDonate(state, id)) return false
  const c = state.career!
  const d = DONATIONS.find((x) => x.id === id)!
  c.money -= d.cost
  c.donated = (c.donated ?? 0) + d.cost
  c.donations = [...(c.donations ?? []), id]
  c.fame = clamp(c.fame + d.fame, 0, 100)
  c.talks.push({ id: `donate:${id}`, speaker: 'todo_maiko' })
  news(state, `${d.name}に ${(d.cost / 10000).toLocaleString()} 億円を寄付した`, d.cost >= 100000)
  return true
}

/** 社会貢献の点（総括）: 一度きりの寄付の点 ＋ 財団の通算 10 億円ごとに 1（合わせて 30 まで） */
export function legacyPoints(state: GameState): number {
  const c = state.career!
  const once = (c.donations ?? []).reduce((s, id) => s + (DONATIONS.find((x) => x.id === id)?.legacy ?? 0), 0)
  const onceCost = (c.donations ?? []).reduce((s, id) => s + (DONATIONS.find((x) => x.id === id)?.cost ?? 0), 0)
  return Math.min(30, once + Math.floor(Math.max(0, (c.donated ?? 0) - onceCost) / 100000))
}

// ---------------------------------------------------------------- 毎週・シーズンの終わり（week.ts から）

/** 週の終わり（careerAfterWeek から） */
export function lifePlusWeek(state: GameState, played: { seasonEnded: boolean }) {
  const c = state.career
  if (!c || c.retiredAt !== undefined) return
  bizWeek(state)
  hobbyWeek(state)
  mediaWeek(state)
  partnerEventWeek(state)
  familyWeek(state)
  if (played.seasonEnded) {
    bizSeasonEnd(state)
    tripSeasonEnd(state)
  }
}

