export interface GeneratedName {
  full: string
  /** 試合中の表示などに使う短い名前（日本人は姓、外国人はファミリーネーム） */
  short: string
}

/** 日本の姓と名の候補（キャリアの主人公の名前をランダムに決めるとき） */
export function jpNamePool(): { family: string[]; given: string[] } {
  return { family: BANK.JP.family, given: BANK.JP.given }
}

export function generateName(nation: Nation, rng: Rng): GeneratedName {
  const b = BANK[nation]
  const family = rng.pick(b.family)
  const given = rng.pick(b.given)
  if (b.familyFirst) return { full: nation === 'JP' ? `${family} ${given}` : `${family}・${given}`, short: family }
  return { full: `${given}・${family}`, short: family }
}

/** 写真の系統（tools/gen の pool の系統）。選手の国籍から決める */
export type FaceGroup = 'black' | 'white' | 'euro' | 'latin' | 'africa' | 'east' | 'mixed'

export function faceGroupOf(nation: Nation, rng: Rng): FaceGroup {
  switch (nation) {
    case 'US':
    case 'CA':
      return rng.chance(0.68) ? 'black' : 'white'
    case 'AU':
      return 'white'
    case 'JP':
      return rng.chance(0.08) ? 'mixed' : 'east'
    case 'KR':
    case 'CN':
    case 'PH':
      return 'east'
    case 'BR':
    case 'AR':
    case 'MX':
    case 'DO':
    case 'PR':
    case 'VE':
      return 'latin'
    case 'NG':
    case 'CM':
    case 'SN':
    case 'SS':
    case 'CD':
    case 'ML':
      return 'africa'
    case 'FR':
      return rng.chance(0.45) ? 'africa' : 'euro'
    default:
      return 'euro'
  }
}

