/**
 * 近くの街でもホームの試合を開く（ホームタウンを広げる。2026-11-14、ユーザーの「都市の規模で決まるならホームタウンを複数にする構造に」）。
 *   2 部で 1 つ、1 部で 2 つまで（降格しても開いている街はそのまま。足せないだけ）。NBA では効き目も会場費もない。
 *   開く費用は 1 つ目 5,000 万円・2 つ目 1 億円（工事費として帳簿に）。毎年の会場費は維持費に入る（manage.ts の upkeepOf）。
 *   効き目（fans.ts）: ファンの天井 ＋その街の人口の 15%、スポンサーの相場は人口の半分として数える。開いたときにその街から少しファンが来る。
 *   やめるのはいつでも（費用は戻らない）。天井を超えたぶんのファンは少しずつ減る。
 */
import { HOMETOWN_BY_ID, SUB_TOWNS, SUB_TOWN_FEES, SUB_TOWN_SLOTS } from '../data/club'
import type { GameState } from '../models/game'
import { addFans, subTownFans } from './fans'
import { clubTeam, currentLedger } from './manage'

/** 今の部で開ける数 */
export const subTownSlots = (state: GameState) => SUB_TOWN_SLOTS[clubTeam(state).league] ?? 0

/** 次に開くときの費用（万円） */
export const subTownFee = (state: GameState) => SUB_TOWN_FEES[Math.min(SUB_TOWN_FEES.length - 1, state.club!.subTowns?.length ?? 0)]

/** 開けない理由（開けるなら null） */
export function subTownProblem(state: GameState, id: string): string | null {
  const c = state.club!
  const lg = clubTeam(state).league
  if (lg === 'NBA') return 'NBA では日本じゅうから応援される'
  if (!(SUB_TOWNS[c.hometown] ?? []).some((t) => t.id === id)) return 'ホームタウンの近くの街ではない'
  const open = c.subTowns ?? []
  if (open.includes(id)) return 'もう開いている'
  const slots = subTownSlots(state)
  if (open.length >= slots) return slots === 0 ? '2 部に上がると開ける' : open.length === 1 && lg === 'JBL2' ? '2 つ目は 1 部に上がってから' : 'これ以上は開けない'
  if (c.money < subTownFee(state)) return '資金が足りない'
  return null
}

/** 開く（費用を払う） */
export function openSubTown(state: GameState, id: string): string | null {
  const why = subTownProblem(state, id)
  if (why) return why
  const c = state.club!
  const t = SUB_TOWNS[c.hometown].find((x) => x.id === id)!
  const fee = subTownFee(state)
  c.money -= fee
  currentLedger(state).build += fee
  c.subTowns = [...(c.subTowns ?? []), id]
  // その街から、少しファンが来る（天井の 1 割）
  addFans(state, 1, Math.round(subTownFans(t) * 0.1))
  c.popularity = Math.min(100, c.popularity + 1)
  state.news.push({ season: state.season, week: state.week, text: `${t.city}でもホームの試合を開くことになった（${clubTeam(state).short}のホームタウンが広がった）`, big: true })
  return null
}

/** やめる（費用は戻らない） */
export function closeSubTown(state: GameState, id: string) {
  const c = state.club!
  const t = (SUB_TOWNS[c.hometown] ?? []).find((x) => x.id === id)
  c.subTowns = (c.subTowns ?? []).filter((x) => x !== id)
  if (t) state.news.push({ season: state.season, week: state.week, text: `${t.city}でのホームの試合をやめた` })
}

// ---------------------------------------------------------------- 移転（ホームタウンを別の街へ移す）

/**
 * 移転（2026-11-14、ユーザーの「移転も残したい」）: 12 のホームタウンのどれかへ。決めたときに移転費を払い、シーズンの終わりに移る（取り消せば戻る）。
 *   代償（重め）: ファンは 3 割だけ残る・人気 −15・オーナーの信頼 −20。アリーナの席数はそのまま（名前は新しい街の体育館に）。近くの街はやめる。
 *   NBA のチームと、NBA への参入を申請しているあいだは移転できない。オーナーの信頼が 20 以下ならできない（移転で解任にはしない）
 */
export const RELOCATION = { fee: 20000, fanKeep: 0.3, pop: 15, trust: 20 }

export function relocationProblem(state: GameState, to: string): string | null {
  const c = state.club!
  if (clubTeam(state).league === 'NBA') return 'NBA のチームは移転できない'
  if (c.nba) return 'NBA への参入を申請している'
  if (!HOMETOWN_BY_ID[to]) return 'ホームタウンの候補ではない'
  if (to === c.hometown) return 'いまのホームタウン'
  if (c.relocation) return 'もう移転を決めている'
  if (c.owner.trust <= RELOCATION.trust) return `オーナーの信頼が足りない（${RELOCATION.trust + 1} から）`
  if (c.money < RELOCATION.fee) return '資金が足りない'
  return null
}

/** 移転を決める（移転費を払う。移るのはシーズンの終わり） */
export function planRelocation(state: GameState, to: string): string | null {
  const why = relocationProblem(state, to)
  if (why) return why
  const c = state.club!
  c.money -= RELOCATION.fee
  currentLedger(state).other -= RELOCATION.fee
  c.relocation = { to, fee: RELOCATION.fee }
  state.news.push({ season: state.season, week: state.week, text: `${clubTeam(state).short}は、シーズンの終わりに${HOMETOWN_BY_ID[to].city}へ移転することを決めた`, big: true })
  return null
}

/** 移転を取り消す（移転費は戻る） */
export function cancelRelocation(state: GameState) {
  const c = state.club!
  if (!c.relocation) return
  c.money += c.relocation.fee
  currentLedger(state).other += c.relocation.fee
  state.news.push({ season: state.season, week: state.week, text: `${HOMETOWN_BY_ID[c.relocation.to].city}への移転を取り消した` })
  delete c.relocation
}

/** シーズンの終わりに移る（clubSeasonEnd から、オーナーの評価のあと）。記録に残す一言を返す */
export function applyRelocation(state: GameState): string | null {
  const c = state.club!
  const r = c.relocation
  if (!r) return null
  delete c.relocation
  const team = clubTeam(state)
  const from = HOMETOWN_BY_ID[c.hometown]
  const to = HOMETOWN_BY_ID[r.to]
  if (!to || c.gameOver || team.league === 'NBA') return null
  c.hometown = to.id
  c.subTowns = []
  c.fans = Math.max(500, Math.round(c.fans * RELOCATION.fanKeep))
  c.popularity = Math.max(1, c.popularity - RELOCATION.pop)
  c.owner.trust = Math.max(1, c.owner.trust - RELOCATION.trust)
  team.city = to.city
  team.name = `${to.city}・${team.nickname}`
  team.abbr = to.id.slice(0, 3).toUpperCase()
  team.arena.name = team.arena.name.includes('アリーナ') ? `${to.city}アリーナ` : `${to.city}市総合体育館`
  state.news.push({ season: state.season, week: state.week, text: `${from.city}から${to.city}へ移転した。新しいチーム名は「${team.name}」`, big: true })
  return `${from.city}から${to.city}へ移転`
}
