/**
 * 選手を作る。能力はポジションの重み・プレースタイル・体格で形を決め、総合値が狙いの値になるようにずらす。
 * 乱数はすべて渡された rng（シード付き）から。
 */
import type { Rng } from '../core/prng'
import { WEEKS_PER_SEASON, absWeekOf } from '../core/calendar'
import { ATTR_KEYS, type Attrs, emptyAttrs } from '../data/attributes'
import { GROWTH_TYPES, type GrowthType } from '../data/growth'
import { faceGroupOf, generateName, type Nation } from '../data/nations'
import { PERSONALITIES } from '../data/personality'
import { ADJACENT, POSITIONS, type Position } from '../data/positions'
import { SKILL_DEFS, SKILL_IDS, type SkillId } from '../data/skills'
import { PLAY_STYLES, PLAY_STYLE_DEFS, type PlayStyle } from '../data/styles'
import { allocId, type GameState } from '../models/game'
import { emptyStats, type Contract, type Player } from '../models/player'
import { applyBias, bodyBias, posHeight, typicalWeight, TYPICAL_REACH } from '../player/body'
import { POS_WEIGHTS, heightFit, rawOvr } from '../player/overall'

export interface GenOptions {
  nation: Nation
  age: number
  pos?: Position
  style?: PlayStyle
  /** 狙いの総合値 */
  ovr: number
  /** 将来の総合値の上限（省略時は年齢から） */
  pot?: number
  /** 伸びしろの倍率（下の部の選手は小さく） */
  potMul?: number
  teamId?: number
  contract?: Contract
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** ポジションに合うプレースタイルを選ぶ */
export function pickStyle(pos: Position, rng: Rng): PlayStyle {
  const cands = PLAY_STYLES.filter((s) => PLAY_STYLE_DEFS[s].positions.includes(pos))
  const w = cands.map((s) => (PLAY_STYLE_DEFS[s].positions[0] === pos ? 2 : 1))
  return cands[rng.weighted(w)]
}

/** 身長の平均のずれ（国ごと。日本人は小柄） */
function heightShift(nation: Nation): number {
  if (nation === 'JP' || nation === 'KR' || nation === 'PH') return -5
  if (nation === 'CN') return -2
  if (nation === 'SS' || nation === 'SN' || nation === 'CD' || nation === 'ML') return 2
  return 0
}

function reachShift(nation: Nation): number {
  if (nation === 'JP' || nation === 'KR' || nation === 'PH' || nation === 'CN') return -3
  if (['NG', 'CM', 'SN', 'SS', 'CD', 'ML'].includes(nation)) return 4
  return 0
}

/** 体格を決める */
export function rollBody(pos: Position, nation: Nation, rng: Rng): { heightCm: number; wingspanCm: number; weightKg: number } {
  const heightCm = Math.round(clamp(rng.normal(posHeight(pos) + heightShift(nation), 3.6), 168, 229))
  const wingspanCm = Math.round(heightCm + rng.normal(TYPICAL_REACH + reachShift(nation), 4))
  const weightKg = Math.round(typicalWeight(heightCm, pos) + rng.normal(0, 5))
  return { heightCm, wingspanCm, weightKg }
}

/** 能力の形（ポジションの重み・スタイル・体格・ゆらぎ）を作り、総合値を target に合わせる */
export function shapeAttrs(target: number, pos: Position, style: PlayStyle, body: { heightCm: number; wingspanCm: number; weightKg: number }, rng: Rng, spread = 1): Attrs {
  const w = POS_WEIGHTS[pos]
  const maxW = Math.max(...ATTR_KEYS.map((k) => w[k]))
  const a = emptyAttrs()
  for (const k of ATTR_KEYS) a[k] = target + (w[k] / maxW - 0.45) * 28 * spread + rng.normal(0, 5.5)
  applyBias(a, PLAY_STYLE_DEFS[style].boost)
  applyBias(a, bodyBias(body.heightCm, body.wingspanCm, body.weightKg, pos))
  fitOvr(a, target, pos, body.heightCm)
  return a
}

/** 全体をずらして、総合値をちょうど target にする（上下の端で切れる分を何回かでならす） */
export function fitOvr(a: Attrs, target: number, pos: Position, heightCm: number) {
  for (let i = 0; i < 6; i++) {
    const diff = target - (rawOvr(a, pos) + heightFit(heightCm, pos))
    if (Math.abs(diff) < 0.3) break
    for (const k of ATTR_KEYS) a[k] = clamp(a[k] + diff, 12, 99)
  }
  for (const k of ATTR_KEYS) a[k] = Math.round(clamp(a[k], 12, 99))
}

/** 年齢から伸びしろ（将来の総合値の上限）を決める */
export function rollPotential(ovr: number, age: number, rng: Rng): number {
  // 伸びしろは小さめに偏らせる（大きく伸びる選手はひと握り）
  const r = rng.next() ** 1.7
  const room = age <= 19 ? 6 + r * 26 : age <= 22 ? 3 + r * 18 : age <= 25 ? 1 + r * 8 : age <= 28 ? r * 3 : 0
  return Math.round(clamp(ovr + room, ovr, 97))
}

const GROWTH_WEIGHTS = [8, 20, 44, 20, 8]

/** 特殊能力: 総合値が高いほど多く、能力に合うものから */
export function rollSkills(a: Attrs, ovr: number, rng: Rng): SkillId[] {
  const n = ovr >= 86 ? rng.int(3, 5) : ovr >= 78 ? rng.int(2, 3) : ovr >= 68 ? rng.int(1, 2) : ovr >= 58 ? rng.int(0, 1) : rng.chance(0.25) ? 1 : 0
  const fit: Partial<Record<SkillId, number>> = {
    sniper: a.three, deepRange: a.three - 6, catchShoot: a.three, midMaster: a.mid, ftMaster: a.ft,
    posterizer: a.dunk, acrobat: a.layup, andOne: (a.layup + a.strength) / 2, postMoves: a.post, floater: a.layup - 4,
    ankleBreaker: a.handle, floorGeneral: (a.pass + a.iq) / 2, dimer: a.vision, ballSecurity: a.handle - 3, pnrMaster: (a.pass + a.handle) / 2,
    lockdown: a.perD, rimGuard: a.block, thief: a.steal, helpD: (a.iq + a.intD) / 2, chargeTaker: a.iq - 5,
    reboundKing: (a.oreb + a.dreb) / 2, boxOut: a.dreb - 3, putback: a.oreb,
    clutchShooter: a.clutch, iceVeins: a.clutch - 4, ironMan: a.stamina - 5, sixthMan: 60, leader: a.iq - 5, transition: a.speed, bigGame: a.clutch - 6,
  }
  const good = SKILL_IDS.filter((s) => !SKILL_DEFS[s].bad)
  const out: SkillId[] = []
  for (let i = 0; i < n; i++) {
    const cands = good.filter((s) => !out.includes(s))
    const w = cands.map((s) => Math.max(0.1, (fit[s] ?? 50) - 55) ** 2)
    out.push(cands[rng.weighted(w)])
  }
  if (rng.chance(0.08)) out.push(rng.pick(SKILL_IDS.filter((s) => SKILL_DEFS[s].bad)))
  return out
}

/** 選手を作って state.players に入れる（チームの roster には入れない。呼ぶ側で） */
export function generatePlayer(state: GameState, rng: Rng, o: GenOptions): Player {
  const pos = o.pos ?? POSITIONS[rng.weighted([21, 21, 20, 19, 19])]
  const style = o.style ?? pickStyle(pos, rng)
  const body = rollBody(pos, o.nation, rng)
  const target = clamp(o.ovr, 25, 97)
  const attr = shapeAttrs(target, pos, style, body, rng)
  const name = generateName(o.nation, rng)
  // 誕生日: 今のシーズンのはじめで age 歳になっている（週はばらす）
  const birthAbs = absWeekOf(state.season, state.week) - o.age * WEEKS_PER_SEASON - rng.int(0, WEEKS_PER_SEASON - 1)
  const growth: GrowthType = GROWTH_TYPES[rng.weighted(GROWTH_WEIGHTS)]
  const p: Player = {
    id: allocId(state),
    name: name.full,
    short: name.short,
    nation: o.nation,
    birthAbs,
    pos,
    pos2: rng.chance(0.55) ? rng.pick(ADJACENT[pos]) : undefined,
    style,
    ...body,
    attr,
    pot: o.pot ?? Math.round(target + (rollPotential(target, o.age, rng) - target) * (o.potMul ?? 1)),
    growth,
    personality: rng.pick(PERSONALITIES),
    skills: rollSkills(attr, target, rng),
    teamId: o.teamId ?? -1,
    contract: o.contract ?? { salary: 0, years: 0, kind: 'none' },
    jersey: 0,
    condition: rng.int(40, 60),
    fatigue: 0,
    morale: rng.int(55, 75),
    stats: emptyStats(),
    history: [],
    faceGroup: faceGroupOf(o.nation, rng),
  }
  state.players[p.id] = p
  return p
}
