/**
 * ゲーム全体の状態（セーブの単位）。mutable なプレーンオブジェクトで、Zustand は参照と version だけを持つ。
 */
import type { Player } from './player'
import type { Fixture, League, LeagueId, Team } from './league'
import type { CareerState } from './career'
import type { ClubState } from './club'
import type { CupRecord, CupState } from '../competition/cup'
import type { EaccRecord, EaccState } from '../competition/eacc'

export const SCHEMA_VERSION = 3

export type GameMode = 'career' | 'club'

export interface NewsItem {
  season: number
  week: number
  text: string
  /** 大事なニュース（ホームで目立たせる） */
  big?: boolean
}

/** プレーオフのシリーズ（NBA 7 戦 4 勝・国内 3 戦 2 勝・大学とプレーインは 1 試合） */
export interface Series {
  id: number
  league: LeagueId
  /** 回戦（プレーインは 0、NBA は 1〜4、国内は 1〜3、大学は 1〜4） */
  round: number
  name: string
  /** 上位（ホームの有利）と下位のチーム */
  hi: number
  lo: number
  wins: [number, number]
  bestOf: number
  /** NBA のカンファレンス（ファイナルはなし） */
  conf?: string
  /** 中立地（大学の選手権） */
  neutral?: boolean
  winner?: number
  /** 行った試合の数 */
  played: number
  /** プレーインの組（7v8・9v10・最後） */
  slot?: string
}

export interface AwardRecord {
  season: number
  league: LeagueId
  award: string
  playerId: number
  name: string
  teamName: string
  /** 成績のひとこと（「平均 28.4 点」など） */
  line: string
}

export interface ChampionRecord {
  season: number
  league: LeagueId
  teamId: number
  teamName: string
  runnerUp?: string
}

export interface GameState {
  schemaVersion: number
  mode: GameMode
  /** ワールドの乱数の種 */
  seed: number
  /** 最初のシーズンの西暦（7 月の年） */
  startYear: number
  /** 何シーズン目か（0 から） */
  season: number
  /** シーズンの中の週（0-51） */
  week: number
  /** ID の採番（モジュール変数のカウンタを作らない）。選手・日程・ニュースなどで共通 */
  nextId: number
  players: Record<number, Player>
  /** 添字 = チームの id（チームは消さない） */
  teams: Team[]
  leagues: Record<LeagueId, League>
  /** 今季の日程（全リーグ） */
  fixtures: Fixture[]
  /** 今季のプレーオフ */
  series: Series[]
  news: NewsItem[]
  awards: AwardRecord[]
  champions: ChampionRecord[]
  /** 今年のドラフトの候補（選手 id） */
  draftPool: number[]
  /** ドラフトの結果（その年の分。指名順に） */
  draftLog: { pick: number; round: number; teamId: number; playerId: number; name: string }[]
  /** キャリアモード */
  career?: CareerState
  /** クラブ経営モード */
  club?: ClubState
  /** 全日本選手権（今季）と歴代の決勝 */
  cup?: CupState
  cupHistory?: CupRecord[]
  /** 東アジアのクラブ選手権（今季）・次のシーズンの出場権・歴代の優勝 */
  eacc?: EaccState
  eaccQual?: { season: number; teams: number[] }
  eaccHistory?: EaccRecord[]
  /** はじめの一歩（ホームの案内）: 済んだ手順・閉じたか */
  tutorial?: { done: string[]; closed?: boolean }
}

/** はじめの一歩の手順を済ませたことにする */
export function markStep(state: GameState, id: string) {
  const t = (state.tutorial ??= { done: [] })
  if (!t.done.includes(id)) t.done.push(id)
}

/** id を 1 つ取る */
export function allocId(state: GameState): number {
  return state.nextId++
}
