/** 順位表。勝率 → 得失点差 → 勝ち数の順に並べる。 */
import type { GameState } from '../models/game'
import { emptyStanding, type GameResult, type League, type LeagueId, type Standing } from '../models/league'

export function winPct(s: Standing): number {
  const g = s.w + s.l
  return g ? s.w / g : 0
}

/** 並べた team id（teamIds を省略するとリーグ全体） */
export function sortedStandings(league: League, teamIds: number[] = league.teamIds): number[] {
  return [...teamIds].sort((a, b) => {
    const sa = league.standings[a] ?? emptyStanding()
    const sb = league.standings[b] ?? emptyStanding()
    return winPct(sb) - winPct(sa) || sb.pf - sb.pa - (sa.pf - sa.pa) || sb.w - sa.w || a - b
  })
}

/** 順位（1 から） */
export function rankIn(league: League, teamId: number, teamIds?: number[]): number {
  return sortedStandings(league, teamIds).indexOf(teamId) + 1
}

/** ゲーム差（首位との） */
export function gamesBehind(lead: Standing, s: Standing): number {
  return (lead.w - s.w + (s.l - lead.l)) / 2
}

/** 試合の結果を順位表に入れる（レギュラーシーズンだけ） */
export function recordResult(state: GameState, league: LeagueId, home: number, away: number, r: GameResult) {
  const lg = state.leagues[league]
  const h = (lg.standings[home] ??= emptyStanding())
  const a = (lg.standings[away] ??= emptyStanding())
  const homeWin = r.hs > r.as
  const sameConf = state.teams[home].conf !== undefined && state.teams[home].conf === state.teams[away].conf
  h.pf += r.hs
  h.pa += r.as
  a.pf += r.as
  a.pa += r.hs
  if (homeWin) {
    h.w++
    h.hw++
    a.l++
    a.al++
    if (sameConf) {
      h.cw++
      a.cl++
    }
    h.streak = h.streak > 0 ? h.streak + 1 : 1
    a.streak = a.streak < 0 ? a.streak - 1 : -1
  } else {
    a.w++
    a.aw++
    h.l++
    h.hl++
    if (sameConf) {
      a.cw++
      h.cl++
    }
    a.streak = a.streak > 0 ? a.streak + 1 : 1
    h.streak = h.streak < 0 ? h.streak - 1 : -1
  }
}
