/**
 * クラブ経営モードの始まり: ワールドを作り、国内 3 部のいちばん格の低いクラブと入れ替えて、自分のクラブを置く。
 *   ロスターは 3 部の下のほうの水準で作り直す（前のクラブの選手は所属なしへ）。アリーナは市の体育館（1,500 席・格 1）
 *   スタッフ（HC・アシスタント・S&C）は安い人で始まり、胸のスポンサーが 1 社ついている
 */
import { createRng, hashSeed } from '../core/prng'
import { CLUB_COLORS, DIFFICULTY_DEFS, HOMETOWN_BY_ID, staffSalary } from '../data/club'
import { EXP_KINDS } from '../data/career'
import { generateName } from '../data/nations'
import { assignJerseys, createWorld, fillJbl } from '../gen/worldGen'
import type { ClubState, Staff, StaffRole } from '../models/club'
import type { GameState } from '../models/game'
import { assignPhotos } from '../player/photos'
import { releasePlayer } from '../transfer/freeAgency'
import { makeSponsorOffers, sponsorValue } from './manage'
import { youthIntake } from './transfer'
import { setOwnerGoal } from './week'
import { storySeasonStart } from './story'

export interface ClubNewOptions {
  seed: number
  hometown: string
  nickname: string
  colors: [string, string]
  difficulty: ClubState['difficulty']
}

export function createClubGame(o: ClubNewOptions): GameState {
  const state = createWorld({ seed: o.seed, mode: 'club' })
  const rng = createRng(hashSeed(o.seed, 0xc10b))
  const town = HOMETOWN_BY_ID[o.hometown]
  // いちばん格の低い 3 部のクラブと入れ替える（日程はそのまま使える）
  const team = state.leagues.JBL3.teamIds.map((id) => state.teams[id]).sort((a, b) => a.rep - b.rep || a.id - b.id)[0]
  for (const id of [...team.roster]) releasePlayer(state, state.players[id])
  team.city = town.city
  team.nickname = o.nickname
  team.name = `${town.city}・${o.nickname}`
  team.short = o.nickname
  team.abbr = o.hometown.slice(0, 3).toUpperCase()
  team.colors = { primary: o.colors[0], secondary: o.colors[1] }
  team.rep = 30
  team.arena = { name: `${town.city}市総合体育館`, capacity: 1500 }
  fillJbl(state, team, rng)
  assignJerseys(state, team, rng)

  const staff = (role: StaffRole, skill: number, note: string): Staff => ({ name: generateName('JP', rng).full, role, skill, salary: staffSalary(role, skill), years: 2, note })
  const hc = staff('hc', 46, '地元出身の熱血監督')
  team.coach = { name: hc.name, skill: hc.skill }
  const club: ClubState = {
    teamId: team.id,
    hometown: o.hometown,
    money: DIFFICULTY_DEFS[o.difficulty].money,
    fans: Math.round(1500 + town.pop * 40),
    popularity: 10 + town.passion * 2,
    arenaGrade: 1,
    facilities: { training: 0, medical: 0, analysis: 0, pr: 0, youth: 0 },
    building: [],
    staff: { hc, asst: staff('asst', 40, '若手の面倒見がいい'), sc: staff('sc', 40, '回復の方法に詳しい'), scout: staff('scout', 35, '地元の高校をよく見ている') },
    sponsors: [],
    sponsorOffers: [],
    training: { intensity: 1, focus: Object.fromEntries(EXP_KINDS.map((k) => [k, 2])) as ClubState['training']['focus'] },
    ledger: [],
    negWeeks: 0,
    bailouts: 0,
    difficulty: o.difficulty,
    history: [],
    seen: [],
    youth: [],
    scouted: [],
    talks: {},
    bids: [],
    owner: { trust: 60 },
    legends: [],
    youthGrads: [],
    rookies: [],
  }
  state.club = club
  // 地元の会社が胸のスポンサーに（相場より少し安く、1 年）
  club.sponsors.push({ slot: 'main', company: `${town.city}信用金庫`, annual: Math.round((sponsorValue(state, 'main') * 0.8) / 10) * 10, until: 0 })
  makeSponsorOffers(state)
  youthIntake(state)
  setOwnerGoal(state)
  assignPhotos(state, team.id)
  // 最初のシーズン: オーナーの目標と HC の見立て（会話の場面）
  storySeasonStart(state)
  state.news.push({ season: 0, week: 0, text: `新しいクラブ「${team.name}」が${state.leagues.JBL3.name}に加わった`, big: true })
  return state
}

export const DEFAULT_CLUB_COLORS = CLUB_COLORS[0]
