export const FACILITY_MAX = 5

export function facilityCost(id: FacilityId, to: number): number {
  return Math.round((FACILITY_DEFS[id].base * to ** 1.5) / 10) * 10
}

export function facilityWeeks(to: number): number {
  return 4 + to * 2
}

