/** スタッフの年俸の相場（万円/年） */
export function staffSalary(role: StaffRole, skill: number): number {
  const base = 300 + Math.max(0, skill - 40) ** 2 * 1.2
  return Math.round((base * (role === 'hc' ? 1 : role === 'scout' ? 0.45 : 0.55)) / 10) * 10
}

