/**
 * キャリアモードを始める: ワールドを作り、主人公（18 歳・高校を出たところ）を置き、入団と奨学金の話を 3 つずつ用意する。
 * 主人公の能力はポジション・プレースタイル・体格から決める（作成画面の見込みと同じ式。乱数は決まった種から）。
 */
import { createRng, hashSeed } from '../core/prng'
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import type { Attrs } from '../data/attributes'
import { EXP_KINDS, type ActionId } from '../data/career'
import { GROWTH_TYPES, type GrowthType } from '../data/growth'
import type { Position } from '../data/positions'
import type { PlayStyle } from '../data/styles'
import { createWorld } from '../gen/worldGen'
import { shapeAttrs } from '../gen/playerGen'
import { allocId, type GameState } from '../models/game'
import type { CareerOffer, CareerPath, CareerState } from '../models/career'
import { emptyStats, type Player } from '../models/player'
import { ovr } from '../player/overall'
import { jblMarketSalary } from '../economy/salary'
import { signPlayer } from '../transfer/freeAgency'
import { assignPhotos } from '../player/photos'
import { pushHeirTalk } from './heir'

export interface CareerNewOptions {
  seed: number
  name: string
  pos: Position
  style: PlayStyle
  heightCm: number
  wingspanCm: number
  weightKg: number
  growth: GrowthType | 'auto'
  growthMode: 'easy' | 'careful'
  /** 顔の写真（tools/gen の protag の id） */
  photo?: string
}

/** 主人公の最初の総合値（高校を出た 18 歳の有望株） */
export const START_OVR = 47

/** 作成画面の見込みと同じ能力（決まった種で形を作る） */
export function protagonistAttrs(o: Pick<CareerNewOptions, 'pos' | 'style' | 'heightCm' | 'wingspanCm' | 'weightKg'>): Attrs {
  const rng = createRng(hashSeed(1801, o.pos.charCodeAt(0), o.style.length))
  return shapeAttrs(START_OVR, o.pos, o.style, { heightCm: o.heightCm, wingspanCm: o.wingspanCm, weightKg: o.weightKg }, rng, 0.85)
}

/** 練習の予定（おまかせ）の既定: プレースタイルの得意 2 つとフィジカル */
export const DEFAULT_PLAN: Record<PlayStyle, ActionId[]> = {
  playmaker: ['handling', 'film', 'shooting', 'physical'],
  scorer: ['shooting', 'handling', 'shooting', 'physical'],
  threeD: ['shooting', 'defense', 'shooting', 'physical'],
  slasher: ['handling', 'physical', 'shooting', 'handling'],
  allround: ['shooting', 'defense', 'handling', 'physical'],
  stretchBig: ['shooting', 'inside', 'defense', 'physical'],
  postScorer: ['inside', 'physical', 'inside', 'defense'],
  rimProtector: ['defense', 'inside', 'physical', 'defense'],
}

export function createCareerGame(o: CareerNewOptions): GameState {
  const state = createWorld({ seed: o.seed, mode: 'career' })
  const rng = createRng(hashSeed(o.seed, 7707))
  const p = addProtagonist(state, o, absWeekOf(0, 0) - 18 * WEEKS_PER_SEASON - 10, rng)
  state.career = newCareerState(p, o)
  // 幼なじみ・恩師・親友とは最初から顔見知り
  state.career.bonds = { haruno_hikari: 30, kuroda_takeshi: 40, murakami_daichi: 40, todo_maiko: 15, kanzaki_leo: 10 }
  makeRookieOffers(state, rng)
  assignPhotos(state)
  return state
}

/** 主人公の選手を世界に置く（所属なし。二代目も同じ） */
export function addProtagonist(state: GameState, o: Omit<CareerNewOptions, 'seed'>, birthAbs: number, rng: ReturnType<typeof createRng>): Player {
  const growth: GrowthType = o.growth === 'auto' ? GROWTH_TYPES[rng.weighted([8, 20, 44, 20, 8])] : o.growth
  const attr = protagonistAttrs(o)
  const p: Player = {
    id: allocId(state),
    name: o.name,
    // 姓（空白で区切る。JS の \s は全角の空白も含む）
    short: o.name.split(/\s+/)[0] || o.name,
    nation: 'JP',
    birthAbs,
    pos: o.pos,
    style: o.style,
    heightCm: o.heightCm,
    wingspanCm: o.wingspanCm,
    weightKg: o.weightKg,
    attr,
    pot: 99,
    growth,
    personality: 'effort',
    skills: [],
    teamId: -1,
    contract: { salary: 0, years: 0, kind: 'none' },
    jersey: 0,
    condition: 60,
    fatigue: 0,
    morale: 70,
    stats: emptyStats(),
    history: [],
    faceGroup: 'east',
    photo: o.photo,
    isPlayer: true,
  }
  state.players[p.id] = p
  return p
}

/** 新しいキャリアの状態（入団の話はまだ） */
export function newCareerState(p: Player, o: Pick<CareerNewOptions, 'growthMode' | 'style'>): CareerState {
  return {
    playerId: p.id,
    money: 50,
    fame: 5,
    trust: 45,
    nbaInterest: 3,
    exp: Object.fromEntries(EXP_KINDS.map((k) => [k, 0])) as Record<(typeof EXP_KINDS)[number], number>,
    growthMode: o.growthMode,
    focus: Object.fromEntries(EXP_KINDS.map((k) => [k, 1])) as Record<(typeof EXP_KINDS)[number], number>,
    autoPlan: [...DEFAULT_PLAN[o.style]],
    offers: [],
    bonds: {},
    met: ['kuroda_takeshi', 'haruno_hikari', 'murakami_daichi', 'kanzaki_leo', 'todo_maiko'],
    seen: [],
    talks: [{ id: 'intro', speaker: 'todo_maiko' }],
    log: [],
    moments: { tried: 0, won: 0 },
  }
}

const ROLE_PITCH: Record<CareerOffer['role'], string> = {
  star: '君を中心にチームを作りたい。1 年目から主役だ',
  starter: '1 年目からスタメンとして使うつもりだ',
  rotation: 'ローテーションの一員として、しっかり出場時間をあげよう',
  bench: '最初はベンチからだが、力を見せればすぐに出番は増える',
}

/** 18 歳の入団・奨学金の話（国内 3・大学 3） */
export function makeRookieOffers(state: GameState, rng: ReturnType<typeof createRng>) {
  const c = state.career!
  const p = state.players[c.playerId]
  const o = ovr(p)
  const pickTeam = (league: 'JBL1' | 'JBL2' | 'JBL3' | 'NCAA', filter: (rep: number) => boolean) => {
    const cands = state.leagues[league].teamIds.filter((id) => filter(state.teams[id].rep) && !c.offers.some((x) => x.teamId === id))
    const list = cands.length ? cands : state.leagues[league].teamIds
    // 同じポジションの選手が少ないチームほど声をかけてくる
    const w = list.map((id) => 1 / (1 + state.teams[id].roster.filter((pid) => state.players[pid].pos === p.pos).length))
    return list[rng.weighted(w)]
  }
  const add = (kind: CareerOffer['kind'], teamId: number, role: CareerOffer['role'], salary: number, years: number) => {
    c.offers.push({ id: allocId(state), kind, teamId, role, salary, years, pitch: ROLE_PITCH[role] })
  }
  // 国内: 1 部はベンチから、2 部はローテーション、3 部はスタメン
  add('rookie', pickTeam('JBL1', () => true), 'bench', jblMarketSalary(o, false, 'JBL1') + 100, 3)
  add('rookie', pickTeam('JBL2', () => true), 'rotation', jblMarketSalary(o, false, 'JBL2') + 80, 3)
  add('rookie', pickTeam('JBL3', () => true), 'starter', jblMarketSalary(o, false, 'JBL3') + 60, 2)
  // 大学: 強豪はベンチから、中堅はローテーション、そのほかはスタメン
  add('college', pickTeam('NCAA', (r) => r >= 74), 'bench', 0, 4)
  add('college', pickTeam('NCAA', (r) => r >= 60 && r < 74), 'rotation', 0, 4)
  add('college', pickTeam('NCAA', (r) => r < 60), 'starter', 0, 4)
}

/** 話を受ける（入団・入学）。最初の話を受けると、もう一方の進路の話は消える */
export function acceptOffer(state: GameState, offerId: number) {
  const c = state.career!
  const off = c.offers.find((x) => x.id === offerId)
  if (!off) return
  const p = state.players[c.playerId]
  const team = state.teams[off.teamId]
  if (off.kind === 'rookie' || off.kind === 'college') {
    const path: CareerPath = off.kind === 'college' ? 'college' : 'pro'
    c.path = path
    c.offers = []
    signPlayer(state, p, team, off.salary, off.years, path === 'college' ? 'college' : 'pro')
    if (path === 'college') p.classYear = 1
    // 監督の評価は約束された役割から始まる
    c.trust = off.role === 'starter' ? 62 : off.role === 'rotation' ? 52 : 44
    c.talks.push({ id: path === 'college' ? 'join_college' : 'join_pro', speaker: path === 'college' ? 'coach_harrison' : 'todo_maiko' })
    pushHeirTalk(state, 'join')
    state.news.push({ season: state.season, week: state.week, text: `${p.name}が${team.name}に${path === 'college' ? '入学' : '入団'}`, big: true })
    // 大学ならルームメイト（ジェイレン）を同じ大学へ
    if (path === 'college') {
      const jalen = Object.values(state.players).find((x) => x.castId === 'jalen_brooks')
      if (jalen && jalen.teamId !== team.id) {
        signPlayer(state, jalen, team, 0, 4, 'college')
        jalen.classYear = 1
      }
    }
  } else {
    c.offers = []
    // 契約の前の所属（挨拶の言葉を変える）: アメリカでプレーしたことがあるか・NBA の経験・同じチームか
    const US = ['NBA', 'DEV', 'NCAA']
    const prev = p.teamId >= 0 ? state.teams[p.teamId] : undefined
    const wasUs = !!prev && US.includes(prev.league)
    const usBefore = wasUs || p.history.some((h) => US.includes(h.league))
    const nbaBefore = prev?.league === 'NBA' || p.history.some((h) => h.league === 'NBA')
    const kind = team.league === 'NBA' ? (off.contract ?? 'standard') : team.league === 'DEV' ? (off.contract === 'twoWay' ? 'twoWay' : 'dev') : 'pro'
    signPlayer(state, p, team, off.salary, off.years, kind)
    const sign =
      off.kind === 'renew' || prev?.id === team.id
        ? 'renew'
        : team.league === 'DEV' || off.contract === 'twoWay'
          ? usBefore ? 'dev' : 'devFirst'
          : team.league === 'NBA'
            ? !usBefore ? 'first' : nbaBefore ? 'move' : 'debut'
            : nbaBefore || usBefore ? 'home' : 'jbl'
    c.talks.push({ id: `sign:${sign}:${team.id}`, speaker: 'todo_maiko' })
    if (team.league === 'NBA') pushHeirTalk(state, 'nba')
  }
  assignPhotos(state, team.id)
}
