/**
 * 古いセーブの直し（migrations の版 3）: 前の版の昇格・降格は、1 部から 2 部へ下がったクラブを、同じシーズンの終わりに 3 部まで落としていた。
 * 前のシーズンのニュース（「〜が JBL 2部へ降格」と「〜が JBL 3部へ降格」の両方）でそのクラブを見つけ、
 * 新しいシーズンの国内の試合がまだ 1 つも行われていなければ、2 部のいちばん弱いクラブ（本来は下がるはずだったクラブの代わり）と入れ替える。
 * 日程はクラブの番号を入れ替えるだけ（どちらも同じ形の 60 試合）。順位表はどちらも 0 勝 0 敗なので作り直す
 */
import type { GameState } from '../models/game'
import { emptyStanding } from '../models/league'
import { teamPower } from '../query'

export function repairDoubleDrop(state: GameState): number[] {
  const last = state.season - 1
  const j2 = state.leagues.JBL2
  const j3 = state.leagues.JBL3
  if (!j2 || !j3 || last < 0) return []
  const news = state.news.filter((n) => n.season === last)
  const said = (name: string, text: string) => news.some((n) => n.text === `${name}${text}`)
  const doubled = j3.teamIds.filter((id) => {
    const t = state.teams[id]
    return said(t.name, `が${j2.name}へ降格`) && said(t.name, `が${j3.name}へ降格`)
  })
  if (!doubled.length) return []
  // 新しいシーズンの国内の試合がもう始まっていたら直さない（成績が混ざる）
  const touched = new Set([...j2.teamIds, ...j3.teamIds])
  if (state.fixtures.some((f) => f.result && (f.league === 'JBL2' || f.league === 'JBL3') && (touched.has(f.home) || touched.has(f.away)))) return []
  // 入れ替える相手: 2 部にいて、前のシーズンに 3 部から上がってきたのではないクラブのうち、いちばん弱いもの
  const promoted = (id: number) => said(state.teams[id].name, `が${j2.name}へ昇格`)
  const pool = j2.teamIds.filter((id) => !promoted(id)).sort((a, b) => teamPower(state, state.teams[a]) - teamPower(state, state.teams[b]))
  const fixed: number[] = []
  for (const a of doubled) {
    const b = pool.shift()
    if (b === undefined) break
    // リーグの所属
    j3.teamIds = j3.teamIds.map((id) => (id === a ? b : id))
    j2.teamIds = j2.teamIds.map((id) => (id === b ? a : id))
    state.teams[a].league = 'JBL2'
    state.teams[b].league = 'JBL3'
    // 順位表（どちらもまだ 0 勝 0 敗）
    delete j3.standings[a]
    delete j2.standings[b]
    j2.standings[a] = emptyStanding()
    j3.standings[b] = emptyStanding()
    // 日程: 2 部と 3 部の試合で、a と b の番号を入れ替える
    for (const f of state.fixtures) {
      if (f.league !== 'JBL2' && f.league !== 'JBL3') continue
      if (f.home === a) f.home = b
      else if (f.home === b) f.home = a
      if (f.away === a) f.away = b
      else if (f.away === b) f.away = a
    }
    state.news.push({ season: state.season, week: state.week, text: `${state.teams[a].name}は、昇格・降格の不具合で 3 部に入っていたので、2 部に戻った（${state.teams[b].name}が 3 部へ）`, big: true })
    fixed.push(a)
  }
  return fixed
}
