/**
 * NBA ドラフト。
 *   候補（第 40 週）: 大学の 4 年生・評価の高い下級生（アーリーエントリー）・海外の若手（その場で作る）・国内の若い有望株・所属なしの若手
 *   順番（第 51 週）: プレーオフに出なかった 14 チームでロッタリー（1〜4 位を抽選。成績が悪いほど当たりやすい）→ 残りは成績の悪い順 → プレーオフのチーム。2 巡・60 人
 *   指名: 評価（draftValue）の高い順に、ポジションの偏りを少し見る。1 巡はルーキー契約（指名順で年俸が決まる 4 年）、2 巡は半分が 2way 契約（育成リーグへ）
 *   クラブ経営の自分のチーム: 指名リスト（club.draftBoard）の上から残っている選手。2 巡は登録がいっぱいのときだけ 2way
 */
import type { Rng } from '../core/prng'
import { ageAt, absWeekOf } from '../core/calendar'
import { NBA_NATION_MIX, type Nation } from '../data/nations'
import { NBA_MIN, TWO_WAY_SALARY, usdToMan } from '../economy/salary'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'
import { generatePlayer } from '../gen/playerGen'
import { sortedStandings } from './standings'

/** ドラフトの評価（今の力と伸びしろ、若さ） */
export function draftValue(p: Player, age: number, college = true): number {
  // 主人公の伸びしろは隠れているので、スカウトは年齢と今の力から見込む
  const o = ovr(p)
  const pot = p.isPlayer ? Math.min(95, o + Math.max(0, 24 - age) * 3.2) : p.pot
  // 大学以外（海外・国内のリーグ）の選手は、見る機会が少ない分だけ低く見る
  return 0.45 * o + 0.55 * pot - Math.max(0, age - 19) * 1.3 - (college ? 0 : 4)
}

const now = (s: GameState) => absWeekOf(s.season, s.week)

function leave(state: GameState, p: Player) {
  const t = state.teams[p.teamId]
  if (t) t.roster = t.roster.filter((id) => id !== p.id)
  p.teamId = -1
  p.contract = { salary: 0, years: 0, kind: 'none' }
  delete p.classYear
}

/** 候補を決める（第 40 週） */
export function buildDraftPool(state: GameState, rng: Rng) {
  const abs = now(state)
  const pool = new Set<number>()
  // 大学
  const college = Object.values(state.players).filter((p) => p.teamId >= 0 && state.teams[p.teamId].league === 'NCAA' && !p.isPlayer)
  const ranked = college.map((p) => ({ p, v: draftValue(p, ageAt(abs, p.birthAbs)) })).sort((a, b) => b.v - a.v)
  ranked.forEach(({ p, v }, i) => {
    const senior = (p.classYear ?? 1) >= 4
    // 下級生は評価の上位だけが名乗り出る（1 年生は特に上位だけ）
    const declare = !senior && ((p.classYear === 1 && i < 10) || (p.classYear !== 1 && i < 34 && v >= 62))
    if ((senior && ovr(p) >= 48) || declare) pool.add(p.id)
  })
  // 海外の若手（その場で作る）
  const n = rng.int(10, 15)
  for (let i = 0; i < n; i++) {
    const nation: Nation = NBA_NATION_MIX.codes[1 + rng.weighted(NBA_NATION_MIX.weights.slice(1))]
    const p = generatePlayer(state, rng, { nation, age: rng.int(19, 21), ovr: Math.round(rng.range(50, 62)), pot: Math.round(70 + rng.next() ** 1.6 * 18) })
    pool.add(p.id)
  }
  // 国内の若手・所属なしの若手
  for (const p of Object.values(state.players)) {
    if (p.isPlayer || p.retired || pool.has(p.id)) continue
    const age = ageAt(abs, p.birthAbs)
    const lg = p.teamId >= 0 ? state.teams[p.teamId].league : 'FA'
    if (age <= 22 && (lg === 'JBL1' || lg === 'FA') && ovr(p) >= 56 && p.pot >= 76 && rng.chance(0.35)) pool.add(p.id)
  }
  // キャリア: ドラフトに名乗り出た主人公
  const c = state.career
  if (c && c.declared === state.season) pool.add(c.playerId)
  state.draftPool = [...pool]
}

/** ドラフトの順番（1 巡の 30 チーム。2 巡は成績の悪い順） */
export function draftOrder(state: GameState, rng: Rng): { first: number[]; second: number[] } {
  const lg = state.leagues.NBA
  const worstFirst = sortedStandings(lg).reverse()
  const playoff = new Set(state.series.filter((s) => s.league === 'NBA' && s.round === 1).flatMap((s) => [s.hi, s.lo]))
  const lottery = worstFirst.filter((id) => !playoff.has(id)).slice(0, 14)
  const rest = worstFirst.filter((id) => !lottery.includes(id))
  // ロッタリー: 1〜4 位を抽選（成績の悪い順に 14・14・14・12.5・10.5・9・7.5・6・4.5・3・2・1.5・1・0.5 %）
  const odds = [140, 140, 140, 125, 105, 90, 75, 60, 45, 30, 20, 15, 10, 5]
  const left = [...lottery]
  const w = [...odds]
  const top: number[] = []
  for (let i = 0; i < 4 && left.length; i++) {
    const k = rng.weighted(w)
    top.push(left[k])
    left.splice(k, 1)
    w.splice(k, 1)
  }
  const first = [...top, ...left, ...rest]
  return { first, second: [...worstFirst] }
}

/** 1 巡のルーキー契約の年俸（指名順。1 位 約 $12M 〜 30 位 約 $2.2M） */
export function rookieScale(pick: number): number {
  return usdToMan(Math.max(2.2e6, 12e6 * 0.94 ** (pick - 1)))
}

/** ドラフトを行う（第 51 週） */
export function runDraft(state: GameState, rng: Rng) {
  const abs = now(state)
  const { first, second } = draftOrder(state, rng)
  const avail = state.draftPool.map((id) => state.players[id]).filter((p) => p && (!p.isPlayer || state.career?.declared === state.season))
  const value = new Map(avail.map((p) => [p.id, draftValue(p, ageAt(abs, p.birthAbs), p.teamId >= 0 && state.teams[p.teamId].league === 'NCAA') + (p.isPlayer ? (state.career?.combine?.grade ?? 0) : 0)]))
  state.draftLog = []
  const year = state.startYear + state.season + 1
  const order = [...first.map((t) => [t, 1] as const), ...second.map((t) => [t, 2] as const)]
  order.forEach(([teamId, round], i) => {
    if (!avail.length) return
    const team = state.teams[teamId]
    const posCount = (pos: string) => team.roster.filter((id) => state.players[id].pos === pos).length
    const mine = state.club?.teamId === teamId
    const fromBoard = mine ? (state.club!.draftBoard ?? []).map((id) => avail.findIndex((p) => p.id === id)).find((k) => k >= 0) : undefined
    let best = fromBoard ?? 0
    let bestScore = fromBoard !== undefined ? Infinity : -Infinity
    avail.forEach((p, k) => {
      if (fromBoard !== undefined) return
      const score = value.get(p.id)! + rng.normal(0, 1.5) - (posCount(p.pos) >= 4 ? 2 : 0) + (p.isPlayer && state.career?.workoutTeam === teamId ? 3 : 0)
      if (score > bestScore) {
        bestScore = score
        best = k
      }
    })
    const p = avail.splice(best, 1)[0]
    const pick = i + 1
    leave(state, p)
    p.draft = { year, round, pick: round === 1 ? pick : pick - first.length, teamId }
    const twoWay = round === 2 && (mine ? team.roster.length >= 15 : rng.chance(0.5))
    const dest = twoWay && team.affiliate !== undefined ? state.teams[team.affiliate] : team
    p.teamId = dest.id
    dest.roster.push(p.id)
    p.contract = round === 1 ? { salary: rookieScale(pick), years: 4, kind: 'rookie' } : twoWay ? { salary: TWO_WAY_SALARY, years: 2, kind: 'twoWay' } : { salary: NBA_MIN, years: 2, kind: 'rookie' }
    state.draftLog.push({ pick, round, teamId, playerId: p.id, name: p.name })
    if (pick <= 3) state.news.push({ season: state.season, week: state.week, text: `ドラフト ${pick} 位: ${team.name}が${p.name}を指名`, big: pick === 1 })
    else if (mine) state.news.push({ season: state.season, week: state.week, text: `ドラフト: ${round} 巡 ${p.draft.pick} 位で${p.name}（${p.pos}）を指名${twoWay ? '（2way 契約）' : ''}`, big: true })
  })
  // 指名されなかった候補: 大学の選手は所属なしへ（大学には戻らない）
  for (const p of avail) if (p.teamId >= 0 && state.teams[p.teamId].league === 'NCAA') leave(state, p)
  state.draftPool = []
  if (state.club) state.club.draftBoard = []
}
