/**
 * キャリアの 1 週（advanceWeek の前と後）。
 *   前: 過ごし方（練習・休養・居残り・おでかけ）→ 経験点・疲れ・調子・監督の評価。おでかけで人と会う
 *   後: 試合の経験点（今週の成績の差から）→ 監督の評価・知名度・NBA の注目度 → 出来事（ドラフトの決断・指名・契約）→ かんたん育成
 */
import { DRAFT_ENTRY_WEEKS, NBA_DRAFT_WEEK, absWeekOf, ageAt } from '../core/calendar'
import { weekRng } from '../core/prng'
import { ACTION_DEFS, PLACES, type ActionId } from '../data/career'
import { CAST_BY_ID } from '../data/cast'
import { HEROINE_STORY } from './heroineLines'
import { NBA_MIN, TWO_WAY_SALARY, jblMarketSalary } from '../economy/salary'
import type { GameState } from '../models/game'
import type { CareerOffer } from '../models/career'
import type { Stats } from '../models/player'
import { ovr } from '../player/overall'
import { draftValue } from '../competition/draft'
import { allocId } from '../models/game'
import { easyGrowth, gainExp } from './growth'
import { combineResult, nbaFreeAgentOffers, nbaWeek } from './nba'
import { lifeWeek, trainerMul } from './life'
import { canConfess, dateTarget, dateWeek, familySeasonEnd } from './romance'
import { sameGeneration } from './castLines'
import { pushHeirTalk } from './heir'
import { rivalWeek } from './rival'
import { traitsWeek } from './traits'
import { nationalWeek } from './national'
import { retireWeek } from './retire'
import { campWeek, lifePlusWeek } from './lifePlus'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

export function careerPlayer(state: GameState) {
  return state.players[state.career!.playerId]
}

export function careerAge(state: GameState): number {
  return ageAt(absWeekOf(state.season, state.week), careerPlayer(state).birthAbs)
}

/** 主人公が今いる地域（大学・NBA・育成リーグならアメリカ） */
export function regionOf(state: GameState): 'jp' | 'us' {
  const p = careerPlayer(state)
  const lg = p.teamId >= 0 ? state.teams[p.teamId].league : state.career?.path === 'college' ? 'NCAA' : 'JBL1'
  return lg === 'NCAA' || lg === 'NBA' || lg === 'DEV' ? 'us' : 'jp'
}

/** おまかせの過ごし方（練習の予定を週ごとに順に。疲れていれば休養） */
export function autoAction(state: GameState): ActionId {
  const c = state.career!
  const p = careerPlayer(state)
  if (p.fatigue >= 70 || p.injury) return 'rest'
  // 6 週に 1 回は出かける（12 週に 1 回は、誘える人がいればデート）
  if (state.week % 6 === 5) return state.week % 12 === 11 && dateTarget(state) ? 'date' : 'outing'
  return c.autoPlan[state.week % c.autoPlan.length]
}

/** 今週の主人公のチームの試合 */
export function careerFixtures(state: GameState) {
  const p = careerPlayer(state)
  return state.fixtures.filter((f) => f.week === state.week && !f.result && (f.home === p.teamId || f.away === p.teamId)).sort((a, b) => a.day - b.day)
}

/** おでかけ先で会える人（地域が合う人。会ったことのない人も） */
export function peopleAt(state: GameState, placeId: string): string[] {
  const place = PLACES.find((x) => x.id === placeId)
  if (!place) return []
  return place.cast.filter((id) => {
    const c = CAST_BY_ID[id]
    return c && (c.region === 'any' || c.region === regionOf(state)) && sameGeneration(state, id)
  })
}

/** おでかけ: 会える人の中から 1 人（絆が低めの人・会ったことのない人を先に） */
function outing(state: GameState, placeId: string, seed: number) {
  const c = state.career!
  const people = peopleAt(state, placeId)
  if (!people.length) return
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), seed)
  const w = people.map((id) => (c.met.includes(id) ? 1 + (100 - (c.bonds[id] ?? 0)) / 50 : 2.5))
  const who = people[rng.weighted(w)]
  const before = c.bonds[who] ?? 0
  const after = Math.min(100, before + rng.int(7, 12))
  c.bonds[who] = after
  if (!c.met.includes(who)) {
    c.met.push(who)
    c.talks.push({ id: `meet:${who}`, speaker: who })
  } else if (before < 30 && after >= 30 && !c.seen.includes(`bond:${who}:30`)) c.talks.push({ id: `bond:${who}:30`, speaker: who })
  else if (before < 60 && after >= 60 && !c.seen.includes(`bond:${who}:60`)) c.talks.push({ id: `bond:${who}:60`, speaker: who })
  else if (before < 80 && after >= 80 && HEROINE_STORY[who] && !c.seen.includes(`bond:${who}:80`)) c.talks.push({ id: `bond:${who}:80`, speaker: who })
  else if (canConfess(state, who)) c.talks.push({ id: `confess:${who}`, speaker: who })
  else c.talks.push({ id: `chat:${who}:${rng.int(0, 9)}`, speaker: who })
  const place = PLACES.find((x) => x.id === placeId)!
  gainExp(state, place.exp, careerAge(state))
}

/** 週のはじめ（試合の前）: 過ごし方の効き目 */
export function careerBeforeWeek(state: GameState) {
  const c = state.career
  if (!c || c.retiredAt !== undefined) return
  const p = careerPlayer(state)
  if (p.teamId < 0 && !c.path) return
  lifeWeek(state)
  const action = c.action ?? autoAction(state)
  const def = ACTION_DEFS[action]
  const games = careerFixtures(state).length
  // 試合の多い週は練習の時間が短い
  const regular = c.trust >= 55
  const mul = !regular ? 1 : games >= 3 ? 0.7 : games === 2 ? 0.8 : games === 1 ? 0.9 : 1
  gainExp(state, def.exp, careerAge(state), mul * trainerMul(state))
  p.fatigue = clamp(p.fatigue + def.fatigue, 0, 100)
  p.condition = clamp(p.condition + def.condition, 5, 95)
  if (def.practice) c.trust = clamp(c.trust + (action === 'defense' ? 0.7 : action === 'film' ? 0.5 : action === 'extra' ? 0.6 : 0.3), 0, 100)
  else if (games > 0 && action === 'rest' && p.fatigue < 40) c.trust = clamp(c.trust - 0.3, 0, 100)
  if (action === 'outing') {
    const place = c.place ?? PLACES.find((x) => x.region === regionOf(state))!.id
    outing(state, place, state.week)
  }
  const dw = action === 'date' ? dateTarget(state) : undefined
  if (dw) dateWeek(state, dw)
  // 合宿: 試合がある・お金が足りないときは、居残り練習と同じ
  if (action === 'camp' && !campWeek(state)) gainExp(state, ACTION_DEFS.extra.exp, careerAge(state), mul * trainerMul(state))
  c.action = undefined
  c.place = undefined
  c.camp = undefined
  c.dateSpot = undefined
  if (c.growthMode === 'easy') easyGrowth(state)
}

/** 成績の写し（週の前と後で差をとる） */
export function statsSnapshot(state: GameState): Stats {
  const p = careerPlayer(state)
  const s = { ...p.stats }
  if (p.poStats) for (const k of Object.keys(s) as (keyof Stats)[]) s[k] += p.poStats[k]
  return s
}

function diff(a: Stats, b: Stats): Stats {
  const d = { ...b }
  for (const k of Object.keys(d) as (keyof Stats)[]) d[k] = b[k] - a[k]
  return d
}

/** NBA のスカウトの注目度の目標（能力・成績・リーグ・若さ） */
function interestTarget(state: GameState): number {
  const p = careerPlayer(state)
  const lg = p.teamId >= 0 ? state.teams[p.teamId].league : 'FA'
  if (lg === 'NBA') return 100
  const o = ovr(p)
  const s = p.stats
  const ppg = s.gp ? s.pts / s.gp : 0
  const leagueAdj = lg === 'NCAA' ? 10 : lg === 'DEV' ? 8 : lg === 'JBL1' ? 0 : lg === 'JBL2' ? -10 : lg === 'JBL3' ? -20 : -15
  return clamp((o - 52) * 4 + Math.min(20, ppg * 0.8) + leagueAdj + (22 - careerAge(state)) * 3, 0, 100)
}

/** モックドラフトの予想順位（大学の選手と主人公を評価で並べる。海外の候補の分を少し足す）。60 位より下は null */
export function mockRank(state: GameState): number | null {
  const abs = absWeekOf(state.season, state.week)
  const p = careerPlayer(state)
  const mine = draftValue(p, ageAt(abs, p.birthAbs) + 1, state.career?.path === 'college')
  let ahead = 0
  for (const x of Object.values(state.players)) {
    if (x.isPlayer || x.teamId < 0 || state.teams[x.teamId].league !== 'NCAA') continue
    if (draftValue(x, ageAt(abs, x.birthAbs) + 1) > mine) ahead++
  }
  const rank = Math.round((ahead + 1) * 1.25)
  return rank <= 60 ? rank : null
}

/** 週の終わり（試合のあと）: 試合の経験点・評価・注目度・出来事 */
/** 大学の試合の経験点の倍率（試合数が国内の半分なので。2026-11-08 に足した: 大学の道は 22 歳で国内より総合 5 ほど低かった） */
export const COLLEGE_GAME_EXP = 1.7

export function careerAfterWeek(state: GameState, before: Stats, played: { week: number; seasonEnded: boolean }) {
  const c = state.career
  if (!c || c.retiredAt !== undefined) return
  const p = careerPlayer(state)
  const d = diff(before, statsSnapshot(state))
  const age = careerAge(state)
  if (d.gp > 0) {
    // 得点だけでシュートが伸びすぎないように（得点 0.3）。守備は出場時間でも少し入る
    // 大学は試合が 1 シーズン 30（国内は 60）なので、1 試合の経験点を多めに（COLLEGE_GAME_EXP）
    const gameMul = 0.7 * (state.teams[p.teamId]?.league === 'NCAA' ? COLLEGE_GAME_EXP : 1)
    gainExp(state, { shoot: d.pts * 0.3 + d.ftm * 0.2, skill: d.ast * 1.0 + d.fgm * 0.3, def: d.stl * 2 + d.blk * 2 + d.dreb * 0.6 + d.oreb * 0.4 + d.min * 0.04, mind: d.min * 0.12 + d.ast * 0.3, phys: d.min * 0.16 }, age, gameMul)
    // 監督の評価: 出場時間あたりの貢献（ゲームスコアの 36 分換算）
    const gs = d.pts + 0.4 * d.fgm - 0.7 * d.fga - 0.4 * (d.fta - d.ftm) + 0.7 * d.oreb + 0.3 * d.dreb + d.stl + 0.7 * d.ast + 0.7 * d.blk - 0.4 * d.pf - d.tov
    const per36 = d.min > 0 ? (gs / d.min) * 36 : 0
    c.trust = clamp(c.trust + clamp((per36 - 10) * 0.12, -1.5, 1.5) * d.gp, 0, 100)
    const lg = state.teams[p.teamId]?.league
    const fameMul = lg === 'NBA' ? 1.3 : lg === 'NCAA' ? 1.1 : lg === 'JBL1' ? 0.9 : 0.6
    c.fame = clamp(c.fame + (d.pts * 0.015 + d.gp * 0.02) * fameMul, 0, 100)
  }
  // 監督の評価は、チームの中での力の順番に少しずつ寄っていく
  const team = state.teams[p.teamId]
  if (team) {
    const top = team.roster
      .map((id) => ovr(state.players[id]))
      .sort((a, b) => b - a)
      .slice(0, 8)
    const avg = top.reduce((s, v) => s + v, 0) / Math.max(1, top.length)
    const base = clamp(52 + (ovr(p) - avg) * 2, 15, 95)
    c.trust = clamp(c.trust + (base - c.trust) * 0.025, 0, 100)
  }
  c.fame = clamp(c.fame * 0.99, 0, 100)
  c.nbaInterest = clamp(c.nbaInterest + (interestTarget(state) - c.nbaInterest) * 0.1, 0, 100)

  // ---- 出来事
  const lg = team?.league
  const eligible = (c.path === 'college' && lg === 'NCAA') || (c.path === 'pro' && (lg === 'JBL1' || lg === 'JBL2' || lg === 'JBL3') && age <= 22)
  if (played.week === DRAFT_ENTRY_WEEKS[0] - 1 && eligible && age >= 18 && c.declared !== state.season && c.nbaInterest >= 25) c.talks.push({ id: 'draft_decision', speaker: 'todo_maiko' })
  if (played.week === NBA_DRAFT_WEEK && c.declared === state.season - (played.seasonEnded ? 1 : 0)) {
    const drafted = p.draft && p.draft.year === state.startYear + state.season + (played.seasonEnded ? 0 : 1)
    c.talks.push({ id: drafted ? 'drafted' : 'undrafted', speaker: 'todo_maiko' })
    if (drafted) pushHeirTalk(state, 'drafted')
  }
  // 育成リーグから NBA へ（提携先の 11 番手より上なら、シーズン中でも声がかかる）
  if (team && team.league === 'DEV' && team.affiliate !== undefined && !c.offers.some((o) => o.kind === 'nba')) {
    const parent = state.teams[team.affiliate]
    const line = parent.roster
      .map((id) => ovr(state.players[id]))
      .sort((a, b) => b - a)[10] ?? 0
    if (ovr(p) > line) {
      c.offers.push({ id: allocId(state), kind: 'nba', teamId: parent.id, role: 'rotation', salary: NBA_MIN, years: 2, contract: 'standard', pitch: '育成リーグでの活躍を見ていた。NBA で力を貸してほしい' })
      c.talks.push({ id: 'callup', speaker: 'todo_maiko' })
    }
  }
  nbaWeek(state, played)
  lifePlusWeek(state, played)
  nationalWeek(state, played)
  retireWeek(state, played)
  rivalWeek(state, played)
  traitsWeek(state, played)
  if (played.seasonEnded) familySeasonEnd(state)
  if (c.declared === state.season && played.week === 43 && !c.combine) c.combine = combineResult(state)
  if (played.seasonEnded) seasonEndCareer(state)
  if (c.growthMode === 'easy') easyGrowth(state)
}

/** シーズンの終わり: 記録・契約・所属なしなら話を集める */
function seasonEndCareer(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  const h = p.history[p.history.length - 1]
  if (h && h.season === state.season - 1) {
    const s = h.stats
    const notes = state.awards.filter((a) => a.season === h.season && a.playerId === p.id).map((a) => `${state.leagues[a.league].short} ${a.award}`)
    const champ = state.champions.find((x) => x.season === h.season && x.teamId === h.teamId)
    if (champ) notes.unshift(`${state.leagues[champ.league].short} 優勝`)
    c.log.push({ season: h.season, age: h.age, teamName: h.teamName, league: state.leagues[h.league].short, ovr: h.ovr, gp: s.gp, ppg: s.gp ? s.pts / s.gp : 0, rpg: s.gp ? (s.oreb + s.dreb) / s.gp : 0, apg: s.gp ? s.ast / s.gp : 0, notes })
  }
  c.moments = { tried: 0, won: 0 }
  delete c.combine
  delete c.workoutTeam
  // 契約: 年数を減らし、切れたら今のチームと、ほかのチームから話
  if (p.teamId >= 0) {
    const t = state.teams[p.teamId]
    if (t.league === 'NCAA') {
      p.classYear = (p.classYear ?? 1) + 1
      if (p.classYear > 4) {
        // 大学を卒業（ドラフトで呼ばれなかった）
        t.roster = t.roster.filter((id) => id !== p.id)
        p.teamId = -1
        p.contract = { salary: 0, years: 0, kind: 'none' }
        delete p.classYear
      }
    } else if (!(p.draft && p.draft.year === state.startYear + state.season)) {
      // ドラフトで指名されたばかりなら減らさない
      p.contract.years--
      if (p.contract.years <= 0) contractOffers(state)
    }
  }
  if (p.teamId < 0) contractOffers(state)
}

/** 契約の話（契約が切れた・所属がない）。注目度が高ければ NBA・育成リーグから、そうでなければ国内から */
export function contractOffers(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  const o = ovr(p)
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), 99)
  const until = absWeekOf(state.season, 6)
  const add = (kind: CareerOffer['kind'], teamId: number, role: CareerOffer['role'], salary: number, years: number, contract?: CareerOffer['contract']) => {
    if (c.offers.some((x) => x.teamId === teamId)) return
    c.offers.push({ id: allocId(state), kind, teamId, role, salary, years, until, contract, pitch: role === 'starter' ? 'スタメンとして迎えたい' : role === 'rotation' ? 'ローテーションの一員として力を貸してほしい' : 'まずはベンチから、チャンスをつかんでほしい' })
  }
  const cur = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  if (cur && cur.league !== 'NCAA') add('renew', cur.id, c.trust >= 60 ? 'starter' : 'rotation', cur.league === 'NBA' ? p.contract.salary : jblMarketSalary(o, false, cur.league), cur.league === 'NBA' ? 2 : 2)
  if (cur?.league === 'NBA' || (c.nbaInterest >= 70 && o >= 66)) nbaFreeAgentOffers(state)
  else if (c.nbaInterest >= 70) {
    const t = rng.pick(state.leagues.NBA.teamIds)
    add('nba', t, 'bench', NBA_MIN, 2, 'min')
  }
  if (c.nbaInterest >= 45 && cur?.league !== 'NBA') {
    const t = rng.pick(state.leagues.NBA.teamIds)
    add('nba', state.teams[t].affiliate ?? t, 'rotation', TWO_WAY_SALARY, 2, 'twoWay')
  }
  for (const lg of ['JBL1', 'JBL2'] as const) {
    const t = rng.pick(state.leagues[lg].teamIds)
    add('transfer', t, lg === 'JBL1' ? 'rotation' : 'starter', jblMarketSalary(o, false, lg), 2)
  }
}
