/** 選手。GameState.players に id で入る。 */
import type { Attrs } from '../data/attributes'
import type { GrowthType } from '../data/growth'
import type { Nation, FaceGroup } from '../data/nations'
import type { Personality } from '../data/personality'
import type { Position } from '../data/positions'
import type { SkillId } from '../data/skills'
import type { PlayStyle } from '../data/styles'
import type { LeagueId } from './league'

/**
 * 契約の種類
 *   rookie ドラフトで指名された選手のルーキー契約（NBA）・standard ふつう・max マックス契約・min 最低保証
 *   twoWay 2way 契約（NBA と育成リーグを行き来する）・dev 育成リーグの契約・pro 国内リーグのプロ契約
 *   college 大学の奨学金（年俸なし）・none 所属なし
 */
export type ContractKind = 'rookie' | 'standard' | 'max' | 'min' | 'twoWay' | 'dev' | 'pro' | 'college' | 'none'

export interface Contract {
  /** 年俸（万円/年） */
  salary: number
  /** 残り年数（今季を含む） */
  years: number
  kind: ContractKind
}

/** 成績（合計。平均は画面で割る） */
export interface Stats {
  gp: number
  gs: number
  min: number
  pts: number
  fgm: number
  fga: number
  tpm: number
  tpa: number
  ftm: number
  fta: number
  oreb: number
  dreb: number
  ast: number
  stl: number
  blk: number
  tov: number
  pf: number
  /** 出ている間の得失点差（+/-） */
  pm: number
}

export const STAT_KEYS = ['gp', 'gs', 'min', 'pts', 'fgm', 'fga', 'tpm', 'tpa', 'ftm', 'fta', 'oreb', 'dreb', 'ast', 'stl', 'blk', 'tov', 'pf', 'pm'] as const

export function emptyStats(): Stats {
  return { gp: 0, gs: 0, min: 0, pts: 0, fgm: 0, fga: 0, tpm: 0, tpa: 0, ftm: 0, fta: 0, oreb: 0, dreb: 0, ast: 0, stl: 0, blk: 0, tov: 0, pf: 0, pm: 0 }
}

/** シーズンごとの記録（経歴） */
export interface SeasonLine {
  season: number
  teamId: number
  teamName: string
  league: LeagueId
  age: number
  ovr: number
  stats: Stats
  playoffs?: Stats
}

export interface Injury {
  name: string
  /** 残りの週 */
  weeks: number
}

export interface Player {
  id: number
  name: string
  /** 試合中などの短い名前（日本人は姓、外国人はファミリーネーム） */
  short: string
  nation: Nation
  /** 生まれた絶対週（年齢は ageAt で） */
  birthAbs: number
  pos: Position
  /** サブのポジション */
  pos2?: Position
  style: PlayStyle
  heightCm: number
  wingspanCm: number
  weightKg: number
  attr: Attrs
  /** 将来の総合値の上限の目安（伸びしろ） */
  pot: number
  growth: GrowthType
  personality: Personality
  skills: SkillId[]
  /** 所属チーム（-1 は所属なし） */
  teamId: number
  contract: Contract
  /** 背番号 */
  jersey: number
  /** 調子（0-100、50 がふつう） */
  condition: number
  /** 疲れ（0-100、高いほど疲れている） */
  fatigue: number
  /** やる気（0-100） */
  morale: number
  injury?: Injury
  /** 今季のレギュラーシーズンの成績 */
  stats: Stats
  /** 今季のプレーオフの成績 */
  poStats?: Stats
  history: SeasonLine[]
  /** 写真の系統と、割り当てた生成写真の id */
  faceGroup: FaceGroup
  photo?: string
  /** 固有キャラ（data/cast.ts の id） */
  castId?: string
  /** ドラフトの記録（西暦・巡・順位・指名したチーム） */
  draft?: { year: number; round: number; pick: number; teamId: number }
  /** 大学の学年（1-4。大学にいるときだけ） */
  classYear?: number
  /** 主人公 */
  isPlayer?: boolean
  /** 引退した（固有キャラ・主人公は記録を残す。ほかの選手は消す） */
  retired?: boolean
}
