/**
 * プレーオフ。
 *   NBA: プレーイン（第 42 週。7v8・9v10 → 7v8 の敗者 vs 9v10 の勝者）→ 16 チームの 7 戦 4 勝 × 4 回戦（各 2 週、2 日おき）
 *        ホームは 2-2-1-1-1（1・2・5・7 戦目が上位）
 *   国内: 上位 8 の 3 戦 2 勝 × 3 回戦（第 45〜47 週の金土日。上位のホーム）
 *   大学: 上位 16 校の 1 試合のトーナメント（第 35〜38 週。中立地）
 * シリーズの次の試合は、前の試合が終わってから日程に足す（advanceWeek が日ごとに nextGames を呼ぶ）。
 */
import { COLLEGE_TOURNAMENT, JBL_PLAYOFF_WEEKS, NBA_PLAYIN_WEEK, NBA_PLAYOFF_ROUNDS } from '../core/calendar'
import { allocId, type GameState, type Series } from '../models/game'
import type { Fixture, LeagueId } from '../models/league'
import { sortedStandings } from './standings'

const NBA_ROUND_NAME = ['プレーイン', '1回戦', 'カンファレンス準決勝', 'カンファレンス決勝', 'ファイナル']
const JBL_ROUND_NAME = ['', '準々決勝', '準決勝', '決勝']
const NCAA_ROUND_NAME = ['', '1回戦', '準々決勝', '準決勝', '決勝']

function newSeries(state: GameState, s: Omit<Series, 'id' | 'wins' | 'played'>): Series {
  const x: Series = { ...s, id: allocId(state), wins: [0, 0], played: 0 }
  state.series.push(x)
  return x
}

function addFixture(state: GameState, league: LeagueId, week: number, day: number, home: number, away: number, seriesId: number) {
  const f: Fixture = { id: allocId(state), league, week, day, home, away, kind: 'playoff', seriesId }
  state.fixtures.push(f)
}

/** シリーズの k 試合目（0 から）の週と曜日・ホーム */
function slotOf(s: Series, k: number): { week: number; day: number; home: number; away: number } {
  if (s.league === 'NBA' && s.round >= 1) {
    const start = NBA_PLAYOFF_ROUNDS[s.round - 1]
    const d = k * 2
    const hiHome = [0, 1, 4, 6].includes(k)
    return { week: start + Math.floor(d / 7), day: d % 7, home: hiHome ? s.hi : s.lo, away: hiHome ? s.lo : s.hi }
  }
  if (s.league === 'NBA') {
    // プレーイン: 7v8・9v10 は火曜、最後の 1 試合は木曜
    return { week: NBA_PLAYIN_WEEK, day: s.slot === 'last' ? 3 : 1, home: s.hi, away: s.lo }
  }
  if (s.league === 'NCAA') return { week: COLLEGE_TOURNAMENT[0] + s.round - 1, day: 5, home: s.hi, away: s.lo }
  return { week: JBL_PLAYOFF_WEEKS[s.round - 1], day: 4 + k, home: s.hi, away: s.lo }
}

function scheduleNext(state: GameState, s: Series) {
  const sl = slotOf(s, s.played)
  addFixture(state, s.league, sl.week, sl.day, sl.home, sl.away, s.id)
}

/** シーズンの区切りでプレーオフを始める（advanceWeek が週のはじめに呼ぶ） */
export function startPlayoffs(state: GameState) {
  const w = state.week
  if (w === NBA_PLAYIN_WEEK) {
    for (const conf of ['E', 'W']) {
      const lg = state.leagues.NBA
      const order = sortedStandings(
        lg,
        lg.teamIds.filter((id) => state.teams[id].conf === conf),
      )
      for (const [slot, hi, lo] of [
        ['78', order[6], order[7]],
        ['910', order[8], order[9]],
      ] as const) {
        const s = newSeries(state, { league: 'NBA', round: 0, name: `プレーイン（${conf === 'E' ? '東' : '西'}）`, hi, lo, bestOf: 1, conf, slot })
        scheduleNext(state, s)
      }
    }
  }
  if (w === COLLEGE_TOURNAMENT[0]) {
    const lg = state.leagues.NCAA
    const seeds = sortedStandings(lg).slice(0, 16)
    const pairs = [
      [0, 15],
      [7, 8],
      [4, 11],
      [3, 12],
      [5, 10],
      [2, 13],
      [6, 9],
      [1, 14],
    ]
    for (const [a, b] of pairs) {
      const s = newSeries(state, { league: 'NCAA', round: 1, name: `全米大学選手権 ${NCAA_ROUND_NAME[1]}`, hi: seeds[a], lo: seeds[b], bestOf: 1, neutral: true })
      scheduleNext(state, s)
    }
  }
  if (w === JBL_PLAYOFF_WEEKS[0]) {
    for (const id of ['JBL1', 'JBL2', 'JBL3'] as const) {
      const seeds = sortedStandings(state.leagues[id]).slice(0, 8)
      for (const [a, b] of [
        [0, 7],
        [3, 4],
        [1, 6],
        [2, 5],
      ]) {
        const s = newSeries(state, { league: id, round: 1, name: `チャンピオンシップ ${JBL_ROUND_NAME[1]}`, hi: seeds[a], lo: seeds[b], bestOf: 3 })
        scheduleNext(state, s)
      }
    }
  }
}

/** 試合の結果をシリーズに入れ、次の試合・次の回戦を日程に足す */
export function seriesResult(state: GameState, f: Fixture) {
  const s = state.series.find((x) => x.id === f.seriesId)
  if (!s || !f.result || s.winner !== undefined) return
  const homeWon = f.result.hs > f.result.as
  const winner = homeWon ? f.home : f.away
  s.wins[winner === s.hi ? 0 : 1]++
  s.played++
  const need = Math.ceil(s.bestOf / 2)
  if (s.wins[0] >= need || s.wins[1] >= need) {
    s.winner = s.wins[0] >= need ? s.hi : s.lo
    onSeriesDone(state, s)
  } else scheduleNext(state, s)
}

function loserOf(s: Series): number {
  return s.winner === s.hi ? s.lo : s.hi
}

function record(state: GameState, id: number) {
  const st = state.leagues[state.teams[id].league].standings[id]
  return st ? st.w / Math.max(1, st.w + st.l) : 0
}

function onSeriesDone(state: GameState, s: Series) {
  const league = s.league
  const sameRound = state.series.filter((x) => x.league === league && x.round === s.round && (league !== 'NBA' || x.conf === s.conf || s.round === 4))
  if (league === 'NBA' && s.round === 0) {
    // プレーインの最後の 1 試合
    const conf = s.conf!
    const r78 = state.series.find((x) => x.round === 0 && x.conf === conf && x.slot === '78')!
    const r910 = state.series.find((x) => x.round === 0 && x.conf === conf && x.slot === '910')!
    if (s.slot !== 'last' && r78.winner !== undefined && r910.winner !== undefined) {
      const last = newSeries(state, { league: 'NBA', round: 0, name: s.name, hi: loserOf(r78), lo: r910.winner, bestOf: 1, conf, slot: 'last' })
      scheduleNext(state, last)
    }
    if (s.slot === 'last') startNbaRound1(state, conf)
    return
  }
  if (sameRound.some((x) => x.winner === undefined)) return
  if (league === 'NBA') {
    if (s.round === 4) return finish(state, s)
    if (s.round === 3) {
      const e = state.series.find((x) => x.round === 3 && x.conf === 'E')
      const w = state.series.find((x) => x.round === 3 && x.conf === 'W')
      if (e?.winner === undefined || w?.winner === undefined) return
      const [hi, lo] = record(state, e.winner) >= record(state, w.winner) ? [e.winner, w.winner] : [w.winner, e.winner]
      scheduleNext(state, newSeries(state, { league, round: 4, name: NBA_ROUND_NAME[4], hi, lo, bestOf: 7 }))
      return
    }
    // 1 回戦 → 準決勝: (1v8 と 4v5)・(2v7 と 3v6) の勝者どうし
    const r = sameRound
    for (const [a, b] of [
      [0, 1],
      [2, 3],
    ]) {
      const x = r[a].winner!
      const y = r[b].winner!
      const [hi, lo] = record(state, x) >= record(state, y) ? [x, y] : [y, x]
      scheduleNext(state, newSeries(state, { league, round: s.round + 1, name: `${NBA_ROUND_NAME[s.round + 1]}（${s.conf === 'E' ? '東' : '西'}）`, hi, lo, bestOf: 7, conf: s.conf }))
      if (s.round + 1 === 3) break
    }
    return
  }
  const final = league === 'NCAA' ? 4 : 3
  if (s.round === final) return finish(state, s)
  const winners = sameRound.map((x) => x.winner!)
  for (let i = 0; i < winners.length; i += 2) {
    const [a, b] = [winners[i], winners[i + 1]]
    const seedOf = (id: number) => sortedStandings(state.leagues[league]).indexOf(id)
    const [hi, lo] = seedOf(a) <= seedOf(b) ? [a, b] : [b, a]
    const names = league === 'NCAA' ? NCAA_ROUND_NAME : JBL_ROUND_NAME
    const nx = newSeries(state, { league, round: s.round + 1, name: `${league === 'NCAA' ? '全米大学選手権' : 'チャンピオンシップ'} ${names[s.round + 1]}`, hi, lo, bestOf: league === 'NCAA' ? 1 : 3, neutral: league === 'NCAA' })
    scheduleNext(state, nx)
  }
}

function startNbaRound1(state: GameState, conf: string) {
  const lg = state.leagues.NBA
  const order = sortedStandings(
    lg,
    lg.teamIds.filter((id) => state.teams[id].conf === conf),
  )
  const r78 = state.series.find((x) => x.round === 0 && x.conf === conf && x.slot === '78')!
  const last = state.series.find((x) => x.round === 0 && x.conf === conf && x.slot === 'last')!
  const seeds = [...order.slice(0, 6), r78.winner!, last.winner!]
  for (const [a, b] of [
    [0, 7],
    [3, 4],
    [1, 6],
    [2, 5],
  ]) {
    scheduleNext(state, newSeries(state, { league: 'NBA', round: 1, name: `${NBA_ROUND_NAME[1]}（${conf === 'E' ? '東' : '西'}）`, hi: seeds[a], lo: seeds[b], bestOf: 7, conf }))
  }
}

function finish(state: GameState, s: Series) {
  const champ = state.teams[s.winner!]
  const runner = state.teams[loserOf(s)]
  state.champions.push({ season: state.season, league: s.league, teamId: champ.id, teamName: champ.name, runnerUp: runner.name })
  const label = s.league === 'NBA' ? 'NBA ファイナル' : s.league === 'NCAA' ? '全米大学選手権' : `${state.leagues[s.league].name}のチャンピオンシップ`
  state.news.push({ season: state.season, week: state.week, text: `${label}: ${champ.name}が優勝（${s.wins[0]}勝${s.wins[1]}敗）`, big: s.league === 'NBA' || s.league === 'JBL1' })
}

/** シリーズの勝者が決まっていない中立地の試合か */
export function isNeutral(state: GameState, f: Fixture): boolean {
  return !!f.neutral || !!state.series.find((x) => x.id === f.seriesId)?.neutral
}
