/**
 * 主人公の成長: 経験点（5 種）で能力を 1 ずつ上げる。費用は能力が高いほど増える。
 *   じっくり: 育成の画面で自分で振る
 *   かんたん: 練習した種類（focus）とポジションの大事さで、毎週と試合のあとに自動で振る
 * 経験点の入り方は成長タイプの年齢カーブの形（expMulAt。18〜33 歳の平均がどのタイプも同じになるようにそろえる）。
 */
import { ATTR_KEYS, type AttrKey } from '../data/attributes'
import { EXP_DEFS, EXP_KINDS, EXP_OF, type ExpKind } from '../data/career'
import { ageCurve, type GrowthType } from '../data/growth'
import type { GameState } from '../models/game'
import { POS_WEIGHTS } from '../player/overall'

/** 経験点の全体の倍率（主人公の伸びの速さ。tools の成長の確認で合わせる） */
export const EXP_SCALE = 0.72

/** 能力を 1 上げる費用（85 からの最後の伸びは特に重い。得意な力でも 99 はリーグの頂点の選手だけ） */
export function attrCost(v: number): number {
  return Math.round(6 + v * 0.16 + Math.max(0, v - 65) ** 1.45 * 0.35 + Math.max(0, v - 85) ** 1.6 * 0.8)
}

const AVG_UP = new Map<GrowthType, number>()
function avgUp(type: GrowthType): number {
  let v = AVG_UP.get(type)
  if (v === undefined) {
    let s = 0
    let n = 0
    for (let a = 18; a <= 33; a += 0.25) {
      s += ageCurve(type, a).up
      n++
    }
    v = s / n
    AVG_UP.set(type, v)
  }
  return v
}

/** 年齢での経験点の倍率（成長タイプのカーブの形。平均 1.1。衰えの年齢でも 0.35 は入る） */
export function expMulAt(type: GrowthType, age: number): number {
  return Math.max(0.35, (ageCurve(type, age).up / avgUp(type)) * 1.1)
}

/** 能力を 1 上げる（経験点が足りれば）。上げたら true */
export function raiseAttr(state: GameState, k: AttrKey): boolean {
  const c = state.career!
  const p = state.players[c.playerId]
  const kind = EXP_OF[k]
  const v = Math.round(p.attr[k])
  if (v >= 99) return false
  const cost = attrCost(v)
  if (c.exp[kind] < cost) return false
  c.exp[kind] -= cost
  p.attr[k] = v + 1
  return true
}

/** かんたん育成: 種類ごとに、ポジションで大事で安い能力から上げていく */
export function easyGrowth(state: GameState) {
  const c = state.career!
  const p = state.players[c.playerId]
  const w = POS_WEIGHTS[p.pos]
  for (const kind of EXP_KINDS) {
    for (let guard = 0; guard < 60; guard++) {
      let best: AttrKey | null = null
      let bestScore = -Infinity
      for (const k of EXP_DEFS[kind].attrs) {
        const v = Math.round(p.attr[k])
        if (v >= 99) continue
        const cost = attrCost(v)
        if (cost > c.exp[kind]) continue
        // 大事さ ÷ 費用。低すぎる能力は少し優先（弱点を残しすぎない）
        const score = (w[k] + 0.25) / cost + (v < 40 ? 0.02 : 0)
        if (score > bestScore) {
          bestScore = score
          best = k
        }
      }
      if (!best || !raiseAttr(state, best)) break
    }
  }
  void ATTR_KEYS
}

/** 経験点を足す（成長タイプの年齢カーブ・倍率をかける） */
/** 買い物の上乗せ（シューティングマシン・映像分析・トレーニングルーム・自宅のコート） */
const PURCHASE_EXP: Record<string, ExpKind> = { shoot_machine: 'shoot', video_suite: 'mind', home_gym: 'phys', home_court: 'skill' }
export function purchaseExpMul(state: GameState, kind: ExpKind): number {
  const owned = state.career?.purchases ?? []
  return owned.some((id) => PURCHASE_EXP[id] === kind) ? 1.08 : 1
}

/**
 * 種類ごとの入り方: 能力の数で割り振りがそろうように（シュート 4・メンタル 3 は 1 つあたりが多くなりすぎるので減らし、
 * ディフェンスは 6 つあるが、リバウンドとブロックで試合の経験点が多いので 1 のまま）。スコアラーのシュートだけがすぐ 99 になるのを防ぐ（2026-11-08）
 */
export const KIND_BALANCE: Record<ExpKind, number> = { shoot: 0.82, skill: 1, phys: 1, def: 1, mind: 0.8 }

/** その種類の能力がすべて 99 か */
function kindMaxed(state: GameState, kind: ExpKind): boolean {
  const p = state.players[state.career!.playerId]
  return EXP_DEFS[kind].attrs.every((a) => Math.round(p.attr[a]) >= 99)
}

/** あふれた経験点を、ほかの種類へ回す割合（すべて 99 の種類の分） */
const SPILL = 0.5

export function gainExp(state: GameState, gain: Partial<Record<ExpKind, number>>, age: number, mul = 1) {
  const c = state.career!
  const p = state.players[c.playerId]
  // 二代目は親ゆずりの伸びやすさ（heritage。親の評価で 1〜1.08）
  const m = expMulAt(p.growth, age) * EXP_SCALE * mul * (c.heritage ?? 1)
  const add: Record<ExpKind, number> = { shoot: 0, skill: 0, phys: 0, def: 0, mind: 0 }
  let spill = 0
  for (const k of EXP_KINDS) {
    const v = (gain[k] ?? 0) * m * KIND_BALANCE[k] * purchaseExpMul(state, k)
    if (v > 0 && kindMaxed(state, k)) spill += v * SPILL
    else add[k] += v
  }
  // すべて 99 の種類の分は、まだ伸びる種類に等しく
  if (spill > 0) {
    const open = EXP_KINDS.filter((k) => !kindMaxed(state, k))
    for (const k of open) add[k] += spill / open.length
  }
  for (const k of EXP_KINDS) {
    c.exp[k] += add[k]
    c.focus[k] = c.focus[k] * 0.995 + add[k] * 0.02
  }
}
