/**
 * 一般の選手に生成写真を割り当てる（写真の数に限りがあるので、目立つ選手から）。乱数は使わない。
 * 優先: 主人公のチームの選手 → NBA の総合値の高い順 → 国内 1 部 → 大学の有望株。系統（faceGroup）ごとに、写真 1 枚につき 1 人。
 * 固有キャラ（castId）と主人公（isPlayer。作成で選んだ顔）は自分の写真があるので対象外（外しも配りもしない）。
 */
import { FACE_POOL } from '../data/facePool.generated'
import type { GameState } from '../models/game'
import { ovr } from './overall'

const LEAGUE_PRIORITY: Record<string, number> = { NBA: 0, JBL1: 1, NCAA: 2, DEV: 3, JBL2: 4, JBL3: 5 }

export function assignPhotos(state: GameState, focusTeamId = -1) {
  const pools: Record<string, string[]> = {}
  for (const [g, ids] of Object.entries(FACE_POOL)) pools[g] = [...ids]
  if (!Object.keys(pools).length) return
  const own = (p: { castId?: string; isPlayer?: boolean }) => !!p.castId || !!p.isPlayer
  const players = Object.values(state.players).filter((p) => !own(p) && p.teamId >= 0)
  const scoreOf = new Map<number, number>()
  for (const p of players) {
    const lp = LEAGUE_PRIORITY[state.teams[p.teamId].league] ?? 9
    scoreOf.set(p.id, (p.teamId === focusTeamId ? -1000 : 0) + lp * 100 - ovr(p))
  }
  players.sort((a, b) => scoreOf.get(a.id)! - scoreOf.get(b.id)! || a.id - b.id)
  // 今の写真は外して、順に配り直す（同じ状態なら同じ結果）
  for (const p of Object.values(state.players)) if (!own(p)) delete p.photo
  for (const p of players) {
    const pool = pools[p.faceGroup]
    if (pool?.length) p.photo = pool.shift()
  }
}
