/**
 * 試合エンジンの型。観戦（LiveSim）も結果だけ（FastSim）も、同じポゼッションのエンジン（engine.ts）で動かす。
 * 観戦のときだけ、ポゼッションごとに選手とボールの動き（choreo.ts の Beat）を作る。結果はサイコロで決め、見た目はそれに合わせる。
 */
import type { Attrs } from '../data/attributes'
import type { Position } from '../data/positions'
import type { RuleSetId } from '../data/rules'
import type { SkillId } from '../data/skills'
import type { Nation } from '../data/nations'
import type { PlayStyle } from '../data/styles'
import type { Tactics } from '../models/league'

/** 1 試合ぶんの個人の成績（秒で持つ出場時間以外は Stats と同じ） */
export interface BoxLine {
  secs: number
  pts: number
  fgm: number
  fga: number
  tpm: number
  tpa: number
  ftm: number
  fta: number
  oreb: number
  dreb: number
  ast: number
  stl: number
  blk: number
  tov: number
  pf: number
  pm: number
  started: boolean
}

export function emptyBox(): BoxLine {
  return { secs: 0, pts: 0, fgm: 0, fga: 0, tpm: 0, tpa: 0, ftm: 0, fta: 0, oreb: 0, dreb: 0, ast: 0, stl: 0, blk: 0, tov: 0, pf: 0, pm: 0, started: false }
}

/** 試合に出る選手（試合の前に作る写し。能力は試合の水準・調子・疲れを入れたもの） */
export interface SimPlayer {
  id: number
  name: string
  short: string
  jersey: number
  pos: Position
  style: PlayStyle
  nation: Nation
  heightCm: number
  wingspanCm: number
  /** 試合で使う能力（水準をそろえたもの） */
  a: Attrs
  skills: Partial<Record<SkillId, true>>
  /** 総合値（ローテーションの順番） */
  ovr: number
  /** 体力（0-100）。コートにいると減り、ベンチで戻る */
  energy: number
  fouls: number
  /** ファウルアウト・ケガで出られない */
  out: boolean
  box: BoxLine
  /** 国内リーグの外国籍枠に数える（コートに同時に 3 人まで: rotation.ts の ON_COURT_FOREIGN） */
  foreignSlot: boolean
  /** 監督が決めた序列（小さいほど上。なければ総合値の順） */
  depth?: number
}

export interface SimTeam {
  teamId: number
  name: string
  short: string
  abbr: string
  colors: { primary: string; secondary: string }
  tactics: Tactics
  players: SimPlayer[]
  /** コートにいる 5 人（players の添字） */
  court: number[]
  score: number
  /** このピリオドのチームファウル */
  periodFouls: number
  timeouts: number
  /** 手動で指示している（AI の監督が交代・作戦を変えない） */
  manual: boolean
}

/** 試合に出る選手の元（setup.ts が GameState から作る）。能力は素の値 */
export type PlayerInput = Omit<SimPlayer, 'energy' | 'fouls' | 'out' | 'box' | 'a'> & { attr: Attrs; energy?: number }

export interface TeamInput {
  teamId: number
  name: string
  short: string
  abbr: string
  colors: { primary: string; secondary: string }
  tactics: Tactics
  players: PlayerInput[]
}

export interface MatchSetup {
  home: TeamInput
  away: TeamInput
  rules: RuleSetId
  seed: number
  /** 中立地（ホームの有利なし） */
  neutral?: boolean
  /** プレーオフ・決勝など（大舞台の特殊能力が効く） */
  big?: boolean
  /** キャリア: 主人公（カメラが追い、見せ場を出す） */
  focusPlayerId?: number
  /** 国内リーグの外国籍のルール（コートに同時に 3 人まで: rotation.ts の ON_COURT_FOREIGN） */
  foreignLimit?: boolean
}

export type ShotZone = 'rim' | 'paint' | 'mid' | 'three' | 'corner3'

/** 試合の出来事（実況・ボックススコア・見た目の元） */
export type GameEvent =
  | { k: 'period'; period: number }
  | { k: 'shot'; side: 0 | 1; pid: number; zone: ShotZone; made: boolean; pts: number; ast?: number; blk?: number; fouled?: boolean; dunk?: boolean; fast?: boolean; clutch?: boolean }
  | { k: 'ft'; side: 0 | 1; pid: number; made: boolean; n: number; of: number }
  | { k: 'reb'; side: 0 | 1; pid: number; off: boolean }
  | { k: 'tov'; side: 0 | 1; pid: number; stl?: number; kind: 'steal' | 'bad' | 'clock' | 'charge' }
  | { k: 'foul'; side: 0 | 1; pid: number; on: number; shooting: boolean; bonus: boolean }
  | { k: 'sub'; side: 0 | 1; out: number; in: number }
  | { k: 'timeout'; side: 0 | 1 }
  | { k: 'end'; period: number }

/** エンジンが記録する、見た目のための流れ（観戦のときだけ）。t はポゼッションの始まりからの秒 */
export interface Trace {
  t: number
  a: 'bring' | 'pass' | 'drive' | 'pnr' | 'post' | 'iso' | 'shot' | 'reb' | 'ft' | 'tov' | 'foul' | 'fast' | 'inbound'
  /** 主役の選手 id */
  p: number
  /** 相手役（パスの受け手・スクリーンをかける人・スティール・ブロック・ファウルした人） */
  q?: number
  zone?: ShotZone
  made?: boolean
  off?: boolean
}

/** キャリア: 主人公の見せ場（観戦のとき、攻めのはじめに選ぶ） */
export interface MomentOption {
  id: 'three' | 'mid' | 'drive' | 'post' | 'pass'
  label: string
  /** 成功しそうな度合い ◎○△ */
  mark: '◎' | '○' | '△'
  /** 成功の見込み（0〜1） */
  pct: number
  note: string
}

export interface Moment {
  side: 0 | 1
  pid: number
  clutch: boolean
  options: MomentOption[]
}

/** 1 ポゼッションの記録 */
export interface PossLog {
  side: 0 | 1
  /** 始まりの時計（ピリオドの残り秒）と、使った秒 */
  period: number
  clock: number
  dur: number
  events: GameEvent[]
  /** 観戦のときだけ: 流れと見た目の動き */
  trace?: Trace[]
  beats?: Beat[]
  /** ポゼッションのあとの点 */
  score: [number, number]
  /** 見せ場の結果（選んだ手と、点に結びついたか） */
  moment?: { choice: MomentOption['id']; success: boolean }
  /** そのときのコートの 10 人（home 5・away 5 の選手 id） */
  lineup: number[]
}

/** 見た目の 1 コマ（ポゼッションの始まりからの秒。選手 10 人の位置 [x, y] とボール） */
export interface Beat {
  t: number
  pos: number[]
  /** ボール: 持っている選手（lineup の添字）か、飛んでいる（-1）。h は高さ（m） */
  holder: number
  ball: [number, number, number]
  /** この区間で鳴らす音・出す文字 */
  cue?: 'dribble' | 'pass' | 'shot' | 'swish' | 'rim' | 'dunk' | 'block' | 'steal' | 'whistle' | 'buzzer'
}

export interface MatchSummary {
  score: [number, number]
  ot: number
  /** 選手 id → 成績 */
  box: Record<number, BoxLine>
  /** チームの合計（home・away） */
  teams: [TeamTotals, TeamTotals]
  /** 試合の流れ: 1 分ごとの点差（ホーム − アウェイ。最後は試合終了のとき） */
  flow: number[]
}

export interface TeamTotals {
  poss: number
  pts: number
  fgm: number
  fga: number
  tpm: number
  tpa: number
  ftm: number
  fta: number
  oreb: number
  dreb: number
  ast: number
  stl: number
  blk: number
  tov: number
  pf: number
}

export function emptyTotals(): TeamTotals {
  return { poss: 0, pts: 0, fgm: 0, fga: 0, tpm: 0, tpa: 0, ftm: 0, fta: 0, oreb: 0, dreb: 0, ast: 0, stl: 0, blk: 0, tov: 0, pf: 0 }
}
