/**
 * 所属なしの選手（FA）と、AI のチームの人数合わせ。
 *   NBA: キャップの空き（$150M − 年俸の合計）で買える選手のうち評価の高い順。空きがなければ最低保証で来る選手
 *   国内: 外国籍枠（3 人。3 部の AI のクラブは 2 人まで）とアジア枠（1 人。3 部の AI は埋めない）を埋め、残りは日本人。部ごとに来てくれる選手の上限がある
 *   育成リーグ: 残りから
 * 人数が多すぎるチームは、評価の低い選手から所属なしにする。FA の数は毎季の補充で 120 前後に保つ。
 */
import type { Rng } from '../core/prng'
import { absWeekOf, ageAt } from '../core/calendar'
import { NBA_NATION_MIX, type Nation } from '../data/nations'
import { DEV_SALARY, NBA_CAP, NBA_MIN, jblMarketSalary, nbaMarketSalary } from '../economy/salary'
import { generatePlayer } from '../gen/playerGen'
import type { GameState } from '../models/game'
import type { LeagueId, Team } from '../models/league'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'

const ASIA = new Set(['PH', 'KR', 'CN'])
const isForeignSlot = (p: Player) => p.nation !== 'JP' && !ASIA.has(p.nation)

/** 国内リーグの外国籍の登録の上限（1〜3 部どれも。2026-11-14 に 3 部も 2 → 3 人に。コートにも 3 人とも立てる: rotation.ts の ON_COURT_FOREIGN） */
export const JBL_FOREIGN_MAX = 3

/** 人数の目安（下限と上限） */
export const ROSTER_RANGE: Record<LeagueId, [number, number]> = { NBA: [14, 15], DEV: [10, 12], JBL1: [12, 13], JBL2: [12, 13], JBL3: [12, 13], NCAA: [13, 15] }

/** 国内の部ごとの、来てくれる選手の総合値の上限（お金の規模の代わり） */
export const JBL_CEIL: Partial<Record<LeagueId, { foreign: number; jp: number }>> = { JBL1: { foreign: 77, jp: 70 }, JBL2: { foreign: 68, jp: 60 }, JBL3: { foreign: 62, jp: 54 } }

export function playerValue(p: Player, age: number): number {
  return 0.8 * ovr(p) + 0.2 * p.pot - Math.max(0, age - 31) * 1.2
}

function payroll(state: GameState, t: Team): number {
  return t.roster.reduce((s, id) => s + state.players[id].contract.salary, 0)
}

export function signPlayer(state: GameState, p: Player, t: Team, salary: number, years: number, kind: Player['contract']['kind']) {
  const old = state.teams[p.teamId]
  if (old) old.roster = old.roster.filter((id) => id !== p.id)
  p.teamId = t.id
  p.contract = { salary, years, kind }
  t.roster.push(p.id)
  // 背番号: 空いている番号
  const used = new Set(t.roster.filter((id) => id !== p.id).map((id) => state.players[id].jersey))
  if (used.has(p.jersey)) for (let n = 0; n < 100; n++) if (!used.has(n)) {
    p.jersey = n
    break
  }
}

export function releasePlayer(state: GameState, p: Player) {
  const t = state.teams[p.teamId]
  if (t) t.roster = t.roster.filter((id) => id !== p.id)
  p.teamId = -1
  p.contract = { salary: 0, years: 0, kind: 'none' }
}

/** AI のチームの人数を合わせる（多ければ外し、少なければ FA から） */
export function fillRosters(state: GameState, rng: Rng) {
  const abs = absWeekOf(state.season, state.week)
  const age = (p: Player) => ageAt(abs, p.birthAbs)
  // 多すぎるチーム
  const clubId = state.club?.teamId ?? -1
  for (const t of state.teams) {
    if (t.league === 'NCAA' || t.id === clubId) continue
    const [, max] = ROSTER_RANGE[t.league]
    while (t.roster.length > max) {
      const cands = t.roster.map((id) => state.players[id]).filter((p) => !p.isPlayer && !p.castId)
      if (!cands.length) break
      const worst = cands.sort((a, b) => playerValue(a, age(a)) - playerValue(b, age(b)))[0]
      releasePlayer(state, worst)
    }
  }
  const fa = Object.values(state.players)
    .filter((p) => p.teamId < 0 && !p.isPlayer && !p.retired)
    .sort((a, b) => playerValue(b, age(b)) - playerValue(a, age(a)))
  const take = (pred: (p: Player) => boolean): Player | undefined => {
    const i = fa.findIndex(pred)
    return i >= 0 ? fa.splice(i, 1)[0] : undefined
  }
  // NBA → 国内 1 部 → 2 部 → 3 部 → 育成の順に、足りないチームが取る
  const order: LeagueId[] = ['NBA', 'JBL1', 'JBL2', 'JBL3', 'DEV']
  for (const lg of order) {
    const teams = state.leagues[lg].teamIds.map((id) => state.teams[id])
    for (const t of rng.shuffle([...teams])) {
      // クラブ経営: 自分のクラブは自分で集める（10 人を切ったときだけ、リーグが選手を回す）
      const [min] = t.id === clubId ? [10] : ROSTER_RANGE[lg]
      let guard = 0
      while (t.roster.length < min && guard++ < 20) {
        let p: Player | undefined
        if (lg === 'NBA') {
          const room = NBA_CAP - payroll(state, t)
          p = take((x) => ovr(x) >= 58 && (nbaMarketSalary(ovr(x)) <= Math.max(room, NBA_MIN) || ovr(x) <= 66))
          if (p) {
            const salary = Math.max(NBA_MIN, Math.min(nbaMarketSalary(ovr(p)), Math.max(room, NBA_MIN)))
            signPlayer(state, p, t, salary, age(p) >= 31 ? 1 : rng.int(1, 3), salary <= NBA_MIN ? 'min' : 'standard')
          }
        } else if (lg === 'DEV') {
          p = take((x) => ovr(x) <= 64)
          if (p) signPlayer(state, p, t, DEV_SALARY, 1, 'dev')
        } else {
          const ceil = JBL_CEIL[lg]!
          const ps = t.roster.map((id) => state.players[id])
          // 3 部の AI のクラブはお金が少ないので、外国籍は 2 人まで（決まりの上限は 3。3 人にすると 3 部が 2 部に迫った: 8 季で 2 部との差 8 → 4）
          const needForeign = ps.filter(isForeignSlot).length < (lg === 'JBL3' ? 2 : JBL_FOREIGN_MAX)
          const needAsia = lg !== 'JBL3' && !ps.some((x) => ASIA.has(x.nation))
          p =
            (needForeign ? take((x) => isForeignSlot(x) && ovr(x) <= ceil.foreign) : undefined) ??
            (needAsia ? take((x) => ASIA.has(x.nation) && ovr(x) <= ceil.foreign - 4) : undefined) ??
            take((x) => x.nation === 'JP' && ovr(x) <= ceil.jp)
          if (p) signPlayer(state, p, t, jblMarketSalary(ovr(p), p.nation !== 'JP', lg), rng.int(1, 2), 'pro')
        }
        if (!p) break
      }
    }
  }
}

/** FA を補充する（シーズンのはじめ。引退で減った分を、若手の外国籍と日本人で） */
export function topUpFreeAgents(state: GameState, rng: Rng, target = 120) {
  const fa = Object.values(state.players).filter((p) => p.teamId < 0 && !p.isPlayer && !p.retired).length
  for (let i = fa; i < target; i++) {
    const foreign = rng.chance(0.75)
    const nation: Nation = foreign ? NBA_NATION_MIX.codes[rng.weighted(NBA_NATION_MIX.weights)] : 'JP'
    const o = Math.round(foreign ? Math.max(48, Math.min(68, rng.normal(59, 4.5))) : Math.max(36, Math.min(58, rng.normal(46, 5))))
    generatePlayer(state, rng, { nation: nation === 'JP' && foreign ? 'US' : nation, age: rng.int(22, 27), ovr: o })
  }
}
