/**
 * 試合の準備: GameState のチームから、試合に出る選手の写し（PlayerInput）を作る。
 * ケガの選手は出ない。試合のベンチに入るのは NBA 13 人・ほか 12 人（総合値の上から。rotation.ts の gameDaySize）。調子で能力が ±3 ほど、疲れで最初の体力が下がる。
 */
import { hashSeed } from '../core/prng'
import { ATTR_KEYS } from '../data/attributes'
import type { GameState } from '../models/game'
import type { Fixture, Team } from '../models/league'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'
import type { MatchSetup, PlayerInput, TeamInput } from './types'
import { gameDaySize } from './rotation'
import { clubDepth, clubMatchBonus } from '../club/effects'
import { recommendTactics } from '../club/advice'

const ASIA = new Set(['PH', 'KR', 'CN'])

export function playerInput(p: Player): PlayerInput {
  const cond = ((p.condition - 50) / 50) * 3
  const attr = { ...p.attr }
  for (const k of ATTR_KEYS) attr[k] = attr[k] + cond
  return {
    id: p.id,
    name: p.name,
    short: p.short,
    jersey: p.jersey,
    pos: p.pos,
    style: p.style,
    nation: p.nation,
    heightCm: p.heightCm,
    wingspanCm: p.wingspanCm,
    skills: Object.fromEntries(p.skills.map((s) => [s, true])),
    ovr: ovr(p),
    attr,
    energy: Math.max(55, 100 - p.fatigue * 0.35),
    foreignSlot: p.nation !== 'JP' && !ASIA.has(p.nation),
  }
}

export function teamInput(state: GameState, team: Team): TeamInput {
  const active = gameDaySize(team.league)
  // 主人公は監督の評価で序列が上下する（出場時間）
  // （並べる前に 1 回ずつ計算しておく。並べ替えの比較のたびに総合値を出すと重い）
  const orderOf = new Map<number, number>()
  const order = (p: Player) => {
    let v = orderOf.get(p.id)
    if (v === undefined) {
      v = ovr(p) + (p.isPlayer && state.career ? (state.career.trust - 50) / 4 : 0)
      orderOf.set(p.id, v)
    }
    return v
  }
  const all = team.roster
    .map((id) => state.players[id])
    .filter((p) => !p.injury)
    .sort((a, b) => order(b) - order(a))
  // 主人公: 監督の評価が 40 以上なら、ローテーション（9 番手）には入れてもらえる。
  // 登録の人数（active）で切る前に当てる（前は大学の 15 人から 12 人を選んだあとだったので、13 番手以下の 1 年生は 1 試合も出られなかった）
  const mi = all.findIndex((p) => p.isPlayer)
  if (mi >= 8 && state.career && state.career.trust >= 40) {
    orderOf.set(all[mi].id, Math.max(order(all[mi]), order(all[7]) + 0.5))
    all.sort((a, b) => order(b) - order(a))
  }
  const sorted = all.slice(0, active)
  const players = sorted.map((p) => {
    const x = { ...playerInput(p), ovr: Math.round(order(p)) }
    // メンタルコーチ: 勝負強さ +6
    if (p.isPlayer && state.career?.services?.includes('mental')) x.attr = { ...x.attr, clutch: x.attr.clutch + 6 }
    return x
  })
  // クラブ経営: 自分のクラブは、監督（あなた）が決めた序列と、分析室・HC の上乗せ
  if (state.club && team.id === state.club.teamId) {
    const depth = clubDepth(state)
    const bonus = clubMatchBonus(state)
    const byId = new Map(team.roster.map((id) => state.players[id]).filter((p) => !p.injury).map((p) => [p.id, p]))
    const ordered = depth.filter((id) => byId.has(id)).slice(0, active)
    const clubPlayers = ordered.map((id, i) => {
      const x = playerInput(byId.get(id)!)
      const attr = { ...x.attr }
      for (const k of ATTR_KEYS) attr[k] = Math.min(99, attr[k] + bonus)
      return { ...x, attr, depth: i }
    })
    return { teamId: team.id, name: team.name, short: team.short, abbr: team.abbr, colors: team.colors, tactics: team.tactics, players: clubPlayers }
  }
  return { teamId: team.id, name: team.name, short: team.short, abbr: team.abbr, colors: team.colors, tactics: team.tactics, players }
}

/** 日程の試合から準備する */
export function fixtureSetup(state: GameState, f: Fixture, opts: { focusPlayerId?: number } = {}): MatchSetup {
  const home = state.teams[f.home]
  const away = state.teams[f.away]
  const rules = state.leagues[f.league].rules
  const hi = teamInput(state, home)
  const ai = teamInput(state, away)
  // クラブ経営: 作戦がおまかせなら、この相手に合わせたおすすめの作戦で
  const c = state.club
  if (c?.autoTactics && (f.home === c.teamId || f.away === c.teamId)) {
    const mine = f.home === c.teamId ? hi : ai
    mine.tactics = { ...recommendTactics(state, f.home === c.teamId ? f.away : f.home).tactics }
  }
  return {
    home: hi,
    away: ai,
    rules,
    seed: hashSeed(state.seed, f.id),
    big: f.kind === 'playoff' || (f.kind === 'cup' && !!f.neutral),
    focusPlayerId: opts.focusPlayerId,
    foreignLimit: f.league === 'JBL1' || f.league === 'JBL2' || f.league === 'JBL3',
  }
}

/** 練習試合（好きな 2 チーム） */
export function exhibitionSetup(state: GameState, homeId: number, awayId: number, seed: number): MatchSetup {
  const home = state.teams[homeId]
  const away = state.teams[awayId]
  // ルールはホームのリーグのもの（大学どうしなら大学のルール）
  const rules = state.leagues[home.league].rules
  return { home: teamInput(state, home), away: teamInput(state, away), rules, seed, foreignLimit: home.league.startsWith('JBL') && away.league.startsWith('JBL') }
}
