/**
 * 子どもの世代へ（二代目のキャリア）: 引退した主人公の息子（8 歳でバスケを始めると決めた子）が 18 歳になったら、同じ世界でその子のキャリアを始める。
 *   候補: plays の息子（このゲームのリーグは男子なので、娘は候補にしない）
 *   早送り: 画面（CareerEndScreen）で、子が 18 歳になるシーズンのはじめまで週を進める（引退したキャリアは何もしない）
 *   引き継ぎ（親の評価で）: 知名度・NBA の注目度・経験点の入り方（heritage）・持ち家・仕送り（貯金の 2%、1 億円まで）
 *   登場人物: 親の世代のヒロインや仲間は年が離れているので、おでかけで会わない・デートしない（castLines の castAge で判定）。
 *     代理人の藤堂と恩師の黒田とは、最初から顔見知り。親（前の主人公）は節目に話しに来る（話し手 'parent'）
 * 会話の id: heir:intro・heir:join・heir:drafted・heir:nba・heir:allstar
 */
import { createRng, hashSeed } from '../core/prng'
import { absWeekOf, ageAt, WEEKS_PER_SEASON } from '../core/calendar'
import type { GameState } from '../models/game'
import type { LineageEntry } from '../models/career'
import { releasePlayer } from '../transfer/freeAgency'
import { addProtagonist, makeRookieOffers, newCareerState, type CareerNewOptions } from './create'
import { careerSummary } from './retire'
import type { Talk, TalkLine } from './talks'

/** 二代目の候補（バスケを続けた息子）と、18 歳になるまでのシーズン */
export function heirCandidates(state: GameState): { index: number; name: string; age: number; seasons: number }[] {
  const c = state.career
  if (!c || c.retiredAt === undefined) return []
  const now = absWeekOf(state.season, state.week)
  return (c.children ?? [])
    .map((ch, index) => ({ ch, index }))
    .filter(({ ch }) => ch.plays && ch.sex === 'm')
    .map(({ ch, index }) => ({ index, name: ch.name, age: ageAt(now, ch.birthAbs), seasons: heirSeason(state, index) - state.season }))
}

/** その子が 18 歳になっている、いちばん早いシーズン（のはじめ） */
export function heirSeason(state: GameState, index: number): number {
  const ch = state.career!.children![index]
  let s = state.season + (state.week > 0 ? 1 : 0)
  while (ageAt(absWeekOf(s, 0), ch.birthAbs) < 18) s++
  return s
}

const BONUS: Record<string, { fame: number; interest: number; heritage: number }> = {
  S: { fame: 22, interest: 12, heritage: 1.08 },
  A: { fame: 16, interest: 9, heritage: 1.06 },
  B: { fame: 11, interest: 6, heritage: 1.04 },
  C: { fame: 7, interest: 4, heritage: 1.02 },
}

/** 二代目を始める（早送りが済んで、子が 18 歳のシーズンのはじめ） */
export function startHeir(state: GameState, index: number, o: Omit<CareerNewOptions, 'seed'>) {
  const old = state.career!
  const child = old.children![index]
  const parent = state.players[old.playerId]
  const sum = careerSummary(state)
  const entry: LineageEntry = {
    name: parent.name,
    short: parent.short,
    photo: parent.photo,
    pos: parent.pos,
    heightCm: parent.heightCm,
    grade: sum.grade,
    hallOfFame: sum.hallOfFame,
    nbaSeasons: sum.nbaSeasons,
    allStar: sum.allStar,
    rings: sum.rings,
    mvp: sum.mvp,
    seasons: [old.startSeason ?? 0, old.retiredAt ?? state.season],
    spouse: old.spouse,
  }
  // 親は世界から退く（記録は残る）
  if (parent.teamId >= 0) releasePlayer(state, parent)
  parent.isPlayer = false
  parent.retired = true
  // 子
  const rng = createRng(hashSeed(state.seed, state.season, 0x4e1))
  const p = addProtagonist(state, o, child.birthAbs, rng)
  const c = newCareerState(p, o)
  const b = BONUS[sum.grade] ?? { fame: 4, interest: 2, heritage: 1 }
  c.startSeason = state.season
  c.lineage = [...(old.lineage ?? []), entry]
  c.heritage = b.heritage
  c.fame = 5 + b.fame
  c.nbaInterest = 3 + b.interest
  c.money = 50 + Math.min(10000, Math.round(Math.max(0, old.money) * 0.02))
  c.ownedHomes = old.ownedHomes ? [...old.ownedHomes] : undefined
  c.met = ['todo_maiko', 'kuroda_takeshi']
  c.bonds = { todo_maiko: 30, kuroda_takeshi: 30 }
  c.talks = [{ id: 'heir:intro', speaker: 'todo_maiko' }]
  state.career = c
  makeRookieOffers(state, rng)
}

/** 親の会話を積む（二代目のときだけ・1 回ずつ） */
export function pushHeirTalk(state: GameState, event: 'join' | 'drafted' | 'nba' | 'allstar') {
  const c = state.career
  if (!c?.lineage?.length) return
  const id = `heir:${event}`
  if (c.seen.includes(id) || c.talks.some((t) => t.id === id)) return
  c.talks.push({ id, speaker: 'parent' })
}

/** いちばん近い親 */
export const parentOf = (state: GameState): LineageEntry | undefined => state.career?.lineage?.[state.career.lineage.length - 1]

const L = (who: string, ...texts: string[]): TalkLine[] => texts.map((t) => (t.startsWith('me:') ? { who: 'me', text: t.slice(3) } : { who, text: t }))

export function heirTalkOf(id: string, state?: GameState): Talk | null {
  const par = state && parentOf(state)
  if (!par) return null
  const [, ev] = id.split(':')
  const star = par.allStar > 0 || par.grade === 'S' || par.grade === 'A'
  if (ev === 'intro')
    return {
      title: '二代目',
      lines: [
        ...L('todo_maiko', '{name}くん、はじめまして……と言うのは変かしら。小さいころ、何度も会っているのよ', `お父さんの代理人をしていた藤堂よ。${par.short}さんがプロに入った日のこと、昨日のことみたいに覚えてる`),
        ...L('parent', star ? '……プレッシャーは感じなくていい。お前はお前のバスケをすればいい' : 'お前は、俺よりずっと遠くまで行ける。……自分の道を選べ'),
        ...L('todo_maiko', 'me:……父さんを超えるために、ここに来ました', 'いい目ね。あの日のお父さんと同じ。日本のプロか、アメリカの大学か。話は 3 つずつ届いているわ'),
      ],
    }
  if (ev === 'join') return { title: '父の言葉', lines: L('parent', '入団、おめでとう。……最初の 1 年は、思うようにいかないことの方が多い', 'それでいい。下を向いた日の練習が、いちばん効くんだ', 'me:……うん。見てて') }
  if (ev === 'drafted') return { title: '父の言葉', lines: L('parent', par.nbaSeasons > 0 ? 'ドラフトで名前を呼ばれたあの瞬間……お前も、同じ景色を見たんだな' : '俺が届かなかった場所に、お前は呼ばれた', '親子で同じ夢を見られて、本当に幸せだ') }
  if (ev === 'nba') return { title: '父の言葉', lines: L('parent', par.nbaSeasons > 0 ? 'NBA の床は、思ったより硬いだろう？ 毎晩、体のケアを忘れるな' : 'NBA か……。お前は、本当にすごいところまで来たな', 'me:父さんがいたから、ここまで来られた') }
  if (ev === 'allstar') return { title: '父の言葉', lines: L('parent', par.allStar > 0 ? `オールスターか。俺は ${par.allStar} 回だった。……抜かれる日が楽しみだ` : 'オールスター……。俺には一度も届かなかった舞台だ', '胸を張って、楽しんでこい') }
  return null
}

/** 何代目か（1 が最初の主人公） */
export const generationOf = (state: GameState) => (state.career?.lineage?.length ?? 0) + 1

export const HEIR_WEEKS = WEEKS_PER_SEASON
