/**
 * クラブの経営の操作と計算: お金（観客・チケット・グッズ・スポンサー・年俸・維持費）、工事（施設・増席・アリーナの格）、
 * スタッフ（候補・契約）、スポンサー（話・契約）。画面からは useGame().mutate で呼ぶ。
 * 乱数はシード付き（候補・話はシーズンと枠で決まる）。
 */
import { WEEKS_PER_SEASON, absWeekOf } from '../core/calendar'
import { createRng, hashSeed } from '../core/prng'
import { FACILITY_DEFS, FACILITY_MAX, GRADE_WEEKS, HOMETOWN_BY_ID, LEAGUE_DIST, OPS_COST, SEAT_STEPS, SPONSOR_BASE, SPONSOR_SLOTS, SPONSOR_SLOT_DEFS, STAFF_DEFS, STAFF_ROLES, TICKET_PRICE, TRAVEL_COST, companyName, facilityCost, facilityWeeks, gradeCost, staffSalary, TICKET_LEVELS, GOODS_CAMPAIGNS, GOODS_MUL, GOODS_FULL_FANS, LICENSE_SEATS } from '../data/club'
import { generateName, type Nation } from '../data/nations'
import type { ClubLedger, ClubSponsor, FacilityId, SponsorOffer, SponsorSlot, Staff, StaffRole } from '../models/club'
import { allocId, type GameState } from '../models/game'
import { marketPop, subTownUpkeepTotal } from './fans'
import type { Fixture, LeagueId, Team } from '../models/league'

export const clubTeam = (state: GameState): Team => state.teams[state.club!.teamId]

/** 今週の、まだ行っていない自分の試合（曜日の順） */
export function clubFixtures(state: GameState): Fixture[] {
  const id = state.club!.teamId
  return state.fixtures.filter((f) => f.week === state.week && !f.result && (f.home === id || f.away === id)).sort((a, b) => a.day - b.day || a.id - b.id)
}
const leagueOf = (state: GameState) => clubTeam(state).league

// ---------------------------------------------------------------- お金

/** 1 試合の観客（人）。mul はプレーオフなど */
export function attendance(state: GameState, opp: Team, mul = 1, rnd = 1, level = ticketLevelOf(state)): number {
  const c = state.club!
  const team = clubTeam(state)
  const town = HOMETOWN_BY_ID[c.hometown]
  const base = c.fans * (0.1 + c.popularity * 0.0022) * (0.85 + c.arenaGrade * 0.06) * (0.9 + opp.rep / 250) * (0.92 + town.passion * 0.03)
  return Math.round(Math.min(team.arena.capacity, base * mul * rnd * level.crowd))
}

/** 今のチケットの段 */
export const ticketLevelOf = (state: GameState) => TICKET_LEVELS[state.club!.ticketLevel ?? 1] ?? TICKET_LEVELS[1]

/** チケットの平均単価（万円/人）: アリーナの格が高いほど高く売れる */
export function ticketPrice(state: GameState, level = ticketLevelOf(state)): number {
  return (TICKET_PRICE[leagueOf(state)] ?? 0.2) * (0.85 + state.club!.arenaGrade * 0.12) * level.price
}

/** 年俸の合計（万円/年） */
export function payrollOf(state: GameState): number {
  return clubTeam(state).roster.reduce((s, id) => s + state.players[id].contract.salary, 0)
}

export function staffPayroll(state: GameState): number {
  const c = state.club!
  return STAFF_ROLES.reduce((s, r) => s + (c.staff[r]?.salary ?? 0), 0)
}

/** 施設とアリーナの維持費（万円/年）。近くの街の会場費も入る */
export function upkeepOf(state: GameState): number {
  const c = state.club!
  const fac = Object.values(c.facilities).reduce((s, lv) => s + lv ** 1.4 * 110, 0)
  return Math.round(fac + clubTeam(state).arena.capacity * 0.12 + c.arenaGrade * 250 + subTownUpkeepTotal(state))
}

export function sponsorIncome(state: GameState): number {
  return state.club!.sponsors.reduce((s, x) => s + x.annual, 0)
}

/** グッズの売り上げの元（企画なし・万円/年）: ファン × 人気 × 広報室 × リーグの倍率（NBA は 100 万人より上のファンは 4 割で数える） */
function goodsBase(state: GameState): number {
  const c = state.club!
  const lg = leagueOf(state)
  const fans = lg === 'NBA' ? Math.min(c.fans, GOODS_FULL_FANS) + Math.max(0, c.fans - GOODS_FULL_FANS) * 0.4 : c.fans
  return fans * 0.12 * (0.6 + c.popularity / 100) * (1 + c.facilities.pr * 0.08) * (GOODS_MUL[lg] ?? 1)
}

/** グッズの売上（万円/年） */
export function goodsIncome(state: GameState): number {
  return Math.round(goodsBase(state) * goodsMul(state))
}

/** グッズの企画の倍率（期間中だけ） */
export function goodsMul(state: GameState): number {
  const g = state.club!.goods
  if (!g || g.until < absWeekOf(state.season, state.week)) return 1
  return GOODS_CAMPAIGNS.find((x) => x.id === g.id)?.mul ?? 1
}

/** グッズの企画の費用: 期間中に増える売り上げの 6 割（元がとれる） */
export function goodsCost(state: GameState, id: string): number {
  const d = GOODS_CAMPAIGNS.find((x) => x.id === id)
  if (!d) return 0
  const base = Math.round(goodsBase(state))
  return Math.max(50, Math.round((base * (d.mul - 1) * d.weeks) / WEEKS_PER_SEASON * 0.6 / 10) * 10)
}

/** グッズの企画を始める（ほかの企画の期間中はできない） */
export function startGoods(state: GameState, id: string): string | null {
  const c = state.club!
  const d = GOODS_CAMPAIGNS.find((x) => x.id === id)
  if (!d) return 'ない'
  const now = absWeekOf(state.season, state.week)
  if (c.goods && c.goods.until >= now) return 'ほかの企画の期間中'
  const cost = goodsCost(state, id)
  if (c.money < cost) return '資金が足りない'
  c.money -= cost
  currentLedger(state).other -= cost
  c.goods = { id, until: now + d.weeks - 1 }
  c.popularity = Math.min(100, c.popularity + d.pop)
  state.news.push({ season: state.season, week: state.week, text: `グッズの企画「${d.name}」を始めた（${d.weeks} 週）` })
  return null
}

/** 1 年の収支の見込み（画面の財務。チケットは今の観客の見込みで） */
export function yearlyOutlook(state: GameState): { ticket: number; dist: number; sponsor: number; goods: number; wages: number; staff: number; upkeep: number; travel: number; ops: number; net: number; perGame: number } {
  const lg = leagueOf(state)
  const games = lg === 'NBA' ? 41 : 30
  const avgOpp = { rep: 40 } as Team
  const perGame = attendance(state, avgOpp)
  const ticket = Math.round(perGame * games * ticketPrice(state))
  const dist = LEAGUE_DIST[lg] ?? 0
  const sponsor = sponsorIncome(state)
  const goods = goodsIncome(state)
  const wages = payrollOf(state)
  const staff = staffPayroll(state)
  const upkeep = upkeepOf(state)
  const travel = TRAVEL_COST[lg] ?? 0
  const ops = OPS_COST[lg] ?? 0
  return { ticket, dist, sponsor, goods, wages, staff, upkeep, travel, ops, net: ticket + dist + sponsor + goods - wages - staff - upkeep - travel - ops, perGame }
}

export function emptyLedger(abs: number): ClubLedger {
  return { abs, ticket: 0, dist: 0, sponsor: 0, goods: 0, prize: 0, wages: 0, staff: 0, upkeep: 0, travel: 0, build: 0, transfer: 0, other: 0 }
}

export function ledgerNet(l: ClubLedger): number {
  return l.ticket + l.dist + l.sponsor + l.goods + l.prize + (l.transfer ?? 0) + l.other - l.wages - l.staff - l.upkeep - l.travel - l.build
}

/** 今の週の帳簿（なければ作る）。工事の支払いなど、週の途中の出入りもここへ */
export function currentLedger(state: GameState): ClubLedger {
  const c = state.club!
  const abs = absWeekOf(state.season, state.week)
  let l = c.ledger.find((x) => x.abs === abs)
  if (!l) {
    l = emptyLedger(abs)
    c.ledger.push(l)
    c.ledger.sort((a, b) => a.abs - b.abs)
    if (c.ledger.length > 104) c.ledger.splice(0, c.ledger.length - 104)
  }
  return l
}

/** 1 週の定期の出入り（試合の入場料は別に足す） */
export function weeklyBooks(state: GameState, l: ClubLedger) {
  const lg = leagueOf(state)
  const per = (v: number) => Math.round(v / WEEKS_PER_SEASON)
  l.dist += per(LEAGUE_DIST[lg] ?? 0)
  l.sponsor += per(sponsorIncome(state))
  l.goods += per(goodsIncome(state))
  l.wages += per(payrollOf(state))
  l.staff += per(staffPayroll(state))
  l.upkeep += per(upkeepOf(state))
  l.travel += per(TRAVEL_COST[lg] ?? 0)
  l.other -= per(OPS_COST[lg] ?? 0)
}

// ---------------------------------------------------------------- 工事

export function canBuild(state: GameState, kind: 'facility' | 'arena'): boolean {
  const c = state.club!
  return !c.building.some((b) => (kind === 'facility' ? b.kind === 'facility' : b.kind !== 'facility'))
}

export function facilityUpgrade(state: GameState, id: FacilityId): { cost: number; weeks: number; to: number } | null {
  const lv = state.club!.facilities[id]
  if (lv >= FACILITY_MAX) return null
  return { cost: facilityCost(id, lv + 1), weeks: facilityWeeks(lv + 1), to: lv + 1 }
}

/**
 * 上の部のライセンス（席数）の見込み。上の部がない（1 部・NBA）か、もう足りていれば null。
 *   building: 足りる席数への工事中なら、その完成の週（シーズンの中の週）。late: 今から工事しても今季の終わり（第 51 週）に間に合わない
 */
export function licenseOutlook(state: GameState): { up: LeagueId; need: number; seats: number; building?: number; late: boolean } | null {
  const team = clubTeam(state)
  const up: LeagueId | null = team.league === 'JBL3' ? 'JBL2' : team.league === 'JBL2' ? 'JBL1' : null
  if (!up) return null
  const need = LICENSE_SEATS[up] ?? 0
  if (team.arena.capacity >= need) return null
  const b = state.club!.building.find((x) => x.kind === 'seats' && x.to >= need)
  const building = b ? b.doneAbs - absWeekOf(state.season, 0) : undefined
  const next = seatUpgrade(state)
  const late = building === undefined && (!next || state.week + next.weeks > 51)
  return { up, need, seats: team.arena.capacity, building, late }
}

export function seatUpgrade(state: GameState): (typeof SEAT_STEPS)[number] | null {
  const cap = clubTeam(state).arena.capacity
  return SEAT_STEPS.find((s) => s.seats > cap) ?? null
}

export function gradeUpgrade(state: GameState): { cost: number; weeks: number; to: number } | null {
  const g = state.club!.arenaGrade
  if (g >= 5) return null
  return { cost: gradeCost(g + 1), weeks: GRADE_WEEKS, to: g + 1 }
}

/** 工事の中身（費用・週・完成したときの値・名前） */
function buildPlan(state: GameState, kind: 'facility' | 'seats' | 'grade', facility?: FacilityId): { cost: number; weeks: number; to: number; label: string } | null {
  if (kind === 'facility') {
    const u = facilityUpgrade(state, facility!)
    return u && { ...u, label: `${FACILITY_DEFS[facility!].name}を Lv${u.to} に` }
  }
  if (kind === 'seats') {
    const u = seatUpgrade(state)
    return u && { cost: u.cost, weeks: u.weeks, to: u.seats, label: `${u.label}（${u.seats.toLocaleString()} 席）` }
  }
  const u = gradeUpgrade(state)
  return u && { ...u, label: `アリーナの格を ${u.to} に` }
}

/** 工事を始める（費用はその場で払う） */
export function startBuild(state: GameState, kind: 'facility' | 'seats' | 'grade', facility?: FacilityId): boolean {
  const c = state.club!
  const abs = absWeekOf(state.season, state.week)
  if (!canBuild(state, kind === 'facility' ? 'facility' : 'arena')) return false
  const plan = buildPlan(state, kind, facility)
  if (!plan || c.money < plan.cost) return false
  const { cost, weeks, to, label } = plan
  c.money -= cost
  currentLedger(state).build += cost
  c.building.push({ kind, facility, label, doneAbs: abs + weeks, cost, to })
  return true
}

/** 完成した工事を反映する（毎週） */
export function finishBuilds(state: GameState, abs: number): string[] {
  const c = state.club!
  const done: string[] = []
  c.building = c.building.filter((b) => {
    if (b.doneAbs > abs) return true
    if (b.kind === 'facility') c.facilities[b.facility!] = b.to
    else if (b.kind === 'seats') {
      const team = clubTeam(state)
      team.arena.capacity = b.to
      if (b.to >= 8000 && !team.arena.name.includes('アリーナ')) team.arena.name = `${team.city}アリーナ`
    } else c.arenaGrade = b.to
    done.push(b.label)
    return false
  })
  return done
}

// ---------------------------------------------------------------- スタッフ

const STAFF_NATION: Nation[] = ['JP', 'JP', 'JP', 'JP', 'US', 'RS', 'ES', 'AU']

/** そのシーズンのスタッフの候補（5 人ずつ。シーズンと役で決まる） */
export function staffCandidates(state: GameState, role: StaffRole): Staff[] {
  const c = state.club!
  const rng = createRng(hashSeed(state.seed, state.season, STAFF_ROLES.indexOf(role), 0x57af))
  const lg = leagueOf(state)
  const center = lg === 'JBL1' ? 62 : lg === 'JBL2' ? 52 : lg === 'NBA' ? 75 : 45
  const out: Staff[] = []
  for (let i = 0; i < 5; i++) {
    const skill = Math.round(Math.max(30, Math.min(95, rng.normal(center + (i - 2) * 6 + c.popularity * 0.08, 6))))
    const nation = role === 'hc' ? rng.pick(STAFF_NATION) : rng.chance(0.85) ? 'JP' : rng.pick(STAFF_NATION)
    const name = generateName(nation, rng).full
    const salary = Math.round((staffSalary(role, skill) * (lg === 'NBA' ? 8 : 1) * rng.range(0.9, 1.1)) / 10) * 10
    out.push({ name, role, skill, salary, years: rng.int(1, 3), note: rng.pick(STAFF_DEFS[role].notes) })
  }
  return out.sort((a, b) => b.skill - a.skill)
}

/** スタッフと契約する（今の人とは契約を終える）。契約金として年俸の半分をその場で払う */
export function hireStaff(state: GameState, s: Staff): boolean {
  const c = state.club!
  const fee = Math.round(s.salary / 2)
  if (c.money < fee) return false
  c.money -= fee
  currentLedger(state).other -= fee
  c.staff[s.role] = { ...s }
  if (s.role === 'hc') clubTeam(state).coach = { name: s.name, skill: s.skill }
  return true
}

/** シーズンの終わり: 契約の年数を減らし、満了のスタッフは去る（HC がいなくなれば、つなぎの HC を置く） */
export function staffSeasonEnd(state: GameState): string[] {
  const c = state.club!
  const out: string[] = []
  for (const r of STAFF_ROLES) {
    const s = c.staff[r]
    if (!s) continue
    s.years--
    if (s.years > 0) continue
    out.push(`${STAFF_DEFS[r].name}の${s.name}が契約満了で去った`)
    delete c.staff[r]
  }
  if (!c.staff.hc) {
    const rng = createRng(hashSeed(state.seed, state.season, 0x1c))
    const s: Staff = { name: generateName('JP', rng).full, role: 'hc', skill: 40, salary: staffSalary('hc', 40), years: 1, note: 'つなぎの監督' }
    c.staff.hc = s
    clubTeam(state).coach = { name: s.name, skill: s.skill }
  }
  return out
}

// ---------------------------------------------------------------- スポンサー

/** 枠ごとの相場（年額） */
export function sponsorValue(state: GameState, slot: SponsorSlot): number {
  const c = state.club!
  // NBA では日本じゅうの会社が相手（ホームタウンの大きさは関係ない）。近くの街は人口の半分として数える
  const market = leagueOf(state) === 'NBA' ? 1.3 : Math.min(1.3, 0.7 + marketPop(state) / 150)
  return (SPONSOR_BASE[leagueOf(state)] ?? 2000) * SPONSOR_SLOT_DEFS[slot].mul * (0.6 + c.popularity / 75) * market * (1 + c.facilities.pr * 0.05)
}

/** 空いている枠にスポンサーの話を作る（各枠 2 社。シーズンと枠で決まる） */
export function makeSponsorOffers(state: GameState) {
  const c = state.club!
  const rng = createRng(hashSeed(state.seed, state.season, state.week, 0x5905))
  c.sponsorOffers = []
  for (const slot of SPONSOR_SLOTS) {
    if (c.sponsors.some((s) => s.slot === slot)) continue
    for (let i = 0; i < 2; i++) {
      const annual = Math.round((sponsorValue(state, slot) * rng.range(0.8, 1.2)) / 10) * 10
      const years = rng.int(1, 3)
      // 長い契約は少し安い
      const offer: SponsorOffer = { id: allocId(state), slot, company: companyName(rng.int(0, 99), rng.int(0, 99)), annual: Math.round((annual * (years === 1 ? 1.05 : years === 3 ? 0.92 : 1)) / 10) * 10, until: state.season + years - 1 }
      c.sponsorOffers.push(offer)
    }
  }
}

export function acceptSponsor(state: GameState, offerId: number): boolean {
  const c = state.club!
  const o = c.sponsorOffers.find((x) => x.id === offerId)
  if (!o || c.sponsors.some((s) => s.slot === o.slot)) return false
  const s: ClubSponsor = { slot: o.slot, company: o.company, annual: o.annual, until: o.until }
  c.sponsors.push(s)
  c.sponsorOffers = c.sponsorOffers.filter((x) => x.slot !== o.slot)
  return true
}

// ---------------------------------------------------------------- 序列

/** 序列を動かす（d = -1 で上へ、+1 で下へ） */
export function moveDepth(state: GameState, ids: number[], playerId: number, d: -1 | 1) {
  const c = state.club!
  const order = [...ids]
  const i = order.indexOf(playerId)
  const j = i + d
  if (i < 0 || j < 0 || j >= order.length) return
  ;[order[i], order[j]] = [order[j], order[i]]
  c.depth = order
  // 手で動かしたら、おまかせは止める
  c.autoDepth = false
}
