/**
 * キャリアモードの定義: 経験点 5 種・毎週の過ごし方・おでかけ先。解説（画面に出す）もここ。
 */
import type { AttrKey } from './attributes'

/** 経験点の種類と、伸ばせる能力 */
export const EXP_KINDS = ['shoot', 'skill', 'phys', 'def', 'mind'] as const
export type ExpKind = (typeof EXP_KINDS)[number]

export const EXP_DEFS: Record<ExpKind, { name: string; color: string; attrs: AttrKey[] }> = {
  shoot: { name: 'シュート', color: '#ff7a1a', attrs: ['close', 'mid', 'three', 'ft'] },
  skill: { name: 'テクニック', color: '#3aa0ff', attrs: ['layup', 'dunk', 'post', 'handle', 'pass'] },
  phys: { name: 'フィジカル', color: '#3ddc84', attrs: ['speed', 'quick', 'jump', 'strength', 'stamina'] },
  def: { name: 'ディフェンス', color: '#ff5a7a', attrs: ['perD', 'intD', 'steal', 'block', 'oreb', 'dreb'] },
  mind: { name: 'メンタル', color: '#f5c542', attrs: ['vision', 'iq', 'clutch'] },
}

/** 能力 → 経験点の種類 */
export const EXP_OF: Record<AttrKey, ExpKind> = Object.fromEntries(EXP_KINDS.flatMap((k) => EXP_DEFS[k].attrs.map((a) => [a, k]))) as Record<AttrKey, ExpKind>

/** 毎週の過ごし方 */
export const ACTIONS = ['shooting', 'handling', 'physical', 'defense', 'inside', 'film', 'rest', 'extra', 'outing', 'date', 'camp'] as const
export type ActionId = (typeof ACTIONS)[number]

export interface ActionDef {
  name: string
  desc: string
  /** 経験点（チーム練習の基本。試合の多い週は少し減る） */
  exp: Partial<Record<ExpKind, number>>
  /** 疲れ（+ で増える） */
  fatigue: number
  /** 調子 */
  condition: number
  /** 練習の種類（監督の評価・かんたん育成の重み） */
  practice: boolean
}

