/**
 * 引退（キャリア）。
 *   33 歳から毎シーズン第 37 週のあとに代理人と相談（続ける／今季限り）。39 歳か、所属がないまま 34 歳を過ぎたら今季限り
 *   引退のシーズンが終わると、総括（評価 G〜S・殿堂入り）
 */
import type { GameState } from '../models/game'
import { careerAge, careerPlayer } from './week'
import { legacyPoints } from './lifePlus'

export function retireWeek(state: GameState, played: { week: number; seasonEnded: boolean }) {
  const c = state.career!
  if (c.retiredAt !== undefined) return
  const p = careerPlayer(state)
  const age = careerAge(state)
  if (played.seasonEnded) {
    // 引退の予定のシーズンが終わった
    if (c.retirePlan === state.season - 1) {
      c.retiredAt = state.season - 1
      p.retired = true
      c.talks.push({ id: 'retired', speaker: 'todo_maiko' })
    }
    return
  }
  if (c.retirePlan !== undefined) return
  if (played.week === 37 && (age >= 39 || (p.teamId < 0 && age >= 34))) {
    c.retirePlan = state.season
    c.talks.push({ id: 'retire_final', speaker: 'todo_maiko' })
  } else if (played.week === 37 && age >= 33) c.talks.push({ id: 'retire_ask', speaker: 'todo_maiko' })
}

export interface CareerSummary {
  seasons: number
  nbaSeasons: number
  games: number
  points: number
  rebounds: number
  assists: number
  allStar: number
  allNba: number
  mvp: number
  rings: number
  awards: string[]
  teams: string[]
  score: number
  /** 社会貢献の点（寄付と財団） */
  legacy: number
  grade: 'G' | 'F' | 'E' | 'D' | 'C' | 'B' | 'A' | 'S'
  hallOfFame: boolean
}

/** 総括（評価と殿堂入り） */
export function careerSummary(state: GameState): CareerSummary {
  const c = state.career!
  const p = careerPlayer(state)
  const lines = p.history
  const nba = lines.filter((h) => h.league === 'NBA')
  const sum = (k: 'gp' | 'pts' | 'ast') => nba.reduce((s, h) => s + h.stats[k], 0)
  const reb = nba.reduce((s, h) => s + h.stats.oreb + h.stats.dreb, 0)
  const awards = state.awards.filter((a) => a.playerId === p.id)
  const count = (pred: (x: string) => boolean) => awards.filter((a) => pred(a.award)).length
  const allStar = count((x) => x === 'オールスター')
  const allNba = count((x) => x.startsWith('オール NBA'))
  const mvp = count((x) => x === 'MVP')
  const rings = c.log.filter((l) => l.notes.includes('NBA 優勝')).length
  const score = nba.length * 3 + allStar * 8 + allNba * 10 + mvp * 30 + rings * 15 + count((x) => x === '新人王') * 6 + count((x) => x === '最優秀守備選手') * 12 + sum('pts') / 800 + (c.national?.caps ?? 0) * 0.3 + legacyPoints(state) * 1.5
  const grades: [number, CareerSummary['grade']][] = [
    [260, 'S'],
    [170, 'A'],
    [110, 'B'],
    [65, 'C'],
    [35, 'D'],
    [15, 'E'],
    [5, 'F'],
  ]
  const grade = grades.find(([t]) => score >= t)?.[1] ?? 'G'
  const teams = [...new Set(lines.map((h) => h.teamName))]
  return {
    seasons: lines.length,
    nbaSeasons: nba.length,
    games: sum('gp'),
    points: sum('pts'),
    rebounds: reb,
    assists: sum('ast'),
    allStar,
    allNba,
    mvp,
    rings,
    awards: [...new Set(awards.map((a) => a.award))],
    teams,
    score: Math.round(score),
    legacy: legacyPoints(state),
    grade,
    hallOfFame: score >= 150 || mvp >= 1 || allStar >= 6,
  }
}
