/** 有名になったぶんの出費（身の回りのスタッフ・警備・付き合い。万円/年） */
export function lifestyleCost(fame: number, nba: boolean): number {
  return Math.round(nba ? 1000 + (fame / 100) ** 2 * 12000 : fame * 8)
}
