/**
 * 試合の確率（シュートの成功・ブロック・ファウル・ターンオーバー・リバウンド・ドライブ）。調整つまみは TUNE。
 * 能力は試合の水準をそろえた値（setup.ts で TUNE.levelRef に合わせてずらす）で、平均的な能力（levelRef）で NBA の平均の数字になるようにする。
 *   目安（1 チーム・1 試合・NBA）: ポゼッション 98〜101・得点 110〜116・FG 46〜48%・3P 試投 33〜38（35〜37%）・FT 試投 20〜24・TO 13〜14
 */
import type { PlayStyle } from '../data/styles'
import type { Rng } from '../core/prng'
import type { ShotZone, SimPlayer } from './types'

export const TUNE = {
  /** 試合の水準をそろえる基準（両チームの主力 8 人の総合値の平均をここへずらす） */
  levelRef: 72,
  /**
   * 能力の差をどれだけ結果に出すか（試合の前に、能力を基準へ寄せる割合。1 で寄せない）。
   * 小さいほど番狂わせが増える。戦力差（主力 8 人の総合値の平均）3 で勝率 6 割台・6 で 7 割台・10 で 9 割前後が目安
   */
  spread: 0.52,
  /** 平均的な能力・ふつうの寄せでのシュートの成功率 */
  base: { rim: 0.68, paint: 0.465, mid: 0.435, three: 0.355, corner3: 0.378 } as Record<ShotZone, number>,
  /** 打つ側の能力 10 あたりの上がり幅 */
  slope: { rim: 0.04, paint: 0.044, mid: 0.048, three: 0.048, corner3: 0.048 } as Record<ShotZone, number>,
  /** 守る側の能力 10 あたりの下がり幅（寄せの強さを掛ける） */
  defSlope: { rim: 0.028, paint: 0.028, mid: 0.024, three: 0.02, corner3: 0.02 } as Record<ShotZone, number>,
  /** フリーかどうか（advantage 0〜1）での上下（0.5 で 0） */
  open: { rim: 0.14, paint: 0.12, mid: 0.12, three: 0.13, corner3: 0.13 } as Record<ShotZone, number>,
  /** ブロック（守る側の能力が平均・ふつうの寄せ） */
  block: { rim: 0.11, paint: 0.08, mid: 0.016, three: 0.008, corner3: 0.008 } as Record<ShotZone, number>,
  /** シュート中のファウル */
  shootFoul: { rim: 0.27, paint: 0.15, mid: 0.055, three: 0.018, corner3: 0.018 } as Record<ShotZone, number>,
  /** 1 回のプレー（パス・ドライブ・ポスト）でのターンオーバー */
  tov: { pass: 0.047, drive: 0.1, post: 0.095, pnr: 0.09, iso: 0.078 },
  /** ターンオーバーのうちスティール */
  stealShare: 0.6,
  /** シュート中以外のファウル（ドライブ・アイソで） */
  reachFoul: 0.075,
  /** シュート中以外のファウル（ほかのプレー・ボールのないところで） */
  offBallFoul: 0.032,
  /** オフェンスリバウンドの取れる割合（平均） */
  oreb: 0.255,
  /** 外れたフリースローのオフェンスリバウンド */
  orebFt: 0.13,
  /** オフェンスリバウンドからそのまま押し込む */
  putback: 0.38,
  /** 守りから攻めに変わったときの速攻（リバウンドから・スティールから） */
  transition: { reb: 0.11, steal: 0.48 },
  /** 時間（秒）: ボール運び・パス・ドライブ・ピック&ロール・ポスト・アイソ */
  time: { bringUp: [5.2, 8.8], pass: [1.5, 3.0], drive: [1.9, 3.6], pnr: [3.2, 5.4], post: [3.2, 5.8], iso: [3.4, 6.2], fast: [3.5, 6.5] } as Record<string, [number, number]>,
  /** リーグのルールごとの時間の倍率（国際ルール・大学は NBA よりゆっくり。1 試合 40 分で 72 前後・大学は 30 秒ルールで 68 前後） */
  rulePace: { NBA: 1.03, FIBA: 1.2, NCAA: 1.27 } as Record<string, number>,
  /** チームリバウンド（選手の記録に付かない）の割合 */
  teamReb: 0.1,
  /** ペースの時間の倍率 */
  pace: { slow: 1.12, normal: 1.0, fast: 0.88 } as Record<string, number>,
  /** ホームの有利（シュートの成功率に足す） */
  home: 0.02,
  /** その日の調子（チームごと・試合ごとのシュートの当たり外れ。標準偏差） */
  form: 0.028,
  /** フリースロー: 能力 0 で 0.42、99 で 0.93 くらい */
  ftLo: 0.5,
  ftHi: 0.95,
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 打つ側のシュートの能力（区域ごと） */
export function shooterRating(p: SimPlayer, zone: ShotZone): number {
  const a = p.a
  switch (zone) {
    case 'rim':
      return 0.45 * a.layup + 0.25 * a.close + 0.3 * Math.max(a.layup, a.dunk)
    case 'paint':
      return 0.5 * a.close + 0.25 * a.post + 0.25 * a.layup + (p.skills.floater ? 4 : 0)
    case 'mid':
      return a.mid + (p.skills.midMaster ? 5 : 0)
    default:
      return a.three + (p.skills.sniper ? 5 : 0)
  }
}

/** 守る側の寄せの能力（区域ごと）。身長と腕の長さも効く */
export function defenderRating(d: SimPlayer, shooter: SimPlayer, zone: ShotZone): number {
  const a = d.a
  const size = (d.heightCm - shooter.heightCm) * 0.35 + (d.wingspanCm - d.heightCm - 6) * 0.3
  if (zone === 'rim' || zone === 'paint') return 0.55 * a.intD + 0.3 * a.block + 0.15 * a.strength + size + (d.skills.rimGuard ? 5 : 0)
  return 0.7 * a.perD + 0.3 * a.quick + size * 0.5 + (d.skills.lockdown ? 5 : 0)
}

export interface ShotContext {
  shooter: SimPlayer
  defender: SimPlayer
  zone: ShotZone
  /** フリーかどうか（0 ぴったり寄せられている〜1 完全にフリー） */
  adv: number
  home: boolean
  clutch: boolean
  big: boolean
  catchShoot: boolean
  late: boolean
  /** その日のチームの当たり外れ */
  form: number
}

/** シュートの成功率 */
export function shotPct(c: ShotContext): number {
  const ref = TUNE.levelRef
  const z = c.zone
  let p = TUNE.base[z]
  p += (TUNE.slope[z] * (shooterRating(c.shooter, z) - ref)) / 10
  const contest = 1 - c.adv
  p -= (TUNE.defSlope[z] * (defenderRating(c.defender, c.shooter, z) - ref) * (0.4 + contest)) / 10
  p += (c.adv - 0.5) * 2 * TUNE.open[z]
  if (c.home) p += TUNE.home
  p += c.form
  // 疲れ: 体力 60 を切ると落ちる
  p *= 0.88 + 0.12 * clamp(c.shooter.energy / 60, 0, 1)
  if (c.catchShoot && c.shooter.skills.catchShoot && (z === 'three' || z === 'corner3' || z === 'mid')) p += 0.03
  if (c.late) p -= 0.05
  if (c.clutch) {
    p += ((c.shooter.a.clutch - 65) / 100) * 0.08
    if (c.shooter.skills.clutchShooter) p += 0.035
    if (c.shooter.skills.choker) p -= 0.04
  }
  if (c.big) {
    if (c.shooter.skills.bigGame) p += 0.02
    if (c.shooter.skills.choker) p -= 0.02
  }
  return clamp(p, 0.04, 0.9)
}

export function blockPct(c: ShotContext): number {
  const d = c.defender
  let p = TUNE.block[c.zone] * (1 + (d.a.block - TUNE.levelRef) / 30 + (d.heightCm - c.shooter.heightCm) / 40) * (1.4 - c.adv)
  if (d.skills.rimGuard) p *= 1.25
  if (c.shooter.skills.acrobat && c.zone !== 'three' && c.zone !== 'corner3') p *= 0.75
  return clamp(p, 0, 0.3)
}

export function shootingFoulPct(c: ShotContext): number {
  let p = TUNE.shootFoul[c.zone] * (1 + (c.shooter.a.strength - TUNE.levelRef) / 120 - (c.defender.a.iq - TUNE.levelRef) / 120)
  if (c.shooter.skills.andOne) p *= 1.2
  return clamp(p, 0, 0.35)
}

/** フリースローの成功率 */
export function ftPct(p: SimPlayer, pressure: boolean): number {
  // フリースローは試合の水準でずらしすぎない（能力の素の値を半分だけ使う）
  let v = TUNE.ftLo + ((TUNE.ftHi - TUNE.ftLo) * clamp(p.a.ft, 0, 110)) / 99
  if (p.skills.ftMaster) v += 0.05
  if (p.skills.ftWoes) v -= 0.1
  if (pressure) v += p.skills.iceVeins ? 0.02 : p.skills.choker ? -0.06 : -0.015
  return clamp(v, 0.3, 0.96)
}

/** 1 回のプレーでのターンオーバー */
export function tovPct(kind: keyof typeof TUNE.tov, holder: SimPlayer, defender: SimPlayer, press: boolean): number {
  const ref = TUNE.levelRef
  const care = kind === 'pass' ? 0.5 * holder.a.pass + 0.3 * holder.a.vision + 0.2 * holder.a.iq : 0.55 * holder.a.handle + 0.25 * holder.a.iq + 0.2 * holder.a.quick
  const pressure = 0.6 * defender.a.steal + 0.4 * defender.a.perD
  let p = TUNE.tov[kind] * (1 - (care - ref) / 70 + (pressure - ref) / 90)
  if (holder.skills.ballSecurity) p *= 0.78
  if (holder.skills.turnoverProne) p *= 1.3
  if (defender.skills.thief) p *= 1.15
  if (press) p *= 1.3
  return clamp(p, 0.004, 0.2)
}

/** ドライブ・アイソで守備を抜けるか（0〜1）。高いほどゴールに近い良いシュートになる */
export function beatChance(holder: SimPlayer, defender: SimPlayer, help: number): number {
  const off = 0.4 * holder.a.quick + 0.35 * holder.a.handle + 0.25 * holder.a.speed + (holder.skills.ankleBreaker ? 6 : 0)
  const def = 0.5 * defender.a.perD + 0.35 * defender.a.quick + 0.15 * defender.a.iq + (defender.skills.lockdown ? 5 : 0)
  return clamp(0.5 + (off - def) / 45 - help * 0.08, 0.12, 0.88)
}

/** 攻めの能力（シュートを打つ回数の重み） */
export function scoringRating(p: SimPlayer): number {
  const a = p.a
  return 0.26 * Math.max(a.three, a.mid) + 0.16 * a.mid + 0.28 * Math.max(0.5 * a.layup + 0.5 * a.close, a.post) + 0.15 * a.handle + 0.15 * a.iq
}

const STYLE_USAGE: Record<PlayStyle, number> = { scorer: 1.16, slasher: 1.07, playmaker: 0.95, allround: 1.0, threeD: 0.76, stretchBig: 0.88, postScorer: 1.0, rimProtector: 0.62 }

/** 打つ回数の重み（チームの中での相対）。エースは役割の選手の 2 倍ほど */
export function usageWeights(ps: SimPlayer[], styles: PlayStyle[]): number[] {
  const r = ps.map(scoringRating)
  const top = Math.max(...r)
  return r.map((v, i) => Math.exp((v - top) / 8.5) * STYLE_USAGE[styles[i]])
}

/** 区域の選び方（打つ人の得意と、場面と、作戦の重心） */
export function pickZone(p: SimPlayer, ctx: 'iso' | 'pullup' | 'drive' | 'catch' | 'roll' | 'pop' | 'post' | 'putback' | 'fast' | 'late', focus: 'inside' | 'balanced' | 'outside', rng: Rng): ShotZone {
  const a = p.a
  const w3 = Math.max(0.02, (a.three - 40) / 40) ** 2
  const wMid = Math.max(0.05, (a.mid - 40) / 50)
  const wRim = Math.max(0.1, (0.5 * a.layup + 0.5 * Math.max(a.dunk, a.close) - 35) / 40)
  const wPaint = Math.max(0.05, (0.6 * a.close + 0.4 * a.post - 35) / 45)
  let w: Record<ShotZone, number>
  switch (ctx) {
    case 'drive':
      w = { rim: wRim * 2.2, paint: wPaint * 1.2, mid: wMid * 0.5, three: 0, corner3: 0 }
      break
    case 'roll':
    case 'putback':
      w = { rim: 3, paint: 1, mid: 0, three: 0, corner3: 0 }
      break
    case 'pop':
      w = { rim: 0, paint: 0, mid: wMid * 0.6, three: w3 * 2, corner3: 0 }
      break
    case 'post':
      w = { rim: wRim * 0.6, paint: wPaint * 2, mid: wMid * 0.3, three: 0, corner3: 0 }
      break
    case 'catch':
      w = { rim: wRim * 0.3, paint: wPaint * 0.35, mid: wMid * 0.7, three: w3 * 1.25, corner3: w3 * 0.55 }
      break
    case 'fast':
      w = { rim: 3, paint: 0.3, mid: 0.1, three: w3 * 0.9, corner3: w3 * 0.3 }
      break
    case 'pullup':
      w = { rim: 0, paint: wPaint * 0.35, mid: wMid * 1.25, three: w3 * 1.0, corner3: 0 }
      break
    case 'late':
    case 'iso':
    default:
      w = { rim: wRim * 0.75, paint: wPaint * 0.65, mid: wMid * 1.1, three: w3 * 0.85, corner3: w3 * 0.12 }
  }
  if (focus === 'inside') {
    w.rim *= 1.25
    w.paint *= 1.25
  } else if (focus === 'outside') {
    w.three *= 1.3
    w.corner3 *= 1.3
  }
  const zones: ShotZone[] = ['rim', 'paint', 'mid', 'three', 'corner3']
  const ws = zones.map((z) => w[z])
  if (ws.every((x) => x <= 0)) return 'mid'
  return zones[rng.weighted(ws)]
}
