/**
 * チームの定義。NBA は都市が実在・愛称は架空（実在のプロチームの愛称と重ならないようにしてある）。
 * 国内（JBL1〜3）・大学・育成リーグはすべて架空。都市は実在。
 * rep は「格」（0-100）。最初の顔ぶれの強さと人気の土台。
 */

export interface TeamDef {
  city: string
  nickname: string
  /** 3 文字の略号 */
  abbr: string
  primary: string
  secondary: string
  rep: number
}

export interface NbaTeamDef extends TeamDef {
  conf: 'E' | 'W'
  div: string
}

const nba = (conf: 'E' | 'W', div: string, list: [string, string, string, string, string, number][]): NbaTeamDef[] =>
  list.map(([city, nickname, abbr, primary, secondary, rep]) => ({ city, nickname, abbr, primary, secondary, rep, conf, div }))

