/**
 * ライバル・神崎レオの物語: レオはワールドの中の本物の選手（アメリカの大学 1 年生から。伸びしろ 91）。その歩みに合わせて話しに来る。
 *   rival:path            入団・入学のあと（進路が同じか違うか）
 *   rival:match:<季>:<勝>  シーズンで最初の直接対決のあと（勝ち負けで台詞）。対戦成績は career.rival に毎試合数える
 *   rival:series:<季>:<勝> プレーオフでレオのチームとのシリーズが終わったとき
 *   rival:draft:<季>       レオが指名された年（同じ年なら順位を比べる）
 *   rival:nba              ふたりとも NBA の選手になったとき
 *   rival:allstar:<季>:<誰> オールスター（どちらか、ふたりとも）
 *   rival:national        日本代表で同じチームになったとき
 *   rival:retire          主人公が引退を決めたとき（最後のシーズン）
 * 二代目では出ない（レオは親の世代）。レオが引退していたら出ない。話のたびに絆が少し上がる（30・60 で絆の話）
 */
import { NATIONAL_WINDOWS } from '../core/calendar'
import { CAST_BY_ID } from '../data/cast'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { nationalSquad } from './national'
import { ovr } from '../player/overall'
import type { GrowthBias } from '../player/growth'
import { sameGeneration } from './castLines'
import type { Talk, TalkLine } from './talks'

export const RIVAL = 'kanzaki_leo'

export function rivalPlayer(state: GameState): Player | undefined {
  return Object.values(state.players).find((p) => p.castId === RIVAL)
}

function push(state: GameState, id: string) {
  const c = state.career!
  if (c.seen.includes(id) || c.talks.some((t) => t.id === id)) return
  c.talks.push({ id, speaker: RIVAL })
  // 話のたびに、ライバルとしての絆が少し深まる（30・60 で絆の話）
  const before = c.bonds[RIVAL] ?? 0
  const after = Math.min(100, before + 5)
  c.bonds[RIVAL] = after
  for (const line of [30, 60]) if (before < line && after >= line && !c.seen.includes(`bond:${RIVAL}:${line}`)) c.talks.push({ id: `bond:${RIVAL}:${line}`, speaker: RIVAL })
}

/**
 * ライバルの成長の上乗せ（毎週の growPlayer に渡す）: 最後まで張り合えるように、主人公に引き離されるほどよく伸びる。
 * 先に 4 以上行っているときは少し控えめ。伸びしろ（91）と年齢のカーブはそのまま効く。主人公が引退したら、ふつうの選手と同じ
 */
export function rivalGrowthBias(state: GameState, p: Player): GrowthBias | undefined {
  const c = state.career
  if (p.castId !== RIVAL || !c || c.retiredAt !== undefined || !sameGeneration(state, RIVAL)) return undefined
  const me = state.players[c.playerId]
  if (!me) return undefined
  const gap = ovr(me) - ovr(p)
  return { mul: gap <= -4 ? 0.9 : 1.15 + Math.min(12, Math.max(0, gap + 2)) * 0.07 }
}

/** 週の終わり（careerAfterWeek から） */
export function rivalWeek(state: GameState, played: { week: number; seasonEnded: boolean }) {
  const c = state.career
  if (!c || c.retiredAt !== undefined || !sameGeneration(state, RIVAL)) return
  const leo = rivalPlayer(state)
  if (!leo || leo.retired) return
  const me = state.players[c.playerId]
  const myLg = me.teamId >= 0 ? state.teams[me.teamId].league : undefined
  const leoLg = leo.teamId >= 0 ? state.teams[leo.teamId].league : undefined
  const season = played.seasonEnded ? state.season - 1 : state.season

  // 進路のあと（最初のシーズンの第 1 週）
  if (c.path && myLg && !played.seasonEnded && season === (c.startSeason ?? 0)) push(state, 'rival:path')

  // 直接対決（この週の試合）。シーズン中・同じ週に終わった試合
  if (!played.seasonEnded && me.teamId >= 0 && leo.teamId >= 0 && me.teamId !== leo.teamId) {
    const games = state.fixtures.filter((f) => f.week === played.week && f.result && ((f.home === me.teamId && f.away === leo.teamId) || (f.away === me.teamId && f.home === leo.teamId)))
    for (const f of games) {
      const home = f.home === me.teamId
      const win = home ? f.result!.hs > f.result!.as : f.result!.as > f.result!.hs
      c.rival = { w: (c.rival?.w ?? 0) + (win ? 1 : 0), l: (c.rival?.l ?? 0) + (win ? 0 : 1) }
      // 話はシーズンで最初の対決のあとだけ
      const pre = `rival:match:${season}:`
      if (f.kind === 'regular' && !c.seen.some((x) => x.startsWith(pre)) && !c.talks.some((t) => t.id.startsWith(pre))) push(state, `${pre}${win ? 1 : 0}`)
    }
    // プレーオフのシリーズが終わった
    const s = state.series.find((x) => x.winner !== undefined && ((x.hi === me.teamId && x.lo === leo.teamId) || (x.lo === me.teamId && x.hi === leo.teamId)))
    if (s) push(state, `rival:series:${season}:${s.winner === me.teamId ? 1 : 0}`)
  }

  // レオが指名された（シーズンの終わりのドラフト）
  if (played.seasonEnded && leo.draft && leo.draft.year === state.startYear + state.season) push(state, `rival:draft:${season}`)

  // ふたりとも NBA
  if (myLg === 'NBA' && leoLg === 'NBA') push(state, 'rival:nba')

  // オールスター
  const as = state.awards.filter((a) => a.season === season && a.award === 'オールスター')
  const meAs = as.some((a) => a.playerId === me.id)
  const leoAs = as.some((a) => a.playerId === leo.id)
  if (meAs || leoAs) push(state, `rival:allstar:${season}:${meAs && leoAs ? 'both' : meAs ? 'me' : 'leo'}`)

  // 日本代表で同じチーム
  if ((NATIONAL_WINDOWS as readonly number[]).includes(played.week)) {
    const squad = nationalSquad(state).map((p) => p.id)
    if (squad.includes(me.id) && squad.includes(leo.id)) push(state, 'rival:national')
  }

  // 最後のシーズン（引退を決めた）
  if (c.retirePlan === state.season && !played.seasonEnded) push(state, 'rival:retire')
}

const L = (who: string, ...texts: string[]): TalkLine[] => texts.map((t) => (t.startsWith('me:') ? { who: 'me', text: t.slice(3) } : { who, text: t }))

export function rivalTalkOf(id: string, state?: GameState): Talk | null {
  if (!state?.career) return null
  const leo = rivalPlayer(state)
  if (!leo) return null
  const c = state.career
  const me = state.players[c.playerId]
  const parts = id.split(':')
  const ev = parts[1]
  const leoTeam = leo.teamId >= 0 ? state.teams[leo.teamId] : undefined
  const rec = c.rival ? `（通算 ${c.rival.w} 勝 ${c.rival.l} 敗）` : ''
  const name = CAST_BY_ID[RIVAL].name
  if (ev === 'path') {
    const myCollege = me.teamId >= 0 && state.teams[me.teamId].league === 'NCAA'
    return {
      title: name,
      lines: L(RIVAL, ...(myCollege ? ['お前もアメリカに来たのか。……面白い', `オレは${leoTeam?.name ?? '大学'}だ。同じリーグにいる限り、何度でも叩きのめしてやる`, 'me:望むところだ'] : ['日本に残ったのか。……まあ、お前らしいな', `オレは${leoTeam?.name ?? 'アメリカの大学'}で先に行く。NBA で待ってるぜ`, 'me:すぐに追いつく。見てろ'])),
    }
  }
  if (ev === 'match') {
    const win = parts[3] === '1'
    return {
      title: `${name}との対決`,
      lines: L(RIVAL, ...(win ? ['……今日はお前の勝ちだ。認めてやる', `次は負けない。${rec}`] : ['見たか。これがオレとお前の差だ', `悔しかったら、次は止めてみろ。${rec}`])),
    }
  }
  if (ev === 'series') {
    const win = parts[3] === '1'
    return {
      title: `${name}とのシリーズ`,
      lines: L(RIVAL, ...(win ? ['……お前のシーズンは続く。オレのシーズンは、ここで終わりだ', '勝てよ。オレを倒したんだからな', 'me:……ああ'] : ['このシリーズは、オレがもらった', 'お前と戦うプレーオフは、どんな試合より熱かった。……また来い'])),
    }
  }
  if (ev === 'draft') {
    const d = leo.draft
    const mine = me.draft && me.draft.year === d?.year ? me.draft : undefined
    const team = d ? state.teams[d.teamId] : undefined
    return {
      title: `${name}、ドラフト指名`,
      lines: L(
        RIVAL,
        `${team?.name ?? 'NBA のチーム'}に、${d?.round ?? 1} 巡目 ${d?.pick ?? '?'} 位で指名された`,
        ...(mine ? [mine.round * 100 + mine.pick < (d!.round * 100 + d!.pick) ? '……順位はお前が上か。だが、NBA で上に行くのはオレだ' : '順位はオレが上だ。……NBA で、決着をつけよう'] : me.teamId >= 0 && state.teams[me.teamId].league === 'NBA' ? ['これで同じ舞台だ。逃げるなよ'] : ['先に行って待ってる。……早く来いよ']),
      ),
    }
  }
  if (ev === 'nba') return { title: '同じ舞台', lines: L(RIVAL, 'やっと、同じ舞台に立ったな', '子どものころから、お前とここで戦う日を考えてた', 'me:……オレもだ') }
  if (ev === 'allstar') {
    const who = parts[3]
    return {
      title: 'オールスター',
      lines: L(RIVAL, ...(who === 'both' ? ['同じオールスターのベンチか……。悪くない', '今日だけは味方だ。……今日だけはな'] : who === 'me' ? ['オールスターか……。先を越されたな', '来年は、オレもそこに立つ'] : ['オレはオールスターだ。お前はまだか？', '待っててやる。早く上がってこい'])),
    }
  }
  if (ev === 'national') return { title: '日の丸', lines: L(RIVAL, 'まさか、お前と同じユニフォームを着る日が来るとはな', '……日本のためなら、お前にパスを出してやってもいい', 'me:じゃあ、オレはお前のシュートを信じる') }
  if (ev === 'retire') return { title: `${name}`, lines: L(RIVAL, '……今季で辞めるって、本当か', 'お前がいたから、ここまで来られた。……最後の試合まで、全力で来い', 'me:ああ。最後まで、お前のライバルでいる') }
  return null
}
