interface Lines {
  meet: string[]
  chat: string[]
  b30: string[]
  b60: string[]
}

interface CastLineSet extends Lines {
  /** 主人公の段階ごとの差し替え（chat は足す） */
  by?: Partial<Record<LifeStage, Partial<Lines>>>
  /** その人の「その後」の手前（学生のあいだなど）だけ言う台詞 */
  young?: string[]
  /** その人の人生が進んだあと（年齢で）。肩書きが変わり、台詞が足される */
  later?: { age: number; role: string } & Partial<Lines>
  /** 主人公が大学に行かなかったときの肩書き（「大学の同級生」などが合わない人） */
  outsider?: string
}

