/** 主人公の今の段階 */
export function lifeStage(state: GameState): LifeStage {
  const p = careerPlayer(state)
  const lg = p.teamId >= 0 ? state.teams[p.teamId].league : undefined
  if (lg === 'NCAA') return 'college'
  if (lg === 'NBA' || lg === 'DEV') return 'nba'
  if (lg) return 'jpro'
  // 所属なし: これまでの道から
  const c = state.career!
  const last = c.log[c.log.length - 1]?.league
  if (last === 'NBA' || last === 'DEV' || last === 'NCAA') return 'nba'
  return c.path === 'college' ? 'college' : 'jpro'
}

/** その人の今の年齢（主人公が 18 歳のときの年齢から） */
/** 二代目のキャリアが始まったシーズン（まだ二代目がいなければ undefined） */
function heirStart(state: GameState): number | undefined {
  const c = state.career
  const n = c?.lineage?.length ?? 0
  if (!c || n === 0) return undefined
  return n === 1 ? (c.startSeason ?? state.season) : c.lineage![1].seasons[0]
}

export function castAge(state: GameState, id: string): number {
  const c = CAST_BY_ID[id]
  // 二代目の人は、二代目のキャリアが始まったときの年齢から数える
  if (c?.gen === 2) {
    const start = heirStart(state)
    return start === undefined ? -1 : c.age + Math.max(0, state.season - start)
  }
  return (c?.age ?? 0) + Math.max(0, Math.floor(absWeekOf(state.season, state.week) / WEEKS_PER_SEASON))
}

/**
 * 主人公と同じ世代の人か。初代のキャリアでは、初代の人はみな会える（ベテランのチームメイトも）。
 * 二代目からは、ヒロイン・仲間・ライバル・チームメイトは主人公より 9 歳を超えて上なら会わない。二代目のヒロインは二代目のキャリアでだけ
 */
export function sameGeneration(state: GameState, id: string): boolean {
  const c = CAST_BY_ID[id]
  if (!c) return true
  const heir = heirStart(state) !== undefined
  if (c.gen === 2) return heir && Math.abs(castAge(state, id) - careerAge(state)) <= 9
  if (!heir) return true
  if (!['heroine', 'friend', 'rival', 'teammate'].includes(c.kind)) return true
  return castAge(state, id) - careerAge(state) <= 9
}

const grown = (state: GameState, id: string) => {
  const later = CAST_LINES[id]?.later
  return !!later && castAge(state, id) >= later.age
}

/** 画面に出す肩書き（その人の人生の進みと、主人公の道で変わる） */
export function castRole(state: GameState, id: string): string {
  const set = CAST_LINES[id]
  if (set?.later && grown(state, id)) return set.later.role
  if (set?.outsider && state.career?.path !== 'college') return set.outsider
  return CAST_BY_ID[id]?.role ?? ''
}

/** 今の段階に合わせた台詞（meet・b30・b60 は置き換え、chat は足し合わせ） */
/**
 * 代理人のふだんの話は、立場で変える（NBA の控え・主力・スター、日本のベテラン）。
 * 前は NBA のスターになっても「まずは監督の信頼。ローテーションに入れば…」と言っていた
 */
function agentChat(state: GameState): string[] | undefined {
  const st = lifeStage(state)
  const rank = careerRank(state)
  if (st === 'nba') {
    if (rank === 'S') return ['あなたのモデルのシューズ、発売日に売り切れたそうよ', '取材の依頼は、大事なものだけにしぼっておいたわ', '記者たちが、殿堂入りの話を始めているわね']
    if (rank === 'A') return ['次の契約は、大きな話になるわよ。今の調子で', 'スポンサーの話がいくつか来ているわ。あなたの評価が上がっている証拠よ', 'オールスターも、もう手の届くところね']
    return ['NBA で生き残るには、まず監督の信頼。ローテーションに入れば道は開けるわ', '練習の態度は、コーチたちがいつも見ているわよ', '焦らないで。チャンスは必ず来る']
  }
  if (st === 'jpro' && careerAge(state) >= 25) return ['日本のバスケを引っ張るのは、あなたよ', '若い選手たちが、あなたの背中を見ているわ', '国内で結果を出し続けることにも、大きな意味があるわ']
  return undefined
}

export function castLines(state: GameState, id: string): Lines | null {
  const set = CAST_LINES[id]
  if (!set) return null
  const stage = set.by?.[lifeStage(state)]
  const later = grown(state, id) ? set.later : undefined
  const agent = id === 'todo_maiko' ? agentChat(state) : undefined
  return {
    meet: later?.meet ?? stage?.meet ?? set.meet,
    b30: later?.b30 ?? stage?.b30 ?? set.b30,
    b60: later?.b60 ?? stage?.b60 ?? set.b60,
    chat: [...set.chat, ...(later ? (later.chat ?? []) : (set.young ?? [])), ...(agent ?? stage?.chat ?? [])],
  }
}

/** ふだんの会話の候補（恋人・結婚相手なら、ふたりの会話を先に） */
export function chatPool(state: GameState, id: string): string[] {
  const lines = castLines(state, id)
  if (!lines) return []
  const c = state.career
  const story = HEROINE_STORY[id]
  if (story && c && (c.partner === id || c.spouse === id)) return [...story.couple, ...story.couple, ...lines.chat]
  return lines.chat
}
