/**
 * ワールドを作る: リーグ 6 つ（NBA・育成・国内 1〜3 部・大学）とチーム、選手（約 2,000 人）、固有キャラ、所属なしの選手、今季の日程。
 * 乱数はすべて seed から（同じ seed なら同じワールド）。
 */
import { createRng, type Rng } from '../core/prng'
import { CAST_BY_ID } from '../data/cast'
import { ASIA_MIX, JBL_FOREIGN_MIX, NBA_NATION_MIX, generateName, type Nation } from '../data/nations'
import { POSITIONS, type Position } from '../data/positions'
import { COLLEGE_CONFS, DEV_LEAGUE_NAME, JBL1_TEAMS, JBL2_TEAMS, JBL3_TEAMS, NBA_TEAMS, type TeamDef } from '../data/teams'
import { DEV_SALARY, NBA_MAX, NBA_MIN, jblMarketSalary, nbaMarketSalary, TWO_WAY_SALARY, usdToMan } from '../economy/salary'
import { SCHEMA_VERSION, type GameMode, type GameState } from '../models/game'
import type { GrowthType } from '../data/growth'
import { DEFAULT_TACTICS, emptyStanding, type League, type LeagueId, type Team } from '../models/league'
import type { Contract, Player } from '../models/player'
import { assignPhotos } from '../player/photos'
import { ovr } from '../player/overall'
import { scheduleSeason } from '../competition/schedule'
import { generatePlayer, type GenOptions } from './playerGen'

export interface WorldOptions {
  seed: number
  mode: GameMode
  startYear?: number
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))
const pickNation = (mix: { codes: Nation[]; weights: number[] }, rng: Rng) => mix.codes[rng.weighted(mix.weights)]

const LEAGUE_DEFS: [LeagueId, string, string, League['rules'], number][] = [
  ['NBA', 'NBA', 'NBA', 'NBA', 0],
  ['DEV', DEV_LEAGUE_NAME, '育成', 'NBA', 9],
  ['JBL1', 'JBL 1部', 'JBL1', 'FIBA', 1],
  ['JBL2', 'JBL 2部', 'JBL2', 'FIBA', 2],
  ['JBL3', 'JBL 3部', 'JBL3', 'FIBA', 3],
  ['NCAA', '全米大学リーグ', '大学', 'NCAA', 9],
]

const NBA_ARENA = ['センター', 'アリーナ', 'ガーデン', 'フォーラム', 'ドーム']

function addTeam(state: GameState, league: LeagueId, d: TeamDef, extra: Partial<Team>, rng: Rng): Team {
  const nation: Nation = league === 'JBL1' || league === 'JBL2' || league === 'JBL3' ? 'JP' : 'US'
  const t: Team = {
    id: state.teams.length,
    league,
    city: d.city,
    nickname: d.nickname,
    name: league === 'NCAA' ? d.city : `${d.city}・${d.nickname}`,
    short: league === 'NCAA' ? d.nickname : d.nickname,
    abbr: d.abbr,
    colors: { primary: d.primary, secondary: d.secondary },
    rep: d.rep,
    roster: [],
    arena: { name: `${d.city}アリーナ`, capacity: 5000 },
    tactics: { ...DEFAULT_TACTICS },
    coach: { name: generateName(nation, rng).full, skill: Math.round(clamp(rng.normal(d.rep, 8), 35, 95)) },
    ...extra,
  }
  if (league !== 'NCAA') t.name = `${d.city}・${d.nickname}`
  state.teams.push(t)
  state.leagues[league].teamIds.push(t.id)
  state.leagues[league].standings[t.id] = emptyStanding()
  return t
}

function sign(p: Player, team: Team, contract: Contract) {
  p.teamId = team.id
  p.contract = contract
  team.roster.push(p.id)
}

/** 5 人ずつ、どのポジションも 1 人入るように並べた 15 人分のポジション */
function positionsFor(n: number, rng: Rng): Position[] {
  const out: Position[] = []
  while (out.length < n) out.push(...rng.shuffle([...POSITIONS]))
  return out.slice(0, n)
}

function nbaAge(rank: number, rng: Rng): number {
  // 主力は 24〜31 歳が多く、控えの下のほうは若手とベテラン
  const mean = rank < 5 ? 27 : rank < 10 ? 27.5 : 25
  return Math.round(clamp(rng.normal(mean, rank < 10 ? 3.4 : 4.2), 19, 38))
}

export function fillNba(state: GameState, team: Team, rng: Rng) {
  const top = clamp(rng.normal(82 + (team.rep - 70) * 0.3, 2.6), 76, 92)
  const offsets = [0, -4, -8, -11, -13, -14, -15, -16, -17, -18, -19, -20, -21, -23, -25]
  const pos = positionsFor(15, rng)
  offsets.forEach((off, i) => {
    const ovr = Math.round(top + off + rng.normal(0, 1.5))
    const age = nbaAge(i, rng)
    const p = generatePlayer(state, rng, { nation: pickNation(NBA_NATION_MIX, rng), age, pos: pos[i], ovr })
    const rookie = age <= 22
    const salary = rookie ? Math.max(NBA_MIN, Math.round(nbaMarketSalary(ovr) * 0.6)) : nbaMarketSalary(ovr)
    sign(p, team, { salary, years: rng.int(1, rookie ? 3 : 4), kind: rookie ? 'rookie' : ovr >= 88 ? 'max' : ovr <= 64 ? 'min' : 'standard' })
    // ドラフトの記録（作り話。若い選手ほど最近）
    if (age <= 30 && p.nation === 'US' && rng.chance(0.8)) {
      const pick = clamp(Math.round(rng.normal(Math.max(1, 70 - ovr) + 4, 8)), 1, 60)
      p.draft = { year: state.startYear - (age - 19), round: pick <= 30 ? 1 : 2, pick, teamId: rng.pick(state.leagues.NBA.teamIds) }
    }
  })
  // 年俸の合計を目安に合わせる（強いチームほど多く払うが、キャップの近くに収まる）
  const target = usdToMan(clamp(rng.normal(125e6 + (team.rep - 70) * 2.2e6, 12e6), 95e6, 190e6))
  const sum = team.roster.reduce((s, id) => s + state.players[id].contract.salary, 0)
  for (const id of team.roster) {
    const c = state.players[id].contract
    c.salary = Math.round(clamp(c.salary * (target / sum), NBA_MIN, NBA_MAX))
  }
}

function fillDev(state: GameState, team: Team, rng: Rng) {
  const pos = positionsFor(10, rng)
  for (let i = 0; i < 10; i++) {
    const ovr = Math.round(clamp(rng.normal(62 - i * 0.5, 2.5), 54, 68))
    const age = Math.round(clamp(rng.normal(23.5, 2), 20, 30))
    const p = generatePlayer(state, rng, { nation: pickNation(NBA_NATION_MIX, rng), age, pos: pos[i], ovr })
    const twoWay = i < 2
    sign(p, team, { salary: twoWay ? TWO_WAY_SALARY : DEV_SALARY, years: twoWay ? 2 : 1, kind: twoWay ? 'twoWay' : 'dev' })
  }
}

/** 国内の部ごとの伸びしろの倍率（下の部ほど小さい） */
export const JBL_POT: Record<'JBL1' | 'JBL2' | 'JBL3', number> = { JBL1: 1, JBL2: 0.8, JBL3: 0.6 }

/** 国内リーグの顔ぶれ: 外国籍・アジア枠・日本人 */
const JBL_SHAPE: Record<'JBL1' | 'JBL2' | 'JBL3', { foreign: number; foreignOvr: number; asia: number; asiaOvr: number; jp: number[]; refRep: number }> = {
  JBL1: { foreign: 3, foreignOvr: 70, asia: 1, asiaOvr: 61, jp: [65, 62, 60, 58, 56, 54, 52, 49], refRep: 65 },
  JBL2: { foreign: 3, foreignOvr: 63, asia: 1, asiaOvr: 55, jp: [58, 55, 53, 51, 49, 47, 45, 43], refRep: 49 },
  JBL3: { foreign: 2, foreignOvr: 57, asia: 0, asiaOvr: 50, jp: [52, 50, 48, 46, 44, 43, 42, 41, 40, 38], refRep: 38 },
}

export function fillJbl(state: GameState, team: Team, rng: Rng) {
  const lg = team.league as 'JBL1' | 'JBL2' | 'JBL3'
  const s = JBL_SHAPE[lg]
  const shift = (team.rep - s.refRep) * 0.25
  // 外国籍は大きい選手が多い
  for (let i = 0; i < s.foreign; i++) {
    const ovr = Math.round(clamp(rng.normal(s.foreignOvr + shift, 2.5), s.foreignOvr - 6, s.foreignOvr + 7))
    const pos = rng.pick<Position>(['C', 'PF', 'PF', 'SF', 'SG', 'C'])
    const p = generatePlayer(state, rng, { nation: pickNation(JBL_FOREIGN_MIX, rng), age: Math.round(clamp(rng.normal(28, 3), 23, 35)), pos, ovr })
    sign(p, team, { salary: jblMarketSalary(ovr, true, lg), years: rng.int(1, 2), kind: 'pro' })
  }
  for (let i = 0; i < s.asia; i++) {
    const ovr = Math.round(clamp(rng.normal(s.asiaOvr + shift, 2.5), 40, 75))
    const p = generatePlayer(state, rng, { nation: pickNation(ASIA_MIX, rng), age: Math.round(clamp(rng.normal(26, 3), 21, 33)), pos: rng.pick<Position>(['PG', 'SG', 'SF']), ovr })
    sign(p, team, { salary: jblMarketSalary(ovr, true, lg), years: rng.int(1, 2), kind: 'pro' })
  }
  const pos = positionsFor(s.jp.length, rng)
  s.jp.forEach((base, i) => {
    const ovr = Math.round(clamp(base + shift + rng.normal(0, 2), 32, 75))
    const age = Math.round(clamp(rng.normal(26, 4), 19, 36))
    // 日本人の大型選手は少ないので、C は PF 寄りに
    const p = generatePlayer(state, rng, { nation: 'JP', age, pos: pos[i] === 'C' && rng.chance(0.4) ? 'PF' : pos[i], ovr, potMul: JBL_POT[lg] })
    sign(p, team, { salary: jblMarketSalary(ovr, false, lg), years: rng.int(1, 3), kind: 'pro' })
  })
}

const COLLEGE_MIX: { codes: Nation[]; weights: number[] } = { codes: ['US', 'CA', 'AU', 'FR', 'NG', 'SS', 'DE', 'LT', 'SN', 'GR'], weights: [84, 4, 3, 2, 2, 1, 1, 1, 1, 1] }

function fillCollege(state: GameState, team: Team, rng: Rng) {
  const years = [1, 1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4]
  const pos = positionsFor(years.length, rng)
  const base = 50 + (team.rep - 65) * 0.3
  years.forEach((y, i) => {
    const star = y === 1 && i === 0 && team.rep >= 74 && rng.chance(0.75)
    const ovr = Math.round(star ? clamp(rng.normal(63, 2), 59, 68) : clamp(base + (y - 1) * 2.6 + rng.normal(-2, 4), 38, 66))
    const age = 17 + y + (rng.chance(0.35) ? 1 : 0)
    const o: GenOptions = { nation: pickNation(COLLEGE_MIX, rng), age, pos: pos[i], ovr }
    if (star) o.pot = rng.int(84, 95)
    const p = generatePlayer(state, rng, o)
    p.classYear = y
    sign(p, team, { salary: 0, years: 5 - y, kind: 'college' })
  })
}

/** 所属なしの選手（FA）。国内の外国籍・NBA の穴埋めの候補 */
function fillFreeAgents(state: GameState, rng: Rng, n: number) {
  for (let i = 0; i < n; i++) {
    const foreign = rng.chance(0.82)
    const nation: Nation = foreign ? pickNation(NBA_NATION_MIX, rng) : 'JP'
    const ovr = Math.round(foreign ? clamp(rng.normal(60, 5), 48, 70) : clamp(rng.normal(46, 5), 35, 58))
    generatePlayer(state, rng, { nation, age: Math.round(clamp(rng.normal(27, 4), 21, 35)), ovr })
  }
}

/** 固有キャラを選手として置く（写真は cast の写真） */
interface StarSpec {
  id: string
  team: (state: GameState) => Team
  pos: Position
  style?: GenOptions['style']
  ovr: number
  pot?: number
  nation: Nation
  contract: (ovr: number) => Contract
  classYear?: number
  /** 成長タイプ（若い固有キャラ。ランダムで超早熟になると、伸びしろに届く前に衰え始める） */
  growth?: GrowthType
}

const byName = (league: LeagueId, nickname: string) => (state: GameState) => state.leagues[league].teamIds.map((id) => state.teams[id]).find((t) => t.nickname === nickname || t.short === nickname)!

/** 若い固有キャラの成長タイプ（古いセーブの直しにも使う） */
export const STAR_GROWTH: Record<string, GrowthType> = { jalen_brooks: 'early', kanzaki_leo: 'normal', murakami_daichi: 'normal' }

const STARS: StarSpec[] = [
  { id: 'darius_king', team: byName('NBA', 'サンセッツ'), pos: 'SF', style: 'scorer', ovr: 92, nation: 'US', contract: () => ({ salary: nbaMarketSalary(95), years: 4, kind: 'max' }) },
  { id: 'andre_washington', team: byName('NBA', 'ハーバーズ'), pos: 'PF', style: 'allround', ovr: 76, nation: 'US', contract: (o) => ({ salary: nbaMarketSalary(o), years: 2, kind: 'standard' }) },
  { id: 'milos_petrovic', team: byName('NBA', 'デルタズ'), pos: 'C', style: 'stretchBig', ovr: 79, nation: 'RS', contract: (o) => ({ salary: nbaMarketSalary(o), years: 3, kind: 'standard' }) },
  { id: 'tyler_hansen', team: byName('NBA', 'サミッツ'), pos: 'SG', style: 'threeD', ovr: 71, pot: 80, nation: 'US', contract: (o) => ({ salary: nbaMarketSalary(o), years: 2, kind: 'rookie' }) },
  { id: 'jalen_brooks', team: byName('NCAA', 'アッシュフォード'), pos: 'PG', style: 'scorer', ovr: 64, pot: 93, nation: 'US', contract: () => ({ salary: 0, years: 4, kind: 'college' }), classYear: 1, growth: 'early' },
  { id: 'kanzaki_leo', team: byName('NCAA', 'ブルーリッジ'), pos: 'SF', style: 'slasher', ovr: 53, pot: 91, nation: 'JP', contract: () => ({ salary: 0, years: 4, kind: 'college' }), classYear: 1, growth: 'normal' },
  { id: 'hasegawa_ryu', team: byName('JBL1', 'スカイライナーズ'), pos: 'SG', style: 'scorer', ovr: 68, nation: 'JP', contract: () => ({ salary: 9000, years: 3, kind: 'pro' }) },
  { id: 'murakami_daichi', team: byName('JBL1', 'スティールズ'), pos: 'PG', style: 'playmaker', ovr: 46, pot: 79, nation: 'JP', contract: () => ({ salary: 480, years: 3, kind: 'pro' }), growth: 'normal' },
]

function placeStars(state: GameState, rng: Rng) {
  for (const s of STARS) {
    const c = CAST_BY_ID[s.id]
    const team = s.team(state)
    const p = generatePlayer(state, rng, { nation: s.nation, age: c.age, pos: s.pos, style: s.style, ovr: s.ovr, pot: s.pot ?? s.ovr })
    p.name = c.name
    p.short = c.name.includes('・') ? c.name.split('・').pop()! : c.name.slice(0, 2)
    p.castId = s.id
    p.photo = s.id
    if (s.classYear) p.classYear = s.classYear
    if (s.growth) p.growth = s.growth
    // ダリウスは確実にスーパースター（特殊能力も多め）
    if (s.id === 'darius_king') p.skills = ['clutchShooter', 'ankleBreaker', 'posterizer', 'bigGame', 'midMaster']
    sign(p, team, s.contract(s.ovr))
    // 人数の上限を超えたら、いちばん弱い選手を所属なしに
    const limit = ROSTER_LIMIT[team.league]
    if (team.roster.length > limit) {
      const weakest = team.roster.map((id) => state.players[id]).filter((x) => !x.castId).sort((a, b) => ovr(a) - ovr(b))[0]
      release(state, weakest)
    }
  }
}

/** チームの人数の上限 */
export const ROSTER_LIMIT: Record<LeagueId, number> = { NBA: 15, DEV: 12, JBL1: 13, JBL2: 13, JBL3: 13, NCAA: 15 }

/** 所属なしにする */
export function release(state: GameState, p: Player) {
  const t = state.teams[p.teamId]
  if (t) t.roster = t.roster.filter((id) => id !== p.id)
  p.teamId = -1
  p.contract = { salary: 0, years: 0, kind: 'none' }
}

/** 背番号を振る（チームの中で重ならないように。0〜99） */
export function assignJerseys(state: GameState, team: Team, rng: Rng) {
  const used = new Set<number>()
  for (const id of team.roster) {
    const p = state.players[id]
    if (p.jersey > 0 && !used.has(p.jersey)) {
      used.add(p.jersey)
      continue
    }
    let n = rng.int(0, 55)
    for (let tries = 0; used.has(n) && tries < 200; tries++) n = rng.int(0, 99)
    p.jersey = n
    used.add(n)
  }
}

export function createWorld(opts: WorldOptions): GameState {
  const rng = createRng(opts.seed)
  const state: GameState = {
    schemaVersion: SCHEMA_VERSION,
    mode: opts.mode,
    seed: opts.seed,
    startYear: opts.startYear ?? 2026,
    season: 0,
    week: 0,
    nextId: 1,
    players: {},
    teams: [],
    leagues: {} as GameState['leagues'],
    fixtures: [],
    series: [],
    news: [],
    awards: [],
    champions: [],
    draftPool: [],
    draftLog: [],
  }
  for (const [id, name, short, rules, tier] of LEAGUE_DEFS) state.leagues[id] = { id, name, short, rules, tier, teamIds: [], standings: {} }

  // NBA と育成リーグ（提携）
  NBA_TEAMS.forEach((d, i) => {
    const t = addTeam(state, 'NBA', d, { conf: d.conf, div: d.div, arena: { name: `${d.city}・${NBA_ARENA[i % NBA_ARENA.length]}`, capacity: 18000 + Math.round(rng.range(0, 3000) / 100) * 100 } }, rng)
    const dev = addTeam(state, 'DEV', { ...d, nickname: `${d.nickname}・ネクスト`, rep: 50 }, { arena: { name: `${d.city}・ネクストアリーナ`, capacity: 4000 } }, rng)
    t.affiliate = dev.id
    dev.affiliate = t.id
  })
  // 国内
  const jbl: [LeagueId, TeamDef[], number][] = [
    ['JBL1', JBL1_TEAMS, 8000],
    ['JBL2', JBL2_TEAMS, 4000],
    ['JBL3', JBL3_TEAMS, 2500],
  ]
  for (const [id, defs, cap] of jbl) for (const d of defs) addTeam(state, id, d, { arena: { name: `${d.city}アリーナ`, capacity: Math.round(cap * (0.8 + (d.rep / 100) * 0.4) / 100) * 100 } }, rng)
  // 大学
  for (const conf of COLLEGE_CONFS)
    for (const s of conf.schools)
      addTeam(state, 'NCAA', { city: s.name, nickname: s.short, abbr: s.short.slice(0, 3), primary: s.primary, secondary: s.secondary, rep: s.rep }, { conf: conf.name, arena: { name: `${s.short}・フィールドハウス`, capacity: 6000 + s.rep * 80 } }, rng)

  // 選手
  for (const t of state.teams) {
    if (t.league === 'NBA') fillNba(state, t, rng)
    else if (t.league === 'DEV') fillDev(state, t, rng)
    else if (t.league === 'NCAA') fillCollege(state, t, rng)
    else fillJbl(state, t, rng)
  }
  placeStars(state, rng)
  fillFreeAgents(state, rng, 120)
  for (const t of state.teams) assignJerseys(state, t, rng)
  assignPhotos(state)
  scheduleSeason(state, rng)
  return state
}
