/**
 * ゲーム状態のストア。GameState 本体は mutable で、Zustand には参照と version だけ置く。
 * エンジンで state を書き換えたら bump() で再描画する。操作のあとに自動保存（まとめて、少し遅らせて）。
 * 週の進行（advance）は M3 で足す。
 */
import { create } from 'zustand'
import { dateLabel, type GameState } from '../engine'
import { markStep } from '../engine/models/game'
import { NBA_DRAFT_WEEK } from '../engine/core/calendar'
import { advanceWeek, type WeekReport } from '../engine/core/advanceWeek'
import type { MatchSummary } from '../engine/match/types'
import { careerAfterWeek, careerBeforeWeek, statsSnapshot } from '../engine/career/week'
import { createCareerGame, type CareerNewOptions } from '../engine/career/create'
import { talkOf } from '../engine/career/talks'
import { createClubGame, type ClubNewOptions } from '../engine/club/create'
import { clubAfterWeek } from '../engine/club/week'
import { hasChoiceScene } from '../engine/club/story'
import { saveSnapshot } from '../persistence/db'
import { loadGame, saveGame } from '../persistence/db'
import { setHasGameProbe, useUi } from './uiStore'

/** 処理中に起きたエラー（画面に出して、直前のセーブに戻す） */
export interface GameError {
  where: string
  message: string
  stack: string
  season: number
  week: number
  /** そのとき開いていた画面（下から順に。書き出したセーブに入れて原因を調べる） */
  screens?: string
  /** 直前のセーブに戻したか */
  restored?: boolean
}

interface GameStore {
  state: GameState | null
  version: number
  slotId: number
  /** 新しいゲームを入れる（作成画面から）。persist=false は保存しない（ワールドを見るだけ・開発用） */
  start: (state: GameState, slotId: number, persist?: boolean) => void
  /** 保存しないゲーム（ワールドを見るだけ） */
  ephemeral: boolean
  load: (slotId: number) => Promise<boolean>
  bump: () => void
  /** state を書き換えて再描画・保存する（画面からの変更はここを通す） */
  mutate: (fn: (state: GameState) => void) => void
  persist: () => void
  close: () => void
  error: GameError | null
  /** エラーを記録して、ゲームを直前のセーブに戻す。restore=false なら戻さない */
  fail: (where: string, e: unknown, restore?: boolean) => void
  clearError: () => void
  /** 週を進める（weeks 週。1 週ずつ、画面に進み具合を出しながら）。シーズンの終わり・返事の要る話で止まる */
  advance: (weeks: number) => Promise<WeekReport[]>
  /** キャリアを始める */
  newCareer: (opts: CareerNewOptions, slotId: number) => GameState
  /** クラブ経営を始める */
  newClub: (opts: ClubNewOptions, slotId: number) => GameState
  /** キャリア・クラブ: 1 週進める（観戦した試合の結果を渡す） */
  playWeek: (played?: Map<number, MatchSummary>) => WeekReport | null
  /** advance の進み具合（進めた週 / 全部）。進めていなければ null */
  progress: { done: number; total: number } | null
}

export function slotMeta(state: GameState) {
  const c = state.career
  const p = c ? state.players[c.playerId] : undefined
  const clubTeam = state.club ? state.teams[state.club.teamId] : undefined
  const team = clubTeam ?? (p && p.teamId >= 0 ? state.teams[p.teamId] : undefined)
  return {
    title: clubTeam ? clubTeam.name : p ? `${p.name}${team ? `（${team.short}）` : ''}` : state.mode === 'career' ? 'キャリア' : 'クラブ',
    season: state.season,
    week: state.week,
    dateLabel: dateLabel(state.startYear, state.season, state.week),
    leagueName: team ? state.leagues[team.league].name : '',
    rank: 0,
    money: state.club?.money ?? c?.money ?? 0,
    mode: state.mode,
  }
}

/**
 * 自動保存をまとめる。セーブは大きな JSON なので、操作のたびに作ると画面が止まる。
 * 操作が落ち着いてから 1 回だけ保存する（SAVE_DELAY）。アプリが裏に回る・閉じるとき、セーブの一覧を見るとき、
 * 別のセーブを読むときはすぐ保存する（flushSave）。エラーで直前のセーブに戻すときは捨てる（cancelSave）
 */
const SAVE_DELAY = 800
let pending: { timer: ReturnType<typeof setTimeout>; state: GameState; slotId: number } | null = null

function scheduleSave(state: GameState, slotId: number) {
  if (pending) clearTimeout(pending.timer)
  pending = { timer: setTimeout(() => void flushSave(), SAVE_DELAY), state, slotId }
}

/** まだ書いていない自動保存をすぐ書く */
export function flushSave(): Promise<void> {
  if (!pending) return Promise.resolve()
  const p = pending
  pending = null
  clearTimeout(p.timer)
  return saveGame(p.slotId, p.state, slotMeta(p.state)).catch((e) => console.error('[自動保存]', e))
}

function cancelSave() {
  if (pending) clearTimeout(pending.timer)
  pending = null
}

if (typeof document !== 'undefined') {
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') void flushSave()
  })
  window.addEventListener('pagehide', () => void flushSave())
  // 新しい版に読み直す前（ui/stage/appUpdate.ts）
  window.addEventListener('cc:flush', () => void flushSave())
}

export const useGame = create<GameStore>((set, get) => ({
  state: null,
  version: 0,
  slotId: 1,
  error: null,
  fail: (where, e, restore = true) => {
    const err = e instanceof Error ? e : new Error(String(e))
    const st = get().state
    console.error(`[${where}]`, err)
    const stack = (err.stack ?? '').split('\n').slice(0, 12).join('\n')
    // 開いていた画面（書き出したセーブに入れる。どの画面・どの操作で起きたかを調べる）
    const screens = useUi
      .getState()
      .stack.map((s) => s.id + (s.params && Object.keys(s.params).length ? JSON.stringify(s.params) : ''))
      .join(' > ')
    set({ error: { where, message: err.message, stack, season: st?.season ?? -1, week: st?.week ?? -1, screens, restored: !!(st && restore) } })
    // 中途半端に書き換わった状態は保存しない
    if (st && restore) {
      cancelSave()
      void get().load(get().slotId)
    }
  },
  clearError: () => set({ error: null }),
  ephemeral: false,
  start: (state, slotId, persist = true) => {
    set({ state, slotId, version: get().version + 1, ephemeral: !persist })
    if (!persist) return
    get().persist()
    void flushSave()
  },
  load: async (slotId) => {
    await flushSave()
    const state = await loadGame(slotId)
    if (!state) return false
    set({ state, slotId, version: get().version + 1, ephemeral: false })
    return true
  },
  bump: () => set((s) => ({ version: s.version + 1 })),
  mutate: (fn) => {
    const { state } = get()
    if (!state) return
    try {
      fn(state)
    } catch (e) {
      get().fail('画面の操作', e)
      return
    }
    get().bump()
    get().persist()
  },
  persist: () => {
    const { state, slotId, ephemeral } = get()
    if (state && !ephemeral) scheduleSave(state, slotId)
  },
  close: () => {
    void flushSave()
    set({ state: null })
  },
  newCareer: (opts, slotId) => {
    const state = createCareerGame(opts)
    get().start(state, slotId)
    return state
  },
  newClub: (opts, slotId) => {
    const state = createClubGame(opts)
    get().start(state, slotId)
    return state
  },
  playWeek: (played) => {
    const { state } = get()
    if (!state) return null
    try {
      const r = careerStep(state, played)
      if (r.seasonEnded && !get().ephemeral) void saveSnapshot(get().slotId, state)
      get().bump()
      get().persist()
      return r
    } catch (e) {
      get().fail('週を進める', e)
      return null
    }
  },
  progress: null,
  advance: async (weeks) => {
    const { state } = get()
    if (!state) return []
    const out: WeekReport[] = []
    if (weeks > 1) markStep(state, 'auto')
    set({ progress: { done: 0, total: weeks } })
    try {
      for (let i = 0; i < weeks; i++) {
        await nextPaint()
        const bidsBefore = new Set(state.club?.bids.map((b) => b.id))
        const r = careerStep(state)
        out.push(r)
        set({ progress: { done: i + 1, total: weeks } })
        if (r.seasonEnded) {
          if (!get().ephemeral) void saveSnapshot(get().slotId, state)
          break
        }
        // クラブ: ゲームオーバーで止まる。NBA ドラフトの週の前に、指名リストが空なら止まる
        if (state.club?.gameOver) break
        if (state.club && hasChoiceScene(state)) break
        // 売りに出した選手に申し入れが来たら止まる（返事の期限が 3 週）
        if (state.club?.bids.some((b) => !bidsBefore.has(b.id) && state.club!.listed?.includes(b.playerId))) break
        if (state.club && state.week === NBA_DRAFT_WEEK && state.draftPool.length && state.teams[state.club.teamId].league === 'NBA' && !state.club.draftBoard?.length) break
        // キャリア: 返事の要る話・契約の話が来たら止まる
        if (state.career && (state.career.talks.some((t) => talkOf(t.id, state)?.choices) || state.career.offers.length > 0)) break
      }
    } catch (e) {
      set({ progress: null })
      get().fail('週を進める', e)
      return out
    }
    set({ progress: null })
    get().bump()
    get().persist()
    return out
  },
}))

/** 1 週（キャリア・クラブなら前と後の処理つき） */
function careerStep(state: GameState, played?: Map<number, MatchSummary>): WeekReport {
  // はじめの一歩: 週を進めた・おでかけした・観戦した
  markStep(state, 'week')
  if (played?.size) markStep(state, 'watch')
  if (state.career?.action === 'outing') markStep(state, 'outing')
  if (state.club) {
    const r = advanceWeek(state, played)
    clubAfterWeek(state, r)
    return r
  }
  if (!state.career) return advanceWeek(state, played)
  careerBeforeWeek(state)
  const before = statsSnapshot(state)
  const r = advanceWeek(state, played)
  careerAfterWeek(state, before, r)
  return r
}

/** 画面に描かせてから次へ（1 週ごとに進み具合を出す） */
const nextPaint = () => new Promise<void>((r) => requestAnimationFrame(() => setTimeout(r, 0)))

// 画面のスタックの「戻る」で、戻り先がないときにゲーム中ならホームへ
setHasGameProbe(() => !!useGame.getState().state)

/** 画面用: state を必ず返す（ゲーム中の画面だけで使う） */
export function useGameState(): GameState {
  const state = useGame((s) => s.state)
  useGame((s) => s.version)
  if (!state) throw new Error('ゲームが始まっていない')
  return state
}
