/** 古いセーブを今の形に直す。SCHEMA_VERSION を上げたらここに変換を足す。 */
import { SCHEMA_VERSION, type GameState } from '../models/game'
import { STAR_GROWTH } from '../gen/worldGen'
import { ageAt } from './calendar'
import { repairDoubleDrop } from '../competition/repair'
import { setOwnerGoal } from '../club/week'

type Migration = (s: GameState) => void

/** MIGRATIONS[n] は version n → n+1 の変換 */
const MIGRATIONS: Record<number, Migration> = {
  // 1 → 2: 若い固有キャラ（レオ・ブルックス・村上）の成長タイプを決める（超早熟だと伸びしろに届く前に衰えた）。まだ 24 歳までの人だけ
  1: (s) => {
    const abs = s.season * 52 + s.week
    for (const p of Object.values(s.players)) {
      const g = p.castId ? STAR_GROWTH[p.castId] : undefined
      if (g && !p.retired && ageAt(abs, p.birthAbs) <= 24) p.growth = g
    }
  },
  // 2 → 3: 1 部から下がったクラブが 3 部まで二段落ちしていたのを、新しいシーズンの試合の前なら 2 部へ戻す
  2: (s) => {
    const fixed = repairDoubleDrop(s)
    // 自分のクラブが 2 部に戻ったら、オーナーの今季の目標も 2 部で決め直す
    if (s.club && fixed.includes(s.club.teamId)) setOwnerGoal(s)
  },
}

export function migrate(state: GameState): GameState {
  let v = state.schemaVersion ?? 1
  while (v < SCHEMA_VERSION) {
    MIGRATIONS[v]?.(state)
    v++
  }
  state.schemaVersion = SCHEMA_VERSION
  return state
}
