/** 状態から引くよく使う値。 */
import { ageAt, absWeekOf } from './core/calendar'
import type { GameState } from './models/game'
import type { Team } from './models/league'
import type { Player } from './models/player'
import { ovr } from './player/overall'

export function nowAbs(state: GameState): number {
  return absWeekOf(state.season, state.week)
}

export function ageOf(state: GameState, p: Player): number {
  return ageAt(nowAbs(state), p.birthAbs)
}

export function teamOf(state: GameState, p: Player): Team | undefined {
  return p.teamId >= 0 ? state.teams[p.teamId] : undefined
}

export function rosterOf(state: GameState, team: Team): Player[] {
  return team.roster.map((id) => state.players[id])
}

export function teamsOf(state: GameState, league: keyof GameState['leagues']): Team[] {
  return state.leagues[league].teamIds.map((id) => state.teams[id])
}

/** 外国籍か（国内リーグの外国籍枠の判定。日本以外はすべて） */
export function isForeign(p: Player): boolean {
  return p.nation !== 'JP'
}

/** チームの戦力（上位 8 人の総合値の平均） */
export function teamPower(state: GameState, t: Team): number {
  const v = rosterOf(state, t)
    .map((p) => ovr(p))
    .sort((a, b) => b - a)
    .slice(0, 8)
  return v.length ? v.reduce((s, x) => s + x, 0) / v.length : 0
}
