/**
 * 年間表彰（シーズンの終わり、成績を経歴に移す前）。
 *   NBA: MVP・新人王・最優秀守備選手・シックスマン賞・MIP（いちばん伸びた選手）・オール NBA 1〜3 番手（G 2・F 2・C 1）・得点王
 *   国内 1 部と 2・3 部: MVP・得点王、大学: 年間最優秀選手
 */
import type { GameState } from '../models/game'
import type { LeagueId } from '../models/league'
import type { Player, Stats } from '../models/player'
import { ovr } from '../player/overall'
import { winPct } from './standings'

const per = (s: Stats, k: keyof Stats) => (s.gp ? s[k] / s.gp : 0)
const reb = (s: Stats) => (s.gp ? (s.oreb + s.dreb) / s.gp : 0)

function line(s: Stats): string {
  return `平均 ${per(s, 'pts').toFixed(1)} 点・${reb(s).toFixed(1)} リバウンド・${per(s, 'ast').toFixed(1)} アシスト`
}

function playersIn(state: GameState, league: LeagueId, minGames: number): Player[] {
  const ids = new Set(state.leagues[league].teamIds)
  return Object.values(state.players).filter((p) => ids.has(p.teamId) && p.stats.gp >= minGames)
}

/** 貢献の点（MVP・オール NBA の順番） */
export function mvpScore(state: GameState, p: Player): number {
  const s = p.stats
  const st = state.leagues[state.teams[p.teamId].league].standings[p.teamId]
  const team = st ? winPct(st) : 0.5
  const eff = s.fga ? (s.pts / (2 * (s.fga + 0.44 * s.fta))) * 10 : 0
  return per(s, 'pts') * 1.0 + reb(s) * 0.55 + per(s, 'ast') * 0.75 + (per(s, 'stl') + per(s, 'blk')) * 1.2 + eff * 1.5 + team * 18 + per(s, 'min') * 0.1
}

function defScore(p: Player): number {
  const s = p.stats
  return per(s, 'stl') * 3 + per(s, 'blk') * 3 + per(s, 'dreb') * 0.6 + (p.attr.perD + p.attr.intD) * 0.05 + per(s, 'min') * 0.08
}

export function giveAwards(state: GameState) {
  const season = state.season
  const add = (league: LeagueId, award: string, p: Player | undefined, extra?: string) => {
    if (!p) return
    state.awards.push({ season, league, award, playerId: p.id, name: p.name, teamName: state.teams[p.teamId]?.name ?? '', line: extra ?? line(p.stats) })
  }
  // ---- NBA
  const nba = playersIn(state, 'NBA', 50)
  if (nba.length) {
    const byMvp = [...nba].sort((a, b) => mvpScore(state, b) - mvpScore(state, a))
    add('NBA', 'MVP', byMvp[0])
    // 新人: この夏のドラフトで指名された選手（ワールドを作ったときは、その年の指名の扱いの選手）
    const year = state.startYear + season
    const rookies = nba.filter((p) => p.history.every((h) => h.league !== 'NBA') && (p.draft?.year ?? 0) >= year)
    add('NBA', '新人王', rookies.sort((a, b) => mvpScore(state, b) - mvpScore(state, a))[0])
    const dpoy = [...nba].sort((a, b) => defScore(b) - defScore(a))[0]
    add('NBA', '最優秀守備選手', dpoy, `平均 ${per(dpoy.stats, 'stl').toFixed(1)} スティール・${per(dpoy.stats, 'blk').toFixed(1)} ブロック`)
    const bench = nba.filter((p) => p.stats.gs < p.stats.gp * 0.3)
    add('NBA', 'シックスマン賞', bench.sort((a, b) => per(b.stats, 'pts') - per(a.stats, 'pts'))[0])
    const mip = nba
      .filter((p) => p.history.length > 0)
      .map((p) => ({ p, d: ovr(p) - p.history[p.history.length - 1].ovr + (per(p.stats, 'pts') - per(p.history[p.history.length - 1].stats, 'pts')) * 0.4 }))
      .sort((a, b) => b.d - a.d)[0]
    add('NBA', 'MIP', mip?.p)
    // オール NBA: ガード 2・フォワード 2・センター 1 を 3 チーム
    const used = new Set<number>()
    for (const [team, label] of [
      [1, '1st'],
      [2, '2nd'],
      [3, '3rd'],
    ] as const) {
      void team
      const need: [string[], number][] = [
        [['PG', 'SG'], 2],
        [['SF', 'PF'], 2],
        [['C'], 1],
      ]
      for (const [pos, n] of need) {
        const picks = byMvp.filter((p) => pos.includes(p.pos) && !used.has(p.id)).slice(0, n)
        for (const p of picks) {
          used.add(p.id)
          add('NBA', `オール NBA ${label}`, p)
        }
      }
    }
    const scorer = [...nba].sort((a, b) => per(b.stats, 'pts') - per(a.stats, 'pts'))[0]
    add('NBA', '得点王', scorer, `平均 ${per(scorer.stats, 'pts').toFixed(1)} 点`)
  }
  // ---- 国内と大学
  for (const [league, min, title] of [
    ['JBL1', 36, 'MVP'],
    ['JBL2', 36, 'MVP'],
    ['JBL3', 36, 'MVP'],
    ['NCAA', 18, '年間最優秀選手'],
  ] as const) {
    const ps = playersIn(state, league, min)
    if (!ps.length) continue
    add(league, title, [...ps].sort((a, b) => mvpScore(state, b) - mvpScore(state, a))[0])
    if (league !== 'NCAA') {
      const scorer = [...ps].sort((a, b) => per(b.stats, 'pts') - per(a.stats, 'pts'))[0]
      add(league, '得点王', scorer, `平均 ${per(scorer.stats, 'pts').toFixed(1)} 点`)
    }
  }
  const mvp = state.awards.find((a) => a.season === season && a.league === 'NBA' && a.award === 'MVP')
  if (mvp) state.news.push({ season, week: state.week, text: `NBA の MVP は ${mvp.name}（${mvp.teamName}）。${mvp.line}`, big: true })
}
