/**
 * 日本代表（キャリア）。
 *   招集: 日本人の選手（どのリーグでも）を総合値の順に 12 人。主人公が入れば試合に出る
 *   代表の週（第 19・31 週）: アジアの国と 2 試合
 *   夏の国際大会（第 5 週。西暦が 4 で割って 3 余る年はワールドカップ、割り切れる年は夏の世界大会）: 予選 3 試合 → 準々決勝・準決勝・決勝
 * 相手の国は、その国の選手（足りなければその国の強さに合わせた仮の選手）で作る。試合は試合エンジン（結果だけ）。
 */
import { NATIONAL_WINDOWS, absWeekOf } from '../core/calendar'
import { createRng, hashSeed, type Rng } from '../core/prng'
import { NATION_NAME, type Nation } from '../data/nations'
import { POSITIONS } from '../data/positions'
import { pickStyle, rollBody, shapeAttrs } from '../gen/playerGen'
import type { GameState } from '../models/game'
import { DEFAULT_TACTICS } from '../models/league'
import type { Player } from '../models/player'
import { MatchEngine } from '../match/engine'
import { playerInput } from '../match/setup'
import type { PlayerInput, TeamInput } from '../match/types'
import { ovr } from '../player/overall'
import { careerPlayer } from './week'

/** 国の強さ（主力 8 人の総合値の目安） */
const STRENGTH: Partial<Record<Nation, number>> = { US: 86, CA: 79, FR: 79, RS: 80, DE: 78, ES: 77, AU: 76, GR: 76, SI: 76, LT: 75, LV: 72, TR: 73, IT: 74, BR: 72, AR: 73, PR: 70, DO: 70, NG: 71, SS: 70, KR: 62, CN: 64, PH: 62 }
const ASIA: Nation[] = ['KR', 'CN', 'PH', 'AU']
const WORLD: Nation[] = ['US', 'CA', 'FR', 'RS', 'DE', 'ES', 'AU', 'GR', 'SI', 'LT', 'BR', 'AR', 'NG', 'TR', 'IT', 'PR']

export function nationalSquad(state: GameState): Player[] {
  return Object.values(state.players)
    .filter((p) => p.nation === 'JP' && !p.retired && !p.injury && (p.teamId >= 0 || p.isPlayer))
    .sort((a, b) => ovr(b) + (b.isPlayer ? (state.career?.fame ?? 0) * 0.04 : 0) - (ovr(a) + (a.isPlayer ? (state.career?.fame ?? 0) * 0.04 : 0)))
    .slice(0, 12)
}

function teamOfNation(state: GameState, nation: Nation, rng: Rng): TeamInput {
  const real = Object.values(state.players)
    .filter((p) => p.nation === nation && p.teamId >= 0 && !p.retired)
    .sort((a, b) => ovr(b) - ovr(a))
    .slice(0, 12)
    .map(playerInput)
  const players: PlayerInput[] = [...real]
  const target = STRENGTH[nation] ?? 68
  let i = 0
  while (players.length < 10) {
    // 足りない分は仮の選手（世界の選手には足さない）
    const pos = POSITIONS[i % 5]
    const body = rollBody(pos, nation, rng)
    const style = pickStyle(pos, rng)
    const o = Math.round(target - 2 - i * 1.2 + rng.normal(0, 2))
    const attr = shapeAttrs(o, pos, style, body, rng)
    players.push({ id: -(100000 + hashSeed(nation.charCodeAt(0), nation.charCodeAt(1), i) % 100000), name: `${NATION_NAME[nation]}の選手 ${i + 1}`, short: `${NATION_NAME[nation].slice(0, 2)}${i + 1}`, jersey: 4 + i, pos, style, nation, ...body, skills: {}, ovr: o, attr, foreignSlot: false })
    i++
  }
  const colors = { primary: nation === 'US' ? '#1e3a8a' : '#334155', secondary: '#ffffff' }
  return { teamId: -1, name: NATION_NAME[nation], short: NATION_NAME[nation], abbr: nation, colors, tactics: { ...DEFAULT_TACTICS }, players }
}

function japan(state: GameState): TeamInput {
  const squad = nationalSquad(state)
  return { teamId: -1, name: '日本', short: '日本', abbr: 'JPN', colors: { primary: '#ffffff', secondary: '#d7263d' }, tactics: { ...DEFAULT_TACTICS }, players: squad.map(playerInput) }
}

interface Played {
  opp: Nation
  win: boolean
  score: string
  pts: number
}

function play(state: GameState, opp: Nation, seed: number): Played {
  const rng = createRng(seed)
  const home = japan(state)
  const away = teamOfNation(state, opp, rng)
  const e = new MatchEngine({ home, away, rules: 'FIBA', seed, neutral: true })
  const s = e.simulate()
  const me = careerPlayer(state)
  return { opp, win: s.score[0] > s.score[1], score: `${s.score[0]}-${s.score[1]}`, pts: s.box[me.id]?.pts ?? 0 }
}

/** 週の終わりに呼ぶ（careerAfterWeek から）。代表の週・夏の大会なら試合をして、会話で知らせる */
export function nationalWeek(state: GameState, played: { week: number; seasonEnded: boolean }) {
  const c = state.career!
  const me = careerPlayer(state)
  if (played.seasonEnded) return
  const year = state.startYear + state.season
  const isWindow = NATIONAL_WINDOWS.includes(played.week)
  const tournament = played.week === 5 && (year % 4 === 3 || year % 4 === 0)
  if (!isWindow && !tournament) return
  if (!nationalSquad(state).some((p) => p.id === me.id)) return
  const seed = hashSeed(state.seed, absWeekOf(state.season, played.week), 8181)
  const rng = createRng(seed)
  const results: Played[] = []
  let title: string
  if (isWindow) {
    title = '代表の試合（アジア予選）'
    for (let i = 0; i < 2; i++) results.push(play(state, rng.pick(ASIA), seed + i))
  } else {
    const name = year % 4 === 3 ? 'ワールドカップ' : '夏の世界大会'
    const group = rng.shuffle([...WORLD]).slice(0, 3)
    for (let i = 0; i < 3; i++) results.push(play(state, group[i], seed + i))
    const wins = results.filter((r) => r.win).length
    let stage = '予選敗退'
    if (wins >= 2) {
      stage = 'ベスト 8'
      const rounds = ['ベスト 4', '準優勝', '優勝']
      const opps = rng.shuffle(WORLD.filter((n) => !group.includes(n)))
      for (let r = 0; r < 3; r++) {
        const res = play(state, r === 2 ? 'US' : opps[r], seed + 10 + r)
        results.push(res)
        if (!res.win) {
          stage = r === 0 ? 'ベスト 8' : r === 1 ? 'ベスト 4' : '準優勝'
          break
        }
        stage = rounds[r]
      }
    }
    title = `${name} ${year}: ${stage}`
    if (stage !== '予選敗退') state.news.push({ season: state.season, week: played.week, text: `日本代表、${name}で${stage}`, big: true })
  }
  const n = (c.national ??= { caps: 0, pts: 0, events: [] })
  n.caps += results.length
  n.pts += results.reduce((s, r) => s + r.pts, 0)
  n.events.push(title)
  const won = title.endsWith('優勝') && !title.endsWith('準優勝')
  c.fame = Math.min(100, c.fame + results.length * 0.8 + (won ? 10 : title.includes('準優勝') || title.includes('ベスト 4') ? 4 : 0))
  c.lastNational = `${title}。${results.map((r) => `${r.win ? '○' : '●'} ${NATION_NAME[r.opp]} ${r.score}（${r.pts} 点）`).join('、')}`
  c.talks.push({ id: 'national', speaker: 'kuroda_takeshi' })
}
