/**
 * キャリアモードの登場人物（固有キャラ）。写真は tools/gen/jobs.py の cast セット（id が同じ）。
 * 名前は実在の選手・有名人と重ならないように選んである。
 * 恋愛が進むのは、主人公と相手がどちらも 18 歳以上で romance: true の人だけ（全年齢向け。性的表現・飲酒の描写なし）。
 */

/** 会える地域。jp は日本にいるとき、us はアメリカ（大学・NBA）にいるとき、any はどこでも */
export type CastRegion = 'jp' | 'us' | 'any'

export type CastKind = 'heroine' | 'mentor' | 'friend' | 'rival' | 'staff' | 'teammate'

export interface CastDef {
  id: string
  name: string
  kana: string
  /** ゲーム開始（主人公 18 歳）のときの年齢 */
  age: number
  kind: CastKind
  /** 肩書き（画面に出す） */
  role: string
  region: CastRegion
  /** 恋愛が進められる（18 歳以上・独身） */
  romance?: boolean
  /** 国籍（JP・US など） */
  nation: string
  /** ひとこと紹介 */
  intro: string
  /** 二代目（主人公の子どもの世代）の人。age は二代目のキャリアが始まったときの年齢 */
  gen?: 2
}

