/**
 * 週を進める。
 *   週のはじめ: プレーオフ（NBA プレーイン・大学の選手権・国内のチャンピオンシップ）・ドラフトの候補・FA と人数合わせ
 *   試合: 曜日の順に。プレーオフの次の試合は、前の試合が終わってから足される
 *   週の終わり: 選手（ケガ・成長と衰え・調子・疲れ）・ドラフト（第 51 週）→ 週を進める（第 51 週のあとはシーズンの終わり）
 * 観戦した試合の結果は played で渡す（その試合はシミュレーションしない）。乱数は週ごとの流れ（weekRng）。
 */
import { DRAFT_ENTRY_WEEKS, NBA_FA_WEEKS, WEEKS_PER_SEASON, absWeekOf } from './calendar'
import { weekRng } from './prng'
import type { GameState, NewsItem } from '../models/game'
import type { Fixture } from '../models/league'
import type { MatchSummary } from '../match/types'
import { simulateMatch } from '../match/engine'
import { fixtureSetup } from '../match/setup'
import { applyResult } from '../competition/results'
import { isNeutral, seriesResult, startPlayoffs } from '../competition/playoffs'
import { buildDraftPool } from '../competition/draft'
import { seasonEnd } from '../competition/seasonEnd'
import { fillRosters } from '../transfer/freeAgency'
import { growPlayer, moveCondition, recoverFatigue } from '../player/growth'
import { clubGrowthBias, clubRecoverBonus, isClubPlayer } from '../club/effects'
import { cupResult, cupWeek } from '../competition/cup'
import { eaccWeek } from '../competition/eacc'
import { clubCupResult, clubEaccGames } from '../club/story'
import { resolveFaBids } from '../club/nbaLife'
import { RIVAL, rivalGrowthBias } from '../career/rival'

export interface WeekReport {
  season: number
  week: number
  games: number
  news: NewsItem[]
  seasonEnded: boolean
}

/** 今週の、まだ行っていない試合（曜日の順） */
export function weekFixtures(state: GameState, day?: number): Fixture[] {
  return state.fixtures.filter((f) => f.week === state.week && !f.result && (day === undefined || f.day === day)).sort((a, b) => a.day - b.day || a.id - b.id)
}

export function advanceWeek(state: GameState, played: Map<number, MatchSummary> = new Map()): WeekReport {
  const abs = absWeekOf(state.season, state.week)
  const rng = weekRng(state.seed, abs)
  const newsFrom = state.news.length
  const week = state.week
  const season = state.season

  // ---- 週のはじめ
  startPlayoffs(state)
  if (state.club) resolveFaBids(state, rng)
  cupWeek(state, rng)
  const eaccGames = eaccWeek(state, rng, played)
  if (state.club && eaccGames.length) clubEaccGames(state, eaccGames)
  if (week === DRAFT_ENTRY_WEEKS[1]) buildDraftPool(state, rng)
  if (week <= NBA_FA_WEEKS[1] || week % 4 === 0) fillRosters(state, rng)

  // ---- 試合（曜日の順。プレーオフの次の試合はその場で足される）
  // 流れ（点差の動き）を残すのは、主人公のチームと自分のクラブの試合だけ
  const focus = new Set<number>([state.club?.teamId ?? -1, state.career ? state.players[state.career.playerId].teamId : -1])
  const minutes = new Map<number, number>()
  const games = new Map<number, number>()
  let n = 0
  for (let day = 0; day < 7; day++) {
    for (const f of weekFixtures(state, day)) {
      const sum = played.get(f.id) ?? simulateMatch({ ...fixtureSetup(state, f), neutral: isNeutral(state, f) })
      applyResult(state, f, sum, rng)
      if (focus.has(f.home) || focus.has(f.away)) f.result!.flow = sum.flow
      if (f.kind === 'cup') {
        const res = cupResult(state, f)
        if (res && state.club) clubCupResult(state, res)
      } else if (f.kind !== 'regular') seriesResult(state, f)
      for (const [id, b] of Object.entries(sum.box)) {
        minutes.set(Number(id), (minutes.get(Number(id)) ?? 0) + b.secs / 60)
        games.set(Number(id), (games.get(Number(id)) ?? 0) + 1)
      }
      for (const id of [f.home, f.away]) for (const pid of state.teams[id].roster) if (!games.has(pid)) games.set(pid, 0)
      n++
    }
  }

  // ---- 選手（クラブ経営: 自分のクラブの選手は練習場・コーチ・練習の計画が効く）
  const hasClub = !!state.club
  const recoverBonus = state.club ? clubRecoverBonus(state) : 0
  for (const p of Object.values(state.players)) {
    if (p.retired) continue
    if (p.injury) {
      p.injury.weeks--
      if (p.injury.weeks <= 0) delete p.injury
    }
    const g = games.get(p.id)
    // 試合のない週（オフ）は練習だけ（出場の割合 0.5 とみなす）。試合があって出なかった選手は 0
    const share = g === undefined ? 0.5 : g === 0 ? 0 : Math.min(1, (minutes.get(p.id) ?? 0) / (g * 32))
    const mine = hasClub && isClubPlayer(state, p)
    growPlayer(p, abs, share, rng, mine ? clubGrowthBias(state, p) : p.castId === RIVAL ? rivalGrowthBias(state, p) : undefined)
    moveCondition(p, rng)
    recoverFatigue(p, mine ? recoverBonus : 0)
  }

  // ---- シーズンの終わり（第 51 週。表彰 → 経歴 → ドラフト → …）
  let seasonEnded = false
  if (state.week >= WEEKS_PER_SEASON - 1) {
    seasonEnd(state, rng)
    seasonEnded = true
  } else state.week++
  return { season, week, games: n, news: state.news.slice(newsFrom), seasonEnded }
}
