export interface SponsorTier {
  id: 'local' | 'national' | 'global' | 'shoe'
  name: string
  fame: number
  /** 毎年の額（万円） */
  pay: number
  desc: string
}

export const SPONSOR_TIERS: SponsorTier[] = [
  { id: 'local', name: '地元の企業', fame: 20, pay: 500, desc: '地元の商店街やお店の広告' },
  { id: 'national', name: '全国の企業', fame: 45, pay: 3000, desc: 'テレビ CM や駅の広告' },
  { id: 'global', name: '世界のブランド', fame: 70, pay: 20000, desc: '世界中の広告に出る（NBA の選手だけ）' },
  { id: 'shoe', name: '自分のモデルのシューズ', fame: 85, pay: 80000, desc: '名前の入ったシューズが世界で売られる（NBA のオールスターだけ）' },
]

/** 今の契約できるスポンサーの段（いちばん上） */
export function sponsorTier(state: GameState): SponsorTier | null {
  const c = state.career!
  const p = careerPlayer(state)
  const nba = p.teamId >= 0 && state.teams[p.teamId].league === 'NBA'
  const allStar = state.awards.some((a) => a.playerId === p.id && a.award === 'オールスター')
  let best: SponsorTier | null = null
  for (const t of SPONSOR_TIERS) {
    if (c.fame < t.fame) continue
    if ((t.id === 'global' || t.id === 'shoe') && !nba) continue
    if (t.id === 'shoe' && !allStar) continue
    best = t
  }
  return best
}

export function housingOf(state: GameState): HousingDef {
  const c = state.career!
  const region = regionOf(state)
  const h = HOUSING.find((x) => x.id === c.housing)
  if (h && h.region === region) return h
  // 地域が変わったら、その地域の家（持ち家があればそこ、なければ寮・チームの部屋）
  const owned = HOUSING.find((x) => x.region === region && x.kind === 'buy' && c.ownedHomes?.includes(x.id))
  return owned ?? HOUSING.find((x) => x.region === region && x.kind === 'free')!
}

/** 税率（地域で） */
export function taxRate(state: GameState): number {
  return regionOf(state) === 'us' ? 0.45 : 0.3
}

/** 1 年の収支（万円）。画面のお金のタブ */
export function yearlyBudget(state: GameState): { salary: number; sponsor: number; tax: number; agent: number; rent: number; services: number; family: number; lifestyle: number; foundation: number; net: number } {
  const c = state.career!
  const p = careerPlayer(state)
  const salary = p.teamId >= 0 ? p.contract.salary : 0
  const sponsor = c.sponsor ? (SPONSOR_TIERS.find((t) => t.id === c.sponsor)?.pay ?? 0) : 0
  const gross = salary + sponsor
  const tax = Math.round(gross * taxRate(state))
  const agent = Math.round(gross * 0.05)
  const h = housingOf(state)
  const rent = h.kind === 'rent' ? h.cost : 0
  const services = (c.services ?? []).reduce((s, id) => s + SERVICE_DEFS[id].cost, 0)
  const family = (c.spouse ? 300 : 0) + (c.children?.length ?? 0) * 200
  const nba = p.teamId >= 0 && state.teams[p.teamId].league === 'NBA'
  // 有名になったぶんの出費は、年俸があるときだけ（大学生は寮ぐらし。年俸のない大学生が借金になっていた）
  const lifestyle = salary > 0 ? lifestyleCost(c.fame, nba) : 0
  const foundation = FOUNDATION_TIERS[c.foundation ?? 0]?.yearly ?? 0
  return { salary, sponsor, tax, agent, rent, services, family, lifestyle, foundation, net: gross - tax - agent - rent - services - family - lifestyle - foundation }
}

/** 毎週のお金と、住まい・サービスの効き目（careerBeforeWeek から） */
export function lifeWeek(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  const bud = yearlyBudget(state)
  c.money += bud.net / 52
  // 財団: 寄付の通算と、節目の知名度
  if (bud.foundation > 0) {
    const before = c.donated ?? 0
    c.donated = before + bud.foundation / 52
    c.fame = Math.min(100, c.fame + (c.foundation ?? 0) * 0.01)
    for (const line of [100000, 500000, 1000000]) if (before < line && c.donated >= line) c.talks.push({ id: `charity:${line}`, speaker: 'todo_maiko' })
  }
  // 足りなくなったら、財団 → サービス → 借りている住まいの順にやめる
  if (c.money < 0 && c.foundation) c.foundation = 0
  if (c.money < 0 && c.services?.length) c.services = []
  if (c.money < 0 && housingOf(state).kind === 'rent') c.housing = HOUSING.find((x) => x.region === regionOf(state) && x.kind === 'free')!.id
  const h = housingOf(state)
  const owned = c.purchases ?? []
  const us = regionOf(state) === 'us'
  p.fatigue = Math.max(0, p.fatigue - h.recover - (c.services?.includes('nutrition') ? 3 : 0) - (owned.includes('oxygen') ? 3 : 0) - (owned.includes('home_gym') ? 2 : 0))
  p.condition = Math.min(95, p.condition + h.comfort * 0.6 + (c.services?.includes('sleep') ? 1.5 : 0) + (carPrestige(state) > 0 ? 0.3 : 0) + (owned.includes('home_court') ? 0.5 : 0) + (us && owned.includes('english') ? 1 : 0))
  // 英会話: アメリカでは監督とも話しやすい
  if (us && owned.includes('english')) c.trust = Math.min(100, c.trust + 0.05)
  // スポンサーの段が上がったら知らせる（一度だけ）
  const tier = sponsorTier(state)
  if (tier && tier.id !== c.sponsor && !(c.seen.includes(`sponsor:${tier.id}`) || c.talks.some((t) => t.id === `sponsor:${tier.id}`))) c.talks.push({ id: `sponsor:${tier.id}`, speaker: 'todo_maiko' })
}

export function carPrestige(state: GameState): number {
  const c = state.career!
  return Math.max(0, ...(c.cars ?? []).map((id) => CARS.find((x) => x.id === id)?.prestige ?? 0))
}

export function canAfford(state: GameState, price: number): boolean {
  return state.career!.money >= price
}

export function moveIn(state: GameState, id: string) {
  const c = state.career!
  const h = HOUSING.find((x) => x.id === id)
  if (!h || h.region !== regionOf(state)) return
  if (h.kind === 'buy' && !c.ownedHomes?.includes(id)) {
    if (c.money < h.cost) return
    c.money -= h.cost
    c.ownedHomes = [...(c.ownedHomes ?? []), id]
  }
  c.housing = id
}

export function buyCar(state: GameState, id: string) {
  const c = state.career!
  const car = CARS.find((x) => x.id === id)
  if (!car || c.cars?.includes(id) || c.money < car.price) return
  c.money -= car.price
  c.cars = [...(c.cars ?? []), id]
  c.fame = Math.min(100, c.fame + car.prestige * 0.5)
}

export function toggleService(state: GameState, id: ServiceId) {
  const c = state.career!
  const s = new Set(c.services ?? [])
  if (s.has(id)) s.delete(id)
  else s.add(id)
  c.services = [...s]
}

/** トレーナーの経験点の倍率 */
export function trainerMul(state: GameState): number {
  return state.career?.services?.includes('trainer') ? 1.1 : 1
}
