/**
 * 成長と衰え（毎週）。成長タイプの年齢カーブ（data/growth.ts）で 1 年あたりの伸びを決め、52 で割って毎週足す。
 *   伸びはポジションで大事な能力ほど大きい。試合に出るほど伸びる（出場時間）。伸びしろ（pot）に近づくと鈍る
 *   衰えはタイプのピークを過ぎてから。瞬発系は早く落ち、頭（IQ・視野・外角守備）は 30 代半ばまで伸びる
 * 能力は小数で持ち、画面では丸めて出す。主人公（isPlayer）は自分の育成（キャリア）で伸ばすので、ここでは衰えだけ。
 */
import { ATTR_DEFS, ATTR_KEYS, type AttrKey } from '../data/attributes'
import { ageCurve, groupDownFactor, groupUpFactor } from '../data/growth'
import { PERSONALITY_DEFS } from '../data/personality'
import { WEEKS_PER_SEASON, ageAt } from '../core/calendar'
import type { Rng } from '../core/prng'
import type { Player } from '../models/player'
import { POS_WEIGHTS, ovr } from './overall'

/** 成長の全体の倍率（ワールドの能力のインフレ・デフレをここで合わせる。tools/drift.ts） */
export const GROWTH_SCALE = 0.56
export const DECLINE_SCALE = 1.2

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 成長の上乗せ（クラブ経営: 練習場・コーチ・練習の強さと重点） */
export interface GrowthBias {
  mul: number
  attr?: Partial<Record<AttrKey, number>>
}

/**
 * 1 週の成長と衰え。minutesShare は今週の出場時間の割合（0〜1。試合がない週は 0.5 とみなす）
 */
export function growPlayer(p: Player, absWeek: number, minutesShare: number, rng: Rng, bias?: GrowthBias) {
  const age = ageAt(absWeek, p.birthAbs) + ((absWeek - p.birthAbs) % WEEKS_PER_SEASON) / WEEKS_PER_SEASON
  const { up, down } = ageCurve(p.growth, age)
  const o = ovr(p)
  // 伸びしろに近いほど鈍る（超えたらほとんど伸びない）
  const room = p.pot - o
  const capMul = room > 6 ? 1 : room > 0 ? 0.25 + (room / 6) * 0.75 : 0.06
  const play = 0.65 + 0.7 * clamp(minutesShare, 0, 1)
  const persona = PERSONALITY_DEFS[p.personality].growthMul
  const upWeek = p.isPlayer ? 0 : (up / WEEKS_PER_SEASON) * GROWTH_SCALE * capMul * play * persona * (bias?.mul ?? 1)
  const downWeek = (down / WEEKS_PER_SEASON) * DECLINE_SCALE * (p.skills.includes('ironMan') ? 0.85 : 1)
  const w = POS_WEIGHTS[p.pos]
  for (const k of ATTR_KEYS) {
    const g = ATTR_DEFS[k].group
    // ポジションで大事な能力ほど伸びる（重み 0〜1.6 → 0.5〜1.5 倍）
    const focus = 0.5 + Math.min(1, w[k] / 1.6)
    const gain = upWeek * groupUpFactor(g, age) * focus * (bias?.attr?.[k] ?? 1) * (0.7 + rng.next() * 0.6)
    const loss = downWeek * groupDownFactor(g, age)
    p.attr[k] = clamp(p.attr[k] + gain - loss, 1, 99)
  }
}

/** 調子の波（毎週）。50 に戻ろうとしながら、性格の振れ幅で上下する */
export function moveCondition(p: Player, rng: Rng) {
  const v = PERSONALITY_DEFS[p.personality].conditionVar
  p.condition = clamp(p.condition + (50 - p.condition) * 0.25 + rng.normal(0, 9 * v), 5, 95)
}

/** 疲れの回復（毎週） */
export function recoverFatigue(p: Player, bonus = 0) {
  const extra = PERSONALITY_DEFS[p.personality].recover
  p.fatigue = clamp(p.fatigue - 32 - extra * 2 - bonus, 0, 100)
}

/** 試合でのケガ（出場した分だけ確率が上がる）。起きたら週数を返す */
export function rollInjury(p: Player, minutes: number, rng: Rng, mul = 1): number {
  let chance = 0.0022 * (minutes / 30) * (1 + p.fatigue / 120) * mul
  if (p.skills.includes('injuryProne')) chance *= 1.7
  if (p.skills.includes('ironMan')) chance *= 0.5
  if (!rng.chance(chance)) return 0
  const r = rng.next()
  return r < 0.6 ? rng.int(1, 2) : r < 0.9 ? rng.int(3, 6) : rng.int(8, 26)
}

export const INJURY_NAMES: [number, string][] = [
  [2, '足首のねんざ'],
  [2, '太ももの張り'],
  [6, 'ひざの打撲'],
  [6, 'ハムストリングの肉離れ'],
  [12, '足の甲の疲労骨折'],
  [30, 'ひざのじん帯の損傷'],
]

export function injuryName(weeks: number, rng: Rng): string {
  const cands = INJURY_NAMES.filter(([w]) => weeks <= w)
  return rng.pick(cands.length ? cands.slice(0, 2) : INJURY_NAMES.slice(-1)).at(1) as string
}
