/**
 * NBA へ向かう・NBA での出来事（キャリア）。
 *   ドラフト前: コンバイン（第 44 週。測定でドラフトの評価が上下）→ ワークアウト（第 47 週。受けたチームは指名しやすい）
 *   サマーリーグ（第 1 週。新人・2way・所属なしの若手）
 *   オールスター（第 31 週の終わりに選考。主人公が選ばれたら第 32 週に 3P コンテスト・ダンクコンテスト・本戦）
 *   トレード（第 20〜31 週。評価が低いと出されることがある・自分から要求もできる）
 *   契約の延長（第 20 週。最終年で主力なら）・FA の話（NBA の相場で複数のチームから）
 */
import { NBA_ALLSTAR_WEEK, NBA_TRADE_DEADLINE_WEEK, absWeekOf, ageAt } from '../core/calendar'
import { weekRng } from '../core/prng'
import { NBA_MIN, TWO_WAY_SALARY, nbaMarketSalary } from '../economy/salary'
import { mvpScore } from '../competition/awards'
import { allocId, type GameState } from '../models/game'
import type { CareerOffer } from '../models/career'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'
import { teamPower } from '../query'
import { signPlayer } from '../transfer/freeAgency'
import { careerAge, careerPlayer } from './week'
import { pushHeirTalk } from './heir'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** コンバインの測定（cm・秒）。能力と体格から（乱数は週の流れ） */
export function combineResult(state: GameState): { vertical: number; sprint: number; reach: number; grade: number } {
  const p = careerPlayer(state)
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), 44)
  const vertical = Math.round(55 + p.attr.jump * 0.38 + rng.normal(0, 3))
  const sprint = Math.round((3.55 - p.attr.speed * 0.0062 + rng.normal(0, 0.04)) * 100) / 100
  const reach = Math.round(p.heightCm * 1.32 + (p.wingspanCm - p.heightCm) * 0.6)
  // 評価: 運動能力の高さで +3〜−3
  const grade = clamp(Math.round(((p.attr.jump + p.attr.speed + p.attr.quick) / 3 - 62) / 6), -3, 3)
  return { vertical, sprint, reach, grade }
}

/** ワークアウトの候補（モックの順位のあたりで指名しそうな 3 チーム） */
export function workoutTeams(state: GameState): number[] {
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), 47)
  return rng.shuffle([...state.leagues.NBA.teamIds]).slice(0, 3)
}

/** 週の終わりに呼ぶ（careerAfterWeek から） */
export function nbaWeek(state: GameState, played: { week: number; seasonEnded: boolean }) {
  const c = state.career!
  const p = careerPlayer(state)
  const team = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  const w = played.week
  // ---- ドラフト前（名乗り出た年）
  if (c.declared === state.season && !played.seasonEnded) {
    if (w === 43) c.talks.push({ id: 'combine', speaker: 'todo_maiko' })
    if (w === 46) c.talks.push({ id: `workout:${workoutTeams(state).join(':')}`, speaker: 'todo_maiko' })
  }
  // ---- サマーリーグ（新しいシーズンの第 0 週のあと）
  if (w === 0 && (team?.league === 'NBA' || team?.league === 'DEV' || p.teamId < 0) && careerAge(state) <= 25 && (p.history.filter((h) => h.league === 'NBA').length <= 1)) {
    summerLeague(state)
  }
  // ---- オールスターの選考（第 31 週のあと）
  if (w === NBA_ALLSTAR_WEEK - 1 && !played.seasonEnded) selectAllStars(state)
  // ---- トレード（NBA。期限まで）
  if (team?.league === 'NBA' && w >= 20 && w <= NBA_TRADE_DEADLINE_WEEK && !played.seasonEnded) {
    const rng = weekRng(state.seed, absWeekOf(state.season, w), 31)
    const chance = c.tradeRequest ? 0.25 : c.trust < 30 ? 0.04 : 0
    if (rng.chance(chance)) tradeProtagonist(state)
  }
  // ---- 契約の延長（最終年で、主力なら）
  if (team && team.league === 'NBA' && w === 20 && p.contract.years === 1 && ovr(p) >= 74 && !c.offers.some((o) => o.kind === 'renew')) {
    const o = ovr(p)
    c.offers.push({ id: allocId(state), kind: 'renew', teamId: team.id, role: o >= 82 ? 'star' : 'starter', salary: Math.round(nbaMarketSalary(o) * 1.05), years: o >= 82 ? 5 : 4, contract: o >= 88 ? 'max' : 'standard', pitch: 'これからもチームの中心でいてほしい。延長の話だ' })
    c.talks.push({ id: 'extension', speaker: 'todo_maiko' })
  }
}

/** サマーリーグ: 4 試合（力からその場で成績を出す）。良ければ注目度と評価、所属なしなら 2way の話 */
function summerLeague(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  const rng = weekRng(state.seed, absWeekOf(state.season, 1), 101)
  const edge = ovr(p) - 64
  const ppg = clamp(Math.round((14 + edge * 1.1 + rng.normal(0, 3)) * 10) / 10, 3, 32)
  c.summer = `4 試合で平均 ${ppg} 点`
  c.trust = clamp(c.trust + (ppg - 12) * 0.6, 0, 100)
  c.nbaInterest = clamp(c.nbaInterest + (ppg - 10) * 1.2, 0, 100)
  c.talks.push({ id: 'summer', speaker: 'todo_maiko' })
  if (p.teamId < 0 && ppg >= 13 && !c.offers.some((o) => o.kind === 'nba')) {
    const t = rng.pick(state.leagues.NBA.teamIds)
    c.offers.push({ id: allocId(state), kind: 'nba', teamId: state.teams[t].affiliate ?? t, role: 'rotation', salary: TWO_WAY_SALARY, years: 2, contract: 'twoWay', pitch: 'サマーリーグを見ていた。2way 契約で迎えたい' })
  }
}

/** オールスター: 各カンファレンス 12 人（貢献の点と知名度）。主人公は知名度が票に効く */
export function selectAllStars(state: GameState) {
  const c = state.career
  const season = state.season
  if (state.awards.some((a) => a.season === season && a.award === 'オールスター')) return
  for (const conf of ['E', 'W']) {
    const ids = new Set(state.leagues.NBA.teamIds.filter((id) => state.teams[id].conf === conf))
    const cands = Object.values(state.players).filter((p) => ids.has(p.teamId) && p.stats.gp >= 15)
    const score = (p: Player) => mvpScore(state, p) + (p.isPlayer && c ? c.fame * 0.06 : 0)
    for (const p of cands.sort((a, b) => score(b) - score(a)).slice(0, 12)) {
      state.awards.push({ season, league: 'NBA', award: 'オールスター', playerId: p.id, name: p.name, teamName: state.teams[p.teamId].name, line: `平均 ${(p.stats.pts / p.stats.gp).toFixed(1)} 点` })
      if (p.isPlayer && c) {
        c.allStar = season
        c.talks.push({ id: 'allstar', speaker: 'todo_maiko' })
        pushHeirTalk(state, 'allstar')
        c.fame = clamp(c.fame + 8, 0, 100)
      }
    }
  }
}

/** 主人公をトレードで別のチームへ */
export function tradeProtagonist(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), 77)
  const from = state.teams[p.teamId]
  const cands = state.leagues.NBA.teamIds.filter((id) => id !== from.id)
  const to = state.teams[rng.pick(cands)]
  // 相手からは同じくらいの年俸の選手が来る
  const back = to.roster.map((id) => state.players[id]).filter((x) => !x.castId).sort((a, b) => Math.abs(a.contract.salary - p.contract.salary) - Math.abs(b.contract.salary - p.contract.salary))[0]
  const keep = { ...p.contract }
  signPlayer(state, p, to, keep.salary, keep.years, keep.kind)
  if (back) signPlayer(state, back, from, back.contract.salary, back.contract.years, back.contract.kind)
  c.tradeRequest = false
  c.trust = 50
  c.lastTrade = `${from.name} → ${to.name}`
  c.talks.push({ id: 'traded', speaker: 'todo_maiko' })
  state.news.push({ season: state.season, week: state.week, text: `トレード: ${p.name}が${from.name}から${to.name}へ`, big: true })
}

/** NBA の FA の話（契約が切れた NBA の選手）: 相場の年俸で 3 チームから。役割はそのチームの中の順番で */
export function nbaFreeAgentOffers(state: GameState) {
  const c = state.career!
  const p = careerPlayer(state)
  const o = ovr(p)
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), 202)
  const until = absWeekOf(state.season, 6)
  const age = ageAt(absWeekOf(state.season, state.week), p.birthAbs)
  const teams = rng.shuffle(state.leagues.NBA.teamIds.filter((id) => id !== p.teamId)).slice(0, 3)
  for (const t of teams) {
    const team = state.teams[t]
    const better = team.roster.filter((id) => ovr(state.players[id]) > o).length
    const role: CareerOffer['role'] = better === 0 ? 'star' : better <= 3 ? 'starter' : better <= 7 ? 'rotation' : 'bench'
    const salary = Math.max(NBA_MIN, Math.round(nbaMarketSalary(o) * rng.range(0.9, 1.12)))
    const contender = teamPower(state, team) >= 76
    c.offers.push({
      id: allocId(state),
      kind: 'nba',
      teamId: t,
      role,
      salary,
      years: age >= 31 ? 2 : rng.int(2, 4),
      until,
      contract: salary <= NBA_MIN ? 'min' : 'standard',
      pitch: contender ? '優勝を狙うチームだ。君の力が最後のピースになる' : role === 'star' ? '君を中心にチームを作り直したい' : '君の力が必要だ',
    })
  }
}
