/**
 * 日程を作る。
 *   NBA  82 試合: 同じディビジョン 4 回（16）・同じカンファレンスのほか 10 チームのうち 6 チームと 4 回・4 チームと 3 回（36）
 *        ・反対のカンファレンス 15 チームと 2 回（30）。ホームはちょうど 41。
 *        カンファレンスの 3・4 回の振り分けは 5×5 の巡回（circulant）で、どのチームも同じ数になるようにする。
 *        週に 3〜4 試合、同じ日に 2 試合はしない。なるべく連戦（2 日続けて）を避ける
 *   国内 16 クラブの総当たりを 2 周（ホームとアウェイ）。1 節は土日に同じ相手と 2 連戦
 *   大学 32 校の総当たりのうち 30 回戦を、火曜と土曜に
 *   育成リーグ 30 チームの総当たりを 2 周（54 回戦まで）。水曜と日曜に
 */
import type { Rng } from '../core/prng'
import { COLLEGE_REGULAR, JBL_ROUNDS, NBA_ALLSTAR_WEEK, NBA_REGULAR, weekOfJblRound } from '../core/calendar'
import { allocId, type GameState } from '../models/game'
import type { Fixture, LeagueId, Team } from '../models/league'

interface Pairing {
  home: number
  away: number
}

/** 円形の総当たり（circle method）。ids の数が奇数なら -1（休み）を足す。回戦ごとの [home, away] */
export function roundRobin(ids: number[]): [number, number][][] {
  const arr = ids.length % 2 ? [...ids, -1] : [...ids]
  const n = arr.length
  const rounds: [number, number][][] = []
  for (let r = 0; r < n - 1; r++) {
    const pairs: [number, number][] = []
    for (let i = 0; i < n / 2; i++) {
      const a = arr[i]
      const b = arr[n - 1 - i]
      if (a < 0 || b < 0) continue
      // ホームは回戦ごと・組ごとに入れ替えて偏らないように
      pairs.push((r + i) % 2 === 0 ? [a, b] : [b, a])
    }
    rounds.push(pairs)
    arr.splice(1, 0, arr.pop()!)
  }
  return rounds
}

/** NBA の 82 試合の組み合わせ（1,230 試合） */
export function nbaPairings(teams: Team[]): Pairing[] {
  const games: Pairing[] = []
  const add = (home: number, away: number, n = 1) => {
    for (let i = 0; i < n; i++) games.push({ home, away })
  }
  const confs = ['E', 'W'] as const
  const divsOf = (c: string) => {
    const names = [...new Set(teams.filter((t) => t.conf === c).map((t) => t.div!))]
    return names.map((d) => teams.filter((t) => t.conf === c && t.div === d).map((t) => t.id))
  }
  for (const c of confs) {
    const divs = divsOf(c)
    // 拡張参入のあと（16 チーム: 5・5・6 のディビジョン）は別の組み方
    if (divs.some((d) => d.length !== 5)) {
      confPairings16(divs, add)
      continue
    }
    // 同じディビジョン: 4 回（ホーム 2・アウェイ 2）
    for (const d of divs)
      for (let i = 0; i < d.length; i++)
        for (let j = i + 1; j < d.length; j++) {
          add(d[i], d[j], 2)
          add(d[j], d[i], 2)
        }
    // 同じカンファレンスのほかのディビジョン（巡回で 4 回・3 回を振り分ける）
    for (const [x, y] of [
      [0, 1],
      [1, 2],
      [2, 0],
    ] as const) {
      const X = divs[x]
      const Y = divs[y]
      for (let i = 0; i < 5; i++)
        for (let j = 0; j < 5; j++) {
          const d = (j - i + 5) % 5
          if (d <= 2) {
            add(X[i], Y[j], 2)
            add(Y[j], X[i], 2)
          } else if (d === 3) {
            add(X[i], Y[j], 2)
            add(Y[j], X[i], 1)
          } else {
            add(X[i], Y[j], 1)
            add(Y[j], X[i], 2)
          }
        }
    }
  }
  // 反対のカンファレンス: 2 回（ホーム 1・アウェイ 1）
  const east = teams.filter((t) => t.conf === 'E').map((t) => t.id)
  const west = teams.filter((t) => t.conf === 'W').map((t) => t.id)
  for (const e of east)
    for (const w of west) {
      add(e, w)
      add(w, e)
    }
  return games
}

/**
 * 16 チームのカンファレンス（ディビジョン 5・5・6）の 50 試合: 同じディビジョン 4 回、5 チームのディビジョンどうしは 1 対 1 の組で 4 回・ほかは 3 回、
 * 6 チームのディビジョンとは 3 回。3 回の組のホームの 2 試合目は、オイラー路で向きを決めて、どのチームもちょうど半分にする（ホーム 41）
 */
function confPairings16(divs: number[][], add: (home: number, away: number, n?: number) => void) {
  const sorted = [...divs].sort((a, b) => a.length - b.length)
  const [A, B, C] = sorted
  for (const d of sorted)
    for (let i = 0; i < d.length; i++)
      for (let j = i + 1; j < d.length; j++) {
        add(d[i], d[j], 2)
        add(d[j], d[i], 2)
      }
  const three: [number, number][] = []
  for (let i = 0; i < A.length; i++)
    for (let j = 0; j < B.length; j++) {
      if (i === j) {
        add(A[i], B[j], 2)
        add(B[j], A[i], 2)
      } else three.push([A[i], B[j]])
    }
  for (const x of [...A, ...B]) for (const y of C) three.push([x, y])
  // オイラー路で向きを決める（どの頂点も次数 10 なので、出る数と入る数が 5 ずつになる）
  const adj = new Map<number, number[]>()
  three.forEach(([a, b], e) => {
    adj.set(a, [...(adj.get(a) ?? []), e])
    adj.set(b, [...(adj.get(b) ?? []), e])
  })
  const used = new Array(three.length).fill(false)
  const dir: [number, number][] = []
  for (const start of adj.keys()) {
    let v = start
    for (;;) {
      const e = (adj.get(v) ?? []).find((k) => !used[k])
      if (e === undefined) break
      used[e] = true
      const [a, b] = three[e]
      const w = a === v ? b : a
      dir.push([v, w])
      v = w
    }
  }
  for (const [h, a] of dir) {
    add(h, a, 2)
    add(a, h, 1)
  }
}

interface Slot extends Pairing {
  week: number
  day: number
}

/**
 * 組み合わせを週と曜日に割り振る。週ごとに、残りの試合数を残りの週で割った数（だいたい 3）までにし、
 * 同じ日に 2 試合はさせない。連戦はなるべく避ける。最後に残った試合は、空いている週へ詰める
 */
export function distribute(pairings: Pairing[], weeks: number[], rng: Rng, maxPerWeek = 4): Slot[] {
  const out: Slot[] = []
  let remaining = rng.shuffle([...pairings])
  const left = new Map<number, number>()
  for (const g of pairings) {
    left.set(g.home, (left.get(g.home) ?? 0) + 1)
    left.set(g.away, (left.get(g.away) ?? 0) + 1)
  }
  // 週ごとの、チームの試合の曜日
  const days = new Map<number, Map<number, Set<number>>>()
  const daysOf = (w: number, t: number) => {
    let m = days.get(w)
    if (!m) days.set(w, (m = new Map()))
    let s = m.get(t)
    if (!s) m.set(t, (s = new Set()))
    return s
  }
  const dayLoad = new Map<string, number>()
  const pickDay = (w: number, g: Pairing): number => {
    const a = daysOf(w, g.home)
    const b = daysOf(w, g.away)
    let best = -1
    let bestScore = Infinity
    for (let d = 0; d < 7; d++) {
      if (a.has(d) || b.has(d)) continue
      // 連戦（前後の日に試合）は重く、その日の試合の多さは軽く
      const b2b = [a, b].reduce((s, set) => s + (set.has(d - 1) ? 1 : 0) + (set.has(d + 1) ? 1 : 0), 0)
      const score = b2b * 10 + (dayLoad.get(`${w}:${d}`) ?? 0) + rng.next() * 0.5
      if (score < bestScore) {
        bestScore = score
        best = d
      }
    }
    return best
  }
  const place = (w: number, g: Pairing, d: number) => {
    out.push({ ...g, week: w, day: d })
    daysOf(w, g.home).add(d)
    daysOf(w, g.away).add(d)
    dayLoad.set(`${w}:${d}`, (dayLoad.get(`${w}:${d}`) ?? 0) + 1)
    left.set(g.home, left.get(g.home)! - 1)
    left.set(g.away, left.get(g.away)! - 1)
  }
  for (let wi = 0; wi < weeks.length; wi++) {
    const w = weeks[wi]
    const weeksLeft = weeks.length - wi
    const target = new Map<number, number>()
    for (const [t, n] of left) target.set(t, Math.min(maxPerWeek, Math.round(n / weeksLeft)))
    // 残りの多いチームの試合を先に
    remaining.sort((x, y) => left.get(y.home)! + left.get(y.away)! - (left.get(x.home)! + left.get(x.away)!))
    const rest: Pairing[] = []
    for (const g of remaining) {
      const ok = daysOf(w, g.home).size < target.get(g.home)! && daysOf(w, g.away).size < target.get(g.away)!
      const d = ok ? pickDay(w, g) : -1
      if (d >= 0) place(w, g, d)
      else rest.push(g)
    }
    remaining = rest
  }
  // 残り: 試合の少ない週から、空いている曜日へ
  for (let cap = maxPerWeek; remaining.length && cap <= 6; cap++) {
    const rest: Pairing[] = []
    for (const g of remaining) {
      let placed = false
      const order = [...weeks].sort((x, y) => daysOf(x, g.home).size + daysOf(x, g.away).size - (daysOf(y, g.home).size + daysOf(y, g.away).size))
      for (const w of order) {
        if (daysOf(w, g.home).size >= cap || daysOf(w, g.away).size >= cap) continue
        const d = pickDay(w, g)
        if (d >= 0) {
          place(w, g, d)
          placed = true
          break
        }
      }
      if (!placed) rest.push(g)
    }
    remaining = rest
  }
  if (remaining.length) throw new Error(`日程に入らない試合が ${remaining.length} 残った`)
  return out
}

/** NBA のレギュラーシーズンの週（オールスターの週は休み） */
export function nbaWeeks(): number[] {
  const out: number[] = []
  for (let w = NBA_REGULAR[0]; w <= NBA_REGULAR[1]; w++) if (w !== NBA_ALLSTAR_WEEK) out.push(w)
  return out
}

function pushFixture(state: GameState, league: LeagueId, s: Slot) {
  const f: Fixture = { id: allocId(state), league, week: s.week, day: s.day, home: s.home, away: s.away, kind: 'regular' }
  state.fixtures.push(f)
}

/** 今季のレギュラーシーズンの日程を全リーグぶん作る（state.fixtures を置き換える） */
export function scheduleSeason(state: GameState, rng: Rng) {
  state.fixtures = []
  const teamsOf = (id: LeagueId) => state.leagues[id].teamIds.map((t) => state.teams[t])

  // NBA
  for (const s of distribute(nbaPairings(teamsOf('NBA')), nbaWeeks(), rng)) pushFixture(state, 'NBA', s)

  // 国内: 節ごとに土日の 2 連戦
  for (const id of ['JBL1', 'JBL2', 'JBL3'] as const) {
    const ids = rng.shuffle([...state.leagues[id].teamIds])
    const half = roundRobin(ids)
    const rounds = [...half, ...half.map((r) => r.map(([h, a]) => [a, h] as [number, number]))]
    for (let r = 0; r < Math.min(JBL_ROUNDS, rounds.length); r++) {
      const week = weekOfJblRound(r)
      for (const [home, away] of rounds[r]) {
        pushFixture(state, id, { home, away, week, day: 5 })
        pushFixture(state, id, { home, away, week, day: 6 })
      }
    }
  }

  // 大学: 30 回戦を火曜と土曜に
  {
    const ids = rng.shuffle([...state.leagues.NCAA.teamIds])
    const rounds = roundRobin(ids).slice(0, 30)
    rounds.forEach((pairs, r) => {
      const week = COLLEGE_REGULAR[0] + Math.floor(r / 2)
      for (const [home, away] of pairs) pushFixture(state, 'NCAA', { home, away, week, day: r % 2 === 0 ? 1 : 5 })
    })
  }

  // 育成リーグ: 2 周の総当たりのうち、NBA の週に 2 回戦ずつ（水曜と日曜）
  {
    const ids = rng.shuffle([...state.leagues.DEV.teamIds])
    const half = roundRobin(ids)
    const rounds = [...half, ...half.map((r) => r.map(([h, a]) => [a, h] as [number, number]))]
    const weeks = nbaWeeks()
    for (let r = 0; r < Math.min(rounds.length, weeks.length * 2); r++) {
      for (const [home, away] of rounds[r]) pushFixture(state, 'DEV', { home, away, week: weeks[Math.floor(r / 2)], day: r % 2 === 0 ? 2 : 6 })
    }
  }
  state.fixtures.sort((a, b) => a.week - b.week || a.day - b.day)
}
