/**
 * クラブ経営の毎週とシーズンの終わり。
 *   毎週（advanceWeek のあと）: 自分の試合の観客と入場料・定期の出入り（配分金・スポンサー・グッズ・年俸・維持費・遠征・運営）、
 *     人気とファン（勝ち負け・広報室・街の熱）、工事の完成、資金難（マイナスが 8 週続くとオーナーが資金を入れる。3 回目はゲームオーバー）
 *   シーズンの終わり（seasonEnd の中、昇格・降格の前）: 賞金・記録・スポンサーとスタッフの契約・昇格や優勝の人気
 * お金の出入りは、帳簿（週ごと）と資金に同時に入れる。工事費・契約金は画面で払ったときに、その週の帳簿に入っている。
 * 乱数は週ごとの流れ（観客の揺れ）。
 */
import { inPromotionSpot, promotedTeams } from '../competition/promotion'
import { absWeekOf } from '../core/calendar'
import { createRng, hashSeed } from '../core/prng'
import { LICENSE_SEATS, POP_BASE, PRIZE } from '../data/club'
import type { ClubLedger } from '../models/club'
import type { GameState } from '../models/game'
import { sortedStandings } from '../competition/standings'
import { attendance, ticketLevelOf, clubTeam, emptyLedger, finishBuilds, ledgerNet, makeSponsorOffers, staffSeasonEnd, ticketPrice, weeklyBooks } from './manage'
import { makeBids, youthGraduation, youthIntake, youthWeek } from './transfer'
import type { OwnerGoal } from '../models/club'
import { teamPower } from '../query'
import { luxuryTax, reviewExpansion } from './nba'
import { OWNER, pushScene, storySeasonStart, storyWeek } from './story'
import { buildReview } from './review'
import { addFans, fanWeek } from './fans'
import { applyRelocation } from './hometown'
import { nbaLifeSeasonEnd, nbaLifeWeek } from './nbaLife'

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** その週の帳簿に足す（なければ作る） */
function addToLedger(state: GameState, w: ClubLedger) {
  const c = state.club!
  let l = c.ledger.find((x) => x.abs === w.abs)
  if (!l) {
    l = emptyLedger(w.abs)
    c.ledger.push(l)
    c.ledger.sort((a, b) => a.abs - b.abs)
    if (c.ledger.length > 104) c.ledger.splice(0, c.ledger.length - 104)
  }
  for (const k of Object.keys(w) as (keyof ClubLedger)[]) if (k !== 'abs') l[k] += w[k]
}

/** 週の終わりに呼ぶ（gameStore の 1 週から）。played は進める前の週 */
export function clubAfterWeek(state: GameState, played: { season: number; week: number; seasonEnded: boolean }) {
  const c = state.club!
  if (c.gameOver) return
  const abs = absWeekOf(played.season, played.week)
  const team = clubTeam(state)
  const rng = createRng(hashSeed(state.seed, abs, 0xc1b))
  const w = emptyLedger(abs)

  // ---- 自分の試合（観客・入場料・人気）。シーズンの終わりの週は日程が次のシーズンに入れ替わっている
  if (!played.seasonEnded) {
    c.lastResults = []
    const mine = state.fixtures.filter((f) => f.week === played.week && f.result && (f.home === team.id || f.away === team.id))
    for (const f of mine) {
      const home = f.home === team.id
      const opp = state.teams[home ? f.away : f.home]
      const us = home ? f.result!.hs : f.result!.as
      const them = home ? f.result!.as : f.result!.hs
      c.lastResults.push({ fixtureId: f.id, opp: opp.short, home, us, them })
      c.popularity += us > them ? (home ? 0.45 : 0.35) : -0.2
      if (home) {
        const att = attendance(state, opp, f.kind === 'regular' ? 1 : 1.3, rng.range(0.9, 1.1))
        w.ticket += Math.round(att * ticketPrice(state))
        c.popularity += ticketLevelOf(state).pop
        addFans(state, 1, Math.round(att * 0.015 * ticketLevelOf(state).crowd))
      }
    }
  }

  // ---- 定期の出入り
  weeklyBooks(state, w)
  c.money += ledgerNet(w)
  addToLedger(state, w)

  // ---- 人気: リーグとアリーナの格で決まる落ち着く先へ少しずつ
  const settle = (POP_BASE[team.league] ?? 20) + c.arenaGrade * 2
  c.popularity = clamp(c.popularity + (settle - c.popularity) * 0.015, 1, 100)
  // ファン: 人気が高いほど増える。天井は街の人口の 3 割＋上の部・優勝で広がる街の外のファン（fans.ts）
  fanWeek(state)

  // ---- 工事（次の週のはじめに完成しているもの）
  for (const label of finishBuilds(state, absWeekOf(state.season, state.week))) state.news.push({ season: state.season, week: state.week, text: `${label}の工事が終わった`, big: true })

  // ---- 編成: ユースの成長・ほかのクラブからの申し入れ・出来事
  if (!played.seasonEnded) {
    youthWeek(state)
    makeBids(state, rng)
    clubEvent(state, rng)
    storyWeek(state, rng)
    nbaLifeWeek(state, rng, played.week)
  } else {
    // 新しいシーズン: ユースの新入生・オーナーの目標（オーナーと HC の話）
    youthIntake(state)
    setOwnerGoal(state)
    c.talks = {}
    storySeasonStart(state)
  }

  // ---- スポンサーの話: シーズンのはじめと、空いた枠があれば 8 週ごと
  if (played.seasonEnded || (played.week % 8 === 0 && c.sponsors.length < 4 && c.sponsorOffers.length === 0)) makeSponsorOffers(state)

  moneyCheck(state)
}

/** 小さな出来事（ときどき）: 地元の特集・イベント・寄付・設備のトラブル */
function clubEvent(state: GameState, rng: ReturnType<typeof createRng>) {
  if (!rng.chance(0.04)) return
  const c = state.club!
  const team = clubTeam(state)
  const news = (text: string) => state.news.push({ season: state.season, week: state.week, text })
  switch (rng.int(0, 4)) {
    case 0:
      addFans(state, 1.03)
      c.popularity = Math.min(100, c.popularity + 2)
      news(`地元のテレビが${team.short}を特集した。ファンが増えた`)
      break
    case 1:
      addFans(state, 1.02)
      news('ブースターと選手のふれあいイベントが大成功')
      break
    case 2:
      c.popularity = Math.min(100, c.popularity + 3)
      news(`${state.players[rng.pick(team.roster)]?.name ?? '選手'}の SNS の投稿が話題になった`)
      break
    case 3: {
      const w = emptyLedger(absWeekOf(state.season, state.week))
      w.other += 500
      c.money += 500
      addToLedger(state, w)
      news('地元の企業から、クラブに 500 万円の寄付があった')
      break
    }
    default: {
      const w = emptyLedger(absWeekOf(state.season, state.week))
      w.other -= 200
      c.money -= 200
      addToLedger(state, w)
      news('アリーナの照明が故障した。修理に 200 万円かかった')
    }
  }
}

/** オーナーの目標（シーズンのはじめ）: リーグの中の戦力の順位で決める */
export function setOwnerGoal(state: GameState) {
  const c = state.club!
  const team = clubTeam(state)
  const lg = state.leagues[team.league]
  const ids = team.league === 'NBA' ? lg.teamIds.filter((id) => state.teams[id].conf === team.conf) : lg.teamIds
  const power = ids.map((id) => [id, teamPower(state, state.teams[id])] as const).sort((a, b) => b[1] - a[1])
  const pr = power.findIndex(([id]) => id === team.id) + 1
  let goal: OwnerGoal
  // 参入して 2 シーズンは、順位を問わない（経験を積む）
  if (team.league === 'NBA' && (c.nba?.joined ?? -9) >= state.season - 1) goal = { kind: 'rank', rank: 16, text: 'NBA の舞台に慣れる（順位は問わない）' }
  else if (team.league === 'NBA') goal = pr <= 2 ? { kind: 'title', text: 'NBA 優勝' } : pr <= 6 ? { kind: 'rank', rank: 6, text: 'プレーオフに直接出る（カンファレンス 6 位以内）' } : pr <= 11 ? { kind: 'rank', rank: 10, text: 'プレーインに出る（10 位以内）' } : { kind: 'rank', rank: 13, text: 'カンファレンス 13 位以内' }
  else if (team.league === 'JBL1') goal = pr <= 1 ? { kind: 'title', text: 'チャンピオンシップ優勝' } : pr <= 8 ? { kind: 'rank', rank: 8, text: '8 位以内（チャンピオンシップ）' } : { kind: 'stay', rank: 14, text: '1 部に残る（14 位以内）' }
  else {
    const up = team.league === 'JBL3' ? '2 部' : '1 部'
    goal = pr <= 1 ? { kind: 'promote', rank: 2, text: `${up}へ昇格（レギュラーシーズン 1 位かチャンピオンシップ優勝）` } : pr <= 4 ? { kind: 'rank', rank: 4, text: '4 位以内' } : pr <= 10 ? { kind: 'rank', rank: 8, text: '8 位以内' } : { kind: 'rank', rank: 12, text: '12 位以内' }
  }
  c.owner.goal = goal
  c.owner.result = undefined
}

/** オーナーの目標の結果（シーズンの終わり）。達成でボーナス、未達で信頼が下がり、0 で解任 */
function judgeOwner(state: GameState, rank: number, champion: boolean): boolean {
  const c = state.club!
  const g = c.owner.goal
  if (!g) return true
  // 昇格の目標は「昇格の圏内」（チャンピオンシップの優勝か、レギュラーシーズンの最上位。ライセンスは問わない）
  const lg0 = clubTeam(state).league
  const ok = g.kind === 'title' ? champion : g.kind === 'promote' && lg0 !== 'NBA' ? inPromotionSpot(state, lg0, clubTeam(state).id) || rank <= 1 : rank <= (g.rank ?? 99)
  // 惜しい（目標の 3 つ下まで・優勝が目標なら上位 4 まで）は、信頼が少し下がるだけ
  const near = !ok && (g.kind === 'title' ? rank <= 4 : rank <= (g.rank ?? 99) + 3)
  const lg = clubTeam(state).league
  if (ok) {
    const bonus = lg === 'NBA' ? 50000 : lg === 'JBL1' ? 8000 : lg === 'JBL2' ? 3000 : 1000
    const w = emptyLedger(absWeekOf(state.season, state.week))
    w.other += bonus
    c.money += bonus
    addToLedger(state, w)
    c.owner.trust = Math.min(100, c.owner.trust + 12)
    c.owner.result = `目標「${g.text}」を達成。オーナーからボーナス ${bonus.toLocaleString()} 万円`
  } else if (near) {
    c.owner.trust = Math.max(0, c.owner.trust - 5)
    c.owner.result = `目標「${g.text}」にあと一歩。オーナーは次に期待している（信頼 ${c.owner.trust}）`
  } else {
    c.owner.trust = Math.max(0, c.owner.trust - 15)
    c.owner.result = `目標「${g.text}」に届かなかった。オーナーの信頼が下がった（${c.owner.trust}）`
    if (c.owner.trust <= 0) {
      c.gameOver = true
      c.owner.result += '。オーナーはクラブを手放すことにした（ゲームオーバー）'
    }
  }
  state.news.push({ season: state.season, week: state.week, text: c.owner.result, big: true })
  c.owner.last = c.owner.result
  pushScene(state, `owner:end:${state.season}:${ok ? 'ok' : near ? 'near' : 'ng'}`, OWNER)
  return ok
}

/** 資金難: マイナスが 8 週続くとオーナーが資金を入れる（人気が下がる）。3 回目はゲームオーバー */
function moneyCheck(state: GameState) {
  const c = state.club!
  if (c.money >= 0) {
    c.negWeeks = 0
    return
  }
  c.negWeeks++
  if (c.negWeeks === 1) state.news.push({ season: state.season, week: state.week, text: '資金がマイナスになった。8 週続くとオーナーが動く', big: true })
  if (c.negWeeks < 8) return
  c.negWeeks = 0
  if (c.bailouts >= 2) {
    c.gameOver = true
    state.news.push({ season: state.season, week: state.week, text: 'オーナーがクラブを手放すことを決めた（ゲームオーバー）', big: true })
    return
  }
  c.bailouts++
  const inject = -Math.round(c.money) + 5000
  c.money += inject
  c.popularity = Math.max(1, c.popularity - 5)
  state.news.push({ season: state.season, week: state.week, text: `オーナーが ${inject.toLocaleString()} 万円を入れて、クラブを立て直した（もう一度で、次は手放される）`, big: true })
  pushScene(state, `owner:bailout:${c.bailouts}`, OWNER)
}

/** シーズンの終わり（seasonEnd の中、昇格・降格の前） */
export function clubSeasonEnd(state: GameState) {
  const c = state.club!
  const team = clubTeam(state)
  const lg = team.league
  const league = state.leagues[lg]
  // NBA はカンファレンスの中の順位
  const ranked = lg === 'NBA' ? sortedStandings(league, league.teamIds.filter((id) => state.teams[id].conf === team.conf)) : sortedStandings(league)
  const rank = ranked.indexOf(team.id) + 1
  const st = league.standings[team.id]
  const champ = state.champions.find((x) => x.season === state.season && x.league === lg)
  const notes: string[] = []
  const w = emptyLedger(absWeekOf(state.season, state.week))
  // 賞金（チャンピオンシップの優勝・準優勝）
  const prize = PRIZE[lg]
  if (champ && prize) {
    if (champ.teamId === team.id) {
      w.prize += prize[0]
      notes.push(`${league.name}優勝`)
      addFans(state, 1.1)
      c.popularity = Math.min(100, c.popularity + 6)
    } else if (champ.runnerUp === team.name) {
      w.prize += prize[1]
      notes.push('準優勝')
    }
  }
  // 全日本選手権・東アジアのクラブ選手権の優勝（賞金は試合のときに入っている）
  if (state.cupHistory?.some((h) => h.season === state.season && h.champion === team.id)) notes.push('全日本選手権優勝')
  if (state.eaccHistory?.some((h) => h.season === state.season && h.team === team.id)) notes.push('東アジア王者')
  c.money += ledgerNet(w)
  addToLedger(state, w)
  // 昇格・降格の見込み（このあと promoteRelegate で動く）。人気とファン
  const up = lg === 'JBL3' ? 'JBL2' : lg === 'JBL2' ? 'JBL1' : null
  if (lg === 'NBA' && rank <= 6) addFans(state, 1.05)
  const promo = up ? promotedTeams(state, lg, up) : undefined
  if (promo?.up.includes(team.id)) {
    addFans(state, 1.15)
    c.popularity = Math.min(100, c.popularity + 8)
  }
  // 昇格の圏内なのに、上の部のライセンス（席数）がなくて上がれない
  if (up && promo?.blocked.includes(team.id)) notes.push(`昇格の圏内でしたが、${state.leagues[up].name}のライセンス（${(LICENSE_SEATS[up] ?? 0).toLocaleString()} 席）がなく昇格できず`)
  if (lg !== 'JBL3' && lg !== 'NBA' && rank >= ranked.length - 1) {
    addFans(state, 0.9)
    c.popularity = Math.max(1, c.popularity - 8)
  }
  const goalOk = judgeOwner(state, rank, champ?.teamId === team.id)
  // 決めていた移転（オーナーの評価のあと。記録にはこのシーズンの行に残す）
  const moved = applyRelocation(state)
  if (moved) notes.push(moved)
  reviewExpansion(state)
  const tax = luxuryTax(state)
  nbaLifeSeasonEnd(state, tax, goalOk)
  for (const t of youthGraduation(state)) state.news.push({ season: state.season, week: state.week, text: t })
  c.history.push({ season: state.season, league: league.name, rank, w: st?.w ?? 0, l: st?.l ?? 0, fans: c.fans, money: Math.round(c.money), note: notes.join('・') })
  c.review = buildReview(state, rank, ranked.length, st?.w ?? 0, st?.l ?? 0, league.name, notes)
  // スポンサー: 満了の契約は終わり、次のシーズンのはじめに話が来る
  const ending = c.sponsors.filter((s) => s.until <= state.season)
  c.sponsors = c.sponsors.filter((s) => s.until > state.season)
  for (const s of ending) state.news.push({ season: state.season, week: state.week, text: `${s.company}とのスポンサー契約が満了した` })
  for (const t of staffSeasonEnd(state)) state.news.push({ season: state.season, week: state.week, text: t })
  c.sponsorOffers = []
}
