/**
 * 恋愛と家族（全年齢向け: 主人公と相手がどちらも 18 歳以上で romance: true の人だけ。性的表現・飲酒の描写なし）。
 *   デート: 絆 30 から誘える（恋人がいればその人だけ）。行き先を選ぶ（地域ごと）。好きな行き先なら絆が 1.6 倍、
 *     同じ趣味があると少し多く上がる。絆 80 で、その人の物語の続き（heroineLines.ts）
 *   告白: 恋人がいない・絆 80・デート 3 回 → 選択（付き合う／今はバスケに集中）。デートでもおでかけでも来る。
 *     断ったあとも、絆 90・デート 6 回で、今度は主人公から（confess2）
 *   誘う相手を選んでいなければ、恋人 → 絆のいちばん高い人（画面の見た目と同じ）
 *   日本とアメリカ: ふだんは今いる地域の人だけ。オフ（キャンプの前で試合のない週）は帰国・渡航して会える（渡航費）
 *   プロポーズ: 付き合って 30 週・絆 95・持ち家がある → 選択 → 結婚式
 *   子ども: 結婚していれば、シーズンの終わりに 45%（3 人まで）
 */
import { absWeekOf } from '../core/calendar'
import { weekRng } from '../core/prng'
import { CAST_BY_ID } from '../data/cast'
import type { GameState } from '../models/game'
import { NBA_CAMP_WEEK } from '../core/calendar'
import { careerFixtures, regionOf } from './week'
import { CAMP_TRAVEL, DATE_SPOTS, DATE_SPOT_BY_ID, HEROINE_PREFS } from '../data/careerLife'
import { HEROINE_STORY } from './heroineLines'
import { hobbySkill } from './lifePlus'
import { sameGeneration } from './castLines'

/** オフ（キャンプの前）で主人公のチームの試合がない週: 日本とアメリカを行き来して会える */
export function offSeasonTrip(state: GameState): boolean {
  return state.week < NBA_CAMP_WEEK && careerFixtures(state).length === 0
}

/** その人と会う地域（恋人・結婚相手は今いる地域へ来てくれる。ほかの人は、オフにその人の地域へ） */
export function dateRegion(state: GameState, id: string): 'jp' | 'us' {
  const c = state.career!
  const who = CAST_BY_ID[id]
  if (!who || who.region === 'any' || c.partner === id || c.spouse === id) return regionOf(state)
  return who.region
}

/** デートに誘えるか */
export function canDate(state: GameState, id: string): boolean {
  const c = state.career!
  const who = CAST_BY_ID[id]
  if (!who?.romance || !c.met.includes(id) || !sameGeneration(state, id)) return false
  if (c.spouse) return c.spouse === id
  if (c.partner) return c.partner === id
  if ((c.bonds[id] ?? 0) < 30) return false
  // 渡航して会うデートは、渡航費が払えるときだけ（年俸のない大学生が借金になっていた）
  if (dateTravel(state, id) > c.money) return false
  return who.region === 'any' || who.region === regionOf(state) || offSeasonTrip(state)
}

/** 誘える人（絆の高い順） */
export function datable(state: GameState): string[] {
  const c = state.career!
  return Object.keys(c.bonds)
    .filter((id) => canDate(state, id))
    .sort((a, b) => (c.bonds[b] ?? 0) - (c.bonds[a] ?? 0))
}

/** 今週デートする相手: 結婚相手・恋人 → 選んだ人 → 絆のいちばん高い人 */
export function dateTarget(state: GameState): string | undefined {
  const c = state.career!
  const fixed = c.spouse ?? c.partner
  if (fixed) return canDate(state, fixed) ? fixed : undefined
  if (c.dateWith && canDate(state, c.dateWith)) return c.dateWith
  return datable(state)[0]
}

/** その人と行けるデートの行き先（車が要るところは車があるとき） */
export function dateSpots(state: GameState, id?: string) {
  const hasCar = (state.career!.cars?.length ?? 0) > 0
  const region = id ? dateRegion(state, id) : regionOf(state)
  return DATE_SPOTS.filter((s) => s.region === region && (!s.needCar || hasCar))
}

/** 行き先を選んでいないときの行き先（画面の見た目と同じ）: 好きな場所を順に。付き合ってからは、いろいろな場所を順に */
export function defaultSpot(state: GameState, id: string): string | undefined {
  const c = state.career!
  const spots = dateSpots(state, id)
  if (!spots.length) return undefined
  const pick = pickSpot(state, id, spots)
  // お金が足りなければ、お金のかからない場所へ（夜景・河川敷・ビーチなど。画面の行き先もこれで）
  return DATE_SPOT_BY_ID[pick].cost > c.money ? (spots.find((x) => x.cost === 0)?.id ?? pick) : pick
}

function pickSpot(state: GameState, id: string, spots: ReturnType<typeof dateSpots>): string {
  const c = state.career!
  if (c.dateSpot && spots.some((s) => s.id === c.dateSpot)) return c.dateSpot
  const n = c.dates?.[id] ?? 0
  const liked = spots.filter((s) => likesSpot(id, s.id))
  const settled = c.partner === id || c.spouse === id || (c.bonds[id] ?? 0) >= 95
  return (settled || !liked.length ? spots[n % spots.length] : liked[n % liked.length]).id
}

/** 帰国・渡航して会うときの渡航費（万円） */
export const dateTravel = (state: GameState, id: string) => (dateRegion(state, id) !== regionOf(state) ? CAMP_TRAVEL : 0)

const queuedOrSeen = (state: GameState, talk: string) => state.career!.seen.includes(talk) || state.career!.talks.some((t) => t.id === talk)

/** 向こうから告白されるか（恋人がいない・絆 80・デート 3 回） */
export function canConfess(state: GameState, id: string): boolean {
  const c = state.career!
  return !!CAST_BY_ID[id]?.romance && !c.partner && !c.spouse && (c.bonds[id] ?? 0) >= 80 && (c.dates?.[id] ?? 0) >= 3 && !queuedOrSeen(state, 'confess:' + id)
}

/** 断ったあと、今度は主人公から（絆 90・デート 6 回） */
export function canConfess2(state: GameState, id: string): boolean {
  const c = state.career!
  return !c.partner && !c.spouse && c.seen.includes('confess:' + id) && (c.bonds[id] ?? 0) >= 90 && (c.dates?.[id] ?? 0) >= 6 && !queuedOrSeen(state, 'confess2:' + id)
}

/** 人間関係の画面に出す「次の一歩」 */
export function romanceHint(state: GameState, id: string): string | null {
  const c = state.career!
  const who = CAST_BY_ID[id]
  if (!who?.romance) return null
  const bond = Math.round(c.bonds[id] ?? 0)
  const dates = c.dates?.[id] ?? 0
  if (c.spouse === id) return '結婚している。家族の出来事や旅行を一緒に'
  if (c.spouse || (c.partner && c.partner !== id)) return 'ほかに大切な人がいる'
  if (c.partner === id) {
    const weeks = absWeekOf(state.season, state.week) - (c.partnerSince ?? 0)
    const home = (c.ownedHomes?.length ?? 0) > 0
    return '恋人（付き合って ' + weeks + ' 週）。プロポーズは、付き合って 30 週・絆 95・持ち家（' + (home ? 'ある' : 'まだない') + '）でデートしたとき'
  }
  const away = who.region !== 'any' && who.region !== regionOf(state)
  const where = away ? '（' + (who.region === 'jp' ? '日本' : 'アメリカ') + 'の人。オフのキャンプ前の、試合のない週に会いに行ける・渡航費 ' + CAMP_TRAVEL + ' 万円）' : ''
  if (bond < 30) return 'おでかけで会って、絆 30 になるとデートに誘える' + where
  if (c.seen.includes('confess2:' + id)) return '大切な友だち' + where
  if (c.seen.includes('confess:' + id)) return '告白を断った。絆 90・デート 6 回（今 ' + dates + ' 回）で、今度は自分から気持ちを伝えられる' + where
  return 'デートに誘える。デート 3 回（今 ' + dates + ' 回）・絆 80 で、大切な話があるかも' + where
}

/** その人の好きな行き先か */
export const likesSpot = (who: string, spot: string) => !!HEROINE_PREFS[who]?.spots.includes(spot)

/** デートの週（careerBeforeWeek から） */
export function dateWeek(state: GameState, id: string) {
  const c = state.career!
  if (!canDate(state, id)) return
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), 333)
  const spot = defaultSpot(state, id)
  if (!spot) return
  const liked = likesSpot(id, spot)
  const pref = HEROINE_PREFS[id]
  const shared = pref && hobbySkill(state, pref.hobby) >= 20
  c.money -= DATE_SPOT_BY_ID[spot].cost + dateTravel(state, id)
  const before = c.bonds[id] ?? 0
  c.bonds[id] = Math.min(100, before + Math.round(rng.int(9, 13) * (liked ? 1.6 : 1) + (shared ? 3 : 0)))
  c.dates = { ...(c.dates ?? {}), [id]: (c.dates?.[id] ?? 0) + 1 }
  const n = c.dates[id]
  const now = absWeekOf(state.season, state.week)
  if (before < 80 && c.bonds[id] >= 80 && HEROINE_STORY[id] && !c.seen.includes(`bond:${id}:80`)) c.talks.push({ id: `bond:${id}:80`, speaker: id })
  else if (canConfess(state, id)) c.talks.push({ id: `confess:${id}`, speaker: id })
  else if (canConfess2(state, id)) c.talks.push({ id: `confess2:${id}`, speaker: id })
  else if (c.partner === id && !c.spouse && c.partnerSince !== undefined && now - c.partnerSince >= 30 && c.bonds[id] >= 95 && (c.ownedHomes?.length ?? 0) > 0 && !c.talks.some((t) => t.id.startsWith('propose:'))) c.talks.push({ id: `propose:${id}`, speaker: id })
  else c.talks.push({ id: `date:${id}:${n}:${spot}:${liked ? 1 : 0}:${shared ? 1 : 0}`, speaker: id })
}

const BOY = ['蓮', '陽翔', '湊', '大和', '颯', '律', '奏太', '悠真', '朝陽', '海翔']
const GIRL = ['陽葵', '凛', '結菜', '紬', '葵', '芽依', '咲良', '澪', '心春', '花']

/** シーズンの終わり: 子ども */
export function familySeasonEnd(state: GameState) {
  const c = state.career!
  if (!c.spouse || (c.children?.length ?? 0) >= 3) return
  const rng = weekRng(state.seed, absWeekOf(state.season, state.week), 444)
  if (!rng.chance(0.45)) return
  const sex = rng.chance(0.5) ? 'm' : 'f'
  const name = rng.pick(sex === 'm' ? BOY : GIRL)
  c.children = [...(c.children ?? []), { name, sex, birthAbs: absWeekOf(state.season, state.week) }]
  c.talks.push({ id: `child:${name}`, speaker: c.spouse })
}

/** 告白・プロポーズの返事（talks.ts の applyTalkChoice から） */
export function romanceChoice(state: GameState, talkId: string, effect: string) {
  const c = state.career!
  const [kind, id] = talkId.split(':')
  if ((kind === 'confess' || kind === 'confess2') && effect === 'yes') {
    c.partner = id
    c.partnerSince = absWeekOf(state.season, state.week)
  }
  if (kind === 'propose' && effect === 'yes') {
    c.spouse = id
    c.marriedSince = absWeekOf(state.season, state.week)
    delete c.partner
    c.talks.push({ id: `wedding:${id}`, speaker: id })
  }
}
