import { traitTalkOf } from './traits'
import { DATE_SPOT_BY_ID } from '../data/careerLife'
import { CAST_LINES, castLines, chatPool, lifeStage } from './castLines'

export interface TalkLine {
  who: string
  text: string
}

export interface TalkChoice {
  label: string
  /** 選んだあとの返事 */
  reply: string
  effect: string
}

export interface Talk {
  title: string
  lines: TalkLine[]
  choices?: TalkChoice[]
}

const L = (who: string, ...texts: string[]): TalkLine[] => texts.map((t) => (t.startsWith('me:') ? { who: 'me', text: t.slice(3) } : { who, text: t }))

