/** 会話を組み立てる（決まった出来事・meet:<人>・chat:<人>:<番号>・bond:<人>:<30|60>・workout:<チーム>:…） */
/** ドラフトの決断と指名漏れは、大学にいるか日本のプロにいるかで文が違う */
function draftTalk(id: string, state: GameState): Talk | null {
  const c = state.career!
  const p = state.players[c.playerId]
  const lg = p.teamId >= 0 ? state.teams[p.teamId].league : undefined
  const college = lg === 'NCAA' || (lg === undefined && c.path === 'college')
  if (id === 'draft_decision') {
    const team = p.teamId >= 0 ? state.teams[p.teamId].name : ''
    return {
      title: 'ドラフトへの決断',
      lines: L(
        'todo_maiko',
        '{name}くん、大事な話よ。今年のドラフトに名乗り出るか、決める時期が来たわ',
        'スカウトの予想（モックドラフト）では、あなたは {mock}',
        college ? '名乗り出て指名されなければ、大学には戻れない。……決めるのはあなたよ' : `名乗り出て指名されなくても、${team}には残れる。でも、NBA は「力をつけてから」でも遅くない。……決めるのはあなたよ`,
      ),
      choices: [
        { label: 'ドラフトに名乗り出る', reply: '分かった。6 月のドラフトの夜まで、全力で準備しましょう', effect: 'declare' },
        college
          ? { label: 'もう 1 年、大学で力をつける', reply: '賢い判断よ。来年、もっと上の順位で呼ばれるように', effect: 'stay' }
          : { label: 'もう 1 年、日本で力をつける', reply: '賢い判断よ。国内でもう一段上の選手になって、来年はもっと上の順位で呼ばれましょう', effect: 'stay' },
      ],
    }
  }
  if (id === 'undrafted') {
    if (!college && lg?.startsWith('JBL'))
      return {
        title: '呼ばれなかった名前',
        lines: L('todo_maiko', '……今年は、名前が呼ばれなかったわね', `でも、${state.teams[p.teamId].name}での毎日は続く。国内で結果を出せば、来年も名乗り出られるし、夏の FA で NBA から声がかかることもある`, '顔を上げて。ここからが勝負よ'),
      }
    return {
      title: '呼ばれなかった名前',
      lines: L('todo_maiko', '……今年は、名前が呼ばれなかったわね', '大学には戻れないけれど、終わりじゃない。サマーリーグや育成リーグから NBA に上がった選手はたくさんいる', '顔を上げて。夏に向けて、声をかけてくれるチームを探すわ'),
    }
  }
  return null
}

/** 契約が決まったときの代理人の言葉（sign:<場面>:<チーム>）。前は NBA と育成リーグの契約にいつも同じ「入団の挨拶」を出していた */
function signTalk(id: string, state: GameState): Talk | null {
  const [, kind, t] = id.split(':')
  const team = state.teams[Number(t)]
  if (!team) return null
  const T = team.name
  const lines: Record<string, string[]> = {
    first: ['契約成立よ、{name}くん。いよいよアメリカね', `${T}の一員として、NBA の舞台に立つのよ`, '最初は控えからかもしれない。でも、チャンスは必ず来る', '向こうでは通訳のケンさんが待っているわ。困ったことがあったら、何でも相談して'],
    debut: ['契約成立よ。ついに NBA ね', `${T}で、あなたの NBA の物語が始まる。アメリカでの経験は、きっと生きるわ`, '最初の目標は、ローテーションに入ること。監督の信頼を勝ち取って'],
    devFirst: ['契約成立よ、{name}くん。いよいよアメリカね', `まずは${T}（育成リーグ）から。提携先の NBA のチームが、いつもあなたを見ている`, '育成リーグで結果を出せば、シーズン中でも NBA に呼ばれるわ', '向こうでは通訳のケンさんが待っているわ'],
    dev: ['契約成立よ', `${T}（育成リーグ）で、もう一度アピールしましょう。提携先の NBA のチームで 11 番手より上の力を見せれば、本契約の話が来るわ`],
    move: ['契約成立よ。新しいチームでの挑戦ね', `${T}のファンは、あなたのプレーを楽しみにしているわ`, '慣れない場所でも、あなたならすぐにチームの中心になれる'],
    renew: ['契約の更新、成立よ', `これからも${T}で。チームもファンも、あなたを必要としているわ`, 'お金のことは任せて。あなたはバスケに集中して'],
    home: ['契約成立よ。おかえりなさい、日本へ', `${T}は、あなたの経験を必要としている。若い選手たちの手本になってあげて`, '日本のバスケを、もう一度盛り上げましょう'],
    jbl: ['契約成立よ', `${T}で、新しいスタートね。結果を出せば、また上の舞台が見えてくる`],
  }
  const l = lines[kind]
  return l ? { title: '契約', lines: L('todo_maiko', ...l) } : null
}

export function talkOf(id: string, state?: GameState): Talk | null {
  if (state?.career && (id === 'draft_decision' || id === 'undrafted')) return draftTalk(id, state)
  if (state && id.startsWith('sign:')) return signTalk(id, state)
  if (FIXED[id]) return FIXED[id]
  const [kind, who, n] = id.split(':')
  if (LIFE_TALK_KINDS.has(kind)) return lifeTalkOf(id, state)
  if (kind === 'heir') return heirTalkOf(id, state)
  if (kind === 'rival') return rivalTalkOf(id, state)
  if (kind === 'trait' || kind === 'growth') return traitTalkOf(id, state)
  if (kind === 'sponsor') {
    const tier = SPONSOR_TIERS.find((t) => t.id === who)
    if (!tier) return null
    return {
      title: 'スポンサーの話',
      lines: L('todo_maiko', `${tier.name}から、スポンサーの話が来たわ（年 ${tier.pay >= 10000 ? `${tier.pay / 10000} 億` : `${tier.pay} 万`}円）`, tier.desc),
      choices: [
        { label: '契約する', reply: 'いい判断ね。結果で応えましょう', effect: `sponsor:${tier.id}` },
        { label: '今は見送る', reply: '分かった。また話が来たら知らせるわ', effect: 'no' },
      ],
    }
  }
  if (kind === 'child') {
    const sp = state?.career?.spouse ?? 'todo_maiko'
    return { title: '新しい家族', lines: L(sp, '{name}、見て。この子……{child}っていう名前、どうかな', 'あなたみたいに、まっすぐ育ってほしいな') }
  }
  if (kind === 'workout') {
    const ids = id.split(':').slice(1).map(Number)
    return {
      title: 'ワークアウト',
      lines: L('todo_maiko', 'ドラフトの前に、チームごとのワークアウト（個別のテスト）を受けられるわ', 'どこを受ける？ 受けたチームは、あなたを指名しやすくなる'),
      choices: ids.map((t) => ({ label: state ? state.teams[t].name : `チーム ${t}`, reply: 'いい選択ね。全力でアピールしてきて', effect: `workout:${t}` })),
    }
  }
  const c = CAST_BY_ID[who]
  const lines = state ? castLines(state, who) : CAST_LINES[who]
  if (!c || !lines) return null
  const pool = state ? chatPool(state, who) : lines.chat
  if (kind === 'meet') return { title: `${c.name}との出会い`, lines: L(who, ...lines.meet) }
  if (kind === 'date') {
    // date:<人>:<回数>:<行き先>:<好き>:<同じ趣味>
    const [, , , spotId, liked, shared] = id.split(':')
    const spot = DATE_SPOT_BY_ID[spotId]
    const story = HEROINE_STORY[who]
    const together = state?.career && (state.career.partner === who || state.career.spouse === who)
    const out: TalkLine[] = []
    if (spot) out.push(...L(who, ...((state && lifeStage(state) === 'nba' && spot.sceneNba) || spot.scene)))
    if (liked === '1' && story) out.push(...L(who, story.likes))
    if (shared === '1') out.push(...L(who, '同じ趣味の話をしてたら、あっという間に時間がたっちゃった'))
    // 恋人・結婚相手: ふたりの会話とふだんの会話から（chatPool）。回数で順に変わる
    out.push(...L(who, pool[(Number(n) * 3) % pool.length]))
    const close = together ? ['また来ようね', '今日も楽しかった。ありがとう', '次は、どこに連れていってくれる？', '……この時間が、いちばん好き'] : ['今日はありがとう。いい気分転換になった', 'また誘ってくれる？ ……楽しみにしてる', '楽しかった。またね']
    out.push(...L(who, close[Number(n) % close.length]))
    return { title: `${c.name}とデート${spot ? `（${spot.name}）` : ''}`, lines: out }
  }
  if (kind === 'confess')
    return {
      title: '大切な話',
      lines: L(who, ...(HEROINE_STORY[who]?.confess ?? ['……あのね、{name}。ずっと言おうと思ってたことがあるの', '{name}と一緒にいると、毎日がもっと楽しくなる。……わたしと、付き合ってくれませんか'])),
      choices: [
        { label: '付き合う', reply: '……うれしい。これからも、よろしくね', effect: 'yes' },
        { label: '今はバスケに集中したい', reply: 'そっか。……うん、{name}らしいね。これからも応援してる', effect: 'no' },
      ],
    }
  if (kind === 'confess2')
    return {
      title: '今度は、自分から',
      lines: L(who, 'me:……前に、返事を待たせたよね', 'me:あのときは、バスケのことで頭がいっぱいだった。でも今は、ちゃんと言える', 'me:僕と、付き合ってください'),
      choices: [
        { label: '気持ちを伝える', reply: '……遅いよ。でも、ずっと待ってた。これからよろしくね', effect: 'yes' },
        { label: 'やっぱり言えない', reply: '（……まだ、そのときじゃない）', effect: 'no' },
      ],
    }
  if (kind === 'propose')
    return {
      title: '指輪',
      lines: L(who, 'me:……大事な話があるんだ', 'me:これからの人生を、ずっと一緒に歩いてほしい'),
      choices: [
        { label: 'プロポーズする', reply: HEROINE_STORY[who]?.yes ?? '……はい。喜んで', effect: 'yes' },
        { label: 'まだ言えない', reply: '（……もう少し、自信がついてから）', effect: 'no' },
      ],
    }
  if (kind === 'wedding') return { title: '結婚式', lines: L(who, 'みんなが来てくれたね。黒田先生も、藤堂さんも', 'これからは、ふたりで。……ずっと、よろしくね') }

  if (kind === 'chat') return { title: c.name, lines: L(who, pool[Number(n) % pool.length]) }
  if (kind === 'bond') return { title: `${c.name}との絆`, lines: L(who, ...(n === '80' ? (HEROINE_STORY[who]?.b80 ?? lines.b60) : n === '60' ? lines.b60 : lines.b30)) }
  return null
}

/** 選択肢を選んだときの効果 */
export function applyTalkChoice(state: GameState, talkId: string, effect: string) {
  const c = state.career!
  if (talkId === 'draft_decision') {
    if (effect === 'declare') c.declared = state.season
  }
  if (effect.startsWith('workout:')) c.workoutTeam = Number(effect.split(':')[1])
  if (effect.startsWith('sponsor:')) c.sponsor = effect.split(':')[1] as typeof c.sponsor
  if (talkId === 'retire_ask' && effect === 'retire') c.retirePlan = state.season
  if (talkId.startsWith('confess:') || talkId.startsWith('confess2:') || talkId.startsWith('propose:')) romanceChoice(state, talkId, effect)
  applyLifeChoice(state, talkId, effect)
}
