/**
 * シーズンのまとめ（クラブ C）: シーズンの終わり（clubSeasonEnd）に作り、新しいシーズンのホームで 1 回だけ出す。
 *   順位と勝敗・記録・オーナーの評価・お金（そのシーズンの帳簿の収入と支出）・ファンの増減・チームの成績の 1 位・いちばん伸びた選手
 */
import type { ClubLedger, ClubReview } from '../models/club'
import type { GameState } from '../models/game'
import { ovr } from '../player/overall'
import { clubTeam } from './manage'

const income = (l: ClubLedger) => l.ticket + l.dist + l.sponsor + l.goods + l.prize + Math.max(0, l.transfer ?? 0) + Math.max(0, l.other)
const expense = (l: ClubLedger) => l.wages + l.staff + l.upkeep + l.travel + l.build + Math.max(0, -(l.transfer ?? 0)) + Math.max(0, -l.other)

export function buildReview(state: GameState, rank: number, teams: number, w: number, l: number, league: string, notes: string[]): ClubReview {
  const c = state.club!
  const team = clubTeam(state)
  const from = state.season * 52
  const books = c.ledger.filter((x) => x.abs >= from && x.abs < from + 52)
  // このシーズンを自分のクラブで過ごした選手の成績（経歴はもう記録されている）
  const lines = team.roster
    .map((id) => state.players[id])
    .map((p) => ({ p, h: p.history.find((x) => x.season === state.season && x.teamId === team.id) }))
    .filter((x) => x.h && x.h.stats.gp >= 10)
  const best = (label: string, f: (s: NonNullable<(typeof lines)[number]['h']>['stats']) => number) => {
    const top = [...lines].sort((a, b) => f(b.h!.stats) - f(a.h!.stats))[0]
    return top ? { label, name: top.p.name, value: f(top.h!.stats).toFixed(1) } : null
  }
  const leaders = [best('得点', (s) => s.pts / s.gp), best('リバウンド', (s) => (s.oreb + s.dreb) / s.gp), best('アシスト', (s) => s.ast / s.gp)].filter((x): x is NonNullable<typeof x> => !!x)
  // いちばん伸びた選手（シーズンのはじめの総合値から）
  let riser: ClubReview['riser']
  for (const id of team.roster) {
    const o0 = c.seasonStart?.ovr[id]
    if (o0 === undefined) continue
    const o1 = ovr(state.players[id])
    if (o1 - o0 >= 2 && (!riser || o1 - o0 > riser.to - riser.from)) riser = { name: state.players[id].name, from: o0, to: o1 }
  }
  return {
    season: state.season,
    league,
    rank,
    teams,
    w,
    l,
    notes: [...notes],
    owner: c.owner.last ?? c.owner.result,
    income: books.reduce((s, x) => s + income(x), 0),
    expense: books.reduce((s, x) => s + expense(x), 0),
    fans: [c.seasonStart?.fans ?? c.fans, c.fans],
    leaders,
    riser,
  }
}
