/** シード付きの決定的な乱数（mulberry32）。エンジンの乱数はすべてここを通す。 */
export interface Rng {
  /** [0, 1) */
  next(): number
  /** [min, max] の整数 */
  int(min: number, max: number): number
  /** [min, max) の実数 */
  range(min: number, max: number): number
  pick<T>(arr: readonly T[]): T
  /** 正規分布（Box-Muller） */
  normal(mean: number, sd: number): number
  shuffle<T>(arr: T[]): T[]
  chance(p: number): boolean
  /** 重みに従って添字を引く */
  weighted(weights: readonly number[]): number
  /** 現在の内部状態（保存して再開したいとき用） */
  state(): number
}

export function createRng(seed: number): Rng {
  let a = seed >>> 0
  const next = () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
  return {
    next,
    int: (min, max) => min + Math.floor(next() * (max - min + 1)),
    range: (min, max) => min + next() * (max - min),
    pick: (arr) => arr[Math.floor(next() * arr.length)],
    normal: (mean, sd) => {
      const u = 1 - next()
      const v = next()
      return mean + sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v)
    },
    shuffle: (arr) => {
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(next() * (i + 1))
        const t = arr[i]
        arr[i] = arr[j]
        arr[j] = t
      }
      return arr
    },
    chance: (p) => next() < p,
    weighted: (weights) => {
      let total = 0
      for (const w of weights) total += w
      let r = next() * total
      for (let i = 0; i < weights.length; i++) {
        r -= weights[i]
        if (r <= 0) return i
      }
      return weights.length - 1
    },
    state: () => a >>> 0,
  }
}

/** 複数の整数から 32bit のシードを作る（順序に依存） */
export function hashSeed(...parts: number[]): number {
  let h = 0x811c9dc5
  for (const p of parts) {
    h ^= p >>> 0
    h = Math.imul(h, 0x01000193)
    h ^= h >>> 15
    h = Math.imul(h, 0x2c1b3c6d)
    h ^= h >>> 12
  }
  return h >>> 0
}

/** 文字列のハッシュ（固有キャラ id からシードを作るときなど） */
export function hashString(s: string): number {
  let h = 0x811c9dc5
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return h >>> 0
}

/** 週ごとの乱数 */
export function weekRng(seed: number, absWeek: number, salt = 0): Rng {
  return createRng(hashSeed(seed, absWeek, salt, 0x5eed))
}
