/**
 * くらしの拡充の会話（その場で組み立てる）: 合宿・メディアの話・旅行・恋人と家族の出来事・子どもの節目・家族の行事。
 *   camp:<合宿>            コーチ（いなければ代理人）の一言
 *   media:<種類>           代理人から出演の話（受ける・断る）
 *   trip:<行き先>:<連れ>   旅先の会話（連れがいれば、その人と）
 *   pev:<出来事>:<人>      恋人・結婚相手との出来事（すれ違いは選択あり）
 *   kid:<何人目>:<節目>    子どもの節目（8 歳は「バスケを始めたいか」の選択あり）
 *   fam:<行事>:<シーズン>  家族の行事
 * 台詞の "me:" は主人公。{name} は主人公、{child} は子どもの名前に置き換える（画面で。子どもの名前はここで差し込む）。
 */
import { CAMP_BY_ID, CHILD_MILESTONES, DONATIONS, COMPANION_NAME, FAMILY_EVENTS, MEDIA_BY_KIND, PARTNER_EVENT_BY_ID, TRIP_BY_ID, type MediaKind, type TripCompanion } from '../data/careerLife'
import type { GameState } from '../models/game'
import { acceptMedia, applyPartnerEffect, setChildPlays } from './lifePlus'
import type { Talk, TalkLine } from './talks'

const L = (who: string, ...texts: string[]): TalkLine[] => texts.map((t) => (t.startsWith('me:') ? { who: 'me', text: t.slice(3) } : { who, text: t }))

const CAMP_LINES: Record<string, string[]> = {
  alma: ['また来たか。プロになっても、ここでやることは同じだ', 'me:基本から、もう一度お願いします', '……いい顔になったな'],
  zen: ['me:（目を閉じると、試合の歓声が遠くなる）', 'me:（入らなかったシュートより、次の 1 本のことを考えよう）'],
  okinawa: ['me:（砂浜のダッシュ、30 本目……脚が鉛みたいだ）', 'me:（でも、この脚が第 4 クォーターを走らせてくれる）'],
  shooting_lab: ['me:（リリースの角度、0.3 度のずれまで画面に出る）', 'me:（1,000 本目のシュートが、いちばんきれいに決まった）'],
  altitude: ['me:（空気が薄い。最初の日は階段だけで息が切れた）', 'me:（平地に戻ったら、どこまでも走れそうだ）'],
  skills_la: ['me:（「ドリブルは目でつくな、リズムでつけ」とコーチは言った）', 'me:（スター選手が通う理由が分かった）'],
  bigman: ['me:（足の向き一つで、相手がどちらに動くか決まる）', 'me:（ゴール下は、力じゃなくて頭の勝負だ）'],
  pro_run: ['来たな。俺の練習についてこられたら、本物だ', 'me:……全部、盗ませてもらいます', 'いい目だ。ライバルになる日を楽しみにしてる'],
}

const TRIP_LINES: Record<string, string[]> = {
  onsen: ['湯けむりの向こうに、紅葉の山が見える', '体の芯まで、ほどけていくみたい'],
  kyoto: ['石畳を歩くと、時間がゆっくり流れる', '試合のことを、少しだけ忘れられた'],
  hokkaido: ['一面の雪。音が全部、吸いこまれていく', '温かいスープが、いちばんのごちそう'],
  okinawa_trip: ['海の色が、何段階にも分かれてる', '何もしない日って、こんなに贅沢なんだ'],
  hawaii: ['朝は海、夜は満天の星', 'また来年も来たいね'],
  newyork: ['ストリートコートで、地元の子たちと 1 対 1', '夜はミュージカル。言葉が分からなくても、心が震えた'],
  paris: ['美術館を一日中歩いた', 'カフェのテラスで、ただ人を眺める時間'],
  maldives: ['部屋の床の下を、魚が泳いでる', '波の音しか聞こえない夜'],
  cruise: ['船で世界を回る、長い長い休み', '港に着くたびに、知らない国の匂いがした'],
}

export function lifeTalkOf(id: string, state?: GameState): Talk | null {
  const [kind, a, b] = id.split(':')
  const c = state?.career
  if (kind === 'camp') {
    const d = CAMP_BY_ID[a]
    if (!d) return null
    const who = d.coach ?? 'todo_maiko'
    return { title: d.name, lines: L(who, ...(CAMP_LINES[a] ?? ['me:（いい合宿だった）'])) }
  }
  if (kind === 'media') {
    const m = MEDIA_BY_KIND[a as MediaKind]
    if (!m) return null
    return {
      title: 'メディアの話',
      lines: L('todo_maiko', `${m.name}の依頼が来ているわ（出演料 ${m.pay.toLocaleString()} 万円）`, m.desc, '受ける？ 疲れは少したまるけど、知名度は上がるわ'),
      choices: [
        { label: '受ける', reply: 'じゃあ、日程を組んでおくわね', effect: `media:${a}` },
        { label: '断る', reply: '分かった。今はバスケに集中しましょう', effect: 'no' },
      ],
    }
  }
  if (kind === 'trip') {
    const t = TRIP_BY_ID[a]
    if (!t) return null
    const w = b as TripCompanion
    const partner = w === 'partner' || w === 'family' ? (c?.spouse ?? c?.partner) : undefined
    const lines = TRIP_LINES[a] ?? ['いい旅だった']
    if (partner) return { title: `${t.name}（${COMPANION_NAME[w]}）`, lines: [...L(partner, lines[0]), ...L(partner, `me:${lines[1]}`), ...L(partner, w === 'family' ? '子どもたち、ずっとはしゃいでたね。……また家族で来よう' : '連れてきてくれて、ありがとう。いい思い出になった')] }
    if (w === 'team') return { title: `${t.name}（チームの仲間と）`, lines: L('todo_maiko', `me:${lines[0]}`, 'me:チームのみんなと、コートの外でも笑い合えた。来季が楽しみだ') }
    return { title: `${t.name}（ひとりで）`, lines: L('todo_maiko', `me:${lines[0]}`, `me:${lines[1]}`) }
  }
  if (kind === 'pev') {
    const e = PARTNER_EVENT_BY_ID[a]
    if (!e) return null
    const who = b
    if (e.id === 'anniversary') {
      const years = Number(id.split(':')[3] ?? 1)
      const married = id.split(':')[4] === '1'
      return {
        title: married ? `結婚 ${years} 年の記念日` : `付き合って ${years} 年`,
        lines: L(who, married ? `結婚して ${years} 年。……あっという間だったね` : `今日で付き合って ${years} 年だよ。覚えてた？`, 'me:……もちろん。だから、店を予約しておいた', married ? 'これからも、ずっと隣で応援させてね' : 'ほんとに？ うれしい'),
      }
    }
    return {
      title: e.title,
      lines: L(who, ...e.lines),
      choices: e.choices?.map((ch, i) => ({ label: ch.label, reply: ch.reply, effect: `pev:${e.id}:${i}` })),
    }
  }
  if (kind === 'kid') {
    const idx = Number(a)
    const ms = CHILD_MILESTONES.find((m) => m.id === b)
    if (!ms) return null
    const child = c?.children?.[idx]
    const name = child?.name ?? 'この子'
    const sp = c?.spouse ?? 'todo_maiko'
    const fill = (t: string) => t.replace(/\{child\}/g, name)
    return {
      title: `${name}：${ms.title}`,
      lines: L(sp, ...ms.lines.map(fill)),
      choices: ms.choices?.map((ch) => ({ label: ch.label, reply: fill(ch.reply), effect: `kid:${idx}:${ch.plays ? 1 : 0}` })),
    }
  }
  if (kind === 'donate') {
    const d = DONATIONS.find((x) => x.id === a)
    if (!d) return null
    return { title: '寄付', lines: L('todo_maiko', `「${d.name}」の式典、無事に終わったわ`, 'あなたの名前を見て、バスケを始める子がきっと出てくる', 'me:僕も、誰かに夢をもらってここまで来たから') }
  }
  if (kind === 'charity') {
    const n = Number(a) / 10000
    return { title: '財団の活動', lines: L('todo_maiko', `財団の寄付が、通算 ${n} 億円になったわ`, '支援したコートで、子どもたちが毎日ボールを追いかけてる', 'me:……それが、いちばんうれしいニュースです') }
  }
  if (kind === 'fam') {
    const e = FAMILY_EVENTS.find((x) => x.id === a)
    if (!e) return null
    return { title: e.title, lines: L(c?.spouse ?? 'todo_maiko', ...e.lines) }
  }
  return null
}

/** くらしの拡充の選択の効果（talks.ts の applyTalkChoice から） */
export function applyLifeChoice(state: GameState, talkId: string, effect: string) {
  const [kind, a, b] = effect.split(':')
  if (kind === 'media') acceptMedia(state, a as MediaKind)
  if (kind === 'pev') {
    const e = PARTNER_EVENT_BY_ID[a]
    const ch = e?.choices?.[Number(b)]
    const who = talkId.split(':')[2]
    if (ch && who) applyPartnerEffect(state, who, ch.effect)
  }
  if (kind === 'kid') setChildPlays(state, Number(a), b === '1')
  if (talkId.startsWith('media:') && effect === 'no') delete state.career!.mediaOffer
}

export const LIFE_TALK_KINDS = new Set(['camp', 'media', 'trip', 'pev', 'kid', 'fam', 'donate', 'charity'])
