/**
 * 試合エンジン（ポゼッション単位）。観戦も結果だけも、このエンジンで動かす。
 *   1 ポゼッション: （デッドボールなら交代）→ 速攻か、ボール運び → タッチを重ねる（パス・ドライブ・ピック&ロール・ポスト・アイソ・シュート）
 *   → シュートの成否・ブロック・ファウル・フリースロー → リバウンド（オフェンスなら続き、ディフェンスなら相手のポゼッション）
 * 成否は放つ瞬間に決める（resolve.ts の確率とサイコロ）。観戦のときは流れ（Trace）を残し、choreo.ts が動きにする。
 * 乱数は setup.seed からの 1 本の流れだけ（同じ setup なら同じ試合）。
 */
import { createRng, hashSeed, type Rng } from '../core/prng'
import { RULES, type RuleSet } from '../data/rules'
import { type Position } from '../data/positions'
import { autoSubs, depthOrder, foreignOk, pickStarters } from './rotation'
import {
  TUNE,
  beatChance,
  blockPct,
  ftPct,
  pickZone,
  shootingFoulPct,
  shotPct,
  tovPct,
  usageWeights,
  type ShotContext,
} from './resolve'
import {
  emptyBox,
  emptyTotals,
  type GameEvent,
  type MatchSetup,
  type Moment,
  type MomentOption,
  type MatchSummary,
  type PossLog,
  type ShotZone,
  type SimPlayer,
  type SimTeam,
  type TeamInput,
  type TeamTotals,
  type Trace,
} from './types'

type Side = 0 | 1
const ACTIONS = ['shoot', 'pass', 'drive', 'pnr', 'post', 'iso'] as const
const ACTION_W = [0, 0, 0, 0, 0, 0]
/** 見せ場で選んだ手 → 最初のプレー */
const FORCED_ACTION: Record<MomentOption['id'], (typeof ACTIONS)[number]> = { three: 'shoot', mid: 'shoot', drive: 'drive', post: 'post', pass: 'pass' }
type StartKind = 'period' | 'inbound' | 'live' | 'steal'

const POS_ORDER: Position[] = ['PG', 'SG', 'SF', 'PF', 'C']
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

/** 試合の水準: 両チームの主力 8 人の総合値の平均 */
export function matchLevel(home: TeamInput, away: TeamInput): number {
  const top = (t: TeamInput) =>
    t.players
      .map((p) => p.ovr)
      .sort((a, b) => b - a)
      .slice(0, 8)
  const all = [...top(home), ...top(away)]
  return all.reduce((s, v) => s + v, 0) / Math.max(1, all.length)
}

function makeTeam(input: TeamInput, shift: number): SimTeam {
  const ref = TUNE.levelRef
  const players: SimPlayer[] = input.players.map((p) => {
    const a = { ...p.attr }
    // 水準をそろえてから、基準へ寄せる（能力の差を出しすぎない。TUNE.spread）
    for (const k of Object.keys(a) as (keyof typeof a)[]) a[k] = ref + (a[k] + shift - ref) * TUNE.spread
    const { attr: _attr, energy, ...rest } = p
    void _attr
    return { ...rest, a, energy: energy ?? 100, fouls: 0, out: false, box: emptyBox() }
  })
  return { teamId: input.teamId, name: input.name, short: input.short, abbr: input.abbr, colors: input.colors, tactics: { ...input.tactics }, players, court: [], score: 0, periodFouls: 0, timeouts: 7, manual: false }
}

/** 次の 1 ポゼッションを進める手（観戦の画面が 1 つずつ呼ぶ） */
export class MatchEngine {
  readonly rules: RuleSet
  readonly rng: Rng
  readonly setup: MatchSetup
  readonly live: boolean
  teams: [SimTeam, SimTeam]
  period = 1
  /** ピリオドの残り秒 */
  clock: number
  poss: Side = 0
  ot = 0
  over = false
  totals: [TeamTotals, TeamTotals] = [emptyTotals(), emptyTotals()]
  private start: StartKind = 'period'
  private jumpWinner: Side = 0
  /** 選手 id → 打つ回数の重み */
  private usage = new Map<number, number>()
  /** このポゼッションのコートの 5 人・マンツーマンの相手・ゴール下の守り（ポゼッションのはじめに作る） */
  private cur: [SimPlayer[], SimPlayer[]] = [[], []]
  private mark = new Map<SimPlayer, SimPlayer>()
  private rimGuard: [SimPlayer | null, SimPlayer | null] = [null, null]
  /** 序列（総合値の順。試合の中で変わらない） */
  private order: [number[], number[]] = [[], []]
  /** コートの顔ぶれが変わった（マッチアップを作り直す） */
  private dirty = true
  /** 交代を考えるのは、前に考えてから 40 秒たったか、ピリオドのはじめ・ファウルのあと */
  private subClock = 0
  private subNow = true
  /** その日のチームの当たり外れ（シュートの成功率に足す） */
  private form: [number, number] = [0, 0]
  /** 観戦: 直近のポゼッションの得点（流れ。AI のタイムアウト） */
  private run: number[] = []
  private log: PossLog | null = null
  /** 見せ場（キャリア・観戦のとき）。試合の乱数とは別の流れで、出すかどうかを決める */
  private momentRng: Rng
  private momentsLeft = 7
  private pending: Moment | null = null
  private forced: MomentOption['id'] | null = null
  /** 観戦（クラブ経営）: 次のデッドボールで行うタイムアウトと交代（選手の添字） */
  private pendingTimeout: [boolean, boolean] = [false, false]
  private pendingSubs: [[number, number][], [number, number][]] = [[], []]

  /** 試合の流れ（1 分ごとの点差）と、経った秒 */
  private flow: number[] = []
  private elapsed = 0

  constructor(setup: MatchSetup, opts: { live?: boolean } = {}) {
    this.setup = setup
    this.live = !!opts.live
    this.rules = RULES[setup.rules]
    this.rng = createRng(setup.seed)
    const shift = TUNE.levelRef - matchLevel(setup.home, setup.away)
    this.teams = [makeTeam(setup.home, shift), makeTeam(setup.away, shift)]
    this.teams.forEach((t, i) => {
      t.court = pickStarters(t, !!setup.foreignLimit)
      for (const idx of t.court) t.players[idx].box.started = true
      t.timeouts = this.rules.periods === 4 && this.rules.periodMin === 12 ? 7 : 5
      // 打つ回数の重みは、寄せる前の能力で（エースがエースらしく打つように）
      const input = i === 0 ? setup.home : setup.away
      const raw = t.players.map((p, j) => ({ ...p, a: input.players[j].attr }))
      const u = usageWeights(raw, t.players.map((p) => p.style))
      t.players.forEach((p, j) => this.usage.set(p.id, u[j]))
      this.order[i] = depthOrder(t)
    })
    this.clock = this.rules.periodMin * 60
    // ジャンプボール: 背の高いほうが少し有利
    const c = (t: SimTeam) => Math.max(...t.court.map((i) => t.players[i].heightCm + t.players[i].a.jump * 0.2))
    this.jumpWinner = this.rng.chance(clamp(0.5 + (c(this.teams[0]) - c(this.teams[1])) / 40, 0.2, 0.8)) ? 0 : 1
    this.poss = this.jumpWinner
    this.form = [this.rng.normal(0, TUNE.form), this.rng.normal(0, TUNE.form)]
    this.momentRng = createRng(hashSeed(setup.seed, 0x6d6f6d))
  }

  /**
   * 次のポゼッションが主人公の見せ場か（観戦のときだけ）。見せ場なら選択肢を返す（step(choice) で選ぶ）。
   * 攻めがハーフコートから始まるとき（スローイン・ピリオドのはじめ）に、ふだん 1 割ほど、終盤の接戦は 4 割ほど
   */
  peekMoment(): Moment | null {
    if (this.pending) return this.pending
    const fid = this.setup.focusPlayerId
    if (!this.live || this.over || fid === undefined || this.momentsLeft <= 0) return null
    if (this.start !== 'inbound' && this.start !== 'period') return null
    const side = this.poss
    const t = this.teams[side]
    const idx = t.players.findIndex((p) => p.id === fid)
    if (idx < 0 || !t.court.includes(idx)) return null
    const clutch = this.clutchNow(side)
    if (!this.momentRng.chance(clutch ? 0.45 : 0.17)) return null
    this.refreshCourt()
    const me = t.players[idx]
    const d = this.defenderOf(side, me)
    const est = (zone: ShotZone, adv: number) => shotPct({ shooter: me, defender: zone === 'rim' || zone === 'paint' ? this.rimProtector(side) : d, zone, adv, home: side === 0 && !this.setup.neutral, clutch, big: !!this.setup.big, catchShoot: false, late: false, form: this.form[side] })
    const mark = (p: number, hi: number, lo: number): MomentOption['mark'] => (p >= hi ? '◎' : p >= lo ? '○' : '△')
    const big = me.pos === 'C' || me.pos === 'PF'
    const opts: MomentOption[] = []
    const three = est('three', 0.42)
    const drive = beatChance(me, d, 0) * 0.62 * est('rim', 0.72) + 0.06
    const pass = clamp(0.36 + (me.a.pass + me.a.vision - 2 * TUNE.levelRef) / 300, 0.15, 0.75)
    if (!big || me.a.three >= 60) opts.push({ id: 'three', label: '3P を打つ', mark: mark(three, 0.42, 0.33), pct: three, note: `マークは ${d.short}。決まれば 3 点` })
    if (big) {
      const post = clamp(0.3 + 0.4 * (0.5 + (0.5 * me.a.post + 0.3 * me.a.strength - (0.5 * d.a.intD + 0.3 * d.a.strength)) / 40), 0.1, 0.8) * est('paint', 0.55) * 1.4
      opts.push({ id: 'post', label: 'ゴール下で勝負', mark: mark(post, 0.5, 0.38), pct: post, note: `${d.short}を背負って押し込む` })
    } else opts.push({ id: 'drive', label: 'ドライブで切り込む', mark: mark(drive, 0.45, 0.34), pct: drive, note: `${d.short}を抜いてゴールへ。ファウルをもらえることも` })
    if (opts.length < 3 && (big || me.a.mid >= me.a.three)) {
      const mid = est('mid', 0.45)
      opts.push({ id: 'mid', label: 'ミドルを打つ', mark: mark(mid, 0.47, 0.38), pct: mid, note: '少し離れたところから' })
    }
    opts.push({ id: 'pass', label: 'パスでさばく', mark: mark(pass, 0.48, 0.36), pct: pass, note: 'ひきつけて、空いた味方へ' })
    this.pending = { side, pid: me.id, clutch, options: opts.slice(0, 3) }
    this.momentsLeft--
    return this.pending
  }

  // ------------------------------------------------------------------ 外から

  /** 1 ポゼッション進める。試合が終わっていたら null */
  step(choice?: MomentOption['id']): PossLog | null {
    if (this.over) return null
    if (this.pending) {
      this.forced = choice ?? this.pending.options[0].id
      this.pending = null
    }
    const log = this.possession()
    if (this.forced) {
      const fid = this.setup.focusPlayerId!
      const success = log.events.some((e) => (e.k === 'shot' && e.made && (e.pid === fid || e.ast === fid)) || (e.k === 'ft' && e.made && e.pid === fid))
      log.moment = { choice: this.forced, success }
      this.forced = null
    }
    this.afterPossession(log)
    return log
  }

  /** 最後まで進める（結果だけ） */
  simulate(): MatchSummary {
    while (!this.over) this.step()
    return this.summary()
  }

  summary(): MatchSummary {
    const box: MatchSummary['box'] = {}
    for (const t of this.teams) for (const p of t.players) box[p.id] = p.box
    const margin = this.teams[0].score - this.teams[1].score
    const flow = this.over && this.flow[this.flow.length - 1] !== margin ? [...this.flow, margin] : [...this.flow]
    return { score: [this.teams[0].score, this.teams[1].score], ot: this.ot, box, teams: this.totals, flow }
  }

  /** 交代（手動）。デッドボールの次のポゼッションから */
  substitute(side: Side, outIdx: number, inIdx: number) {
    const t = this.teams[side]
    const i = t.court.indexOf(outIdx)
    if (i < 0 || t.court.includes(inIdx) || t.players[inIdx].out) return
    t.court[i] = inIdx
    this.dirty = true
  }

  // ------------------------------------------------------------------ ポゼッション

  private ev(e: GameEvent) {
    if (this.live) this.log!.events.push(e)
  }
  private tr(x: Trace) {
    this.log!.trace?.push(x)
  }

  private court(side: Side): SimPlayer[] {
    return this.cur[side]
  }

  /** コートの 5 人・マッチアップ・ゴール下の守りを作り直す（交代のあと） */
  private refreshCourt() {
    if (!this.dirty) return
    this.dirty = false
    for (const s of [0, 1] as Side[]) {
      const t = this.teams[s]
      this.cur[s] = t.court.map((i) => t.players[i])
    }
    const byPos = (ps: SimPlayer[]) => [...ps].sort((a, b) => POS_ORDER.indexOf(a.pos) - POS_ORDER.indexOf(b.pos) || b.heightCm - a.heightCm)
    this.mark.clear()
    const a = byPos(this.cur[0])
    const b = byPos(this.cur[1])
    for (let i = 0; i < 5; i++) {
      this.mark.set(a[i], b[i])
      this.mark.set(b[i], a[i])
    }
    const guard = (ps: SimPlayer[]) => ps.reduce((x, d) => (0.5 * d.a.block + 0.5 * d.a.intD + d.heightCm * 0.2 > 0.5 * x.a.block + 0.5 * x.a.intD + x.heightCm * 0.2 ? d : x))
    // rimGuard[s] は s が攻めるときに守るゴール下の選手（相手チームの）
    this.rimGuard = [guard(this.cur[1]), guard(this.cur[0])]
  }

  /** マンツーマンの相手（ポジションの順に並べて同じ順位どうし） */
  private defenderOf(_side: Side, p: SimPlayer): SimPlayer {
    return this.mark.get(p)!
  }

  /** ゴール下を守る選手（ヘルプ） */
  private rimProtector(side: Side): SimPlayer {
    return this.rimGuard[side]!
  }

  private pick(side: Side, weight: (p: SimPlayer) => number, exclude?: SimPlayer): SimPlayer {
    const ps = this.cur[side]
    let total = 0
    const w = [0, 0, 0, 0, 0]
    for (let i = 0; i < 5; i++) {
      w[i] = ps[i] === exclude ? 0 : Math.max(0.001, weight(ps[i]))
      total += w[i]
    }
    let r = this.rng.next() * total
    for (let i = 0; i < 5; i++) {
      r -= w[i]
      if (r < 0) return ps[i]
    }
    return ps[4] === exclude ? ps[3] : ps[4]
  }

  private usageOf(_side: Side, p: SimPlayer): number {
    return this.usage.get(p.id) ?? 1
  }

  private paceMul(side: Side): number {
    return TUNE.pace[this.teams[side].tactics.pace] * TUNE.rulePace[this.setup.rules]
  }

  private dt(kind: string, side: Side): number {
    const [lo, hi] = TUNE.time[kind]
    return this.rng.range(lo, hi) * this.paceMul(side)
  }

  private clutchNow(side: Side): boolean {
    const diff = this.teams[side].score - this.teams[1 - side].score
    return this.period >= this.rules.periods && this.clock < 300 && Math.abs(diff) <= 6
  }

  private addPts(side: Side, pts: number) {
    this.teams[side].score += pts
    this.totals[side].pts += pts
    for (const p of this.court(side)) p.box.pm += pts
    for (const p of this.court((1 - side) as Side)) p.box.pm -= pts
    this.run.push(side === 0 ? pts : -pts)
  }

  private possession(): PossLog {
    const side = this.poss
    const log: PossLog = { side, period: this.period, clock: this.clock, dur: 0, events: [], lineup: [], score: [0, 0] }
    if (this.live) log.trace = []
    this.log = log
    // デッドボールなら、頼まれたタイムアウトと交代 → AI の交代とタイムアウト
    const dead = this.start === 'period' || this.start === 'inbound'
    if (dead) this.applyRequests()
    if (dead && (this.subNow || this.subClock >= 40)) {
      for (const s of [0, 1] as Side[]) this.aiTimeout(s)
      for (const s of [0, 1] as Side[]) this.runSubs(s)
      this.subClock = 0
      this.subNow = false
    }
    this.refreshCourt()
    log.lineup = [...this.cur[0], ...this.cur[1]].map((p) => p.id)
    this.totals[side].poss++
    const t = this.playPossession(side)
    log.dur = Math.min(t, this.clock)
    log.score = [this.teams[0].score, this.teams[1].score]
    return log
  }

  /** ポゼッションを最後まで。使った秒を返し、次の始まり方（this.start）と攻めの向き（this.poss）を決める */
  private playPossession(side: Side): number {
    const def = (1 - side) as Side
    const off = this.teams[side]
    const tac = off.tactics
    const press = this.teams[def].tactics.defense === 'press'
    let t = 0
    let shotEnd = this.rules.shotClock
    const limit = () => Math.min(shotEnd, this.clock)
    let adv = 0.25
    let passes = 0
    let lastPasser: SimPlayer | undefined
    let holder: SimPlayer
    let kick = false

    // ---- 速攻（リバウンド・スティールから）
    const transChance = this.start === 'steal' ? TUNE.transition.steal : this.start === 'live' ? TUNE.transition.reb : 0
    const speedEdge = (this.court(side).reduce((s, p) => s + p.a.speed, 0) - this.court(def).reduce((s, p) => s + p.a.speed, 0)) / 500
    const fastMul = (tac.pace === 'fast' ? 1.35 : tac.pace === 'slow' ? 0.7 : 1) * (press ? 1.15 : 1)
    if (transChance > 0 && this.rng.chance(clamp((transChance + speedEdge) * fastMul, 0, 0.8))) {
      t += this.dt('fast', side)
      holder = this.pick(side, (p) => p.a.speed + (p.skills.transition ? 25 : 0))
      this.tr({ t, a: 'fast', p: holder.id })
      if (t >= this.clock) return this.endOfPeriod(side, holder, t)
      const outlet = this.rng.chance(0.55) ? this.pick(side, (p) => p.a.pass + p.a.vision, holder) : undefined
      const r = this.shoot(side, holder, pickZone(holder, 'fast', tac.focus, this.rng), 0.82, t, outlet, { fast: true })
      if (r.kind === 'end') return t
      t = r.t
      adv = 0.3
    } else {
      // ---- ボール運び
      t += this.dt('bringUp', side)
      if (press) {
        const h0 = this.pick(side, (p) => p.a.handle)
        if (this.rng.chance(tovPct('drive', h0, this.defenderOf(side, h0), true) * 0.6)) return this.turnover(side, h0, t, true)
      }
    }
    holder = this.pick(side, (p) => (p.a.handle + p.a.pass + p.a.vision) * (p.pos === 'PG' ? 1.6 : p.pos === 'SG' ? 1.15 : 0.6))
    // 見せ場: ボールは主人公へ
    const forced = this.forced
    if (forced) holder = this.court(side).find((p) => p.id === this.setup.focusPlayerId) ?? holder
    this.tr({ t, a: 'bring', p: holder.id })

    // ---- タッチを重ねる
    for (let touch = 0; touch < 12; touch++) {
      const left = limit() - t
      if (left <= 1.6) {
        // 時間切れ間近: 無理にでも打つ
        if (t >= this.clock) return this.endOfPeriod(side, holder, t)
        const r = this.shoot(side, holder, pickZone(holder, 'late', tac.focus, this.rng), adv * 0.5, t + Math.max(0.3, left - 0.4), lastPasser, { late: true })
        if (r.kind === 'end') return r.t
        t = r.t
        shotEnd = t + 14
        adv = 0.25
        passes = 0
        lastPasser = undefined
        continue
      }
      const fa = touch === 0 && forced ? FORCED_ACTION[forced] : null
      const action = fa ?? this.chooseAction(side, holder, adv, passes, left, kick)
      kick = false
      const d = this.defenderOf(side, holder)
      if (action !== 'shoot' && action !== 'drive' && action !== 'iso' && this.rng.chance(TUNE.offBallFoul)) {
        const victim = this.pick(side, (p) => p.a.strength + 20)
        const r = this.nonShootingFoul(side, victim, this.defenderOf(side, victim), t + 0.8)
        if (r === 'end') return t + 0.8
        t += 0.8
        shotEnd = Math.max(shotEnd, t + 14)
        continue
      }
      switch (action) {
        case 'shoot': {
          const ctx = lastPasser && passes > 0 ? 'catch' : 'pullup'
          const zone = touch === 0 && (forced === 'three' || forced === 'mid') ? (forced === 'three' ? 'three' : 'mid') : pickZone(holder, ctx, tac.focus, this.rng)
          const r = this.shoot(side, holder, zone, touch === 0 && forced ? Math.max(adv, 0.42) : adv, t + 0.6, lastPasser, { catchShoot: ctx === 'catch' })
          if (r.kind === 'end') return r.t
          t = r.t
          if (r.kind === 'reset') {
            shotEnd = Math.max(shotEnd, t + 14)
            adv = 0.25
            passes = 0
            lastPasser = undefined
            holder = r.holder!
          }
          continue
        }
        case 'pass': {
          t += this.dt('pass', side)
          if (this.rng.chance(tovPct('pass', holder, this.pick(def, (p) => p.a.steal), press))) return this.turnover(side, holder, t, false)
          const to = this.pick(side, (p) => this.usageOf(side, p) + 0.35, holder)
          this.tr({ t, a: 'pass', p: holder.id, q: to.id })
          lastPasser = holder
          holder = to
          passes++
          adv = clamp(adv * 0.75 + 0.05 + (holder.a.vision - TUNE.levelRef) / 400, 0.1, 0.9)
          continue
        }
        case 'drive':
        case 'iso': {
          t += this.dt(action, side)
          this.tr({ t, a: action === 'iso' ? 'iso' : 'drive', p: holder.id })
          if (this.rng.chance(tovPct(action === 'iso' ? 'iso' : 'drive', holder, d, press))) return this.turnover(side, holder, t, false)
          if (this.rng.chance(TUNE.reachFoul)) {
            const r = this.nonShootingFoul(side, holder, d, t)
            if (r === 'end') return t
            continue
          }
          const beat = beatChance(holder, d, this.teams[def].tactics.defense === 'man' ? 0 : 1)
          const roll = this.rng.next()
          if (roll < beat * 0.62) {
            // 抜いた: ゴールへ
            const r = this.shoot(side, holder, pickZone(holder, action === 'iso' ? 'iso' : 'drive', tac.focus, this.rng), clamp(0.45 + beat * 0.4, 0, 0.9), t + 0.5, passes > 0 && action === 'drive' ? lastPasser : undefined, {})
            if (r.kind === 'end') return r.t
            t = r.t
            holder = r.holder ?? holder
            shotEnd = Math.max(shotEnd, t + 14)
            adv = 0.25
            passes = 0
            lastPasser = undefined
          } else if (roll < beat * 0.62 + 0.25) {
            // 守備が寄った: 外へさばく（キックアウト）
            const to = this.pick(side, (p) => (p.a.three + 10) * this.usageOf(side, p), holder)
            this.tr({ t, a: 'pass', p: holder.id, q: to.id })
            lastPasser = holder
            holder = to
            passes++
            adv = clamp(0.55 + (lastPasser.a.pass - TUNE.levelRef) / 200, 0.3, 0.9)
            kick = true
          } else {
            // 止められた: 組み立て直し
            adv = clamp(adv - 0.05, 0.1, 0.9)
            if (action === 'iso' && this.rng.chance(0.55)) {
              const r = this.shoot(side, holder, pickZone(holder, 'iso', tac.focus, this.rng), clamp(0.2 + beat * 0.2, 0, 0.6), t + 0.6, undefined, {})
              if (r.kind === 'end') return r.t
              t = r.t
              holder = r.holder ?? holder
              shotEnd = Math.max(shotEnd, t + 14)
              adv = 0.25
              passes = 0
              lastPasser = undefined
            }
          }
          continue
        }
        case 'pnr': {
          t += this.dt('pnr', side)
          const screener = this.pick(side, (p) => (p.pos === 'C' || p.pos === 'PF' ? 3 : p.pos === 'SF' ? 1 : 0.3) * (p.a.strength + 20), holder)
          this.tr({ t, a: 'pnr', p: holder.id, q: screener.id })
          if (this.rng.chance(tovPct('pnr', holder, d, press))) return this.turnover(side, holder, t, false)
          const master = holder.skills.pnrMaster ? 0.08 : 0
          const roll = this.rng.next()
          const pop = screener.a.three >= 62 && screener.a.three > screener.a.close - 5
          if (roll < 0.3 + master) {
            // 自分で打つ（プルアップ）かドライブ
            const r = this.shoot(side, holder, pickZone(holder, this.rng.chance(0.5) ? 'pullup' : 'drive', tac.focus, this.rng), clamp(0.5 + master + (holder.a.handle - TUNE.levelRef) / 200, 0.2, 0.9), t + 0.5, passes > 0 ? lastPasser : undefined, {})
            if (r.kind === 'end') return r.t
            t = r.t
            holder = r.holder ?? holder
            shotEnd = Math.max(shotEnd, t + 14)
            adv = 0.25
            passes = 0
            lastPasser = undefined
          } else if (roll < 0.52 + master) {
            // スクリーンをかけた選手へ（ロールかポップ）
            this.tr({ t: t + 0.4, a: 'pass', p: holder.id, q: screener.id })
            const r = this.shoot(side, screener, pickZone(screener, pop ? 'pop' : 'roll', tac.focus, this.rng), clamp(0.55 + (holder.a.pass - TUNE.levelRef) / 180, 0.3, 0.92), t + 1.0, holder, { catchShoot: pop })
            if (r.kind === 'end') return r.t
            t = r.t
            holder = r.holder ?? screener
            shotEnd = Math.max(shotEnd, t + 14)
            adv = 0.25
            passes = 0
            lastPasser = undefined
          } else if (roll < 0.78) {
            // 守備が 2 人寄った: 空いた選手へ
            const to = this.pick(side, (p) => (p.a.three + 5) * this.usageOf(side, p), holder)
            this.tr({ t, a: 'pass', p: holder.id, q: to.id })
            lastPasser = holder
            holder = to
            passes++
            adv = clamp(0.5 + (lastPasser.a.vision - TUNE.levelRef) / 200, 0.3, 0.9)
            kick = true
          } else {
            adv = clamp(adv + 0.03, 0.1, 0.9)
          }
          continue
        }
        case 'post': {
          t += this.dt('post', side)
          this.tr({ t, a: 'post', p: holder.id })
          if (this.rng.chance(tovPct('post', holder, d, press))) return this.turnover(side, holder, t, false)
          const edge = clamp(0.5 + (0.5 * holder.a.post + 0.3 * holder.a.strength + 0.2 * holder.heightCm * 0.4 - (0.5 * d.a.intD + 0.3 * d.a.strength + 0.2 * d.heightCm * 0.4)) / 40, 0.15, 0.85)
          if (this.rng.chance(0.68)) {
            const r = this.shoot(side, holder, pickZone(holder, 'post', tac.focus, this.rng), clamp(0.3 + edge * 0.4 + (holder.skills.postMoves ? 0.08 : 0), 0.1, 0.85), t + 0.6, passes > 0 ? lastPasser : undefined, {})
            if (r.kind === 'end') return r.t
            t = r.t
            holder = r.holder ?? holder
            shotEnd = Math.max(shotEnd, t + 14)
            adv = 0.25
            passes = 0
            lastPasser = undefined
          } else {
            const to = this.pick(side, (p) => (p.a.three + 5) * this.usageOf(side, p), holder)
            this.tr({ t, a: 'pass', p: holder.id, q: to.id })
            lastPasser = holder
            holder = to
            passes++
            adv = clamp(0.5 + (lastPasser.a.pass - TUNE.levelRef) / 200, 0.3, 0.85)
            kick = true
          }
          continue
        }
      }
    }
    // タッチが多すぎた（ふつうは起きない）: 24 秒のバイオレーション
    return this.turnover(side, holder, Math.min(limit(), t + 1), false, 'clock')
  }

  /** 次のプレー。作戦・打つ人の役割・フリーかどうか・残り時間で決める */
  private chooseAction(side: Side, h: SimPlayer, adv: number, passes: number, left: number, kick: boolean): 'shoot' | 'pass' | 'drive' | 'pnr' | 'post' | 'iso' {
    const tac = this.teams[side].tactics
    const u = this.usageOf(side, h)
    const urgent = left < 7 ? 2.6 : left < 11 ? 1.4 : 1
    const big = h.pos === 'C' || h.pos === 'PF'
    const set = tac.set
    const w = ACTION_W
    w[0] = (0.32 + u * 0.38) * (0.4 + adv * 1.6) * urgent * (kick ? 1.6 : 1) * (passes === 0 ? 0.55 : 1)
    w[1] = Math.max(0.05, (1.45 - u * 0.5) * (passes >= 4 ? 0.35 : 1) * (left < 6 ? 0.3 : 1) * (0.6 + h.a.vision / 160)) * (set === 'motion' ? 1.4 : 1)
    w[2] = (0.1 + (h.a.quick + h.a.handle) / 460) * (big ? 0.35 : 1) * (kick ? 1.4 : 1)
    w[3] = !big && passes <= 2 ? (set === 'pnr' ? 0.62 : 0.2) * (0.5 + h.a.handle / 140) : 0
    w[4] = big ? (set === 'post' ? 0.6 : 0.2) * (0.4 + h.a.post / 120) : 0
    w[5] = u > 0.8 ? (set === 'iso' ? 0.55 : 0.12) * u : 0
    let total = 0
    for (let i = 0; i < 6; i++) total += w[i]
    let r = this.rng.next() * total
    for (let i = 0; i < 6; i++) {
      r -= w[i]
      if (r < 0) return ACTIONS[i]
    }
    return 'shoot'
  }

  // ------------------------------------------------------------------ シュート・フリースロー・リバウンド

  /**
   * シュート。end: ポゼッション終わり（相手ボール）／reset: オフェンスリバウンドを取ってやり直し（holder が持つ）
   */
  private shoot(side: Side, shooter: SimPlayer, zone: ShotZone, adv: number, t: number, passer: SimPlayer | undefined, o: { fast?: boolean; late?: boolean; catchShoot?: boolean; putback?: boolean }): { kind: 'end' | 'reset'; t: number; holder?: SimPlayer } {
    const def = (1 - side) as Side
    if (t >= this.clock) t = Math.max(0, this.clock - 0.2)
    const man = this.defenderOf(side, shooter)
    const inside = zone === 'rim' || zone === 'paint'
    const defender = inside && !o.fast ? (this.rng.chance(0.45) ? this.rimProtector(side) : man) : man
    // ゾーンは外が空き、中が固い
    const dz = this.teams[def].tactics.defense
    const zoneAdj = dz === 'zone23' ? (inside ? -0.08 : 0.07) : dz === 'zone32' ? (inside ? -0.03 : 0.03) : 0
    const ctx: ShotContext = {
      shooter,
      defender,
      zone,
      adv: clamp(adv + zoneAdj, 0, 1),
      home: side === 0 && !this.setup.neutral,
      clutch: this.clutchNow(side),
      big: !!this.setup.big,
      catchShoot: !!o.catchShoot,
      late: !!o.late,
      form: this.form[side],
    }
    const three = zone === 'three' || zone === 'corner3'
    const pts = three ? 3 : 2
    const tot = this.totals[side]
    // ブロック
    if (this.rng.chance(blockPct(ctx))) {
      shooter.box.fga++
      tot.fga++
      if (three) {
        shooter.box.tpa++
        tot.tpa++
      }
      defender.box.blk++
      this.totals[def].blk++
      this.ev({ k: 'shot', side, pid: shooter.id, zone, made: false, pts, blk: defender.id, fast: o.fast })
      this.tr({ t, a: 'shot', p: shooter.id, q: defender.id, zone, made: false })
      // ブロックされたボールは守備側が拾いやすい
      return this.rebound(side, shooter, t + 1.2, 0.36)
    }
    const fouled = this.rng.chance(shootingFoulPct(ctx))
    const made = this.rng.chance(shotPct(ctx) * (fouled ? 0.55 : 1))
    if (fouled) {
      defender.fouls++
      defender.box.pf++
      this.totals[def].pf++
      this.teams[def].periodFouls++
      this.subNow = this.subNow || defender.fouls >= 2
      this.ev({ k: 'foul', side: def, pid: defender.id, on: shooter.id, shooting: true, bonus: false })
    }
    if (made || !fouled) {
      shooter.box.fga++
      tot.fga++
      if (three) {
        shooter.box.tpa++
        tot.tpa++
      }
    }
    if (made) {
      shooter.box.fgm++
      shooter.box.pts += pts
      tot.fgm++
      if (three) {
        shooter.box.tpm++
        tot.tpm++
      }
      // アシスト: パスから打ったシュート（区域で割合が違う）
      let ast: number | undefined
      const astP = zone === 'three' || zone === 'corner3' ? 0.96 : zone === 'mid' ? 0.86 : zone === 'rim' ? 0.86 : 0.72
      if (passer && passer !== shooter && this.rng.chance(astP * (passer.skills.dimer ? 1.1 : 1))) {
        passer.box.ast++
        tot.ast++
        ast = passer.id
      }
      this.addPts(side, pts)
      const dunk = zone === 'rim' && shooter.a.dunk >= 60 && this.rng.chance(clamp((shooter.a.dunk - 55) / 50, 0, 0.75))
      this.ev({ k: 'shot', side, pid: shooter.id, zone, made: true, pts, ast, fouled, dunk, fast: o.fast, clutch: ctx.clutch })
      this.tr({ t, a: 'shot', p: shooter.id, q: ast, zone, made: true })
      if (fouled) return this.freeThrows(side, shooter, 1, t, true)
      this.poss = def
      this.start = 'inbound'
      return { kind: 'end', t: t + 1 }
    }
    this.ev({ k: 'shot', side, pid: shooter.id, zone, made: false, pts, fouled, fast: o.fast })
    this.tr({ t, a: 'shot', p: shooter.id, zone, made: false })
    if (fouled) return this.freeThrows(side, shooter, pts, t, false)
    return this.rebound(side, shooter, t + 1.2, 0)
  }

  private freeThrows(side: Side, shooter: SimPlayer, n: number, t: number, andOne: boolean): { kind: 'end' | 'reset'; t: number; holder?: SimPlayer } {
    void andOne
    const pressure = this.clutchNow(side)
    let lastMade = false
    for (let i = 1; i <= n; i++) {
      const made = this.rng.chance(ftPct(shooter, pressure))
      shooter.box.fta++
      this.totals[side].fta++
      if (made) {
        shooter.box.ftm++
        shooter.box.pts++
        this.totals[side].ftm++
        this.addPts(side, 1)
      }
      this.ev({ k: 'ft', side, pid: shooter.id, made, n: i, of: n })
      this.tr({ t, a: 'ft', p: shooter.id, made })
      lastMade = made
    }
    if (lastMade) {
      this.poss = (1 - side) as Side
      this.start = 'inbound'
      return { kind: 'end', t: t + 0.5 }
    }
    return this.rebound(side, shooter, t + 0.8, 0, true)
  }

  /** リバウンド。defBias は守備側に寄せる分（ブロックのあと）、ft は外れたフリースロー */
  private rebound(side: Side, shooter: SimPlayer, t: number, defBias: number, ft = false): { kind: 'end' | 'reset'; t: number; holder?: SimPlayer } {
    const def = (1 - side) as Side
    const strength = (ps: SimPlayer[], key: 'oreb' | 'dreb') => ps.reduce((s, p) => s + p.a[key] + (p.heightCm - 200) * 0.6 + (p.skills.reboundKing ? 5 : 0) + (p.skills.boxOut && key === 'dreb' ? 4 : 0), 0) / 5
    const edge = (strength(this.court(side), 'oreb') - strength(this.court(def), 'dreb')) / 100
    const base = ft ? TUNE.orebFt : TUNE.oreb
    const pOff = clamp(base + edge * 0.6 - defBias, 0.05, 0.5)
    const offense = this.rng.chance(pOff)
    const rs = offense ? side : def
    const key = offense ? 'oreb' : 'dreb'
    const reb = this.pick(rs, (p) => (Math.max(1, p.a[key] + (p.heightCm - 195) * 0.8 - 20) ** 2) * (p === shooter ? 0.6 : 1) * (p.skills.reboundKing ? 1.3 : 1))
    // チームリバウンド（ラインの外へ出たなど）は選手の記録に付けない
    if (!this.rng.chance(TUNE.teamReb)) {
      reb.box[key]++
      this.totals[rs][key]++
    }
    this.ev({ k: 'reb', side: rs, pid: reb.id, off: offense })
    this.tr({ t, a: 'reb', p: reb.id, off: offense })
    if (!offense) {
      this.poss = def
      this.start = 'live'
      return { kind: 'end', t }
    }
    // オフェンスリバウンド: ゴール下ならそのまま押し込む
    const near = reb.pos === 'C' || reb.pos === 'PF' || reb.heightCm >= 203
    if (t < this.clock - 1 && near && this.rng.chance(TUNE.putback * (reb.skills.putback ? 1.3 : 1))) {
      return this.shoot(side, reb, 'rim', 0.5, t + 0.8, undefined, { putback: true })
    }
    return { kind: 'reset', t: t + 0.5, holder: reb }
  }

  private turnover(side: Side, holder: SimPlayer, t: number, press: boolean, kind?: 'clock'): number {
    const def = (1 - side) as Side
    holder.box.tov++
    this.totals[side].tov++
    const steal = kind !== 'clock' && this.rng.chance(TUNE.stealShare * (press ? 1.15 : 1))
    let stl: SimPlayer | undefined
    if (steal) {
      stl = this.pick(def, (p) => (p.a.steal + (p.skills.thief ? 12 : 0)) ** 2)
      stl.box.stl++
      this.totals[def].stl++
    }
    const charge = !steal && kind !== 'clock' && this.rng.chance(0.12)
    this.ev({ k: 'tov', side, pid: holder.id, stl: stl?.id, kind: kind ?? (steal ? 'steal' : charge ? 'charge' : 'bad') })
    this.tr({ t, a: 'tov', p: holder.id, q: stl?.id })
    if (charge) {
      holder.fouls++
      holder.box.pf++
      this.totals[side].pf++
    }
    this.poss = def
    this.start = steal ? 'steal' : 'inbound'
    return t
  }

  /** シュート中でないファウル。ボーナスならフリースロー 2 本、そうでなければスローインでやり直し */
  private nonShootingFoul(side: Side, holder: SimPlayer, d: SimPlayer, t: number): 'end' | 'continue' {
    const def = (1 - side) as Side
    d.fouls++
    d.box.pf++
    this.totals[def].pf++
    const team = this.teams[def]
    team.periodFouls++
    const bonus = team.periodFouls > this.rules.bonusAt
    this.ev({ k: 'foul', side: def, pid: d.id, on: holder.id, shooting: false, bonus })
    this.tr({ t, a: 'foul', p: holder.id, q: d.id })
    if (bonus) {
      const r = this.freeThrows(side, holder, 2, t, false)
      return r.kind === 'end' ? 'end' : 'continue'
    }
    return 'continue'
  }

  /** ピリオドの終わり（ブザー）。残りが少なければ、ブザービーターを狙う */
  private endOfPeriod(side: Side, holder: SimPlayer, t: number): number {
    if (this.clock >= 1.2 && this.rng.chance(0.75)) {
      this.shoot(side, holder, 'three', 0.05, Math.max(0, this.clock - 0.3), undefined, { late: true })
    }
    return Math.max(t, this.clock)
  }

  // ------------------------------------------------------------------ 時計・体力・交代

  private afterPossession(log: PossLog) {
    const dur = log.dur
    this.clock -= dur
    this.subClock += dur
    // 流れ: 1 分ごとの点差
    this.elapsed += dur
    while (this.elapsed >= (this.flow.length + 1) * 60) this.flow.push(this.teams[0].score - this.teams[1].score)
    for (const s of [0, 1] as Side[]) {
      const t = this.teams[s]
      const pace = s === log.side ? this.paceMul(s) : 1
      t.players.forEach((p, i) => {
        if (t.court.includes(i)) {
          p.box.secs += dur
          const drain = 0.06 * (1.3 - p.a.stamina * 0.006) * (t.tactics.defense === 'press' ? 1.15 : 1) * (TUNE.rulePace[this.setup.rules] / pace)
          p.energy = Math.max(0, p.energy - dur * drain * (p.skills.ironMan ? 0.85 : 1))
        } else {
          p.energy = Math.min(100, p.energy + dur * 0.075)
        }
        if (p.fouls >= this.rules.foulOut && !p.out) {
          p.out = true
          this.subNow = true
        }
      })
    }
    if (this.clock <= 0.05) this.endPeriod()
  }

  private endPeriod() {
    this.ev({ k: 'end', period: this.period })
    const regulation = this.period >= this.rules.periods
    const tied = this.teams[0].score === this.teams[1].score
    if (regulation && !tied) {
      this.over = true
      return
    }
    // 休み: ハーフタイムは長い
    const half = this.rules.periods === 2 ? this.period === 1 : this.period === 2
    for (const t of this.teams) for (const p of t.players) p.energy = Math.min(100, p.energy + (half ? 30 : 10))
    this.period++
    if (this.period > this.rules.periods) this.ot++
    this.clock = (this.period > this.rules.periods ? this.rules.otMin : this.rules.periodMin) * 60
    for (const t of this.teams) t.periodFouls = 0
    this.subNow = true
    // 攻めの順番: 2・3 クォーターはジャンプボールに負けたほう、4 は勝ったほう。延長はジャンプボール
    if (this.period > this.rules.periods) this.poss = this.rng.chance(0.5) ? 0 : 1
    else if (this.rules.periods === 2) this.poss = (1 - this.jumpWinner) as Side
    else this.poss = this.period === 4 ? this.jumpWinner : ((1 - this.jumpWinner) as Side)
    this.start = 'period'
    this.ev({ k: 'period', period: this.period })
  }

  private runSubs(side: Side) {
    const t = this.teams[side]
    if (t.manual) return this.forcedSubs(side)
    const subs = autoSubs(t, this.order[side], {
      period: this.period,
      periods: this.rules.periods,
      clock: this.clock,
      diff: t.score - this.teams[1 - side].score,
      foulOut: this.rules.foulOut,
      foreignLimit: !!this.setup.foreignLimit,
    })
    for (const [o, i] of subs) this.ev({ k: 'sub', side, out: t.players[o].id, in: t.players[i].id })
    if (subs.length) this.dirty = true
  }

  /** 自分で交代するチーム: 退場・ケガの選手だけは、序列の上の控えと入れ替える */
  private forcedSubs(side: Side) {
    const t = this.teams[side]
    for (const out of [...t.court]) {
      const p = t.players[out]
      if (!p.out && p.fouls < this.rules.foulOut) continue
      const cand = this.order[side].find((i) => !t.court.includes(i) && !t.players[i].out && t.players[i].fouls < this.rules.foulOut && foreignOk(t, t.court, i, !!this.setup.foreignLimit, out))
      if (cand === undefined) continue
      t.court[t.court.indexOf(out)] = cand
      this.ev({ k: 'sub', side, out: p.id, in: t.players[cand].id })
      this.dirty = true
    }
  }

  /** 頼まれたタイムアウトと交代（デッドボールのとき） */
  private applyRequests() {
    for (const side of [0, 1] as Side[]) {
      const t = this.teams[side]
      if (this.pendingTimeout[side] && t.timeouts > 0) {
        t.timeouts--
        this.run = []
        for (const i of t.court) t.players[i].energy = Math.min(100, t.players[i].energy + 4)
        this.ev({ k: 'timeout', side })
      }
      this.pendingTimeout[side] = false
      for (const [o, i] of this.pendingSubs[side]) {
        if (!t.court.includes(o) || t.court.includes(i) || t.players[i].out || t.players[i].fouls >= this.rules.foulOut) continue
        if (!foreignOk(t, t.court, i, !!this.setup.foreignLimit, o)) continue
        t.court[t.court.indexOf(o)] = i
        this.ev({ k: 'sub', side, out: t.players[o].id, in: t.players[i].id })
        this.dirty = true
      }
      this.pendingSubs[side] = []
    }
  }

  // ---------------------------------------------------------------- 観戦の操作（クラブ経営）

  /** タイムアウトを取る（次のデッドボールで）。残りがなければ false */
  callTimeout(side: Side): boolean {
    if (this.teams[side].timeouts <= 0 || this.pendingTimeout[side]) return false
    this.pendingTimeout[side] = true
    return true
  }

  /** 交代を頼む（次のデッドボールで）。外国籍の枠・退場は、そのときに確かめる */
  requestSub(side: Side, outId: number, inId: number): boolean {
    const t = this.teams[side]
    const o = t.players.findIndex((p) => p.id === outId)
    const i = t.players.findIndex((p) => p.id === inId)
    if (o < 0 || i < 0 || !t.court.includes(o) || t.court.includes(i) || t.players[i].out) return false
    this.pendingSubs[side] = this.pendingSubs[side].filter(([a, b]) => a !== o && b !== i)
    this.pendingSubs[side].push([o, i])
    return true
  }

  /** 頼んでいるタイムアウトと交代（画面に出す） */
  requests(side: Side): { timeout: boolean; subs: { out: number; in: number }[] } {
    const t = this.teams[side]
    return { timeout: this.pendingTimeout[side], subs: this.pendingSubs[side].map(([o, i]) => ({ out: t.players[o].id, in: t.players[i].id })) }
  }

  /** 作戦を変える（次のポゼッションから） */
  setTactics(side: Side, patch: Partial<SimTeam['tactics']>) {
    Object.assign(this.teams[side].tactics, patch)
    this.dirty = true
  }

  /** 交代を AI に任せるか（false なら自分で。退場とケガだけは自動） */
  setAutoSubs(side: Side, auto: boolean) {
    this.teams[side].manual = !auto
  }

  /** AI のタイムアウト: 相手に 8 点以上の連続得点を許したとき */
  private aiTimeout(side: Side) {
    const t = this.teams[side]
    if (t.manual || t.timeouts <= 0 || this.run.length < 3) return
    let against = 0
    for (let i = this.run.length - 1; i >= 0; i--) {
      const v = side === 0 ? this.run[i] : -this.run[i]
      if (v > 0) break
      against -= v
    }
    if (against >= 8) {
      t.timeouts--
      this.run = []
      for (const i of t.court) t.players[i].energy = Math.min(100, t.players[i].energy + 4)
      this.ev({ k: 'timeout', side })
    }
  }
}

/** 結果だけ（FastSim）: 最後まで回して成績を返す */
export function simulateMatch(setup: MatchSetup): MatchSummary {
  return new MatchEngine(setup).simulate()
}
