/**
 * クラブ経営のおすすめ: 序列（先発の 5 人と控えの順）と作戦（ペース・攻めの重心・セット・守り・出場の人数）。
 *   序列: ケガの選手を外し、総合値に調子と疲れを少し足した「今の力」で、ポジションの並び（PG〜C）と
 *         国内リーグの外国籍（コートに 3 人まで。アジア枠は数えない）を考えて先発の 5 人を選ぶ。控えはガードとビッグが必ず入るように
 *   作戦: 自分の主力 8 人の得意（3P か中か・司令塔・ポスト・エース）と、次の相手（戦力・攻めの得意）から選び、理由を添える
 *   おまかせ: club.autoDepth（序列。手で動かすまで既定でおまかせ）・club.autoTactics（作戦。試合ごとに相手を見て選ぶ。fixtureSetup で）
 * 乱数は使わない（同じ状態なら同じおすすめ）。
 */
import { POSITIONS, type Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { Tactics, Team } from '../models/league'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'
import { ON_COURT_FOREIGN } from '../match/rotation'

const ASIA = new Set(['PH', 'KR', 'CN'])
const isForeign = (p: Player) => p.nation !== 'JP' && !ASIA.has(p.nation)
const posIdx = (p: Position) => POSITIONS.indexOf(p)
/** ポジションがずれたときの減点（1 つずれ・2 つ・3 つ以上） */
const POS_PENALTY = [0, 3, 8, 15, 22]

/** 今の力: 総合値 ＋ 調子 − 疲れ */
export function formScore(p: Player): number {
  return ovr(p) + (p.condition - 50) * 0.05 - p.fatigue * 0.04
}

const domestic = (team: Team) => team.league === 'JBL1' || team.league === 'JBL2' || team.league === 'JBL3'

/** その選手を PG〜C のそれぞれに置いたときの減点（2 つ目のポジションもあれば、近いほう） */
function slotPenalty(p: Player): number[] {
  return POSITIONS.map((_, i) => {
    const d1 = Math.abs(posIdx(p.pos) - i)
    const d2 = p.pos2 ? Math.abs(posIdx(p.pos2) - i) : 9
    return POS_PENALTY[Math.min(4, d1, d2)]
  })
}

/** 5 人を 5 つのポジションに当てる並べ方（120 通り） */
const PERMS: number[][] = (() => {
  const out: number[][] = []
  const go = (rest: number[], cur: number[]) => (rest.length ? rest.forEach((x, i) => go([...rest.slice(0, i), ...rest.slice(i + 1)], [...cur, x])) : out.push(cur))
  go([0, 1, 2, 3, 4], [])
  return out
})()

/** 先発の 5 人の点（今の力の合計 − ポジションのずれのいちばん小さい当て方） */
function lineupScore(ps: Player[], score: Map<number, number>, pen: Map<number, number[]>): number {
  let best = Infinity
  for (const perm of PERMS) {
    let v = 0
    for (let i = 0; i < 5; i++) v += pen.get(ps[i].id)![perm[i]]
    if (v < best) best = v
  }
  return ps.reduce((s, p) => s + score.get(p.id)!, 0) - best
}

/** おすすめの序列（選手の id。ケガの選手はいちばん下） */
export function recommendDepth(state: GameState, team: Team = state.teams[state.club!.teamId]): number[] {
  const all = team.roster.map((id) => state.players[id])
  const fit = all.filter((p) => !p.injury)
  const hurt = all.filter((p) => p.injury).sort((a, b) => ovr(b) - ovr(a))
  const score = new Map(fit.map((p) => [p.id, formScore(p)]))
  const byScore = [...fit].sort((a, b) => score.get(b.id)! - score.get(a.id)!)
  // 候補は今の力の上位 11 人まで（組み合わせを全部見る）
  const pool = byScore.slice(0, 11)
  const pen = new Map(pool.map((p) => [p.id, slotPenalty(p)]))
  const limit = domestic(team) ? ON_COURT_FOREIGN : 5
  let best: Player[] = pool.slice(0, 5)
  let bestV = -Infinity
  const n = pool.length
  if (n >= 5) {
    for (let a = 0; a < n; a++)
      for (let b = a + 1; b < n; b++)
        for (let c = b + 1; c < n; c++)
          for (let d = c + 1; d < n; d++)
            for (let e = d + 1; e < n; e++) {
              const five = [pool[a], pool[b], pool[c], pool[d], pool[e]]
              if (five.filter(isForeign).length > limit) continue
              const v = lineupScore(five, score, pen)
              if (v > bestV) {
                bestV = v
                best = five
              }
            }
  }
  // 出番を約束した選手（クラブの気持ちの約束）は先発に入れる（いちばん力の低い先発と入れ替え）
  const promised = state.club && team.id === state.club.teamId ? Object.keys(state.club.promises ?? {}).map(Number) : []
  for (const id of promised) {
    const p = fit.find((x) => x.id === id)
    if (!p || best.includes(p)) continue
    const out = best.filter((x) => !promised.includes(x.id)).sort((a, b) => score.get(a.id)! - score.get(b.id)!)[0]
    if (out) best = best.map((x) => (x === out ? p : x))
  }
  // 先発は PG → C の順に並べる
  const starters = [...best].sort((x, y) => posIdx(x.pos) - posIdx(y.pos) || score.get(y.id)! - score.get(x.id)!)
  const bench = byScore.filter((p) => !best.includes(p))
  // 控えの上の 3 人に、ガードとビッグが少なくとも 1 人ずつ
  const guard = (p: Player) => p.pos === 'PG' || p.pos === 'SG'
  const big = (p: Player) => p.pos === 'PF' || p.pos === 'C'
  for (const want of [guard, big]) {
    if (bench.slice(0, 3).some(want)) continue
    const i = bench.findIndex(want)
    if (i > 2) bench.splice(2, 0, bench.splice(i, 1)[0])
  }
  return [...starters, ...bench, ...hurt].map((p) => p.id)
}

// ---------------------------------------------------------------- 作戦

export interface TacticsAdvice {
  tactics: Tactics
  /** 作戦の項目ごとの理由 */
  reasons: Record<keyof Tactics, string>
  /** 相手（次の試合） */
  opp?: number
}

const avg = (ps: Player[], f: (p: Player) => number) => (ps.length ? ps.reduce((s, p) => s + f(p), 0) / ps.length : 0)
const insideOf = (p: Player) => (p.attr.close + p.attr.layup + p.attr.dunk + p.attr.post) / 4

/** 自分のクラブの次の試合の相手（今週か、それより先でいちばん近い試合） */
export function nextOpponent(state: GameState): number | undefined {
  const id = state.club!.teamId
  const f = state.fixtures.filter((x) => !x.result && (x.home === id || x.away === id) && x.week >= state.week).sort((a, b) => a.week - b.week || a.day - b.day)[0]
  return f ? (f.home === id ? f.away : f.home) : undefined
}

/** チームの主力 8 人（ケガを除いて、今の力の順） */
function core(state: GameState, team: Team): Player[] {
  return team.roster
    .map((id) => state.players[id])
    .filter((p) => !p.injury)
    .sort((a, b) => formScore(b) - formScore(a))
    .slice(0, 8)
}

/** おすすめの作戦（oppId を渡すとその相手に合わせる） */
export function recommendTactics(state: GameState, oppId: number | undefined = nextOpponent(state), team: Team = state.teams[state.club!.teamId]): TacticsAdvice {
  const mine = core(state, team)
  const top5 = mine.slice(0, 5)
  const bench = mine.slice(5, 9)
  const power = avg(mine, ovr)
  const opp = oppId !== undefined ? state.teams[oppId] : undefined
  const theirs = opp ? core(state, opp) : []
  const oppPower = opp ? avg(theirs, ovr) : undefined
  const r = {} as Record<keyof Tactics, string>

  // 攻めの重心: 3P と中のどちらが得意か
  const out3 = avg(mine, (p) => p.attr.three)
  const inIn = avg(mine, insideOf)
  let focus: Tactics['focus'] = 'balanced'
  if (out3 - inIn >= 4) {
    focus = 'outside'
    r.focus = `3P が得意な選手が多い（主力の 3P ${Math.round(out3)}・中 ${Math.round(inIn)}）`
  } else if (inIn - out3 >= 4) {
    focus = 'inside'
    r.focus = `ゴール下が得意な選手が多い（主力の中 ${Math.round(inIn)}・3P ${Math.round(out3)}）`
  } else r.focus = `外と中の力が近い（3P ${Math.round(out3)}・中 ${Math.round(inIn)}）`

  // 主なセット: 司令塔・ポスト・エース・パスの回り
  const guards = mine.filter((p) => p.pos === 'PG' || p.pos === 'SG')
  const bigs = mine.filter((p) => p.pos === 'PF' || p.pos === 'C')
  const pg = [...guards].sort((a, b) => b.attr.handle + b.attr.pass - (a.attr.handle + a.attr.pass))[0]
  const postMan = [...bigs].sort((a, b) => b.attr.post - a.attr.post)[0]
  const ace = top5[0]
  const gap = ace && top5[1] ? ovr(ace) - ovr(top5[1]) : 0
  const cand: [Tactics['set'], number, string][] = [
    ['pnr', pg && bigs.length ? (pg.attr.handle + pg.attr.pass) / 2 : 0, pg ? `${pg.short}のドリブルとパスでスクリーンを使える（${Math.round((pg.attr.handle + pg.attr.pass) / 2)}）` : ''],
    ['post', postMan ? postMan.attr.post - 2 : 0, postMan ? `${postMan.short}のポストプレーが強い（${Math.round(postMan.attr.post)}）` : ''],
    ['iso', ace && gap >= 6 && ace.pos !== 'C' ? ovr(ace) + 2 : 0, ace ? `${ace.short}が飛び抜けたエース（2 番手より ${gap} 上）` : ''],
    ['motion', avg(top5, (p) => (p.attr.pass + p.attr.vision + p.attr.iq) / 3) + 4, `パスと判断のいい選手がそろっている（${Math.round(avg(top5, (p) => (p.attr.pass + p.attr.vision + p.attr.iq) / 3))}）`],
  ]
  const [set, , setWhy] = cand.sort((a, b) => b[1] - a[1])[0]
  r.set = setWhy

  // ペース: 相手との力の差と、走れるか
  const speed = avg(mine, (p) => (p.attr.speed + p.attr.stamina) / 2)
  let pace: Tactics['pace'] = 'normal'
  if (oppPower !== undefined && oppPower - power >= 2.5) {
    pace = 'slow'
    r.pace = `相手のほうが強い（主力 ${oppPower.toFixed(1)} 対 ${power.toFixed(1)}）。攻めの回数を減らすと、番狂わせが起きやすい`
  } else if (speed >= 66 && (oppPower === undefined || power - oppPower >= 1)) {
    pace = 'fast'
    r.pace = `走れる選手が多い（スピードとスタミナ ${Math.round(speed)}）${oppPower !== undefined ? '。力でも上回っている' : ''}`
  } else if (oppPower !== undefined && power - oppPower >= 3) {
    pace = 'fast'
    r.pace = `力で上回っている（主力 ${power.toFixed(1)} 対 ${oppPower.toFixed(1)}）。攻めの回数を増やすと、力の差が出やすい`
  } else r.pace = oppPower !== undefined ? `力が近い（主力 ${power.toFixed(1)} 対 ${oppPower.toFixed(1)}）` : 'ふだんのペースで'

  // 守り: 相手の攻めの得意と、自分の守りの得意
  const steal = avg(mine, (p) => p.attr.steal)
  const stamina = avg(mine, (p) => p.attr.stamina)
  const perD = avg(top5, (p) => p.attr.perD)
  const intD = avg(top5, (p) => (p.attr.intD + p.attr.block) / 2)
  const oppOut = theirs.length ? avg(theirs, (p) => p.attr.three) : undefined
  const oppIn = theirs.length ? avg(theirs, insideOf) : undefined
  let defense: Tactics['defense'] = 'man'
  if (steal >= 64 && stamina >= 70) {
    defense = 'press'
    r.defense = `奪うのがうまく、体力もある（スティール ${Math.round(steal)}・スタミナ ${Math.round(stamina)}）`
  } else if (oppIn !== undefined && oppOut !== undefined && oppIn - oppOut >= 5) {
    defense = 'zone23'
    r.defense = `相手はゴール下が得意（中 ${Math.round(oppIn)}・3P ${Math.round(oppOut)}）。中を固める`
  } else if (oppIn !== undefined && oppOut !== undefined && oppOut - oppIn >= 4) {
    defense = 'man'
    r.defense = `相手は 3P が得意（3P ${Math.round(oppOut)}）。ゾーンは外が空くので、1 人ずつ守る`
  } else if (intD - perD >= 6) {
    defense = 'zone23'
    r.defense = `外の守りより中の守りが得意（中 ${Math.round(intD)}・外 ${Math.round(perD)}）`
  } else r.defense = '相手に大きな得意がないので、ふつうのマンツーマンで'

  // 出場の人数: 控えの力と疲れ
  const gapBench = bench.length ? avg(top5, ovr) - avg(bench, ovr) : 99
  const tired = avg(top5, (p) => p.fatigue)
  let rotation: Tactics['rotation'] = 'normal'
  if (tired >= 35 || pace === 'fast' || defense === 'press' || gapBench <= 4) {
    rotation = 'deep'
    r.rotation = tired >= 35 ? `先発の疲れがたまっている（${Math.round(tired)}）` : pace === 'fast' || defense === 'press' ? '速いペースやプレスは体力を使うので、控えも使う' : `控えの力が先発に近い（差 ${gapBench.toFixed(1)}）`
  } else if (gapBench >= 9) {
    rotation = 'tight'
    r.rotation = `先発と控えの力の差が大きい（差 ${gapBench.toFixed(1)}）。主力を長く使う`
  } else r.rotation = `控えとの差がほどほど（差 ${gapBench.toFixed(1)}）`

  return { tactics: { pace, focus, set, defense, rotation }, reasons: r, opp: oppId }
}
