/** 試合の結果を世界に入れる: 順位表・成績（レギュラーとプレーオフは別）・疲れ・ケガ・ニュース。 */
import type { Rng } from '../core/prng'
import type { GameState } from '../models/game'
import type { Fixture } from '../models/league'
import { emptyStats, type Stats } from '../models/player'
import type { MatchSummary } from '../match/types'
import { injuryName, rollInjury } from '../player/growth'
import { recordResult } from './standings'
import { clubInjuryMul, isClubPlayer } from '../club/effects'

export function addBox(s: Stats, b: MatchSummary['box'][number]) {
  if (b.secs <= 0) return
  s.gp++
  if (b.started) s.gs++
  s.min += b.secs / 60
  s.pts += b.pts
  s.fgm += b.fgm
  s.fga += b.fga
  s.tpm += b.tpm
  s.tpa += b.tpa
  s.ftm += b.ftm
  s.fta += b.fta
  s.oreb += b.oreb
  s.dreb += b.dreb
  s.ast += b.ast
  s.stl += b.stl
  s.blk += b.blk
  s.tov += b.tov
  s.pf += b.pf
  s.pm += b.pm
}

/** 主人公の 1 試合の最高（実績の判定） */
function recordHighs(state: GameState, teamId: number, b: MatchSummary['box'][number]) {
  const h = (state.career!.highs ??= { pts: 0, nbaPts: 0, reb: 0, ast: 0, tripleDoubles: 0 })
  const reb = b.oreb + b.dreb
  h.pts = Math.max(h.pts, b.pts)
  h.reb = Math.max(h.reb, reb)
  h.ast = Math.max(h.ast, b.ast)
  if (state.teams[teamId]?.league === 'NBA') h.nbaPts = Math.max(h.nbaPts, b.pts)
  if ([b.pts, reb, b.ast, b.stl, b.blk].filter((x) => x >= 10).length >= 3) h.tripleDoubles++
}

export function applyResult(state: GameState, f: Fixture, sum: MatchSummary, rng: Rng) {
  f.result = { hs: sum.score[0], as: sum.score[1], ot: sum.ot }
  if (f.kind === 'regular') recordResult(state, f.league, f.home, f.away, f.result)
  for (const [idStr, b] of Object.entries(sum.box)) {
    const p = state.players[Number(idStr)]
    if (!p) continue
    // 全日本選手権の成績は数えない（疲れとケガはある）
    const target = f.kind === 'regular' ? p.stats : f.kind === 'cup' ? null : (p.poStats ??= emptyStats())
    if (target) addBox(target, b)
    if (p.isPlayer && state.career && b.secs > 0) recordHighs(state, p.teamId, b)
    const min = b.secs / 60
    p.fatigue = Math.min(100, p.fatigue + min * 0.55)
    const weeks = rollInjury(p, min, rng, isClubPlayer(state, p) ? clubInjuryMul(state) : 1)
    if (weeks > 0 && !p.injury) {
      p.injury = { name: injuryName(weeks, rng), weeks }
      if (weeks >= 6 && (state.teams[p.teamId]?.league === 'NBA' || p.castId || p.isPlayer)) state.news.push({ season: state.season, week: state.week, text: `${p.name}（${state.teams[p.teamId]?.short ?? ''}）が${p.injury.name}で全治 ${weeks} 週` })
    }
  }
}
