/**
 * キャリアのランク（ホームの札・キャリアの画面のはしご）。
 *   E 国内 3 部 → D 国内 2 部 → C 国内 1 部・大学・育成リーグ → B NBA（ベンチ・2way）→ A NBA のローテーション・スタメン → S オールスター級
 */
import type { GameState } from '../models/game'
import { ovr } from '../player/overall'

export type CareerRank = 'E' | 'D' | 'C' | 'B' | 'A' | 'S'

export const RANK_DEFS: Record<CareerRank, { label: string; desc: string; color: string }> = {
  E: { label: '国内 3 部', desc: 'プロの入り口', color: '#7a8698' },
  D: { label: '国内 2 部', desc: '上を目指す', color: '#a8b4c4' },
  C: { label: '国内 1 部・大学・育成', desc: 'NBA が見えてくる', color: '#7dd3fc' },
  B: { label: 'NBA の控え', desc: '夢の舞台に立つ', color: '#3ddc84' },
  A: { label: 'NBA の主力', desc: 'ローテーション・スタメン', color: '#ff9d4d' },
  S: { label: 'オールスター級', desc: 'リーグの顔', color: '#ffd34d' },
}

export const RANKS: CareerRank[] = ['E', 'D', 'C', 'B', 'A', 'S']

export function careerRank(state: GameState): CareerRank {
  const c = state.career
  if (!c) return 'E'
  const p = state.players[c.playerId]
  const lg = p.teamId >= 0 ? state.teams[p.teamId].league : 'FA'
  if (lg === 'NBA') {
    const allStar = state.awards.some((a) => a.playerId === p.id && (a.award === 'オールスター' || a.award.startsWith('オール NBA') || a.award === 'MVP') && a.season >= state.season - 1)
    if (allStar || ovr(p) >= 86) return 'S'
    const s = p.stats
    const mpg = s.gp ? s.min / s.gp : 0
    return mpg >= 20 || (s.gp === 0 && c.trust >= 60) ? 'A' : 'B'
  }
  if (lg === 'JBL3') return 'E'
  if (lg === 'JBL2') return 'D'
  if (lg === 'FA') return c.path === 'college' ? 'C' : 'D'
  return 'C'
}
