/**
 * ローテーション（AI の監督）: 先発の 5 人、交代（体力・ファウル・大差・終盤）。
 * 交代はデッドボール（得点・ファウル・タイムアウト・ピリオドのはじめ）でだけ行う（engine.ts が呼ぶ）。
 * 序列（総合値の順）が上の選手ほど体力が減っても我慢して出し続けるので、主力は 32〜36 分、控えは 10〜20 分ほどになる。
 */
import type { Position } from '../data/positions'
import type { SimPlayer, SimTeam } from './types'

const POS_ORDER: Position[] = ['PG', 'SG', 'SF', 'PF', 'C']

/** ポジションの近さ（0 が同じ。交代の相手を選ぶとき） */
function posGap(a: Position, b: Position): number {
  return Math.abs(POS_ORDER.indexOf(a) - POS_ORDER.indexOf(b))
}

/** 出場の人数（作戦）: 8・9・10 人 */
export function rotationSize(t: SimTeam): number {
  return t.tactics.rotation === 'tight' ? 8 : t.tactics.rotation === 'deep' ? 10 : 9
}

/** 序列（監督が決めた順。なければ総合値の順に並べた players の添字） */
export function depthOrder(t: SimTeam): number[] {
  const key = (i: number) => t.players[i].depth ?? 1000 - t.players[i].ovr
  return t.players.map((_, i) => i).sort((a, b) => key(a) - key(b))
}

/** 試合のベンチに入る人数（NBA 13・ほか 12）。登録がこれより多くても、試合に出られるのは序列の上からこの人数（ケガの選手を除く） */
export const gameDaySize = (league: string) => (league === 'NBA' ? 13 : 12)

/** 国内リーグのコートに同時に立てる外国籍（アジア枠は数えない）。2026-11-14 にユーザーの希望で 2 → 3 人に（登録の上限 JBL_FOREIGN_MAX と同じ） */
export const ON_COURT_FOREIGN = 3

/** 外国籍の枠（国内リーグ: コートに同時に ON_COURT_FOREIGN 人まで） */
export function foreignOk(t: SimTeam, court: number[], cand: number, limit: boolean, replacing = -1): boolean {
  if (!limit || !t.players[cand].foreignSlot) return true
  const n = court.filter((i) => i !== replacing && t.players[i].foreignSlot).length
  return n < ON_COURT_FOREIGN
}

/**
 * 先発の 5 人: 序列の上から、ポジションが偏らないように（ガード・フォワード・センターのどれかが欠けないように）選ぶ
 */
export function pickStarters(t: SimTeam, foreignLimit: boolean): number[] {
  const order = depthOrder(t).filter((i) => !t.players[i].out)
  const court: number[] = []
  const has = (pred: (p: SimPlayer) => boolean) => court.some((i) => pred(t.players[i]))
  const guard = (p: SimPlayer) => p.pos === 'PG' || p.pos === 'SG'
  const big = (p: SimPlayer) => p.pos === 'C' || p.pos === 'PF'
  for (const i of order) {
    if (court.length >= 5) break
    if (!foreignOk(t, court, i, foreignLimit)) continue
    const p = t.players[i]
    // 残りの枠で、ガードとビッグを 1 人ずつは確保する
    const left = 5 - court.length
    const needGuard = !has(guard) && !guard(p)
    const needBig = !has(big) && !big(p)
    if (left === 1 && (needGuard || needBig)) continue
    if (left === 2 && needGuard && needBig) continue
    court.push(i)
  }
  for (const i of order) if (court.length < 5 && !court.includes(i) && foreignOk(t, court, i, foreignLimit)) court.push(i)
  for (const i of order) if (court.length < 5 && !court.includes(i)) court.push(i)
  return court
}

export interface SubContext {
  period: number
  periods: number
  /** ピリオドの残り秒 */
  clock: number
  /** 自分のチームから見た点差 */
  diff: number
  foulOut: number
  foreignLimit: boolean
}

/** この選手を下げたい度合い（0 は下げない）。序列が上の選手ほど我慢する */
function benchUrge(t: SimTeam, idx: number, rank: number, ctx: SubContext): number {
  const p = t.players[idx]
  if (p.out) return 100
  const late = ctx.period >= ctx.periods && ctx.clock < 300
  const close = Math.abs(ctx.diff) <= 10
  // ファウルトラブル: 1Q 2・2Q 3・3Q 4・4Q（退場の 1 つ手前）で下げる。大学は前半 2・後半（手前）。終盤の接戦と延長は我慢
  const caps = ctx.periods === 2 ? [2, ctx.foulOut - 1] : [2, 3, 4, ctx.foulOut - 1]
  const foulCap = ctx.period <= ctx.periods ? caps[ctx.period - 1] : ctx.foulOut
  if (p.fouls >= foulCap && !(late && close)) return 50
  const size = rotationSize(t)
  const threshold = rank < 5 ? 50 + rank * 2 : rank < size ? 70 + (rank - 5) * 3 : 84
  // 終盤の接戦は主力を出し続ける
  if (late && close && rank < 5) return p.energy < 30 ? 10 : 0
  return p.energy < threshold ? threshold - p.energy : 0
}

/** 交代（デッドボールのとき）。交代した [out, in] の組を返す */
export function autoSubs(t: SimTeam, order: number[], ctx: SubContext): [number, number][] {
  const rank = new Map(order.map((idx, r) => [idx, r]))
  const size = rotationSize(t)
  const subs: [number, number][] = []
  const garbage = ctx.period >= ctx.periods && ctx.clock < 360 && Math.abs(ctx.diff) >= 20
  const late = ctx.period >= ctx.periods && ctx.clock < 300 && Math.abs(ctx.diff) <= 10
  for (const out of [...t.court]) {
    const r = rank.get(out)!
    let urge = benchUrge(t, out, r, ctx)
    // 大差の終盤: 主力を休ませる
    if (garbage && r < 6) urge = Math.max(urge, 20)
    if (urge <= 0) continue
    const outP = t.players[out]
    // 代わり: ベンチで休めていて、ポジションが近く、序列が上の選手
    let best = -1
    let bestScore = -Infinity
    for (const cand of order) {
      if (t.court.includes(cand)) continue
      const c = t.players[cand]
      if (c.out || c.fouls >= ctx.foulOut) continue
      const cr = rank.get(cand)!
      if (!garbage && cr >= size && !(late && cr < 5)) continue
      if (c.energy < (garbage ? 30 : cr < 5 ? 74 : 82)) continue
      if (!foreignOk(t, t.court, cand, ctx.foreignLimit, out)) continue
      const score = (garbage ? cr : -cr) * 3 - posGap(c.pos, outP.pos) * 4 + c.energy * 0.05
      if (score > bestScore) {
        bestScore = score
        best = cand
      }
    }
    if (best >= 0) {
      t.court[t.court.indexOf(out)] = best
      subs.push([out, best])
    }
  }
  return subs
}
