/**
 * 東アジアのクラブ選手権（架空）: 前のシーズンの JBL1 の優勝クラブと、レギュラーシーズンの上位のクラブ（優勝と別）＋外国のクラブ 6
 *   出場権: 第 48 週のはじめ（国内のチャンピオンシップのあと）に決まる。次のシーズンに 1 部にいなければ、1 部の戦力の上位から
 *   組み合わせは第 16 週（グループの前の週）に決まる → グループ（4 クラブ × 2。日本のクラブは別の組）: 第 17・23・28 週（水）に総当たり
 *   → ファイナル 4（中立地）: 第 34 週に準決勝（A1-B2・B1-A2）、第 35 週に決勝（1 週に 1 試合なので、どれも観戦できる）
 *   外国のクラブ（韓国 2・中国 2・フィリピン 1・台湾 1）はその場の仮の選手（世界の選手には足さない）
 *   観戦: クラブ経営の自分のクラブの試合は、ホームで観戦できる（eaccFixtures・eaccSetup。観戦した結果は advanceWeek の played の EACC_PLAYED で渡す）
 *   成績は数えない（疲れはある）。乱数は大会と試合ごとのシード
 */
import { createRng, hashSeed, type Rng } from '../core/prng'
import { generateName, type Nation } from '../data/nations'
import { POSITIONS } from '../data/positions'
import { pickStyle, rollBody, shapeAttrs } from '../gen/playerGen'
import type { GameState } from '../models/game'
import { DEFAULT_TACTICS } from '../models/league'
import { teamInput } from '../match/setup'
import { simulateMatch } from '../match/engine'
import type { PlayerInput, TeamInput, MatchSetup, MatchSummary } from '../match/types'
import { teamPower } from '../query'
import { sortedStandings } from './standings'

export const EACC_NAME = '東アジアのクラブ選手権'
export const EACC_GROUP_WEEKS = [17, 23, 28] as const
/** 準決勝の週（ファイナル 4 のはじめ） */
export const EACC_FINAL_WEEK = 34
/** 決勝の週 */
export const EACC_TITLE_WEEK = 35
/** 組み合わせが決まる週 */
export const EACC_DRAW_WEEK = EACC_GROUP_WEEKS[0] - 1
/** 観戦した自分のクラブの試合の結果を advanceWeek に渡すときの鍵（日程の試合の id とは重ならない） */
export const EACC_PLAYED = -1
export const EACC_QUAL_WEEK = 48

interface ForeignDef {
  name: string
  abbr: string
  nation: Nation
  /** 戦力（主力 8 人の平均の目安）の幅 */
  power: [number, number]
  color: string
}

/** 外国のクラブ（都市は実在・愛称は架空） */
const FOREIGN: Record<'KR' | 'CN' | 'PH' | 'TW', ForeignDef[]> = {
  KR: [
    { name: 'ソウル・サンダーバーズ', abbr: 'SEO', nation: 'KR', power: [65, 69], color: '#1d4ed8' },
    { name: '釜山・ウェーブス', abbr: 'BUS', nation: 'KR', power: [64, 68], color: '#0891b2' },
    { name: '仁川・スカイラインズ', abbr: 'ICN', nation: 'KR', power: [63, 67], color: '#7c3aed' },
  ],
  CN: [
    { name: '北京・ガーディアンズ', abbr: 'BJG', nation: 'CN', power: [67, 72], color: '#b91c1c' },
    { name: '上海・ネオンズ', abbr: 'SHN', nation: 'CN', power: [66, 71], color: '#db2777' },
    { name: '広州・フェニックス', abbr: 'GZP', nation: 'CN', power: [65, 70], color: '#ea580c' },
  ],
  PH: [
    { name: 'マニラ・ストーム', abbr: 'MNL', nation: 'PH', power: [63, 67], color: '#0f766e' },
    { name: 'セブ・マリナーズ', abbr: 'CEB', nation: 'PH', power: [62, 66], color: '#0369a1' },
  ],
  // 台湾の選手の名前は中国の名前の表を使う
  TW: [
    { name: '台北・ライトニング', abbr: 'TPE', nation: 'CN', power: [62, 66], color: '#ca8a04' },
    { name: '台中・ジャガーズ', abbr: 'TXG', nation: 'CN', power: [61, 65], color: '#4d7c0f' },
  ],
}

export interface EaccForeign {
  name: string
  abbr: string
  nation: Nation
  power: number
  color: string
}

/** 出場する側: 世界のチーム（team）か外国のクラブ（foreign の番号） */
export interface EaccSide {
  team?: number
  foreign?: number
}

export interface EaccGame {
  stage: 'A' | 'B' | 'SF' | 'F'
  week: number
  home: EaccSide
  away: EaccSide
  hs: number
  as: number
}

export interface EaccState {
  season: number
  foreign: EaccForeign[]
  groups: { A: EaccSide[]; B: EaccSide[] }
  games: EaccGame[]
  champion?: EaccSide
}

export interface EaccRecord {
  season: number
  champion: string
  /** 日本のクラブが優勝したときの世界のチーム */
  team?: number
}

const sameSide = (a: EaccSide, b: EaccSide) => a.team === b.team && a.foreign === b.foreign

export function sideName(state: GameState, e: EaccState, s: EaccSide): string {
  return s.team !== undefined ? state.teams[s.team].name : e.foreign[s.foreign!].name
}

/** 外国のクラブの選手（仮。毎回同じシードで同じ顔ぶれ） */
function foreignTeam(state: GameState, e: EaccState, idx: number): TeamInput {
  const f = e.foreign[idx]
  const rng = createRng(hashSeed(state.seed, e.season, 0xeacc, idx))
  const players: PlayerInput[] = []
  for (let i = 0; i < 10; i++) {
    const pos = POSITIONS[i % 5]
    const body = rollBody(pos, f.nation, rng)
    const style = pickStyle(pos, rng)
    const o = Math.round(f.power + 4 - i * 1.2 + rng.normal(0, 2))
    const name = generateName(f.nation, rng)
    players.push({ id: -(200000 + idx * 100 + i), name: name.full, short: name.short, jersey: 3 + i * 2, pos, style, nation: f.nation, ...body, skills: {}, ovr: o, attr: shapeAttrs(o, pos, style, body, rng), foreignSlot: false })
  }
  return { teamId: -1, name: f.name, short: f.name.split('・')[0], abbr: f.abbr, colors: { primary: f.color, secondary: '#ffffff' }, tactics: { ...DEFAULT_TACTICS }, players }
}

const inputOf = (state: GameState, e: EaccState, s: EaccSide): TeamInput => (s.team !== undefined ? teamInput(state, state.teams[s.team]) : foreignTeam(state, e, s.foreign!))

/** 今週の大会の試合（組み合わせだけ。まだ行っていないもの） */
export interface EaccFixture {
  stage: EaccGame['stage']
  home: EaccSide
  away: EaccSide
  /** 試合のシードの番号 */
  n: number
}

const winnerOf = (g: EaccGame) => (g.hs > g.as ? g.home : g.away)

/** 今週の試合（グループの 3 節・準決勝・決勝）。もう行った週は空 */
export function eaccFixtures(state: GameState): EaccFixture[] {
  const e = state.eacc
  if (!e || e.season !== state.season || e.games.some((g) => g.week === state.week)) return []
  const gi = (EACC_GROUP_WEEKS as readonly number[]).indexOf(state.week)
  if (gi >= 0) {
    // 4 クラブの総当たり（3 節）: 0-1・2-3 → 0-2・1-3 → 0-3・1-2
    const pairs = [
      [
        [0, 1],
        [2, 3],
      ],
      [
        [0, 2],
        [1, 3],
      ],
      [
        [0, 3],
        [1, 2],
      ],
    ][gi]
    const out: EaccFixture[] = []
    let n = 0
    for (const grp of ['A', 'B'] as const) for (const [a, b] of pairs) out.push({ stage: grp, home: e.groups[grp][a], away: e.groups[grp][b], n: n++ })
    return out
  }
  if (state.week === EACC_FINAL_WEEK) {
    const A = eaccTable(e, 'A')
    const B = eaccTable(e, 'B')
    return [
      { stage: 'SF', home: A[0].side, away: B[1].side, n: 10 },
      { stage: 'SF', home: B[0].side, away: A[1].side, n: 11 },
    ]
  }
  if (state.week === EACC_TITLE_WEEK) {
    const sf = e.games.filter((g) => g.stage === 'SF')
    if (sf.length === 2 && !e.games.some((g) => g.stage === 'F')) return [{ stage: 'F', home: winnerOf(sf[0]), away: winnerOf(sf[1]), n: 12 }]
  }
  return []
}

/** 試合の設定（観戦でも結果だけでも同じ。準決勝と決勝は中立地の大舞台） */
export function eaccSetup(state: GameState, f: EaccFixture): MatchSetup {
  const e = state.eacc!
  const big = f.stage === 'SF' || f.stage === 'F'
  return { home: inputOf(state, e, f.home), away: inputOf(state, e, f.away), rules: 'FIBA', seed: hashSeed(state.seed, e.season, state.week, f.n, 0xea), neutral: big, big }
}

/** そのチームの今週の大会の試合 */
export function teamEaccFixture(state: GameState, teamId: number): EaccFixture | undefined {
  return eaccFixtures(state).find((f) => f.home.team === teamId || f.away.team === teamId)
}

/** 試合の呼び名（グループ A・準決勝・決勝） */
export const eaccStageLabel = (stage: EaccGame['stage']) => (stage === 'F' ? '決勝' : stage === 'SF' ? '準決勝' : `グループ ${stage}`)

/** 1 試合。観戦した自分のクラブの試合は、その結果を使う。日本のクラブの選手は疲れる */
function play(state: GameState, e: EaccState, f: EaccFixture, played?: Map<number, MatchSummary>): EaccGame {
  const { stage, home, away } = f
  const club = state.club?.teamId
  const watched = club !== undefined && (home.team === club || away.team === club) ? played?.get(EACC_PLAYED) : undefined
  const sum: MatchSummary = watched ?? simulateMatch(eaccSetup(state, f))
  for (const [id, b] of Object.entries(sum.box)) {
    const p = state.players[Number(id)]
    if (p) p.fatigue = Math.min(100, p.fatigue + (b.secs / 60) * 0.5)
  }
  const g: EaccGame = { stage, week: state.week, home, away, hs: sum.score[0], as: sum.score[1] }
  e.games.push(g)
  // 日本のクラブの試合はニュースに
  if (home.team !== undefined || away.team !== undefined) {
    const label = eaccStageLabel(stage)
    state.news.push({ season: state.season, week: state.week, text: `${EACC_NAME}（${label}）: ${sideName(state, e, home)} ${g.hs}-${g.as} ${sideName(state, e, away)}` })
  }
  return g
}

/** グループの順位（勝ち → 得失点差） */
export function eaccTable(e: EaccState, group: 'A' | 'B') {
  return e.groups[group]
    .map((s) => {
      const gs = e.games.filter((g) => g.stage === group && (sameSide(g.home, s) || sameSide(g.away, s)))
      let w = 0
      let l = 0
      let diff = 0
      for (const g of gs) {
        const home = sameSide(g.home, s)
        const d = home ? g.hs - g.as : g.as - g.hs
        if (d > 0) w++
        else l++
        diff += d
      }
      return { side: s, w, l, diff }
    })
    .sort((a, b) => b.w - a.w || b.diff - a.diff)
}

/** 出場権（第 48 週のはじめ）: JBL1 の優勝と、レギュラーシーズンの上位（優勝と別） */
function qualify(state: GameState) {
  const lg = state.leagues.JBL1
  const champ = state.champions.find((c) => c.season === state.season && c.league === 'JBL1')?.teamId
  const order = sortedStandings(lg)
  const teams = [champ, ...order].filter((x): x is number => x !== undefined)
  state.eaccQual = { season: state.season + 1, teams: [...new Set(teams)].slice(0, 2) }
}

/** 大会のはじめ（新しいシーズンの最初のグループの週）: 外国のクラブと組み分け */
function start(state: GameState, rng: Rng) {
  const lg = state.leagues.JBL1
  let jp = (state.eaccQual?.season === state.season ? state.eaccQual.teams : []).filter((id) => lg.teamIds.includes(id))
  if (jp.length < 2) {
    const byPower = [...lg.teamIds].sort((a, b) => teamPower(state, state.teams[b]) - teamPower(state, state.teams[a]))
    jp = [...new Set([...jp, ...byPower])].slice(0, 2)
  }
  const pick = (k: keyof typeof FOREIGN, n: number) =>
    rng
      .shuffle([...FOREIGN[k]])
      .slice(0, n)
      .map((d): EaccForeign => ({ name: d.name, abbr: d.abbr, nation: d.nation, power: Math.round(rng.range(d.power[0], d.power[1])), color: d.color }))
  const foreign = [...pick('KR', 2), ...pick('CN', 2), ...pick('PH', 1), ...pick('TW', 1)]
  const order = rng.shuffle(foreign.map((_, i) => i))
  state.eacc = {
    season: state.season,
    foreign,
    groups: { A: [{ team: jp[0] }, ...order.slice(0, 3).map((i) => ({ foreign: i }))], B: [{ team: jp[1] }, ...order.slice(3, 6).map((i) => ({ foreign: i }))] },
    games: [],
  }
  state.news.push({ season: state.season, week: state.week, text: `${EACC_NAME}の組み合わせが決まった。日本からは${jp.map((id) => state.teams[id].name).join('と')}が出場`, big: true })
}

/** 週のはじめ（advanceWeek から）。行った試合を返す（クラブ経営の反応のため）。played は観戦した自分のクラブの試合（EACC_PLAYED） */
export function eaccWeek(state: GameState, rng: Rng, played?: Map<number, MatchSummary>): EaccGame[] {
  if (state.week === EACC_QUAL_WEEK) qualify(state)
  // 組み合わせはグループの前の週に（観戦の前に相手が分かるように）。その週を飛ばしたときは最初のグループの週に
  const fresh = !state.eacc || state.eacc.season !== state.season
  if (fresh && (state.week === EACC_DRAW_WEEK || state.week === EACC_GROUP_WEEKS[0])) start(state, rng)
  const e = state.eacc
  if (!e || e.season !== state.season) return []
  const out = eaccFixtures(state).map((f) => play(state, e, f, played))
  const fin = out.find((g) => g.stage === 'F')
  if (fin) {
    e.champion = winnerOf(fin)
    const name = sideName(state, e, e.champion)
    ;(state.eaccHistory ??= []).push({ season: state.season, champion: name, team: e.champion.team })
    state.news.push({ season: state.season, week: state.week, text: `${EACC_NAME}の決勝で${name}が優勝した（${Math.max(fin.hs, fin.as)}-${Math.min(fin.hs, fin.as)}）`, big: true })
  }
  return out
}

/** そのチームが今季の大会に出ているか */
export const inEacc = (state: GameState, teamId: number) => !!state.eacc && state.eacc.season === state.season && [...state.eacc.groups.A, ...state.eacc.groups.B].some((s) => s.team === teamId)
