/**
 * 体格（身長・ウイングスパン・体重）。バスケでは大事で、最初の能力と試合の確率（リバウンド・ブロック・競り合い）に効く。
 * 作成画面の「体格の解説」もここ（bodyNotes）。
 */
import type { AttrKey, Attrs } from '../data/attributes'
import { POSITION_DEFS, type Position } from '../data/positions'

/** ポジションの身長の目安の真ん中 */
export function posHeight(pos: Position): number {
  const [lo, hi] = POSITION_DEFS[pos].height
  return (lo + hi) / 2
}

/** 身長に対するふつうの体重（kg） */
export function typicalWeight(heightCm: number, pos: Position): number {
  const bmi = { PG: 23, SG: 23.5, SF: 24.2, PF: 25.2, C: 26 }[pos]
  return Math.round(bmi * (heightCm / 100) ** 2)
}

/** ウイングスパン（両腕を広げた長さ）の、身長との差のふつう（cm） */
export const TYPICAL_REACH = 6

/**
 * 体格による能力の上げ下げ（作成と生成で足す）。ポジションの目安の身長・ふつうの体重・ふつうの腕の長さとの差から。
 * 背が高いほどリバウンド・ブロック・ゴール下が強く、スピード・クイックネス・ドリブルは落ちる
 */
export function bodyBias(heightCm: number, wingspanCm: number, weightKg: number, pos: Position): Partial<Record<AttrKey, number>> {
  const dh = heightCm - posHeight(pos)
  const reach = wingspanCm - heightCm - TYPICAL_REACH
  const dw = weightKg - typicalWeight(heightCm, pos)
  return {
    block: dh * 0.6 + reach * 0.6,
    dreb: dh * 0.5 + reach * 0.25 + dw * 0.1,
    oreb: dh * 0.45 + reach * 0.2 + dw * 0.1,
    intD: dh * 0.4 + reach * 0.2 + dw * 0.2,
    close: dh * 0.3,
    steal: reach * 0.45 - dh * 0.1,
    perD: reach * 0.3 - dh * 0.15,
    speed: -dh * 0.5 - dw * 0.25,
    quick: -dh * 0.6 - dw * 0.2,
    handle: -dh * 0.3,
    jump: -dh * 0.15 - dw * 0.15,
    strength: dw * 0.6 + dh * 0.15,
    post: dw * 0.25 + dh * 0.2,
    stamina: -dw * 0.15,
  }
}

export function applyBias(a: Attrs, bias: Partial<Record<AttrKey, number>>, mul = 1) {
  for (const k of Object.keys(bias) as AttrKey[]) a[k] += (bias[k] ?? 0) * mul
}

/** 作成画面の体格の解説（変化の向きをひとことで） */
export function bodyNotes(heightCm: number, wingspanCm: number, weightKg: number, pos: Position): string[] {
  const out: string[] = []
  const dh = heightCm - posHeight(pos)
  const reach = wingspanCm - heightCm - TYPICAL_REACH
  const dw = weightKg - typicalWeight(heightCm, pos)
  if (dh >= 4) out.push(`${POSITION_DEFS[pos].name}としては背が高い: リバウンド・ブロックに強い／スピードとドリブルは落ちる`)
  else if (dh <= -4) out.push(`${POSITION_DEFS[pos].name}としては小柄: スピードとクイックネスで勝負／ゴール下とリバウンドは苦手`)
  else out.push(`${POSITION_DEFS[pos].name}として標準的な身長`)
  if (reach >= 5) out.push('腕が長い: ブロック・スティール・シュートへの寄せが届きやすい')
  else if (reach <= -4) out.push('腕が短め: ブロックとスティールは少し不利')
  if (dw >= 6) out.push('がっしり: 筋力・ポストプレーが強い／スピードとスタミナは少し落ちる')
  else if (dw <= -6) out.push('細身: 身軽で速い／当たり負けしやすい')
  return out
}
