/**
 * シーズンの終わり（第 51 週のあと）→ 次のシーズンのはじめ。
 *   表彰 → 成績を経歴へ → 国内の昇格・降格 → 契約（満了の選手は AI が残すか決める）→ 大学の学年（4 年生は卒業）
 *   → 引退 → 大学の新入生・国内の新人 → FA の補充 → 次のシーズン（順位表・日程・プレーオフをやり直す）
 */
import type { Rng } from '../core/prng'
import { absWeekOf, ageAt } from '../core/calendar'
import { NBA_TAX, jblMarketSalary, nbaMarketSalary } from '../economy/salary'
import { generatePlayer } from '../gen/playerGen'
import type { GameState } from '../models/game'
import { emptyStanding, type LeagueId, type Team } from '../models/league'
import { emptyStats, type Player } from '../models/player'
import { ovr } from '../player/overall'
import { assignPhotos } from '../player/photos'
import { JBL_POT, assignJerseys } from '../gen/worldGen'
import { playerValue, releasePlayer, topUpFreeAgents } from '../transfer/freeAgency'
import { giveAwards } from './awards'
import { runDraft } from './draft'
import { scheduleSeason } from './schedule'
import { sortedStandings } from './standings'
import { promotedTeams } from './promotion'
import { LICENSE_SEATS } from '../data/club'
import { clubSeasonEnd } from '../club/week'
import { clubFarewell, clubRookies } from '../club/transfer'
import { joinNba } from '../club/nba'

const COLLEGE_MIX: { codes: Player['nation'][]; weights: number[] } = { codes: ['US', 'CA', 'AU', 'FR', 'NG', 'SS', 'DE', 'LT', 'SN', 'GR'], weights: [84, 4, 3, 2, 2, 1, 1, 1, 1, 1] }

/** 成績を経歴に移す */
function archiveStats(state: GameState) {
  const abs = absWeekOf(state.season, state.week)
  for (const p of Object.values(state.players)) {
    if (!p.isPlayer && p.stats.gp === 0 && !(p.poStats && p.poStats.gp > 0)) {
      p.stats = emptyStats()
      delete p.poStats
      continue
    }
    const t = state.teams[p.teamId]
    p.history.push({
      season: state.season,
      teamId: p.teamId,
      teamName: t?.name ?? '所属なし',
      league: t?.league ?? 'NBA',
      age: ageAt(abs, p.birthAbs),
      ovr: ovr(p),
      stats: p.stats,
      playoffs: p.poStats,
    })
    p.stats = emptyStats()
    delete p.poStats
    // 経歴は主人公・固有キャラ以外は 10 シーズンまで（セーブを軽く）
    if (!p.isPlayer && !p.castId && p.history.length > 10) p.history.splice(0, p.history.length - 10)
  }
}

/**
 * 国内の昇格・降格。上がるのは下の部のチャンピオンシップの優勝クラブとレギュラーシーズンの最上位（promotion.ts）、下がるのは上の部の下位 2。
 * 先に 2 組（1 部と 2 部・2 部と 3 部）の入れ替えを全部決めてから動かす。
 * 前は 1 部と 2 部を動かしてから 2 部の下位 2 を決めていたので、1 部から下がったばかりのクラブ（2 部の成績は 0 勝 0 敗）が
 * そのまま 3 部まで二段落ちしていた（2026-11-14 に直した。古いセーブは migrations の版 3 で直す）
 */
export function promoteRelegate(state: GameState) {
  const move = (team: Team, to: LeagueId) => {
    const from = state.leagues[team.league]
    from.teamIds = from.teamIds.filter((id) => id !== team.id)
    state.leagues[to].teamIds.push(team.id)
    team.league = to
  }
  // クラブ経営: 自分のクラブは、上の部のライセンス（アリーナの席数）がないと上がれない（次の順位のクラブが上がる）
  const plan = (
    [
      ['JBL1', 'JBL2'],
      ['JBL2', 'JBL3'],
    ] as const
  ).map(([upper, lower]) => ({ upper, lower, down: sortedStandings(state.leagues[upper]).slice(-2), ...promotedTeams(state, lower, upper) }))
  for (const { upper, lower, down, up, blocked } of plan) {
    const need = LICENSE_SEATS[upper] ?? 0
    for (const id of blocked) state.news.push({ season: state.season, week: state.week, text: `${state.teams[id].name}は${state.leagues[upper].name}のライセンス（アリーナ ${need.toLocaleString()} 席）がなく、昇格できなかった`, big: true })
    for (const id of down) {
      move(state.teams[id], lower)
      state.news.push({ season: state.season, week: state.week, text: `${state.teams[id].name}が${state.leagues[lower].name}へ降格` })
    }
    for (const id of up) {
      move(state.teams[id], upper)
      state.news.push({ season: state.season, week: state.week, text: `${state.teams[id].name}が${state.leagues[upper].name}へ昇格`, big: upper === 'JBL1' })
    }
  }
}

/** 契約の年数を減らし、満了の選手は AI が残すか決める */
function contracts(state: GameState, rng: Rng) {
  const abs = absWeekOf(state.season, state.week)
  for (const t of state.teams) {
    if (t.league === 'NCAA') continue
    const ps = t.roster.map((id) => state.players[id])
    const vals = ps.map((p) => playerValue(p, ageAt(abs, p.birthAbs))).sort((a, b) => b - a)
    const keepLine = vals[Math.min(vals.length - 1, 9)] ?? 0
    const club = !!state.club && t.id === state.club.teamId
    for (const p of ps) {
      if (p.isPlayer) continue
      // クラブ経営: 自分のクラブは契約更改をした選手だけ残る（満了の選手は所属なしへ）
      if (club) {
        p.contract.years--
        if (p.contract.years <= 0) {
          releasePlayer(state, p)
          state.news.push({ season: state.season, week: state.week, text: `${p.name}が契約満了でクラブを離れた` })
        }
        continue
      }
      // NBA の AI のチームは、年俸の合計を見て残す（別の関数で）
      if (t.league === 'NBA') continue
      // 育成リーグで NBA の水準に届いた選手は、契約が残っていても FA へ（NBA のチームが拾う）
      if (t.league === 'DEV' && ovr(p) >= 65) {
        releasePlayer(state, p)
        continue
      }
      p.contract.years--
      if (p.contract.years > 0) continue
      const age = ageAt(abs, p.birthAbs)
      const v = playerValue(p, age)
      const keep = (v >= keepLine && age <= 34) || (age <= 30 && rng.chance(0.4))
      if (!keep) {
        releasePlayer(state, p)
        continue
      }
      const o = ovr(p)
      const years = age >= 32 ? 1 : age >= 29 ? rng.int(1, 3) : rng.int(2, 4)
      if (t.league === 'DEV') p.contract = { salary: p.contract.salary, years: 1, kind: p.contract.kind }
      else p.contract = { salary: jblMarketSalary(o, p.nation !== 'JP', t.league), years: Math.min(3, years), kind: 'pro' }
    }
    if (t.league === 'NBA' && !club) nbaContracts(state, ps, keepLine, abs, rng)
  }
}

/**
 * NBA の AI のチームの契約の満了: 価値の高い選手から、残すかを決める。
 * 残すと年俸の合計がぜいたく税の線を超えるなら、チームの柱（価値の上位 3 人・32 歳まで）でなければ FA へ。
 * 前は年俸の合計を見ずに残していたので、チームの年俸の平均が 11 シーズンで $136M → $245M に膨らんでいた（2026-11-08）
 */
function nbaContracts(state: GameState, ps: Player[], keepLine: number, abs: number, rng: Rng) {
  const value = new Map(ps.map((p) => [p.id, playerValue(p, ageAt(abs, p.birthAbs))]))
  const core = new Set([...ps].sort((a, b) => value.get(b.id)! - value.get(a.id)!).slice(0, 3).map((p) => p.id))
  let pay = 0
  const expiring: Player[] = []
  for (const p of ps) {
    if (p.isPlayer) {
      pay += p.contract.salary
      continue
    }
    p.contract.years--
    if (p.contract.years > 0) pay += p.contract.salary
    else expiring.push(p)
  }
  expiring.sort((a, b) => value.get(b.id)! - value.get(a.id)!)
  for (const p of expiring) {
    const age = ageAt(abs, p.birthAbs)
    const v = value.get(p.id)!
    const want = (v >= keepLine && age <= 34) || (age <= 30 && rng.chance(0.4))
    const o = ovr(p)
    const salary = nbaMarketSalary(o)
    const fits = pay + salary <= NBA_TAX || (core.has(p.id) && age <= 32)
    if (!want || !fits) {
      releasePlayer(state, p)
      continue
    }
    const years = age >= 32 ? 1 : age >= 29 ? rng.int(1, 3) : rng.int(2, 4)
    p.contract = { salary, years, kind: o >= 88 ? 'max' : 'standard' }
    pay += salary
  }
}

/** 大学: 学年を上げ、4 年生は卒業（所属なしへ） */
function collegeYear(state: GameState) {
  for (const id of state.leagues.NCAA.teamIds) {
    const t = state.teams[id]
    for (const pid of [...t.roster]) {
      const p = state.players[pid]
      if (p.isPlayer) continue
      p.classYear = (p.classYear ?? 1) + 1
      if (p.classYear > 4) {
        releasePlayer(state, p)
        delete p.classYear
      }
    }
  }
}

/** 引退（年齢・力・所属の有無）。主人公と固有キャラは記録を残す */
function retirements(state: GameState, rng: Rng) {
  const abs = absWeekOf(state.season, state.week)
  for (const p of Object.values(state.players)) {
    if (p.isPlayer || p.retired) continue
    const age = ageAt(abs, p.birthAbs)
    const o = ovr(p)
    const lg = p.teamId >= 0 ? state.teams[p.teamId].league : 'FA'
    if (lg === 'NCAA') continue
    let chance = 0
    if (age >= 40) chance = 1
    else if (age >= 33) chance = 0.12 + (age - 33) * 0.13 + (o < 62 ? 0.15 : 0) - (o >= 80 ? 0.15 : 0)
    else if (age >= 31 && lg.startsWith('JBL')) chance = 0.06 + (age - 31) * 0.08
    // 所属のないまま 1 年たった選手は、多くがほかの国のリーグへ（このゲームでは引退と同じ扱い）
    if (lg === 'FA') chance += age >= 28 ? 0.55 : age >= 24 ? 0.35 : o < 50 ? 0.3 : 0.1
    if (!rng.chance(Math.max(0, chance))) continue
    releasePlayer(state, p)
    if (state.club) clubFarewell(state, p)
    if (p.castId) {
      p.retired = true
      continue
    }
    delete state.players[p.id]
  }
}

/** 大学の新入生（人数を 13 にそろえる。強い大学には有望株） */
function recruit(state: GameState, rng: Rng) {
  for (const id of state.leagues.NCAA.teamIds) {
    const t = state.teams[id]
    let first = true
    while (t.roster.length < 13) {
      const star = first && t.rep >= 74 && rng.chance(0.6)
      first = false
      const o = Math.round(star ? rng.range(59, 67) : Math.max(38, Math.min(60, rng.normal(48 + (t.rep - 65) * 0.3, 4))))
      const p = generatePlayer(state, rng, { nation: COLLEGE_MIX.codes[rng.weighted(COLLEGE_MIX.weights)], age: 18, ovr: o, pot: star ? rng.int(84, 95) : undefined })
      p.classYear = 1
      p.teamId = t.id
      p.contract = { salary: 0, years: 4, kind: 'college' }
      t.roster.push(p.id)
    }
  }
}

/** 国内の新人（日本人。大学を出た 22 歳が中心、たまに高校生） */
function jblRookies(state: GameState, rng: Rng) {
  for (const lg of ['JBL1', 'JBL2', 'JBL3'] as const) {
    const base = lg === 'JBL1' ? 52 : lg === 'JBL2' ? 47 : 43
    for (const id of state.leagues[lg].teamIds) {
      const t = state.teams[id]
      // クラブ経営: 自分のクラブには、新人の候補が練習に来る（契約は編成の画面で）
      if (state.club && id === state.club.teamId) {
        clubRookies(state, rng, base)
        continue
      }
      const jp = t.roster.filter((pid) => state.players[pid].nation === 'JP').length
      const n = jp < 8 ? 2 : rng.chance(0.5) ? 1 : 0
      for (let i = 0; i < n && t.roster.length < 13; i++) {
        const hs = rng.chance(0.15)
        const p = generatePlayer(state, rng, { nation: 'JP', age: hs ? 18 : 22, ovr: Math.round(Math.max(36, rng.normal(hs ? base - 6 : base, 4))), potMul: JBL_POT[lg] })
        p.teamId = t.id
        p.contract = { salary: jblMarketSalary(ovr(p), false, lg), years: 3, kind: 'pro' }
        t.roster.push(p.id)
      }
    }
  }
}

/** 次のシーズンへ */
function newSeason(state: GameState, rng: Rng) {
  state.season++
  state.week = 0
  for (const lg of Object.values(state.leagues)) {
    lg.standings = {}
    for (const id of lg.teamIds) lg.standings[id] = emptyStanding()
  }
  state.series = []
  scheduleSeason(state, rng)
  for (const t of state.teams) assignJerseys(state, t, rng)
  // ニュースは直近の 2 シーズンぶん
  state.news = state.news.filter((n) => n.season >= state.season - 1)
}

export function seasonEnd(state: GameState, rng: Rng) {
  giveAwards(state)
  archiveStats(state)
  runDraft(state, rng)
  // クラブ経営: 順位・賞金・記録（昇格・降格の前に、そのシーズンのリーグで）
  if (state.club) clubSeasonEnd(state)
  promoteRelegate(state)
  // クラブ経営: NBA への参入（承認されていれば）
  if (state.club) joinNba(state, rng)
  contracts(state, rng)
  collegeYear(state)
  retirements(state, rng)
  recruit(state, rng)
  jblRookies(state, rng)
  topUpFreeAgents(state, rng)
  newSeason(state, rng)
  assignPhotos(state, state.club?.teamId ?? -1)
}
