/**
 * クラブ経営の効き目（自分のクラブの選手だけ）: 成長・ケガ・疲れの回復・試合の能力・序列。
 * engine の週の進行（advanceWeek・results・setup）から呼ぶ。乱数は使わない。
 */
import { ATTR_KEYS, type AttrKey } from '../data/attributes'
import { EXP_KINDS, EXP_OF } from '../data/career'
import { INTENSITY_DEFS } from '../data/club'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import type { GrowthBias } from '../player/growth'
import { ovr } from '../player/overall'
import { recommendDepth } from './advice'

export function isClubPlayer(state: GameState, p: Player): boolean {
  return !!state.club && p.teamId === state.club.teamId
}

const skillOf = (state: GameState, role: 'hc' | 'asst' | 'sc') => state.club?.staff[role]?.skill ?? 40

/** 成長の倍率（練習場・HC・アシスタントコーチ・練習の強さ） */
export function clubGrowthMul(state: GameState): number {
  const c = state.club!
  const fac = 1 + c.facilities.training * 0.08
  const hc = 1 + (skillOf(state, 'hc') - 50) / 500
  const asst = 1 + (skillOf(state, 'asst') - 50) / 250
  return fac * hc * asst * INTENSITY_DEFS[c.training.intensity].grow
}

/** 練習の重点 → 能力ごとの伸びの重み（平均が 1） */
export function clubGrowthBias(state: GameState, p?: { id: number }): GrowthBias {
  const c = state.club!
  const raw = Object.fromEntries(EXP_KINDS.map((k) => [k, 0.5 + c.training.focus[k] * 0.25])) as Record<string, number>
  // 選手ごとの重点: その種類をチームの重点の上にさらに（ほかは少しゆっくり）
  const own = p ? c.playerFocus?.[p.id] : undefined
  if (own) raw[own] += 0.9
  const mean = EXP_KINDS.reduce((s, k) => s + raw[k], 0) / EXP_KINDS.length
  const attr: Partial<Record<AttrKey, number>> = {}
  for (const a of ATTR_KEYS) attr[a] = raw[EXP_OF[a]] / mean
  return { mul: clubGrowthMul(state), attr }
}

/** ケガの倍率（メディカル・S&C・練習の強さ） */
export function clubInjuryMul(state: GameState): number {
  const c = state.club!
  return Math.max(0.2, (1 - c.facilities.medical * 0.1) * (1 - (skillOf(state, 'sc') - 50) / 150) * INTENSITY_DEFS[c.training.intensity].injury)
}

/** 疲れの回復の上乗せ（毎週。練習が厳しいと減る） */
export function clubRecoverBonus(state: GameState): number {
  const c = state.club!
  const base = c.facilities.medical * 2 + (skillOf(state, 'sc') - 50) / 10
  return base - (INTENSITY_DEFS[c.training.intensity].fatigue - 1) * 20
}

/** 試合の能力の上乗せ（分析室・HC） */
export function clubMatchBonus(state: GameState): number {
  const c = state.club!
  return c.facilities.analysis * 0.4 + (skillOf(state, 'hc') - 50) / 12
}

/** 序列（監督が決めた順）。ロスターにいない id は飛ばし、決めていない選手は後ろに総合値の順 */
/** 序列がおまかせか（手で並べるまでは既定でおまかせ） */
export const depthAuto = (state: GameState) => state.club!.autoDepth ?? !state.club!.depth?.length

export function clubDepth(state: GameState): number[] {
  const c = state.club!
  const team = state.teams[c.teamId]
  // おまかせ（手で並べるまでは既定でおまかせ）
  if (depthAuto(state)) return recommendDepth(state, team)
  const manual = (c.depth ?? []).filter((id) => team.roster.includes(id))
  const rest = team.roster.filter((id) => !manual.includes(id)).sort((a, b) => ovr(state.players[b]) - ovr(state.players[a]))
  return [...manual, ...rest]
}
