/**
 * セーブ／ロード（Dexie / IndexedDB）。GameState は JSON の文字列にして入れる（オブジェクトのまま入れるより 4 割ほど速い）。
 * 文字列は core/savePack.ts で詰める（経歴を表の形・小数を丸める。前の形のセーブも読める）。
 * スロットごとにシーズン末のスナップショットも持ち、1 年単位で戻れる。
 */
import Dexie, { type EntityTable } from 'dexie'
import type { GameState } from '../engine'
import { migrate } from '../engine/core/migrations'
import { packState, unpackState } from '../engine/core/savePack'

export interface SaveSlotMeta {
  id: number
  /** キャリア: 「選手名（所属）」、クラブ: クラブ名 */
  title: string
  season: number
  week: number
  dateLabel: string
  /** 所属のリーグ（大学・入団前もここ） */
  leagueName: string
  /** 順位（0 は不明） */
  rank: number
  /** キャリアは貯金、クラブは資金（万円） */
  money: number
  updatedAt: number
  mode: 'club' | 'career'
}

interface SaveData {
  slotId: number
  json: string
}

interface SeasonSnapshot {
  id?: number
  slotId: number
  season: number
  json: string
}

const unpack = (d: { json: string }): GameState => migrate(unpackState(d.json))

const db = new Dexie('court_crown') as Dexie & {
  slots: EntityTable<SaveSlotMeta, 'id'>
  states: EntityTable<SaveData, 'slotId'>
  snapshots: EntityTable<SeasonSnapshot, 'id'>
}

db.version(1).stores({
  slots: 'id',
  states: 'slotId',
  snapshots: '++id, slotId, [slotId+season]',
})

export const SLOT_COUNT = 5

export async function listSlots(): Promise<SaveSlotMeta[]> {
  const slots = await db.slots.toArray()
  return slots.sort((a, b) => b.updatedAt - a.updatedAt)
}

export async function saveGame(slotId: number, state: GameState, meta: Omit<SaveSlotMeta, 'id' | 'updatedAt'>): Promise<void> {
  // 呼んだ時点の中身で（文字列にするのはトランザクションの前に）
  const json = packState(state)
  await db.transaction('rw', db.slots, db.states, async () => {
    await db.slots.put({ ...meta, id: slotId, updatedAt: Date.now() })
    await db.states.put({ slotId, json })
  })
}

export async function loadGame(slotId: number): Promise<GameState | null> {
  const data = await db.states.get(slotId)
  return data ? unpack(data) : null
}

export async function deleteSlot(slotId: number): Promise<void> {
  await db.transaction('rw', db.slots, db.states, db.snapshots, async () => {
    await db.slots.delete(slotId)
    await db.states.delete(slotId)
    await db.snapshots.where('slotId').equals(slotId).delete()
  })
}

/** シーズンの控えは直近の数だけ残す（たまるとスマホの保存容量を圧迫する） */
const KEEP_SNAPSHOTS = 3

export async function saveSnapshot(slotId: number, state: GameState): Promise<void> {
  const json = packState(state)
  const existing = await db.snapshots.where('[slotId+season]').equals([slotId, state.season]).first()
  await db.snapshots.put({ ...(existing?.id != null ? { id: existing.id } : {}), slotId, season: state.season, json })
  const keys = (await db.snapshots.where('slotId').equals(slotId).primaryKeys()) as number[]
  if (keys.length > KEEP_SNAPSHOTS) await db.snapshots.bulkDelete(keys.sort((a, b) => a - b).slice(0, keys.length - KEEP_SNAPSHOTS))
}

export async function listSnapshots(slotId: number): Promise<{ id: number; season: number }[]> {
  const out: { id: number; season: number }[] = []
  await db.snapshots.where('slotId').equals(slotId).each((s) => void out.push({ id: s.id!, season: s.season }))
  return out.sort((a, b) => a.season - b.season)
}

export async function loadSnapshot(id: number): Promise<GameState | null> {
  const s = await db.snapshots.get(id)
  return s ? unpack(s) : null
}
