/**
 * 年俸の相場（万円/年）。NBA はドルで考えて 1$=150 円で万円に直す。
 *   NBA: 最低 約 $1.2M 〜 マックス 約 $50M（総合値 80 で約 $38M・75 で約 $22M・70 で約 $12M・65 で約 $5M）。
 *         ワールドを作るときは、チームごとに合計を目安（$95M〜$190M）へ合わせる（契約した時期の違いで、相場より安い・高い選手がいる）
 *   国内: 日本人の 1 部の主力で 3,000 万前後、外国籍は 5,000 万〜1 億。2 部・3 部は下がる
 */
import type { LeagueId } from '../models/league'

export const YEN_PER_DOLLAR = 150
export const usdToMan = (usd: number) => Math.round((usd * YEN_PER_DOLLAR) / 10000)
export const manToUsd = (man: number) => (man * 10000) / YEN_PER_DOLLAR

/** NBA のサラリーキャップ（簡略。$150M）・ぜいたく税のライン（$185M）・最低保証・マックス */
export const NBA_CAP = usdToMan(150e6)
export const NBA_TAX = usdToMan(185e6)
export const NBA_MIN = usdToMan(1.2e6)
export const NBA_MAX = usdToMan(50e6)
export const TWO_WAY_SALARY = usdToMan(0.6e6)
export const DEV_SALARY = usdToMan(0.04e6)

export function nbaMarketSalary(ovr: number): number {
  const usd = 1.2e6 + Math.max(0, (ovr - 58) / 32) ** 2.2 * 83e6
  return Math.min(NBA_MAX, usdToMan(usd))
}

const JBL_TIER_MUL: Partial<Record<LeagueId, number>> = { JBL1: 1, JBL2: 0.55, JBL3: 0.35 }

export function jblMarketSalary(ovr: number, foreign: boolean, league: LeagueId): number {
  const mul = JBL_TIER_MUL[league] ?? 1
  const base = foreign ? 2000 + Math.max(0, ovr - 52) ** 2 * 22 : 300 + Math.max(0, ovr - 40) ** 2 * 4
  return Math.round((base * mul) / 10) * 10
}
