/** 長所はいくつまで */
export const MAX_GOOD = 6
/** リーグのレギュラーシーズンの試合数（シーズンの終わりの「ほぼ全試合」の判定） */
const SEASON_GAMES: Record<string, number> = { NBA: 82, DEV: 54, JBL1: 60, JBL2: 60, JBL3: 60, NCAA: 30 }

/** 条件の 1 つ（画面の進み具合にも使う）: いまの値と目標。lower は「目標より下」で満たす */
export interface Meter {
  label: string
  now: number
  target: number
  unit: '%' | '' | '本' | '点' | '回' | '試合' | '歳'
  lower?: boolean
}

interface Rule {
  id: SkillId
  /** 身につく（短所は付く）条件 */
  gain: (s: Stats, x: Extra) => Meter[]
  /** 短所が消える条件 */
  lose?: (s: Stats, x: Extra) => Meter[]
}

interface Extra {
  attr: Record<string, number>
  moments: { tried: number; won: number }
  playoffs?: Stats
  age: number
  trust: number
  teamGames: number
}

const per = (s: Stats, k: keyof Stats) => (s.gp ? s[k] / s.gp : 0)
const pct = (m: number, a: number) => (a ? (m / a) * 100 : 0)
const ratio = (a: number, b: number) => (b ? a / b : a > 0 ? 9 : 0)
const M = (label: string, now: number, target: number, unit: Meter['unit'] = '', lower = false): Meter => ({ label, now, target, unit, lower })
const A = (x: Extra, k: string, label: string, target: number) => M(`${label}${/[A-Za-z0-9]$/.test(label) ? ' ' : ''}の能力`, x.attr[k], target)
const ok = (m: Meter) => (m.lower ? m.now < m.target : m.now >= m.target)
/** 条件を満たしているか（画面用） */
export const meterOk = ok
/** 条件への近さ 0〜1（画面のバー。「目標より下」は、下回っていれば 1） */
export function meterRate(m: Meter): number {
  if (ok(m)) return 1
  if (m.lower) return m.now > 0 ? Math.max(0, Math.min(1, m.target / m.now)) : 1
  return m.target > 0 ? Math.max(0, Math.min(1, m.now / m.target)) : 0
}

