/** 決め手の一言（満たした条件の値を並べる） */
const fmt = (m: Meter) => `${m.label} ${m.unit === '%' ? Math.round(m.now) : Number.isInteger(m.now) ? m.now : m.now.toFixed(1)}${m.unit}`
const why = (ms: Meter[]) => ms.filter((m) => !m.label.endsWith('の能力')).map(fmt).join('・') || ms.map(fmt).join('・')

/** 判定に使う今季の成績と、そのほか（画面の進み具合も同じものを使う） */
function extraOf(state: GameState, teamGames: number, playoffs?: Stats): Extra {
  const c = state.career!
  const p = careerPlayer(state)
  return { attr: p.attr as unknown as Record<string, number>, moments: c.moments, playoffs, age: careerAge(state), trust: c.trust, teamGames }
}

/** 画面の 1 行: その特殊能力の条件（持っている短所は消える条件）と、満たしているか */
export interface SkillRow {
  id: SkillId
  has: boolean
  meters: Meter[]
  ready: boolean
  kind: 'gain' | 'lose'
}

/** 判定に必要な試合数（これより少ないシーズンは判定しない） */
export const MIN_GAMES = 15

/** 育成の画面: 特殊能力ごとの、いまの進み具合（今季の成績で） */
export function skillProgress(state: GameState): SkillRow[] {
  const p = careerPlayer(state)
  const team = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  const st = team ? state.leagues[team.league].standings[team.id] : undefined
  const x = extraOf(state, st ? st.w + st.l : 0, p.poStats)
  return RULES.map((r) => {
    const has = p.skills.includes(r.id)
    const bad = !!SKILL_DEFS[r.id].bad
    const kind: SkillRow['kind'] = has && bad ? 'lose' : 'gain'
    const meters = kind === 'lose' ? r.lose!(p.stats, x) : r.gain(p.stats, x)
    return { id: r.id, has, meters, ready: p.stats.gp >= MIN_GAMES && meters.every(ok), kind }
  })
}

/** いちばん近い、まだ持っていない長所（ホームの欄の「あと少し」） */
export function nearestSkill(state: GameState): SkillRow | undefined {
  let best: SkillRow | undefined
  let bestRate = 0
  for (const r of skillProgress(state)) {
    if (r.has || SKILL_DEFS[r.id].bad) continue
    // 年齢が足りないものは「あと少し」ではない
    if (r.meters.some((m) => m.unit === '歳' && !ok(m))) continue
    const rate = Math.min(...r.meters.map(meterRate))
    if (rate > bestRate) {
      best = r
      bestRate = rate
    }
  }
  return best
}

/** 成績を見て、特殊能力を身につける・短所が付く・消える（1 回に 1 つまで。会話は 1 つ） */
function checkSkills(state: GameState, s: Stats, playoffs: Stats | undefined, teamGames: number) {
  const p = careerPlayer(state)
  if (s.gp < MIN_GAMES) return
  const x = extraOf(state, teamGames, playoffs)
  const good = p.skills.filter((k) => !SKILL_DEFS[k].bad).length
  for (const r of RULES) {
    const bad = !!SKILL_DEFS[r.id].bad
    const has = p.skills.includes(r.id)
    if (has && bad && r.lose) {
      const ms = r.lose(s, x)
      if (ms.every(ok)) {
        p.skills = p.skills.filter((k) => k !== r.id)
        return note(state, r.id, 'lose', why(ms))
      }
    }
    if (!has && (bad || good < MAX_GOOD)) {
      const ms = r.gain(s, x)
      if (ms.every(ok)) {
        p.skills = [...p.skills, r.id]
        return note(state, r.id, 'gain', why(ms))
      }
    }
  }
}

function note(state: GameState, id: SkillId, kind: 'gain' | 'lose', why: string) {
  const c = state.career!
  const p = careerPlayer(state)
  const d = SKILL_DEFS[id]
  c.traitWhy = { ...(c.traitWhy ?? {}), [id]: why }
  c.talks.push({ id: `trait:${id}:${kind}:${state.season}`, speaker: 'todo_maiko' })
  const text = d.bad ? (kind === 'gain' ? `${p.name}に短所「${d.name}」がついた（${why}）` : `${p.name}が短所「${d.name}」を克服した（${why}）`) : `${p.name}が特殊能力「${d.name}」を身につけた（${why}）`
  state.news.push({ season: state.season, week: state.week, text, big: !d.bad })
}

/** 成長タイプを 1 つずらす */
function shiftGrowth(state: GameState, dir: 1 | -1, reason: 'awaken' | 'care' | 'injury') {
  const c = state.career!
  const p = careerPlayer(state)
  const i = GROWTH_TYPES.indexOf(p.growth)
  const j = Math.max(0, Math.min(GROWTH_TYPES.length - 1, i + dir))
  if (i === j || c.growthEvents?.includes(reason)) return
  const from = p.growth
  p.growth = GROWTH_TYPES[j]
  c.growthEvents = [...(c.growthEvents ?? []), reason]
  c.talks.push({ id: `growth:${reason}:${from}`, speaker: 'todo_maiko' })
  state.news.push({ season: state.season, week: state.week, text: `${p.name}の成長タイプが「${GROWTH_DEFS[from].name}」から「${GROWTH_DEFS[p.growth].name}」に変わった`, big: true })
}

/** 週の終わり（careerAfterWeek から。シーズンの終わりは seasonEndCareer の前） */
export function traitsWeek(state: GameState, played: { week: number; seasonEnded: boolean }) {
  const c = state.career
  if (!c || c.retiredAt !== undefined) return
  const p = careerPlayer(state)
  const team = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  if (!played.seasonEnded && played.week === 26 && team) {
    const lg = state.leagues[team.league].standings[team.id]
    checkSkills(state, p.stats, undefined, lg ? lg.w + lg.l : 0)
  }
  if (played.seasonEnded) {
    const h = p.history[p.history.length - 1]
    if (h && h.season === state.season - 1) {
      checkSkills(state, h.stats, h.playoffs, SEASON_GAMES[h.league] ?? 60)
      // 覚醒: 若いうちに大きく伸びたシーズン
      const start = c.log.length >= 1 ? c.log[c.log.length - 1].ovr : undefined
      const age = careerAge(state)
      if (start !== undefined && age >= 22 && age <= 26 && ovr(p) - start >= 6) shiftGrowth(state, 1, 'awaken')
      // 体のケア: ベテランがサービスを続けて、ほぼ全試合に出た
      if (age >= 29 && (c.services?.length ?? 0) >= 2 && h.stats.gp >= (SEASON_GAMES[h.league] ?? 60) * 0.9) shiftGrowth(state, 1, 'care')
    }
  }
  // 大ケガ（27 歳から、全治 24 週以上）
  if (p.injury && p.injury.weeks >= 24 && careerAge(state) >= 27) shiftGrowth(state, -1, 'injury')
}

const L = (who: string, ...texts: string[]): TalkLine[] => texts.map((t) => (t.startsWith('me:') ? { who: 'me', text: t.slice(3) } : { who, text: t }))

export function traitTalkOf(id: string, state?: GameState): Talk | null {
  const [kind, a, b] = id.split(':')
  const c = state?.career
  if (kind === 'trait') {
    const d = SKILL_DEFS[a as SkillId]
    if (!d) return null
    const why = c?.traitWhy?.[a] ?? ''
    if (d.bad && b === 'gain') return { title: `短所「${d.name}」`, lines: L('todo_maiko', `${why}……。記者たちが「${d.name}」と書き始めたわ`, d.desc, '数字が戻れば、評判もすぐに戻る。練習で取り返しましょう') }
    if (d.bad) return { title: `「${d.name}」を克服`, lines: L('todo_maiko', `${why}。もう誰も「${d.name}」なんて言わないわ`, 'あなたが練習を続けた結果よ', 'me:……やっと、胸を張れる') }
    return { title: `特殊能力「${d.name}」`, lines: L('todo_maiko', `${why}。監督も記者も、あなたを「${d.name}」と呼び始めたわ`, d.desc, 'me:……これが、自分の武器だ') }
  }
  if (kind === 'growth' && state) {
    const p = careerPlayer(state)
    const from = GROWTH_DEFS[b as GrowthType]?.name ?? ''
    const to = GROWTH_DEFS[p.growth].name
    if (a === 'awaken') return { title: '覚醒', lines: L('todo_maiko', 'このシーズン、あなたは別人みたいに伸びた。トレーナーも驚いていたわ', `成長タイプが「${from}」から「${to}」に変わった。ピークはまだ先よ（${GROWTH_DEFS[p.growth].peak}）`, 'me:まだ、もっと上に行ける') }
    if (a === 'care') return { title: '体のケア', lines: L('todo_maiko', '毎日のケアを続けてきた成果ね。この歳で、ほとんど休まずに戦い抜いた', `成長タイプが「${from}」から「${to}」に。衰えが、ゆっくりになるわ`, 'me:体は正直だな') }
    if (a === 'injury') return { title: '大ケガ', lines: L('todo_maiko', '……長いケガになったわね。医師の話だと、体の回復には時間がかかるみたい', `成長タイプが「${from}」から「${to}」に変わった。衰えが早まるかもしれない`, 'でも、経験と頭は衰えない。プレーの形を変えていけばいいのよ') }
  }
  return null
}
