/**
 * 全日本選手権（国内のカップ戦。架空）: JBL1〜3 の 48 クラブのトーナメント（1 試合で勝ち抜け。延長あり）。
 *   1 回戦（第 15 週・水）: 2 部と 3 部の 32 クラブ → 2 回戦（第 18 週）: 勝った 16 と 1 部の 16 → 3 回戦（第 21 週）
 *   → 準々決勝（第 24 週）→ 準決勝（第 26 週・土。年明けの中断）→ 決勝（第 31 週・日。中断の週）
 *   組み合わせはその回戦の週のはじめに抽選。準々決勝の前までは下の部のクラブのホーム（同じ部なら抽選の先）、準々決勝からは中立地
 *   成績は数えない（疲れとケガはある）。ニュース: 番狂わせ・決勝。クラブ経営: 賞金・ファンと人気・会話の場面
 */
import type { Rng } from '../core/prng'
import type { GameState } from '../models/game'
import { allocId } from '../models/game'
import type { Fixture, LeagueId } from '../models/league'

export const CUP_NAME = '全日本選手権'
export const CUP_WEEKS = [15, 18, 21, 24, 26, 31] as const
const CUP_DAYS = [2, 2, 2, 2, 5, 6]
export const CUP_ROUNDS = ['1 回戦', '2 回戦', '3 回戦', '準々決勝', '準決勝', '決勝'] as const
const TIER: Partial<Record<LeagueId, number>> = { JBL1: 1, JBL2: 2, JBL3: 3 }

export interface CupGame {
  r: number
  fixtureId: number
  home: number
  away: number
  /** 試合のときの部（番狂わせの判定と画面） */
  homeLg: LeagueId
  awayLg: LeagueId
  hs?: number
  as?: number
  winner?: number
}

export interface CupState {
  season: number
  round: number
  alive: number[]
  games: CupGame[]
}

export interface CupRecord {
  season: number
  champion: number
  runnerUp: number
  championName: string
  runnerUpName: string
}

const tierOf = (state: GameState, id: number) => TIER[state.teams[id].league] ?? 4

/** 週のはじめ（advanceWeek から）: 回戦の週なら組み合わせを決めて日程に入れる */
export function cupWeek(state: GameState, rng: Rng) {
  const r = (CUP_WEEKS as readonly number[]).indexOf(state.week)
  if (r < 0) return
  if (r === 0) state.cup = { season: state.season, round: 0, alive: [...state.leagues.JBL2.teamIds, ...state.leagues.JBL3.teamIds], games: [] }
  const cup = state.cup
  if (!cup || cup.season !== state.season) return
  if (r === 1) cup.alive.push(...state.leagues.JBL1.teamIds)
  cup.round = r
  const draw = rng.shuffle([...cup.alive])
  for (let i = 0; i + 1 < draw.length; i += 2) {
    const [a, b] = [draw[i], draw[i + 1]]
    const home = tierOf(state, b) > tierOf(state, a) ? b : a
    const away = home === a ? b : a
    const f: Fixture = { id: allocId(state), league: 'JBL1', week: state.week, day: CUP_DAYS[r], home, away, kind: 'cup', neutral: r >= 3 || undefined }
    state.fixtures.push(f)
    cup.games.push({ r, fixtureId: f.id, home, away, homeLg: state.teams[home].league, awayLg: state.teams[away].league })
  }
}

/** 試合のあと（advanceWeek から）: 勝ち抜け・番狂わせ・優勝 */
export function cupResult(state: GameState, f: Fixture): { game: CupGame; winner: number; loser: number; upset: number } | null {
  const cup = state.cup
  const g = cup?.games.find((x) => x.fixtureId === f.id)
  if (!cup || !g || !f.result || g.winner !== undefined) return null
  const winner = f.result.hs > f.result.as ? f.home : f.away
  const loser = winner === f.home ? f.away : f.home
  g.hs = f.result.hs
  g.as = f.result.as
  g.winner = winner
  cup.alive = cup.alive.filter((id) => id !== loser)
  const wLg = winner === g.home ? g.homeLg : g.awayLg
  const lLg = winner === g.home ? g.awayLg : g.homeLg
  const upset = (TIER[wLg] ?? 4) - (TIER[lLg] ?? 4)
  const W = state.teams[winner]
  const Lo = state.teams[loser]
  const news = (text: string, big = false) => state.news.push({ season: state.season, week: state.week, text, big })
  if (g.r === 5) {
    news(`${CUP_NAME}の決勝で${W.name}が${Lo.name}を破り、優勝した（${Math.max(g.hs, g.as)}-${Math.min(g.hs, g.as)}）`, true)
    ;(state.cupHistory ??= []).push({ season: state.season, champion: winner, runnerUp: loser, championName: W.name, runnerUpName: Lo.name })
  } else if (upset > 0) news(`${CUP_NAME} ${CUP_ROUNDS[g.r]}: ${W.name}（${state.leagues[wLg].name}）が${Lo.name}（${state.leagues[lLg].name}）を倒す番狂わせ`, upset >= 2)
  return { game: g, winner, loser, upset }
}

/** 試合の札（画面）: プレーオフ・プレーイン・全日本選手権の回戦 */
export function fixtureLabel(state: GameState, f: Fixture): string | null {
  if (f.kind === 'regular') return null
  if (f.kind === 'cup') {
    const g = state.cup?.games.find((x) => x.fixtureId === f.id)
    return `${CUP_NAME}${g ? ` ${CUP_ROUNDS[g.r]}` : ''}`
  }
  return f.kind === 'playin' ? 'プレーイン' : 'プレーオフ'
}
