/** チーム・リーグ・日程・順位。 */
import type { RuleSetId } from '../data/rules'

export type LeagueId = 'NBA' | 'DEV' | 'JBL1' | 'JBL2' | 'JBL3' | 'NCAA'

export const LEAGUE_IDS: LeagueId[] = ['NBA', 'DEV', 'JBL1', 'JBL2', 'JBL3', 'NCAA']

/** 作戦（試合エンジンが読む。M2 で使い始める） */
export interface Tactics {
  /** 攻めのペース */
  pace: 'slow' | 'normal' | 'fast'
  /** 攻めの重心 */
  focus: 'inside' | 'balanced' | 'outside'
  /** 主なセット: ピック&ロール・モーション（パスと動き）・アイソレーション（1 対 1）・ポストアップ */
  set: 'pnr' | 'motion' | 'iso' | 'post'
  /** 守備: マンツーマン・2-3 ゾーン・3-2 ゾーン・プレス */
  defense: 'man' | 'zone23' | 'zone32' | 'press'
  /** 出場の人数（8 人で回す・9 人・10 人以上） */
  rotation: 'tight' | 'normal' | 'deep'
}

export const DEFAULT_TACTICS: Tactics = { pace: 'normal', focus: 'balanced', set: 'pnr', defense: 'man', rotation: 'normal' }

export interface Team {
  id: number
  league: LeagueId
  city: string
  nickname: string
  /** 表示名（都市＋愛称。大学は大学名） */
  name: string
  /** 短い名前（愛称。大学は略称） */
  short: string
  abbr: string
  colors: { primary: string; secondary: string }
  /** 格（0-100） */
  rep: number
  /** 所属選手の id */
  roster: number[]
  /** NBA のカンファレンスとディビジョン・大学のカンファレンス */
  conf?: string
  div?: string
  /** NBA ↔ 育成リーグの提携先 */
  affiliate?: number
  arena: { name: string; capacity: number }
  tactics: Tactics
  /** ヘッドコーチ */
  coach: { name: string; skill: number }
}

export interface Standing {
  w: number
  l: number
  pf: number
  pa: number
  hw: number
  hl: number
  aw: number
  al: number
  /** 同じカンファレンスどうしの勝敗（NBA・大学） */
  cw: number
  cl: number
  /** 連勝（+）・連敗（-） */
  streak: number
}

export function emptyStanding(): Standing {
  return { w: 0, l: 0, pf: 0, pa: 0, hw: 0, hl: 0, aw: 0, al: 0, cw: 0, cl: 0, streak: 0 }
}

export interface League {
  id: LeagueId
  name: string
  short: string
  rules: RuleSetId
  /** 1 部・2 部…（国内）。NBA は 0、育成・大学は 9 */
  tier: number
  teamIds: number[]
  standings: Record<number, Standing>
}

export type FixtureKind = 'regular' | 'playin' | 'playoff' | 'cup'

export interface GameResult {
  hs: number
  as: number
  /** 延長の回数 */
  ot: number
  /** 試合の流れ（1 分ごとの点差。主人公・自分のクラブの試合だけ残す） */
  flow?: number[]
}

export interface Fixture {
  id: number
  league: LeagueId
  week: number
  /** 週の中の曜日（0 月〜6 日）。同じ週の試合はこの順に行う */
  day: number
  home: number
  away: number
  kind: FixtureKind
  /** プレーオフのシリーズ */
  seriesId?: number
  /** 中立地（全日本選手権の準々決勝から） */
  neutral?: boolean
  result?: GameResult
}
