/**
 * 総合値（OVR）: ポジションごとの能力の重みの加重平均。体格（身長）がポジションに合っているかで少しだけ上下する。
 * 目安: NBA のスター 88〜、スタメン 75〜、ベンチ 68〜／国内 1 部の日本人 55〜65・外国籍 66〜74／18 歳の有望株 45〜55
 */
import { ATTR_KEYS, type AttrKey, type Attrs } from '../data/attributes'
import { POSITION_DEFS, POSITIONS, type Position } from '../data/positions'

export const POS_WEIGHTS: Record<Position, Record<AttrKey, number>> = {
  PG: { close: 0.3, mid: 0.7, three: 1.2, ft: 0.4, layup: 0.9, dunk: 0.1, post: 0.05, handle: 1.5, pass: 1.6, vision: 1.4, perD: 0.9, intD: 0.1, steal: 0.6, block: 0.05, oreb: 0.05, dreb: 0.25, speed: 0.9, quick: 1.0, jump: 0.3, strength: 0.25, stamina: 0.4, iq: 1.2, clutch: 0.4 },
  SG: { close: 0.3, mid: 1.0, three: 1.6, ft: 0.5, layup: 0.9, dunk: 0.3, post: 0.1, handle: 1.0, pass: 0.7, vision: 0.6, perD: 1.1, intD: 0.2, steal: 0.6, block: 0.15, oreb: 0.1, dreb: 0.3, speed: 0.9, quick: 0.9, jump: 0.5, strength: 0.35, stamina: 0.4, iq: 0.9, clutch: 0.5 },
  SF: { close: 0.6, mid: 0.8, three: 1.2, ft: 0.4, layup: 1.0, dunk: 0.6, post: 0.3, handle: 0.7, pass: 0.6, vision: 0.5, perD: 1.1, intD: 0.5, steal: 0.5, block: 0.4, oreb: 0.35, dreb: 0.6, speed: 0.8, quick: 0.8, jump: 0.7, strength: 0.6, stamina: 0.4, iq: 0.9, clutch: 0.4 },
  PF: { close: 1.2, mid: 0.6, three: 0.6, ft: 0.3, layup: 0.7, dunk: 0.8, post: 0.8, handle: 0.3, pass: 0.4, vision: 0.35, perD: 0.5, intD: 1.1, steal: 0.3, block: 0.8, oreb: 0.9, dreb: 1.2, speed: 0.5, quick: 0.5, jump: 0.7, strength: 1.1, stamina: 0.4, iq: 0.8, clutch: 0.3 },
  C: { close: 1.4, mid: 0.3, three: 0.2, ft: 0.25, layup: 0.4, dunk: 0.9, post: 1.1, handle: 0.15, pass: 0.35, vision: 0.3, perD: 0.2, intD: 1.5, steal: 0.15, block: 1.4, oreb: 1.1, dreb: 1.5, speed: 0.3, quick: 0.3, jump: 0.7, strength: 1.3, stamina: 0.4, iq: 0.8, clutch: 0.25 },
}

const WEIGHT_SUM: Record<Position, number> = Object.fromEntries(
  POSITIONS.map((p) => [p, ATTR_KEYS.reduce((s, k) => s + POS_WEIGHTS[p][k], 0)]),
) as Record<Position, number>

/** 能力だけの加重平均 */
export function rawOvr(a: Attrs, pos: Position): number {
  const w = POS_WEIGHTS[pos]
  let s = 0
  for (const k of ATTR_KEYS) s += a[k] * w[k]
  return s / WEIGHT_SUM[pos]
}

/** 身長がポジションの目安から外れているときの補正（-3〜+1） */
export function heightFit(heightCm: number, pos: Position): number {
  const [lo, hi] = POSITION_DEFS[pos].height
  if (heightCm < lo) return Math.max(-3, (heightCm - lo) * 0.25)
  if (heightCm > hi) return pos === 'C' || pos === 'PF' ? Math.min(1, (heightCm - hi) * 0.1) : 0
  return 0
}

export interface OvrInput {
  attr: Attrs
  pos: Position
  heightCm: number
}

export function ovrAt(p: OvrInput, pos: Position): number {
  return Math.round(Math.min(99, Math.max(1, rawOvr(p.attr, pos) + heightFit(p.heightCm, pos))))
}

/** メインのポジションでの総合値 */
export function ovr(p: OvrInput): number {
  return ovrAt(p, p.pos)
}

/** いちばん高くなるポジション */
export function bestPosition(p: OvrInput): Position {
  let best: Position = p.pos
  let v = -1
  for (const pos of POSITIONS) {
    const o = ovrAt(p, pos)
    if (o > v) {
      v = o
      best = pos
    }
  }
  return best
}
