/**
 * 試合のルール。NBA・国際（国内リーグと代表）・大学で少しずつ違う。解説は用語集（glossary.ts）。
 */
export type RuleSetId = 'NBA' | 'FIBA' | 'NCAA'

export interface RuleSet {
  name: string
  /** 1 ピリオドの長さ（分） */
  periodMin: number
  /** ピリオドの数（大学は前後半の 2） */
  periods: number
  /** 延長の長さ（分） */
  otMin: number
  /** 個人ファウルで退場になる数 */
  foulOut: number
  /** ショットクロック（秒） */
  shotClock: number
  /** 3P ラインの距離（m。コーナーは短い） */
  threeDist: number
  threeCorner: number
  /** チームファウルがこの数を超えると相手にフリースロー（ボーナス）。ピリオドごと（大学は前後半ごと） */
  bonusAt: number
  /** コートの大きさ（m） */
  courtLen: number
  courtWid: number
}

export const RULES: Record<RuleSetId, RuleSet> = {
  NBA: { name: 'NBA ルール', periodMin: 12, periods: 4, otMin: 5, foulOut: 6, shotClock: 24, threeDist: 7.24, threeCorner: 6.71, bonusAt: 4, courtLen: 28.65, courtWid: 15.24 },
  FIBA: { name: '国際ルール', periodMin: 10, periods: 4, otMin: 5, foulOut: 5, shotClock: 24, threeDist: 6.75, threeCorner: 6.6, bonusAt: 4, courtLen: 28, courtWid: 15 },
  NCAA: { name: '大学ルール', periodMin: 20, periods: 2, otMin: 5, foulOut: 5, shotClock: 30, threeDist: 6.75, threeCorner: 6.6, bonusAt: 6, courtLen: 28.65, courtWid: 15.24 },
}

export function gameMinutes(r: RuleSet): number {
  return r.periodMin * r.periods
}
