export type Attrs = Record<AttrKey, number>

/** 成長のグループ: tech 技術（ゆっくり衰える）・phys 瞬発系（早く衰える）・body 体（遅くまで伸びる）・mind 頭（30 代まで伸びる） */
export type GrowthGroup = 'tech' | 'phys' | 'body' | 'mind'

export interface AttrDef {
  label: string
  /** 短い名前（表の見出し） */
  short: string
  group: GrowthGroup
  /** 能力の分類（画面の並び） */
  cat: AttrCat
  desc: string
}

export type AttrCat = 'shoot' | 'finish' | 'play' | 'defense' | 'rebound' | 'athletic' | 'mental'

