/** レーダーチャートの 6 つの軸（分類ごとの平均。メンタルはバスケ IQ として運動能力と分ける） */
export const RADAR_AXES: { label: string; keys: AttrKey[] }[] = [
  { label: 'シュート', keys: ['close', 'mid', 'three', 'ft'] },
  { label: 'フィニッシュ', keys: ['layup', 'dunk', 'post'] },
  { label: 'プレーメイク', keys: ['handle', 'pass', 'vision'] },
  { label: '守備', keys: ['perD', 'intD', 'steal', 'block'] },
  { label: 'リバウンド', keys: ['oreb', 'dreb'] },
  { label: '運動能力', keys: ['speed', 'quick', 'jump', 'strength', 'stamina'] },
]

export function radarValues(a: Attrs): number[] {
  return RADAR_AXES.map((ax) => ax.keys.reduce((s, k) => s + a[k], 0) / ax.keys.length)
}

export function emptyAttrs(v = 0): Attrs {
  return Object.fromEntries(ATTR_KEYS.map((k) => [k, v])) as Attrs
}

/** 能力のランク（S〜G） */
export function attrRank(v: number): string {
  if (v >= 90) return 'S'
  if (v >= 80) return 'A'
  if (v >= 70) return 'B'
  if (v >= 60) return 'C'
  if (v >= 50) return 'D'
  if (v >= 40) return 'E'
  if (v >= 30) return 'F'
  return 'G'
}
