/** 選手の性格（8タイプ）。成長・調子の波・やる気・連携の相性にゆるく効く。 */

export const PERSONALITIES = ['hot', 'cool', 'mood', 'effort', 'genius', 'mypace', 'leader', 'shy'] as const
export type Personality = (typeof PERSONALITIES)[number]

export interface PersonalityDef {
  name: string
  blurb: string
  growthMul: number
  /** 調子の振れ幅 */
  conditionVar: number
  /** 疲労回復ボーナス（週あたり） */
  recover: number
  /** やる気の上下しやすさ */
  moraleVar: number
}

export const PERSONALITY_DEFS: Record<Personality, PersonalityDef> = {
  hot: { name: '熱血漢', blurb: '誰よりも練習する。たまに飛ばしすぎる。', growthMul: 1.15, conditionVar: 1.15, recover: -1, moraleVar: 1.2 },
  cool: { name: 'クール', blurb: '常に冷静。調子の波が小さい。', growthMul: 1.0, conditionVar: 0.7, recover: 1, moraleVar: 0.7 },
  mood: { name: 'ムードメーカー', blurb: 'チームを明るくする人気者。', growthMul: 1.02, conditionVar: 0.9, recover: 2, moraleVar: 0.8 },
  effort: { name: '努力家', blurb: 'コツコツ積み上げて伸びしろを引き出す。', growthMul: 1.22, conditionVar: 1.0, recover: 0, moraleVar: 0.9 },
  genius: { name: '天才肌', blurb: '感覚派。練習は普通でも本番に強い。', growthMul: 0.95, conditionVar: 0.85, recover: 1, moraleVar: 1.0 },
  mypace: { name: 'マイペース', blurb: '気分屋。ハマると強いが波が大きい。', growthMul: 1.03, conditionVar: 1.45, recover: 1, moraleVar: 0.6 },
  leader: { name: 'リーダー', blurb: '仲間を引っ張る。連携が育ちやすい。', growthMul: 1.05, conditionVar: 0.85, recover: 0, moraleVar: 0.9 },
  shy: { name: '繊細', blurb: '人見知りだが心優しい。環境に左右されやすい。', growthMul: 1.08, conditionVar: 1.2, recover: 0, moraleVar: 1.35 },
}

/** 連携の育ちやすさ（性格の相性、1.0 が普通） */
export function chemistryAffinity(a: Personality, b: Personality): number {
  if (a === b) return a === 'mypace' ? 0.95 : 1.1
  const good: [Personality, Personality][] = [
    ['hot', 'effort'],
    ['mood', 'shy'],
    ['leader', 'shy'],
    ['leader', 'hot'],
    ['cool', 'genius'],
    ['mood', 'mypace'],
    ['effort', 'cool'],
  ]
  const bad: [Personality, Personality][] = [
    ['hot', 'mypace'],
    ['cool', 'hot'],
    ['genius', 'effort'],
  ]
  const has = (list: [Personality, Personality][]) => list.some(([x, y]) => (x === a && y === b) || (x === b && y === a))
  if (has(good)) return 1.2
  if (has(bad)) return 0.85
  return 1.0
}
